const app = new Hono();

// Create Supabase client with service role for database operations
const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
);

// Helper function to verify user authentication using anon key
async function verifyUserAuth(accessToken: string) {
  const authSupabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_ANON_KEY")!,
    {
      global: {
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      },
    },
  );
  
  return await authSupabase.auth.getUser();
}

// 🔥 Helper function to check if student is graduated
async function checkIfStudentGraduated(userId: string) {
  const { data: profile } = await supabase
    .from('profiles')
    .select('is_graduated, role')
    .eq('id', userId)
    .single();
  
  return {
    isGraduated: profile?.is_graduated === true,
    role: profile?.role
  };
}

