// Auth diagnostic endpoint - check if token is valid
app.get("/make-server-1ddd013a/auth-check", async (c) => {
  const accessToken = c.req.header("Authorization")?.split(" ")[1];
  
  if (!accessToken) {
    return c.json({
      success: false,
      error: "No access token provided",
      hasAuthHeader: !!c.req.header("Authorization"),
      authHeaderValue: c.req.header("Authorization")?.substring(0, 20) + "...",
    });
  }

  const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
  
  return c.json({
    success: !!user,
    hasUser: !!user,
    userId: user?.id,
    userEmail: user?.email,
    error: authError?.message,
    tokenPreview: accessToken.substring(0, 20) + "...",
  });
});

// List all users with profiles - diagnostic endpoint
app.get(
  "/make-server-1ddd013a/list-users-with-profiles",
  async (c) => {
    try {
      console.log("Listing all users with profiles...");

      // Get all auth users
      const { data: authData } =
        await supabase.auth.admin.listUsers();
      const authUsers = authData?.users || [];

      // Get all profiles
      const { data: profiles } = await supabase
        .from("profiles")
        .select("*");

      const result = authUsers.map((authUser) => {
        const profile = profiles?.find(
          (p) => p.id === authUser.id,
        );
        return {
          auth_id: authUser.id,
          email: authUser.email,
          has_profile: !!profile,
          profile_role: profile?.role || "NO_PROFILE",
          profile_name: profile
            ? `${profile.first_name} ${profile.last_name}`
            : "NO_PROFILE",
        };
      });

      return c.json({
        success: true,
        total_auth_users: authUsers.length,
        total_profiles: profiles?.length || 0,
        users: result,
        users_without_profiles: result.filter(
          (u) => !u.has_profile,
        ),
      });
    } catch (error) {
      console.error("Error listing users:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Unknown error",
        },
        500,
      );
    }
  },
);

