// Get profile photo endpoint
app.get("/make-server-1ddd013a/profile-photo", async (c) => {
  try {
    const email = c.req.query("email");

    if (!email) {
      return c.json(
        { success: false, error: "Email parameter required" },
        400,
      );
    }

    console.log("[Profile Photo] Fetching photo for:", email);

    // Get user profile from KV store
    const kvKey = `user_profile:${email}`;
    const profileData = await kv.get(kvKey);

    if (profileData && profileData.photo_url) {
      return c.json({
        success: true,
        photo_url: profileData.photo_url,
      });
    }

    // If not in KV store, return no photo
    return c.json({
      success: true,
      photo_url: null,
    });
  } catch (error) {
    console.error("[Profile Photo] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch profile photo",
      },
      500,
    );
  }
});

// Get users endpoint (for director dashboard)
app.get("/make-server-1ddd013a/users", async (c) => {
  try {
    const role = c.req.query("role");

    console.log("[Users] Fetching users with role:", role);

    let query = supabase
      .from("profiles")
      .select(
        "id, first_name, middle_name, last_name, email, role, class_id",
      );

    if (role) {
      query = query.eq("role", role);
      
      // 🔥 FIX: Filter out graduated students
      if (role === "student") {
        query = query.or("is_graduated.is.null,is_graduated.eq.false");
      }
    }
    
    query = query.order("first_name", { ascending: true });

    const { data: users, error } = await query;

    if (error) {
      console.error("[Users] Error fetching users:", error);
      return c.json(
        { success: false, error: error.message },
        500,
      );
    }

    console.log(`[Users] Found ${users?.length || 0} users`);

    return c.json({
      success: true,
      users: users || [],
    });
  } catch (error) {
    console.error("[Users] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch users",
      },
      500,
    );
  }
});

