// Verify user authentication and get profile
app.post("/make-server-1ddd013a/verify-auth", async (c) => {
  try {
    const { email } = await c.req.json();

    if (!email) {
      return c.json(
        { success: false, error: "Email is required" },
        400,
      );
    }

    console.log(`Verifying auth for user: ${email}`);

    // Get the user profile
    const { data: profile, error } = await supabase
      .from("profiles")
      .select("*")
      .eq("email", email)
      .maybeSingle();

    if (error) {
      console.error("Error fetching user profile:", error);
      return c.json({
        success: false,
        error: "Profile not found",
      });
    }

    if (!profile) {
      console.log("No profile found for email:", email);
      return c.json({
        success: false,
        error: "Profile not found",
      });
    }

    console.log("User profile found:", profile);

    return c.json({
      success: true,
      profile,
      redirectTo: "/dashboard", // Default redirect
    });
  } catch (error) {
    console.error("Error in verify-auth endpoint:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Unknown error occurred",
      },
      500,
    );
  }
});

// Check if demo users exist
app.get("/make-server-1ddd013a/check-demo-users", async (c) => {
  try {
    console.log("Checking if demo users exist...");

    const { data: profiles, error } = await supabase
      .from("profiles")
      .select("email, first_name, last_name, role")
      .in("email", [
        "principal@school.edu",
        "it.admin@school.edu",
        "teacher@school.edu",
        "student@school.edu",
      ]);

    if (error) {
      console.error("Error checking demo users:", error);
      return c.json({
        success: false,
        error: error.message,
        profilesExist: false,
      });
    }

    const existingEmails = profiles?.map((p) => p.email) || [];
    const missingUsers = [
      "principal@school.edu",
      "it.admin@school.edu",
      "teacher@school.edu",
      "student@school.edu",
    ].filter((email) => !existingEmails.includes(email));

    return c.json({
      success: true,
      profilesExist: profiles && profiles.length > 0,
      existingUsers: profiles || [],
      missingUsers,
      needsSetup: missingUsers.length > 0,
    });
  } catch (error) {
    console.error("Error in check-demo-users endpoint:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Unknown error occurred",
        profilesExist: false,
      },
      500,
    );
  }
});

