// Submit registration application
app.post(
  "/make-server-1ddd013a/submit-registration",
  async (c) => {
    try {
      const body = await c.req.json();
      const {
        email,
        first_name,
        middle_name,
        last_name,
        role,
        password,
        additional_info,
      } = body;

      console.log(
        "Processing registration application for:",
        email,
      );

      // Validate required fields
      if (
        !email ||
        !first_name ||
        !last_name ||
        !role ||
        !password
      ) {
        return c.json(
          {
            success: false,
            error: "Missing required fields",
          },
          400,
        );
      }

      // Check if email already exists in pending registrations or profiles
      const existingProfile = await kv.get(
        `pending_registration:${email}`,
      );
      if (existingProfile) {
        return c.json(
          {
            success: false,
            error:
              "Registration already submitted for this email",
          },
          400,
        );
      }

      // Check if user already exists in profiles
      const { data: existingUser, error: checkError } =
        await supabase
          .from("profiles")
          .select("email")
          .eq("email", email)
          .maybeSingle();

      if (existingUser) {
        return c.json(
          {
            success: false,
            error: "User already exists with this email",
          },
          400,
        );
      }

      // Store pending registration in KV store
      const registrationData = {
        email,
        first_name,
        middle_name: middle_name || "",
        last_name,
        role,
        password, // Will be hashed when creating auth user
        additional_info: additional_info || {},
        status: "pending",
        submitted_at: new Date().toISOString(),
        reviewed_at: null,
        reviewed_by: null,
      };

      await kv.set(
        `pending_registration:${email}`,
        registrationData,
      );

      // Also store in a list for admin dashboard
      const pendingList =
        (await kv.get("pending_registrations_list")) || [];
      if (!pendingList.includes(email)) {
        pendingList.push(email);
        await kv.set("pending_registrations_list", pendingList);
      }

      console.log(
        "Registration application submitted successfully for:",
        email,
      );

      return c.json({
        success: true,
        message:
          "Registration application submitted successfully. You will be notified once approved.",
        registration_id: email,
      });
    } catch (error) {
      console.error(
        "Error in submit-registration endpoint:",
        error,
      );
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Registration submission failed",
        },
        500,
      );
    }
  },
);

// Get pending registrations for admin
app.post(
  "/make-server-1ddd013a/get-pending-registrations",
  async (c) => {
    try {
      // Verify admin access
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is IT Admin - only IT Admin can view pending registrations
      const { data: profile, error: profileError } =
        await supabase
          .from("profiles")
          .select("role")
          .eq("id", user.id)
          .maybeSingle();

      if (!profile || profile.role !== "it_admin") {
        return c.json(
          {
            success: false,
            error:
              "Insufficient permissions - only IT Administrators can view pending registrations",
          },
          403,
        );
      }

      console.log(
        "Fetching pending registrations for admin:",
        user.id,
      );

      // Get list of pending registration emails
      const pendingList =
        (await kv.get("pending_registrations_list")) || [];

      // Fetch all pending registration details
      const pendingRegistrations = [];
      for (const email of pendingList) {
        const registration = await kv.get(
          `pending_registration:${email}`,
        );
        if (registration && registration.status === "pending") {
          // Remove sensitive data before sending to frontend
          const { password, ...safeRegistration } =
            registration;
          pendingRegistrations.push(safeRegistration);
        }
      }

      return c.json({
        success: true,
        registrations: pendingRegistrations,
      });
    } catch (error) {
      console.error(
        "Error in get-pending-registrations endpoint:",
        error,
      );
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch pending registrations",
        },
        500,
      );
    }
  },
);

// Approve registration
app.post(
  "/make-server-1ddd013a/approve-registration",
  async (c) => {
    try {
      const body = await c.req.json();
      const { email, action } = body; // action: 'approve' or 'reject'

      // Verify admin access
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is IT Admin - only IT Admin can approve/reject registrations
      const { data: adminProfile, error: profileError } =
        await supabase
          .from("profiles")
          .select("role, email")
          .eq("id", user.id)
          .maybeSingle();

      if (!adminProfile || adminProfile.role !== "it_admin") {
        return c.json(
          {
            success: false,
            error:
              "Insufficient permissions - only IT Administrators can approve registrations",
          },
          403,
        );
      }

      console.log(
        `Processing ${action} for registration:`,
        email,
      );

      // Get pending registration
      const registrationData = await kv.get(
        `pending_registration:${email}`,
      );
      if (!registrationData) {
        return c.json(
          {
            success: false,
            error: "Registration not found",
          },
          404,
        );
      }

      if (registrationData.status !== "pending") {
        return c.json(
          {
            success: false,
            error: "Registration already processed",
          },
          400,
        );
      }

      if (action === "approve") {
        // Create Supabase auth user
        const { data: authData, error: authError } =
          await supabase.auth.admin.createUser({
            email: registrationData.email,
            password: registrationData.password,
            user_metadata: {
              first_name: registrationData.first_name,
              middle_name: registrationData.middle_name,
              last_name: registrationData.last_name,
              role: registrationData.role,
            },
            email_confirm: true,
          });

        if (authError) {
          console.error("Error creating auth user:", authError);
          return c.json(
            {
              success: false,
              error: `Failed to create user account: ${authError.message}`,
            },
            500,
          );
        }

        // Determine the actual role to use
        let actualRole = registrationData.role;

        // For admin registrations, use the specific admin_role from additional_info
        if (
          registrationData.role === "admin" &&
          registrationData.additional_info?.admin_role
        ) {
          actualRole =
            registrationData.additional_info.admin_role;
        }

        // Create profile in profiles table
        const profileData: any = {
          id: authData.user.id,
          email: registrationData.email,
          first_name: registrationData.first_name,
          middle_name: registrationData.middle_name,
          last_name: registrationData.last_name,
          role: actualRole,
        };

        // For students, include class_id and new fields from additional_info
        if (registrationData.role === "student") {
          if (registrationData.additional_info?.class_id) {
            profileData.class_id =
              registrationData.additional_info.class_id;
          }

          // Add gender (required for students)
          if (registrationData.additional_info?.gender) {
            profileData.gender =
              registrationData.additional_info.gender;
          }

          // Add date_of_birth (required for students)
          if (registrationData.additional_info?.date_of_birth) {
            profileData.date_of_birth =
              registrationData.additional_info.date_of_birth;
          }

          // Add phone (optional for students)
          if (registrationData.additional_info?.phone) {
            profileData.phone =
              registrationData.additional_info.phone;
          }

          // Auto-generate admission number
          // Format: ADM{YEAR}{SEQUENTIAL_NUMBER} e.g., ADM2025001
          const currentYear = new Date().getFullYear();

          // Get highest existing admission number for this year to avoid duplicates
          const { data: existingStudents } = await supabase
            .from("profiles")
            .select("admission_number")
            .eq("role", "student")
            .like("admission_number", `ADM${currentYear}%`)
            .order("admission_number", { ascending: false })
            .limit(1);

          let nextNumber = 1;
          if (existingStudents && existingStudents.length > 0) {
            const lastAdmission = existingStudents[0].admission_number;
            // Extract the sequential part (last 3 digits)
            const lastNumber = parseInt(lastAdmission.substring(7), 10);
            nextNumber = lastNumber + 1;
          }

          const sequentialNumber = String(nextNumber).padStart(3, "0");
          profileData.admission_number = `ADM${currentYear}${sequentialNumber}`;

          console.log(
            `[Registration] Generated admission number: ${profileData.admission_number}`,
          );
        }

        // For teachers, include phone and is_part_time
        if (registrationData.role === "teacher") {
          // Add phone (optional for teachers)
          if (registrationData.additional_info?.phone) {
            profileData.phone =
              registrationData.additional_info.phone;
          }

          // Add is_part_time (convert string "true"/"false" to boolean)
          if (
            registrationData.additional_info?.is_part_time !==
            undefined
          ) {
            profileData.is_part_time =
              registrationData.additional_info.is_part_time ===
                "true" ||
              registrationData.additional_info.is_part_time ===
                true;
          }
        }

        // Retry logic for duplicate admission numbers
        let insertSuccess = false;
        let retries = 0;
        const maxRetries = 3;
        let profileError;

        while (!insertSuccess && retries < maxRetries) {
          const { error } = await supabase
            .from("profiles")
            .insert(profileData);

          if (!error) {
            insertSuccess = true;
          } else if (error.code === "23505" && error.message.includes("admission_number")) {
            // Duplicate admission number - regenerate
            console.log(
              `[Registration] Duplicate admission number detected, retrying... (attempt ${retries + 1}/${maxRetries})`,
            );
            retries++;

            if (retries < maxRetries) {
              // Get the latest admission number again
              const { data: latestStudents } = await supabase
                .from("profiles")
                .select("admission_number")
                .eq("role", "student")
                .like("admission_number", `ADM${new Date().getFullYear()}%`)
                .order("admission_number", { ascending: false })
                .limit(1);

              let nextNumber = 1;
              if (latestStudents && latestStudents.length > 0) {
                const lastAdmission = latestStudents[0].admission_number;
                const lastNumber = parseInt(lastAdmission.substring(7), 10);
                nextNumber = lastNumber + 1;
              }

              const sequentialNumber = String(nextNumber).padStart(3, "0");
              profileData.admission_number = `ADM${new Date().getFullYear()}${sequentialNumber}`;
              console.log(
                `[Registration] New admission number: ${profileData.admission_number}`,
              );
            }
          } else {
            // Different error - break and handle below
            profileError = error;
            break;
          }
        }

        if (!insertSuccess) {
          console.error(
            "Error creating profile:",
            profileError,
          );
          // Clean up auth user if profile creation fails
          await supabase.auth.admin.deleteUser(
            authData.user.id,
          );
          return c.json(
            {
              success: false,
              error: `Failed to create user profile: ${profileError?.message || "Maximum retries exceeded"}`,
            },
            500,
          );
        }

        console.log(
          "User account created successfully:",
          email,
        );
      }

      // Update registration status
      const updatedRegistration = {
        ...registrationData,
        status: action === "approve" ? "approved" : "rejected",
        reviewed_at: new Date().toISOString(),
        reviewed_by: adminProfile.email,
      };

      await kv.set(
        `pending_registration:${email}`,
        updatedRegistration,
      );

      // Remove from pending list
      const pendingList =
        (await kv.get("pending_registrations_list")) || [];
      const updatedPendingList = pendingList.filter(
        (e) => e !== email,
      );
      await kv.set(
        "pending_registrations_list",
        updatedPendingList,
      );

      // Store in processed registrations for history
      const processedList =
        (await kv.get("processed_registrations_list")) || [];
      if (!processedList.includes(email)) {
        processedList.push(email);
        await kv.set(
          "processed_registrations_list",
          processedList,
        );
      }

      return c.json({
        success: true,
        message: `Registration ${action}d successfully`,
        action: action,
      });
    } catch (error) {
      console.error(
        "Error in approve-registration endpoint:",
        error,
      );
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Registration processing failed",
        },
        500,
      );
    }
  },
);

// Check registration status (for applicants)
app.post(
  "/make-server-1ddd013a/check-registration-status",
  async (c) => {
    try {
      const { email } = await c.req.json();

      if (!email) {
        return c.json(
          { success: false, error: "Email is required" },
          400,
        );
      }

      // Check pending registration
      const registration = await kv.get(
        `pending_registration:${email}`,
      );

      if (!registration) {
        // Check if user already exists in profiles (already approved and active)
        const { data: profile, error } = await supabase
          .from("profiles")
          .select("email, role")
          .eq("email", email)
          .maybeSingle();

        if (profile) {
          return c.json({
            success: true,
            status: "active",
            message:
              "Your account is active. You can login now.",
          });
        }

        return c.json(
          {
            success: false,
            error: "No registration found for this email",
          },
          404,
        );
      }

      // Return status without sensitive information
      const { password, ...safeData } = registration;
      return c.json({
        success: true,
        status: registration.status,
        submitted_at: registration.submitted_at,
        reviewed_at: registration.reviewed_at,
        message:
          registration.status === "pending"
            ? "Your registration is under review"
            : registration.status === "approved"
              ? "Your registration has been approved. You can now login."
              : "Your registration was not approved. Please contact administration.",
      });
    } catch (error) {
      console.error(
        "Error in check-registration-status endpoint:",
        error,
      );
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Status check failed",
        },
        500,
      );
    }
  },
);

