// Get all subjects
app.get("/make-server-1ddd013a/subjects", async (c) => {
  try {
    // Verify authentication
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    console.log(
      "[Subjects] Fetching subjects from database...",
    );

    // Get query parameters for filtering
    const url = new URL(c.req.url);
    const teacherId = url.searchParams.get("teacher_id");

    // Build query
    let query = supabase
      .from("subjects")
      .select("*")
      .order("created_at", { ascending: false });

    // Apply teacher filter if provided
    if (teacherId) {
      query = query.eq("main_teacher_id", teacherId);
      console.log(
        "[Subjects] Filtering subjects for teacher:",
        teacherId,
      );
    }

    const { data: subjects, error } = await query;

    if (error) {
      console.error(
        "[Subjects] Error fetching subjects from database:",
        error,
      );
      return c.json(
        {
          success: false,
          error: `Failed to fetch subjects: ${error.message}`,
        },
        500,
      );
    }

    console.log(
      "[Subjects] Fetched",
      subjects?.length || 0,
      "subjects",
    );

    return c.json({
      success: true,
      subjects: subjects || [],
      total_subjects: subjects?.length || 0,
    });
  } catch (error) {
    console.error("[Subjects] Error fetching subjects:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch subjects",
      },
      500,
    );
  }
});

