// ===== CLASS SUBJECTS =====

// Get class subjects for a specific class
app.get("/make-server-1ddd013a/class-subjects", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const classId = c.req.query("class_id");
    if (!classId) {
      return c.json(
        { success: false, error: "class_id required" },
        400,
      );
    }

    const { data, error } = await supabase
      .from("class_subjects")
      .select(
        `
        *,
        subject:subjects(id, name, code, level)
      `,
      )
      .eq("class_id", classId);

    if (error) {
      console.error("[Class Subjects] Error:", error);
      // If table doesn't exist, return empty array instead of error
      if (
        error.message?.includes("does not exist") ||
        error.code === "42P01"
      ) {
        console.warn(
          "[Class Subjects] Table not created yet. Run CREATE_SUBJECT_OFFERING_SYSTEM.sql",
        );
        return c.json({
          success: true,
          classSubjects: [],
          warning:
            "Subject offerings not configured. Please run database setup.",
        });
      }
      return c.json(
        { success: false, error: error.message },
        500,
      );
    }

    // Get current session from academic calendar
    const { data: currentSessionData } = await supabase
      .from("academic_calendar")
      .select("sessions(session_name)")
      .eq("is_current", true)
      .single();

    const currentSession = (currentSessionData as any)?.sessions
      ?.session_name;

    // Fetch student counts for each subject
    const classSubjectsWithCounts = await Promise.all(
      (data || []).map(async (cs) => {
        // Count students assigned to this subject
        // If current session exists, filter by it; otherwise count all active students
        let query = supabase
          .from("student_subjects")
          .select("*", { count: "exact", head: true })
          .eq("subject_id", cs.subject_id)
          .eq("class_id", classId)
          .eq("status", "active");

        // Only filter by session if a current session is configured
        if (currentSession) {
          query = query.eq("session", currentSession);
        }

        const { count } = await query;
        const studentCount = count || 0;

        return {
          ...cs,
          student_count: studentCount,
        };
      }),
    );

    return c.json({
      success: true,
      classSubjects: classSubjectsWithCounts,
    });
  } catch (error) {
    console.error("[Class Subjects] Error:", error);
    return c.json(
      { success: false, error: "Internal server error" },
      500,
    );
  }
});

