// Sync subject to class (upsert - creates if not exists, ignores if exists)
// Used when assigning teachers to subjects, to automatically sync to Subject Offerings
app.post("/make-server-1ddd013a/class-subjects/sync", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const { class_id, subject_id, is_compulsory } =
      await c.req.json();

    if (!class_id || !subject_id) {
      return c.json(
        {
          success: false,
          error: "class_id and subject_id required",
        },
        400,
      );
    }

    // Check if this combination already exists
    const { data: existing, error: checkError } = await supabase
      .from("class_subjects")
      .select("id")
      .eq("class_id", class_id)
      .eq("subject_id", subject_id)
      .maybeSingle();

    if (checkError) {
      console.error("[Class Subjects Sync] Check error:", checkError);
      return c.json(
        { success: false, error: checkError.message },
        500,
      );
    }

    if (existing) {
      // Already exists, no need to create
      console.log(`[Class Subjects Sync] Already exists: subject ${subject_id} in class ${class_id}`);
      return c.json({
        success: true,
        message: "Subject already exists for this class",
        classSubject: existing,
      });
    }

    // Create new entry
    const { data, error } = await supabase
      .from("class_subjects")
      .insert({
        class_id,
        subject_id,
        is_compulsory: is_compulsory ?? false,
      })
      .select()
      .single();

    if (error) {
      console.error("[Class Subjects Sync] Insert error:", error);
      return c.json(
        { success: false, error: error.message },
        500,
      );
    }

    console.log(`[Class Subjects Sync] ✅ Created: subject ${subject_id} in class ${class_id}`);
    return c.json({
      success: true,
      message: "Subject synced to class successfully",
      classSubject: data,
    });
  } catch (error) {
    console.error("[Class Subjects Sync] Error:", error);
    return c.json(
      { success: false, error: "Internal server error" },
      500,
    );
  }
});

