// Get student subjects (works for both students viewing own subjects and admins viewing any student's subjects)
app.get("/make-server-1ddd013a/student-subjects", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const studentId = c.req.query("student_id");
    const session = c.req.query("session");

    if (!studentId || !session) {
      return c.json(
        {
          success: false,
          error: "student_id and session required",
        },
        400,
      );
    }

    // 🔥 Check if student is graduated - graduated students cannot access student dashboard
    const { isGraduated, role } = await checkIfStudentGraduated(user.id);
    if (role === 'student' && isGraduated) {
      return c.json(
        {
          success: false,
          error: "Your account has been graduated. Please use the Alumni Portal to access your records.",
          isGraduated: true
        },
        403,
      );
    }

    // Check if the table exists
    const { data, error } = await supabase
      .from("student_subjects")
      .select(
        `
        *,
        subject:subjects(id, name, code, level)
      `,
      )
      .eq("student_id", studentId)
      .eq("session", session);

    if (error) {
      console.error("[Student Subjects] Error:", error);
      // If table doesn't exist, return empty array instead of error
      if (
        error.message?.includes("does not exist") ||
        error.code === "42P01"
      ) {
        console.warn(
          "[Student Subjects] Table not created yet. Run CREATE_SUBJECT_OFFERING_SYSTEM.sql",
        );
        return c.json({
          success: true,
          studentSubjects: [],
          warning:
            "Subject offerings not configured. Please run database setup.",
        });
      }
      return c.json(
        { success: false, error: error.message },
        500,
      );
    }

    return c.json({
      success: true,
      studentSubjects: data || [],
    });
  } catch (error) {
    console.error("[Student Subjects] Error:", error);
    return c.json(
      { success: false, error: "Internal server error" },
      500,
    );
  }
});

