// Bulk assign subjects to multiple students
app.post(
  "/make-server-1ddd013a/bulk-assign-subjects",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Verify user is IT Admin or Director
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        !profile ||
        !["it_admin", "director"].includes(profile.role)
      ) {
        return c.json(
          { success: false, error: "Insufficient permissions" },
          403,
        );
      }

      const { student_ids, subject_ids, class_id, session } =
        await c.req.json();

      if (
        !student_ids ||
        !subject_ids ||
        !class_id ||
        !session
      ) {
        return c.json(
          {
            success: false,
            error:
              "student_ids, subject_ids, class_id, and session required",
          },
          400,
        );
      }

      // Build array of assignments
      const assignments = [];
      for (const studentId of student_ids) {
        for (const subjectId of subject_ids) {
          assignments.push({
            student_id: studentId,
            subject_id: subjectId,
            class_id,
            session,
            status: "active",
          });
        }
      }

      const { data, error } = await supabase
        .from("student_subjects")
        .upsert(assignments, {
          onConflict: "student_id,subject_id,class_id,session",
          ignoreDuplicates: true,
        });

      if (error) {
        console.error("[Bulk Assign] Error:", error);
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      return c.json({
        success: true,
        count: assignments.length,
      });
    } catch (error) {
      console.error("[Bulk Assign] Error:", error);
      return c.json(
        { success: false, error: "Internal server error" },
        500,
      );
    }
  },
);

