// Add "General" department if it doesn't exist
app.post(
  "/make-server-1ddd013a/departments/ensure-general",
  async (c) => {
    try {
      // Verify authentication
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      console.log('Ensuring "General" department exists...');

      // Check if "General" department already exists
      const { data: existingDept, error: checkError } =
        await supabase
          .from("departments")
          .select("*")
          .eq("name", "General")
          .single();

      if (checkError && checkError.code !== "PGRST116") {
        // PGRST116 = no rows found
        console.error(
          "Error checking for General department:",
          checkError,
        );
        return c.json(
          {
            success: false,
            error: `Failed to check for General department: ${checkError.message}`,
          },
          500,
        );
      }

      if (existingDept) {
        console.log(
          "General department already exists:",
          existingDept,
        );
        return c.json({
          success: true,
          message: "General department already exists",
          department: existingDept,
        });
      }

      // Create "General" department
      const { data: newDept, error: insertError } =
        await supabase
          .from("departments")
          .insert({
            name: "General",
          })
          .select()
          .single();

      if (insertError) {
        console.error(
          "Error creating General department:",
          insertError,
        );
        return c.json(
          {
            success: false,
            error: `Failed to create General department: ${insertError.message}`,
          },
          500,
        );
      }

      console.log(
        "General department created successfully:",
        newDept,
      );

      return c.json({
        success: true,
        message: "General department created successfully",
        department: newDept,
      });
    } catch (error) {
      console.error("Error in ensure-general endpoint:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to ensure General department",
        },
        500,
      );
    }
  },
);

// Get teachers for dropdown selection AND TeachersManager with subject counts
app.get("/make-server-1ddd013a/teachers", async (c) => {
  try {
    // Verify authentication
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      console.error("[Teachers] No access token provided");
      return c.json(
        { success: false, error: "No access token provided" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await verifyUserAuth(accessToken);
    
    if (!user?.id) {
      console.error("[Teachers] Unauthorized - no user ID. Auth error:", authError?.message || "Session expired");
      return c.json(
        { success: false, error: authError?.message || "Unauthorized - please sign in again" },
        401,
      );
    }

    console.log(
      "[Teachers] Fetching teachers from profiles table...",
    );

    // Get teachers from profiles table
    const { data: teachers, error: teachersError } =
      await supabase
        .from("profiles")
        .select("id, first_name, middle_name, last_name, email")
        .eq("role", "teacher")
        .order("first_name");

    if (teachersError) {
      console.error(
        "[Teachers] Error fetching teachers from profiles:",
        teachersError,
      );
      return c.json(
        {
          success: false,
          error: `Failed to fetch teachers: ${teachersError.message}`,
        },
        500,
      );
    }

    console.log(
      "[Teachers] Found",
      teachers?.length || 0,
      "teachers",
    );

    // Get all subject assignments to calculate subject counts per teacher
    const { data: assignments, error: assignmentsError } =
      await supabase.from("subject_assignments").select(`
          teacher_id,
          subject_id,
          subjects (id, name)
        `);

    if (assignmentsError) {
      console.error(
        "[Teachers] Error fetching subject assignments:",
        assignmentsError,
      );
    }

    // Build teachers array with subject information from assignments
    const teachersWithSubjects = await Promise.all((teachers || []).map(
      async (teacher) => {
        // Get all assignments for this teacher
        const teacherAssignments = (assignments || []).filter(
          (assignment: any) =>
            assignment.teacher_id === teacher.id,
        );

        // Get unique subjects (teacher might teach same subject in multiple classes)
        const uniqueSubjectsMap = new Map();
        teacherAssignments.forEach((assignment: any) => {
          if (assignment.subjects && assignment.subject_id) {
            uniqueSubjectsMap.set(assignment.subject_id, {
              id: assignment.subjects.id,
              name: assignment.subjects.name,
            });
          }
        });

        const teacherSubjects = Array.from(
          uniqueSubjectsMap.values(),
        );

        // Fetch teacher profile photo from KV store (check multiple keys for backwards compatibility)
        let teacherProfile = await kv.get(`teacher_profile_${teacher.id}`) as any;
        if (!teacherProfile?.photo_url) {
          teacherProfile = await kv.get(`profile_${teacher.id}`) as any;
        }
        if (!teacherProfile?.photo_url) {
          teacherProfile = await kv.get(`student_profile_${teacher.id}`) as any;
        }

        return {
          id: teacher.id,
          first_name: teacher.first_name,
          middle_name: teacher.middle_name,
          last_name: teacher.last_name,
          email: teacher.email,
          photo_url: teacherProfile?.photo_url || '',
          subjects: teacherSubjects,
          subject_count: teacherSubjects.length,
        };
      },
    ));

    console.log(
      "[Teachers] Returning",
      teachersWithSubjects.length,
      "teachers with subject counts",
    );

    return c.json({
      success: true,
      teachers: teachersWithSubjects,
      total_teachers: teachersWithSubjects.length,
    });
  } catch (error) {
    console.error("[Teachers] Error fetching teachers:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch teachers",
      },
      500,
    );
  }
});

