// POST /classes - Create a new class
app.post("/make-server-1ddd013a/classes", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Check if user has permission
    const { data: profile } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .single();

    const authorizedRoles = [
      "principal",
      "director",
      "it_admin",
      "secretary",
    ];
    if (!profile || !authorizedRoles.includes(profile.role)) {
      return c.json(
        { success: false, error: "Insufficient permissions" },
        403,
      );
    }

    const body = await c.req.json();
    const { name, level, class_teacher_id, section_id } = body;

    if (!name || !level) {
      return c.json(
        {
          success: false,
          error: "Class name and level are required",
        },
        400,
      );
    }

    // If section_id is provided, fetch the section name and combine it with the class name
    let finalClassName = name.trim();
    if (section_id && section_id !== 'none') {
      const { data: section, error: sectionError } = await supabase
        .from("sections")
        .select("name")
        .eq("id", section_id)
        .single();

      if (sectionError) {
        console.error("[Classes] Error fetching section:", sectionError);
        return c.json(
          { success: false, error: "Invalid section selected" },
          400,
        );
      }

      // Combine class name with section name (e.g., "SS2 - Silver")
      finalClassName = `${name.trim()} - ${section.name}`;
    }

    const { data: newClass, error: insertError } =
      await supabase
        .from("classes")
        .insert({
          name: finalClassName,
          level: level.trim(),
          class_teacher_id: class_teacher_id || null,
          section_id: section_id && section_id !== 'none' ? section_id : null,
        })
        .select()
        .single();

    if (insertError) {
      console.error(
        "[Classes] Error creating class:",
        insertError,
      );
      return c.json(
        { success: false, error: insertError.message },
        500,
      );
    }

    return c.json({
      success: true,
      message: "Class created successfully",
      class: newClass,
    });
  } catch (error) {
    console.error("[Classes] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to create class",
      },
      500,
    );
  }
});

