// Get all academic sessions/years from calendar
app.get(
  "/make-server-1ddd013a/academic-sessions",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      console.log(
        "Fetching academic sessions from calendar...",
      );

      const { data: calendar, error } = await supabase
        .from("academic_calendar")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) {
        console.error(
          "Error fetching academic calendar:",
          error,
        );
        return c.json(
          {
            success: false,
            error: `Failed to fetch academic sessions: ${error.message}`,
          },
          500,
        );
      }

      console.log(
        "Academic calendar fetched:",
        calendar?.length || 0,
      );

      // Extract unique sessions (years)
      const uniqueSessions = calendar
        ? [
            ...new Set(calendar.map((item) => item.session)),
          ].map((session) => ({
            session,
            id: session, // Using session as ID for simplicity
          }))
        : [];

      return c.json({
        success: true,
        sessions: uniqueSessions,
      });
    } catch (error) {
      console.error(
        "Error in get academic sessions endpoint:",
        error,
      );
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch academic sessions",
        },
        500,
      );
    }
  },
);

