// Create a new section
app.post("/make-server-1ddd013a/sections", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Check if user is admin
    const { data: profile } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .single();

    if (
      !profile ||
      !["principal", "director", "secretary", "it_admin"].includes(
        profile.role,
      )
    ) {
      return c.json(
        {
          success: false,
          error: "Unauthorized - Admin access required",
        },
        403,
      );
    }

    const body = await c.req.json();
    const { name, description } = body;

    if (!name?.trim()) {
      return c.json(
        { success: false, error: "Section name is required" },
        400,
      );
    }

    console.log("[Sections] Creating new section:", name);

    const { data: section, error } = await supabase
      .from("sections")
      .insert({
        name: name.trim(),
        description: description?.trim() || null,
      })
      .select()
      .single();

    if (error) {
      console.error("[Sections] Database error:", error);
      if (error.code === "23505") {
        return c.json(
          {
            success: false,
            error: "A section with this name already exists",
          },
          400,
        );
      }
      return c.json(
        {
          success: false,
          error: `Failed to create section: ${error.message}`,
        },
        500,
      );
    }

    console.log(
      "[Sections] Section created successfully:",
      section.id,
    );

    return c.json({ success: true, section });
  } catch (error) {
    console.error("[Sections] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to create section",
      },
      500,
    );
  }
});

