// Delete a section
app.delete("/make-server-1ddd013a/sections/:id", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Check if user is admin
    const { data: profile } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .single();

    if (
      !profile ||
      !["principal", "director", "secretary", "it_admin"].includes(
        profile.role,
      )
    ) {
      return c.json(
        {
          success: false,
          error: "Unauthorized - Admin access required",
        },
        403,
      );
    }

    const sectionId = c.req.param("id");

    console.log("[Sections] Deleting section:", sectionId);

    // Check if there are classes assigned to this section
    const { data: classesInSection, error: classCheckError } = await supabase
      .from("classes")
      .select("id, name")
      .eq("section_id", sectionId);

    if (classCheckError) {
      console.error("[Sections] Error checking classes:", classCheckError);
      return c.json(
        {
          success: false,
          error: "Failed to check for classes in section",
        },
        500,
      );
    }

    if (classesInSection && classesInSection.length > 0) {
      console.log(`[Sections] Cannot delete - ${classesInSection.length} class(es) still in section`);
      return c.json(
        {
          success: false,
          error: `Cannot delete section: ${classesInSection.length} class(es) are still assigned to this section. Please reassign or remove classes first.`,
          classCount: classesInSection.length,
        },
        400,
      );
    }

    // Proceed with deletion
    const { error } = await supabase
      .from("sections")
      .delete()
      .eq("id", sectionId);

    if (error) {
      console.error("[Sections] Database error:", error);
      
      // Check for foreign key constraint errors
      if (error.code === "23503") {
        return c.json(
          {
            success: false,
            error: "Cannot delete section: There are still records (classes or other data) associated with this section. Please remove all associations first.",
          },
          400,
        );
      }
      
      return c.json(
        {
          success: false,
          error: `Failed to delete section: ${error.message}`,
        },
        500,
      );
    }

    console.log("[Sections] Section deleted successfully");

    return c.json({
      success: true,
      message: "Section deleted successfully",
    });
  } catch (error) {
    console.error("[Sections] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to delete section",
      },
      500,
    );
  }
});

