// GET /users - Fetch users by role
app.get("/make-server-1ddd013a/users", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const url = new URL(c.req.url);
    const role = url.searchParams.get("role");

    console.log("[Users] Fetching users with role:", role);

    if (!role) {
      return c.json(
        { success: false, error: "Role parameter is required" },
        400,
      );
    }

    // 🔥 FIX: Filter out graduated students
    let query = supabase
      .from("profiles")
      .select(
        "id, first_name, middle_name, last_name, email, phone, role, class_id, created_at",
      )
      .eq("role", role);
    
    // For students, exclude graduated ones
    if (role === "student") {
      query = query.or("is_graduated.is.null,is_graduated.eq.false");
    }
    
    query = query.order("first_name", { ascending: true });
    
    const { data: users, error } = await query;

    if (error) {
      console.error("[Users] Error fetching users:", error);
      return c.json(
        {
          success: false,
          error: `Failed to fetch users: ${error.message}`,
        },
        500,
      );
    }

    console.log(`[Users] Found ${users?.length || 0} ${role}s`);

    return c.json({
      success: true,
      users: users || [],
      [role === "teacher"
        ? "teachers"
        : role === "student"
          ? "students"
          : "users"]: users || [],
    });
  } catch (error) {
    console.error("[Users] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch users",
      },
      500,
    );
  }
});

