// Delete a class
app.delete("/make-server-1ddd013a/classes/:id", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Check if user is admin
    const { data: profile } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .single();

    if (
      !profile ||
      !["principal", "director", "secretary", "it_admin"].includes(
        profile.role,
      )
    ) {
      return c.json(
        {
          success: false,
          error: "Unauthorized - Admin access required",
        },
        403,
      );
    }

    const classId = c.req.param("id");

    console.log("[Classes] Deleting class:", classId);

    // Check if there are students assigned to this class
    const { data: studentsInClass, error: studentCheckError } = await supabase
      .from("profiles")
      .select("id, first_name, last_name")
      .eq("class_id", classId)
      .eq("role", "student");

    if (studentCheckError) {
      console.error("[Classes] Error checking students:", studentCheckError);
      return c.json(
        {
          success: false,
          error: "Failed to check for students in class",
        },
        500,
      );
    }

    if (studentsInClass && studentsInClass.length > 0) {
      console.log(`[Classes] Auto-unassigning ${studentsInClass.length} student(s) from class before deletion`);
      
      // Automatically unassign students from this class
      const { error: unassignError } = await supabase
        .from("profiles")
        .update({ class_id: null })
        .eq("class_id", classId)
        .eq("role", "student");
      
      if (unassignError) {
        console.error("[Classes] Error unassigning students:", unassignError);
        return c.json(
          {
            success: false,
            error: `Failed to unassign students from class: ${unassignError.message}`,
          },
          500,
        );
      }
      
      console.log(`[Classes] Successfully unassigned ${studentsInClass.length} student(s)`);
    }

    // Check if there are teachers assigned to this class as class teacher
    const { data: teachersInClass, error: teacherCheckError } = await supabase
      .from("classes")
      .select("class_teacher_id")
      .eq("id", classId)
      .single();

    if (!teacherCheckError && teachersInClass?.class_teacher_id) {
      // Just log it, but allow deletion (class teacher can be reassigned)
      console.log("[Classes] Class has a class teacher assigned, but proceeding with deletion");
    }

    // Check if there are promotion records referencing this class
    const { data: promotionsFromClass, error: promotionFromError } = await supabase
      .from("promotions")
      .select("id")
      .eq("from_class_id", classId);

    const { data: promotionsToClass, error: promotionToError } = await supabase
      .from("promotions")
      .select("id")
      .eq("to_class_id", classId);

    const totalPromotions = (promotionsFromClass?.length || 0) + (promotionsToClass?.length || 0);

    if (totalPromotions > 0) {
      console.log(`[Classes] Cannot delete - ${totalPromotions} promotion record(s) reference this class`);
      return c.json(
        {
          success: false,
          error: `Cannot delete class: ${totalPromotions} promotion record(s) reference this class. Please delete the promotion records first.`,
          promotionCount: totalPromotions,
        },
        400,
      );
    }

    // Proceed with deletion
    const { error } = await supabase
      .from("classes")
      .delete()
      .eq("id", classId);

    if (error) {
      console.error("[Classes] Database error:", error);
      
      // Check for foreign key constraint errors
      if (error.code === "23503") {
        return c.json(
          {
            success: false,
            error: "Cannot delete class: There are still records (students, marks, or attendance) associated with this class. Please remove all associations first.",
          },
          400,
        );
      }
      
      return c.json(
        {
          success: false,
          error: `Failed to delete class: ${error.message}`,
        },
        500,
      );
    }

    console.log("[Classes] Class deleted successfully");

    return c.json({
      success: true,
      message: "Class deleted successfully",
    });
  } catch (error) {
    console.error("[Classes] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to delete class",
      },
      500,
    );
  }
});

