// Get teacher's assigned subjects and classes
app.get(
  "/make-server-1ddd013a/teacher-assignments",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      console.log(
        "Fetching teacher assignments for user:",
        user.id,
      );

      // Get teacher's profile to check role
      const { data: profile, error: profileError } =
        await supabase
          .from("profiles")
          .select("role")
          .eq("id", user.id)
          .maybeSingle();

      if (profileError || !profile) {
        return c.json(
          { success: false, error: "Profile not found" },
          404,
        );
      }

      // If admin/principal/IT admin/director, return all subjects and classes
      if (
        ["principal", "director", "admin", "it_admin"].includes(
          profile.role,
        )
      ) {
        const { data: allSubjects } = await supabase
          .from("subjects")
          .select("*")
          .order("name");

        const { data: allClasses } = await supabase
          .from("classes")
          .select("*, sections(name)")
          .order("name");

        // Add display_name field to classes
        const classesWithDisplayName =
          allClasses?.map((classItem: any) => ({
            ...classItem,
            // Note: classItem.name already includes the section
            display_name: classItem.name,
            section_name: classItem.sections?.name || null,
          })) || [];

        // For admins, fetch actual class_subjects configuration
        const { data: classSubjects } = await supabase
          .from("class_subjects")
          .select("subject_id, class_id");

        return c.json({
          success: true,
          subjects: allSubjects || [],
          classes: classesWithDisplayName,
          assignments: classSubjects || [],
          isAdmin: true,
        });
      }

      // For teachers, get their assignments from subject_assignments table
      console.log(
        "[Teacher Assignments] Fetching assignments from subject_assignments for teacher:",
        user.id,
      );

      const { data: assignments, error: assignmentsError } =
        await supabase
          .from("subject_assignments")
          .select(
            `
          subject_id,
          class_id,
          subjects (id, name, code),
          classes (id, name, level, sections(name))
        `,
          )
          .eq("teacher_id", user.id);

      if (assignmentsError) {
        console.error(
          "[Teacher Assignments] Error fetching assignments:",
          assignmentsError,
        );
        return c.json(
          { success: false, error: assignmentsError.message },
          500,
        );
      }

      console.log(
        "[Teacher Assignments] Found assignments:",
        assignments?.length || 0,
      );

      // Extract unique subjects
      const subjectsMap = new Map();
      const classesMap = new Map();
      const assignmentPairs: Array<{
        subject_id: string;
        class_id: string;
      }> = [];

      (assignments || []).forEach((assignment: any) => {
        // Add subject
        if (
          assignment.subjects &&
          !subjectsMap.has(assignment.subject_id)
        ) {
          subjectsMap.set(assignment.subject_id, {
            id: assignment.subjects.id,
            name: assignment.subjects.name,
            code: assignment.subjects.code,
          });
        }

        // Add class with display_name
        if (
          assignment.classes &&
          !classesMap.has(assignment.class_id)
        ) {
          const classData = assignment.classes;
          // Note: classData.name already includes the section
          const display_name = classData.name;

          classesMap.set(assignment.class_id, {
            id: classData.id,
            name: classData.name,
            level: classData.level,
            display_name: display_name,
            section_name: classData.sections?.name || null,
          });
        }

        // Store the subject-class pair for filtering
        if (assignment.subject_id && assignment.class_id) {
          assignmentPairs.push({
            subject_id: assignment.subject_id,
            class_id: assignment.class_id,
          });
        }
      });

      const uniqueSubjects = Array.from(
        subjectsMap.values(),
      ).sort((a, b) => a.name.localeCompare(b.name));

      const uniqueClasses = Array.from(
        classesMap.values(),
      ).sort((a, b) => a.name.localeCompare(b.name));

      console.log(
        "[Teacher Assignments] Returning - Subjects:",
        uniqueSubjects.length,
        "Classes:",
        uniqueClasses.length,
        "Assignment Pairs:",
        assignmentPairs.length,
      );

      return c.json({
        success: true,
        subjects: uniqueSubjects,
        classes: uniqueClasses,
        assignments: assignmentPairs,
        isAdmin: false,
      });
    } catch (error) {
      console.error(
        "Error in teacher assignments endpoint:",
        error,
      );
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch teacher assignments",
        },
        500,
      );
    }
  },
);

