// Get uploads (with filtering)
app.get("/make-server-1ddd013a/uploads", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Get query parameters for filtering
    const subjectId = c.req.query("subject_id");
    const type = c.req.query("type");
    const term = c.req.query("term");
    const session = c.req.query("session");
    const teacherId = c.req.query("teacher_id");

    console.log("Fetching uploads with filters:", {
      subjectId,
      type,
      term,
      session,
      teacherId,
    });

    // Build query
    let query = supabase.from("uploads").select(`
      *,
      subject:subjects(id, name)
    `);

    if (subjectId) query = query.eq("subject_id", subjectId);
    if (type) query = query.eq("type", type);
    if (term) query = query.eq("term", term);
    if (session) query = query.eq("session", session);
    if (teacherId) query = query.eq("teacher_id", teacherId);

    const { data: uploads, error } = await query.order(
      "created_at",
      { ascending: false },
    );

    if (error) {
      console.error("Error fetching uploads:", error);
      return c.json(
        {
          success: false,
          error: `Failed to fetch uploads: ${error.message}`,
        },
        500,
      );
    }

    console.log("Uploads fetched:", uploads?.length || 0);

    // Generate signed URLs for files
    const bucketName = "make-1ddd013a-uploads";
    const uploadsWithUrls = await Promise.all(
      (uploads || []).map(async (upload) => {
        if (upload.file_url) {
          const path = upload.file_url.replace(
            `${bucketName}/`,
            "",
          );
          const { data } = await supabase.storage
            .from(bucketName)
            .createSignedUrl(path, 3600);
          if (data)
            return { ...upload, signed_url: data.signedUrl };
        }
        return upload;
      }),
    );

    return c.json({
      success: true,
      uploads: uploadsWithUrls,
    });
  } catch (error) {
    console.error("Error in get uploads endpoint:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch uploads",
      },
      500,
    );
  }
});

// Upload files
app.post("/make-server-1ddd013a/uploads", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Create bucket if it doesn't exist
    const bucketName = "make-1ddd013a-uploads";
    const { data: buckets } =
      await supabase.storage.listBuckets();
    const bucketExists = buckets?.some(
      (bucket) => bucket.name === bucketName,
    );

    if (!bucketExists) {
      console.log("Creating uploads bucket...");
      const { error: bucketError } =
        await supabase.storage.createBucket(bucketName, {
          public: false,
          fileSizeLimit: 52428800, // 50MB
        });
      if (bucketError) {
        console.error("Error creating bucket:", bucketError);
      } else {
        console.log("Uploads bucket created successfully");
      }
    }

    const body = await c.req.json();
    const {
      title, // ✅ CRITICAL: Extract title from request
      description, // ✅ CRITICAL: Extract description from request
      subject_id,
      class_id, // NEW: Class ID for folder structure
      type,
      week,
      term,
      session,
      files, // Array of { name, data (base64), type, size }
      on_behalf_of_teacher_id, // For admin uploads on behalf of teachers
      uploaded_by_admin, // Flag to indicate admin upload
    } = body;

    console.log("Processing upload:", {
      title: title || "(no title)",
      description: description ? "yes" : "no",
      subject_id,
      class_id,
      type,
      filesCount: files?.length,
      uploaded_by_admin,
      on_behalf_of_teacher_id,
    });

    if (
      !subject_id ||
      !class_id ||
      !type ||
      !term ||
      !session ||
      !files?.length
    ) {
      return c.json(
        {
          success: false,
          error:
            "Missing required fields (subject, class, type, term, session, files)",
        },
        400,
      );
    }

    const validTypes = [
      "enote",
      "exam_question",
      "assignment",
      "resource",
      "other_resources",
      "e-notes",
      "exam-questions",
      "other-resources",
    ];
    if (!validTypes.includes(type)) {
      return c.json(
        { success: false, error: "Invalid type" },
        400,
      );
    }

    // Normalize type (convert frontend formats to database formats)
    const normalizedType =
      type === "e-notes"
        ? "enote"
        : type === "exam-questions"
          ? "exam_question"
          : type === "other-resources"
            ? "other_resources"
            : type === "resource"
              ? "other_resources" // Map old "resource" to "other_resources"
              : type;

    // Week is required for e-notes and assignments only
    if (
      (normalizedType === "enote" ||
        normalizedType === "assignment") &&
      !week
    ) {
      return c.json(
        {
          success: false,
          error: `Week required for ${normalizedType === "enote" ? "e-notes" : "assignments"}`,
        },
        400,
      );
    }

    // Upload first file to storage
    const file = files[0]; // Use first file only
    const timestamp = Date.now();
    const randomStr = Math.random().toString(36).substring(7);
    const filePath = `${user.id}/${timestamp}-${randomStr}-${file.name}`;

    // Convert base64 to Uint8Array
    const base64Data = file.data.split(",")[1] || file.data;
    const binaryString = atob(base64Data);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    const { error: uploadError } = await supabase.storage
      .from(bucketName)
      .upload(filePath, bytes, {
        contentType: file.type,
        upsert: false,
      });

    if (uploadError) {
      console.error("Error uploading file:", uploadError);
      return c.json(
        {
          success: false,
          error: `Failed to upload file ${file.name}: ${uploadError.message}`,
        },
        500,
      );
    }

    // Determine the actual teacher ID for the upload
    // If admin is uploading on behalf of a teacher, use that teacher's ID
    // Otherwise use the logged-in user's ID
    const actualTeacherId =
      uploaded_by_admin && on_behalf_of_teacher_id
        ? on_behalf_of_teacher_id
        : user.id;

    // Save upload metadata to database
    const { data: uploadRecord, error: dbError } =
      await supabase
        .from("uploads")
        .insert({
          title: title || null, // ✅ CRITICAL: Save title to database
          description: description || null, // ✅ CRITICAL: Save description to database
          file_name: file.name, // ✅ Save original filename
          file_type: file.type, // ✅ Save file type
          file_size: file.size, // ✅ Save file size
          teacher_id: actualTeacherId,
          subject_id,
          class_id, // NEW: Store class_id for folder structure
          type: normalizedType,
          week:
            normalizedType === "enote" ||
            normalizedType === "assignment"
              ? week
              : null,
          term,
          session,
          file_url: `${bucketName}/${filePath}`,
          version: 1,
          uploaded_by_admin: uploaded_by_admin || false,
          admin_id: uploaded_by_admin ? user.id : null, // Track which admin uploaded
        })
        .select()
        .single();

    if (dbError) {
      console.error(
        "[Supabase] Error saving upload metadata:",
        dbError,
      );
      // Clean up uploaded file
      await supabase.storage
        .from(bucketName)
        .remove([filePath]);
      return c.json(
        {
          success: false,
          error: `Failed to save upload metadata: ${dbError.message}`,
        },
        500,
      );
    }

    console.log(
      "Upload completed successfully:",
      uploadRecord.id,
    );

    return c.json({
      success: true,
      upload: uploadRecord,
      message: "Files uploaded successfully",
    });
  } catch (error) {
    console.error("Error in upload endpoint:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to upload files",
      },
      500,
    );
  }
});

// Delete upload
app.delete("/make-server-1ddd013a/uploads/:id", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const uploadId = c.req.param("id");

    console.log("Deleting upload:", uploadId);

    // Get upload to access file paths
    const { data: upload, error: fetchError } = await supabase
      .from("uploads")
      .select("*")
      .eq("id", uploadId)
      .eq("teacher_id", user.id) // Only allow teachers to delete their own uploads
      .maybeSingle();

    if (fetchError) {
      console.error(
        "Error fetching upload for deletion:",
        fetchError,
      );
      return c.json(
        {
          success: false,
          error: "Database error",
        },
        500,
      );
    }

    if (!upload) {
      console.error(
        "Upload not found or access denied:",
        uploadId,
      );
      return c.json(
        {
          success: false,
          error: "Upload not found or access denied",
        },
        404,
      );
    }

    // Delete file from storage
    if (upload.file_url) {
      const path = upload.file_url.replace(
        "make-1ddd013a-uploads/",
        "",
      );
      const { error: storageError } = await supabase.storage
        .from("make-1ddd013a-uploads")
        .remove([path]);

      if (storageError) {
        console.error(
          "Error deleting file from storage:",
          storageError,
        );
      }
    }

    // Delete upload record from database
    const { error: deleteError } = await supabase
      .from("uploads")
      .delete()
      .eq("id", uploadId)
      .eq("teacher_id", user.id);

    if (deleteError) {
      console.error(
        "Error deleting upload record:",
        deleteError,
      );
      return c.json(
        {
          success: false,
          error: `Failed to delete upload: ${deleteError.message}`,
        },
        500,
      );
    }

    console.log("Upload deleted successfully");

    return c.json({
      success: true,
      message: "Upload deleted successfully",
    });
  } catch (error) {
    console.error("Error deleting upload:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to delete upload",
      },
      500,
    );
  }
});

