// Get marks entries grouped by exam, subject, and class
app.get("/make-server-1ddd013a/marks", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // ✅ FIX: Use verifyUserAuth instead of supabase.auth.getUser(accessToken)
    const {
      data: { user },
      error: authError,
    } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      console.error("[Marks GET] Auth error:", authError?.message || "User not found");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // 🔥 Get session and term from query parameters
    const session = c.req.query("session");
    const term = c.req.query("term");

    console.log("[Supabase] Fetching marks entries...", { session, term });

    // Get all marks from the marks table with subject and exam details
    // Note: We'll manually fetch user details from profiles table using submitted_by/approved_by UUIDs
    let marksQuery = supabase
      .from("marks")
      .select(
        `
        *,
        subjects:subject_id (name),
        exams:exam_id (name)
      `,
      );
    
    // 🔥 Filter by session and term if provided
    if (session) {
      marksQuery = marksQuery.eq("session", session);
    }
    if (term) {
      marksQuery = marksQuery.eq("term", term);
    }
    
    marksQuery = marksQuery.order("created_at", { ascending: false });

    const { data: marks, error } = await marksQuery;

    if (error) {
      console.error("[Supabase] Error fetching marks:", error);
      return c.json(
        {
          success: false,
          error: `Failed to fetch marks: ${error.message}`,
        },
        500,
      );
    }

    console.log(
      "[Supabase] Fetched marks count:",
      marks?.length || 0,
    );
    if (marks && marks.length > 0) {
      console.log(
        "[Supabase] First mark sample:",
        JSON.stringify(marks[0], null, 2),
      );
    }

    // Group marks by exam_id and subject_id and fetch metadata
    const groupedMarksPromises =
      marks?.reduce((acc: any[], mark) => {
        const key = `${mark.exam_id}_${mark.subject_id}`;
        const existing = acc.find((g) => g.key === key);

        if (!existing) {
          acc.push({ key, mark });
        }
        return acc;
      }, []) || [];

    const groupedMarks = await Promise.all(
      groupedMarksPromises.map(async ({ key, mark }) => {
        // Manually fetch the submitted_by user from profiles table
        let submittedByUser = null;
        if (mark.submitted_by) {
          const { data: userData, error: userError } =
            await supabase
              .from("profiles")
              .select(
                "id, first_name, last_name, role, class_id",
              )
              .eq("id", mark.submitted_by)
              .single();

          if (userError) {
            console.error(
              `[Supabase] Error fetching submitted_by user ${mark.submitted_by}:`,
              userError,
            );
          } else {
            submittedByUser = userData;
          }
        }

        // Manually fetch approved_by user if it exists
        let approvedByUser = null;
        if (mark.approved_by) {
          const { data: userData, error: userError } =
            await supabase
              .from("profiles")
              .select("id, first_name, last_name, role")
              .eq("id", mark.approved_by)
              .single();

          if (userError) {
            console.error(
              `[Supabase] Error fetching approved_by user ${mark.approved_by}:`,
              userError,
            );
          } else {
            approvedByUser = userData;
          }
        }

        // Get session, term, and class info from exam
        let session = "";
        let term = "";
        if (mark.exam_id) {
          const { data: examInfo } = await supabase
            .from("exams")
            .select("session, term")
            .eq("id", mark.exam_id)
            .single();
          if (examInfo) {
            session = examInfo.session || "";
            term = examInfo.term || "";
          }
        }

        // Count students and calculate average for this exam/subject combination
        const { data: allMarksForGroup } = await supabase
          .from("marks")
          .select("student_id, total")
          .eq("exam_id", mark.exam_id)
          .eq("subject_id", mark.subject_id);

        const uniqueStudents = new Set(
          allMarksForGroup?.map((m) => m.student_id) || [],
        );
        const studentCount = uniqueStudents.size;

        const validTotals =
          allMarksForGroup
            ?.filter((m) => m.total !== null)
            .map((m) => m.total) || [];
        const averageMark =
          validTotals.length > 0
            ? Math.round(
                validTotals.reduce((sum, t) => sum + t, 0) /
                  validTotals.length,
              )
            : 0;

        // Get class info directly from marks table (marks have class_id)
        let classInfo = {
          id: "",
          name: "Unknown Class",
          display_name: "Unknown Class",
        };

        // ✅ FIX: Use class_id directly from marks table instead of looking up student profile
        if (mark.class_id) {
          const { data: classData } = await supabase
            .from("classes")
            .select("id, name, sections(name)")
            .eq("id", mark.class_id)
            .single();

          if (classData) {
            // Note: classData.name already includes the section
            const display_name = classData.name;
            classInfo = {
              id: classData.id,
              name: display_name,
              display_name: display_name,
            };
          }
        } else if (
          allMarksForGroup &&
          allMarksForGroup.length > 0
        ) {
          // Fallback: Try to get class from student profile if class_id not in marks
          const firstStudentId = allMarksForGroup[0].student_id;
          const { data: studentProfile } = await supabase
            .from("profiles")
            .select("class_id")
            .eq("id", firstStudentId)
            .single();

          if (studentProfile?.class_id) {
            const { data: classData } = await supabase
              .from("classes")
              .select("id, name, sections(name)")
              .eq("id", studentProfile.class_id)
              .single();
            if (classData) {
              // Note: classData.name already includes the section
              const display_name = classData.name;
              classInfo = {
                id: classData.id,
                name: display_name,
                display_name: display_name,
              };
            }
          }
        }

        return {
          id: key,
          exam_id: mark.exam_id,
          exam_name: mark.exams?.name || "Unknown Exam",
          subject_id: mark.subject_id,
          subject_name:
            mark.subjects?.name || "Unknown Subject",
          status: mark.status,
          created_at: mark.created_at,
          updated_at: mark.updated_at,
          submitted_by: mark.submitted_by,
          submitted_by_name: submittedByUser
            ? `${submittedByUser.first_name} ${submittedByUser.last_name}`
            : "Unknown",
          submitted_by_role: submittedByUser?.role || "unknown",
          action_by: submittedByUser
            ? `${submittedByUser.first_name} ${submittedByUser.last_name}`
            : "Unknown",
          action_by_role: submittedByUser?.role || "unknown",
          approved_by: mark.approved_by,
          approved_by_name: approvedByUser
            ? `${approvedByUser.first_name} ${approvedByUser.last_name}`
            : null,
          approved_by_role: approvedByUser?.role || null,
          approved_at: mark.approved_at,
          rejection_comment: mark.rejection_comment,
          is_update: false,
          // Additional info for approval panel and progress tracking
          session,
          term,
          class_id: classInfo.id,
          class_name: classInfo.name,
          student_count: studentCount,
          average_mark: averageMark,
        };
      }),
    );

    console.log(
      `[Supabase] Found ${groupedMarks.length} grouped marks entries`,
    );
    if (groupedMarks.length > 0) {
      console.log("[Supabase] Sample grouped mark:", {
        id: groupedMarks[0].id,
        subject: groupedMarks[0].subject_name,
        submitted_by_name: groupedMarks[0].submitted_by_name,
        action_by: groupedMarks[0].action_by,
        status: groupedMarks[0].status,
      });
    }

    return c.json({
      success: true,
      marks: groupedMarks,
    });
  } catch (error) {
    console.error("[Supabase] Error in marks endpoint:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch marks",
      },
      500,
    );
  }
});

