// Create or update marks entry
app.post("/make-server-1ddd013a/marks", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const body = await c.req.json();
    const {
      exam_id,
      subject_id,
      class_id,
      students_marks,
      status,
      session,
      term,
    } = body;

    console.log(
      "[Supabase] Saving marks for exam:",
      exam_id,
      "subject:",
      subject_id,
      "class:",
      class_id,
    );
    console.log(
      "[Supabase] 🔥 CRITICAL: session value received:",
      session,
      "Type:",
      typeof session,
    );
    console.log(
      "[Supabase] 🔥 CRITICAL: term value received:",
      term,
      "Type:",
      typeof term,
    );

    // Validate required fields
    if (!exam_id) {
      return c.json(
        {
          success: false,
          error:
            "Missing required field: exam_id. Please select an exam.",
        },
        400,
      );
    }

    if (!class_id) {
      return c.json(
        {
          success: false,
          error:
            "Missing required field: class_id. This is required for historical context.",
        },
        400,
      );
    }

    if (
      !subject_id ||
      !students_marks ||
      !students_marks.students
    ) {
      return c.json(
        {
          success: false,
          error:
            "Missing required fields: subject_id, students_marks",
        },
        400,
      );
    }

    // Verify the exam exists
    const { data: exam, error: examError } = await supabase
      .from("exams")
      .select("id, name")
      .eq("id", exam_id)
      .single();

    if (examError || !exam) {
      console.error("[Supabase] Exam not found:", examError);
      return c.json(
        {
          success: false,
          error:
            "Selected exam not found. Please select a valid exam.",
        },
        400,
      );
    }

    console.log("[Supabase] Using exam:", exam.name);
    console.log(
      "[Supabase] Received marks for",
      students_marks.students.length,
      "students",
    );

    // Log first student's data to see what we received
    if (students_marks.students.length > 0) {
      console.log(
        "[Supabase] Sample student data received:",
        JSON.stringify(students_marks.students[0], null, 2),
      );
    }

    // ✅ SUBJECT OFFERING VALIDATION: Check if students offer this subject
    // This ensures marks are only entered for students who actually take the subject
    console.log(
      "[Marks Save] Validating subject offerings for students...",
    );

    const submittedStudentIds = students_marks.students.map(
      (s) => s.studentId,
    );

    // Get current session from kv_store
    const currentSessionData = await kv.get("active_session");
    const currentSession = currentSessionData || "2024/2025"; // fallback

    // Query student_subjects to find which students offer this subject
    const { data: studentSubjects, error: subjectCheckError } =
      await supabase
        .from("student_subjects")
        .select("student_id")
        .eq("subject_id", subject_id)
        .eq("class_id", class_id)
        .eq("session", currentSession)
        .eq("status", "active")
        .in("student_id", submittedStudentIds);

    if (subjectCheckError) {
      console.warn(
        "[Marks Save] Could not validate subject offerings:",
        subjectCheckError,
      );
      // Continue anyway - this is a soft validation
    } else if (studentSubjects) {
      const offeringStudentIds = new Set(
        studentSubjects.map((ss) => ss.student_id),
      );
      const invalidStudents = students_marks.students.filter(
        (s) => !offeringStudentIds.has(s.studentId),
      );

      if (invalidStudents.length > 0) {
        console.warn(
          `[Marks Save] WARNING: ${invalidStudents.length} students don't offer this subject:`,
          invalidStudents.map((s) => s.studentName),
        );
        // Log warning but allow marks entry - IT Admin may not have configured offerings yet
        // In production, you might want to block this:
        // return c.json({
        //   success: false,
        //   error: `Some students don't offer this subject. Please configure subject offerings first.`
        // }, 400);
      } else {
        console.log(
          "[Marks Save] ✅ All students offer this subject",
        );
      }
    }

    // Process each student's marks
    const marksToInsert = [];
    for (const student of students_marks.students) {
      // ✅ MIDTERM ROW: Save to midterm_ca1, midterm_ca2, midterm_exam columns
      if (
        student.midterm.ca1 !== null ||
        student.midterm.ca2 !== null ||
        student.midterm.exam !== null
      ) {
        const midterm_ca1 =
          student.midterm.ca1 !== null
            ? Math.round(
                Math.min(Math.max(0, student.midterm.ca1), 10),
              )
            : null;
        const midterm_ca2 =
          student.midterm.ca2 !== null
            ? Math.round(
                Math.min(Math.max(0, student.midterm.ca2), 10),
              )
            : null;
        const midterm_exam =
          student.midterm.exam !== null
            ? Math.round(
                Math.min(Math.max(0, student.midterm.exam), 20),
              )
            : null;

        marksToInsert.push({
          student_id: student.studentId,
          exam_id,
          subject_id,
          class_id, // ✅ CRITICAL: Preserves historical class context
          session, // ✅ Academic session for filtering
          term, // ✅ Academic term for filtering
          type: "midterm",
          midterm_ca1, // ✅ Use midterm_ca1 column
          midterm_ca2, // ✅ Use midterm_ca2 column
          midterm_exam, // ✅ Use midterm_exam column
          status: status || "draft",
          submitted_by: user.id,
        });
      }

      // ✅ TERMINAL ROW: Save to terminal_ca1, terminal_ca2, terminal_exam columns
      if (
        student.terminal.ca1 !== null ||
        student.terminal.ca2 !== null ||
        student.terminal.exam !== null
      ) {
        // Terminal CA1 can be decimal (e.g., 17.5), so DON'T round it
        const terminal_ca1 =
          student.terminal.ca1 !== null
            ? Math.min(Math.max(0, student.terminal.ca1), 20) // Clamp but don't round
            : null;
        const terminal_ca2 =
          student.terminal.ca2 !== null
            ? Math.round(
                Math.min(Math.max(0, student.terminal.ca2), 20),
              )
            : null;
        const terminal_exam =
          student.terminal.exam !== null
            ? Math.round(
                Math.min(
                  Math.max(0, student.terminal.exam),
                  60,
                ),
              )
            : null;

        console.log(
          `[Supabase] Terminal CA1 for ${student.studentName}: ${student.terminal.ca1} → ${terminal_ca1} (preserving decimal)`,
        );

        marksToInsert.push({
          student_id: student.studentId,
          exam_id,
          subject_id,
          class_id, // ✅ CRITICAL: Preserves historical class context
          session, // ✅ Academic session for filtering
          term, // ✅ Academic term for filtering
          type: "terminal",
          terminal_ca1, // ✅ Use terminal_ca1 column (DECIMAL)
          terminal_ca2, // ✅ Use terminal_ca2 column
          terminal_exam, // ✅ Use terminal_exam column
          status: status || "draft",
          submitted_by: user.id,
        });
      }
    }

    console.log(
      "[Supabase] Processing",
      marksToInsert.length,
      "mark entries",
    );

    // Log first few marks to see what's being saved
    if (marksToInsert.length > 0) {
      console.log(
        "[Supabase] Sample mark entry to be saved:",
        JSON.stringify(marksToInsert[0], null, 2),
      );
      if (marksToInsert.length > 1) {
        console.log(
          "[Supabase] Another sample mark entry:",
          JSON.stringify(marksToInsert[1], null, 2),
        );
      }
    }

    // Extract student IDs from the payload
    const studentIds = marksToInsert.map((m) => m.student_id);
    console.log(
      "[Supabase] Student IDs being saved:",
      studentIds.length,
    );

    // Check if marks already exist for THESE SPECIFIC STUDENTS
    const marksMetadataKey = `marks_metadata_${exam_id}_${subject_id}`;
    const existingMetadata = await kv.get(marksMetadataKey);

    const { data: existingMarks } = await supabase
      .from("marks")
      .select("id, student_id, type, submitted_by, created_at")
      .eq("exam_id", exam_id)
      .eq("subject_id", subject_id)
      .in("student_id", studentIds);

    const isUpdate = existingMarks && existingMarks.length > 0;

    // Track metadata: original creator and current updater
    const metadata = existingMetadata
      ? JSON.parse(existingMetadata as string)
      : {
          original_creator: user.id,
          original_creator_time: new Date().toISOString(),
        };

    if (isUpdate) {
      metadata.last_updater = user.id;
      metadata.last_update_time = new Date().toISOString();
      console.log(
        `[Supabase] Updating marks - originally by ${metadata.original_creator}, now by ${user.id}`,
      );
    } else {
      console.log(
        `[Supabase] Creating new marks by ${user.id}`,
      );
    }

    // Save metadata
    await kv.set(marksMetadataKey, JSON.stringify(metadata));

    // Delete existing marks ONLY for the specific students AND types being saved
    // This prevents erasing marks from other classes when a teacher teaches multiple classes
    // AND prevents erasing midterm marks when submitting terminal marks (and vice versa)
    if (isUpdate) {
      // Determine which types are being submitted
      const typesBeingSubmitted = [
        ...new Set(marksToInsert.map((m) => m.type)),
      ];
      console.log(
        "[Supabase] Deleting marks for specific students and types:",
        {
          students: studentIds.length,
          types: typesBeingSubmitted,
        },
      );

      // Delete only marks that match the types being submitted
      for (const type of typesBeingSubmitted) {
        const { error: deleteError } = await supabase
          .from("marks")
          .delete()
          .eq("exam_id", exam_id)
          .eq("subject_id", subject_id)
          .eq("type", type) // 🔥 TYPE-SPECIFIC DELETION
          .in("student_id", studentIds);

        if (deleteError) {
          console.error(
            `[Supabase] Error deleting old ${type} marks:`,
            deleteError,
          );
        } else {
          console.log(
            `[Supabase] ✅ Deleted ${type} marks for specific students (preserving other types and classes)`,
          );
        }
      }
    }

    // Insert marks - submitted_by will track who last touched it
    const { data: insertedMarks, error: insertError } =
      await supabase
        .from("marks")
        .insert(marksToInsert)
        .select();

    if (insertError) {
      console.error(
        "[Supabase] Error saving marks entry:",
        insertError,
      );
      return c.json(
        {
          success: false,
          error: `Failed to save marks: ${insertError.message}`,
        },
        500,
      );
    }

    // Count marks by type to show what was saved
    const midtermCount =
      insertedMarks?.filter((m) => m.type === "midterm")
        .length || 0;
    const terminalCount =
      insertedMarks?.filter((m) => m.type === "terminal")
        .length || 0;

    console.log(
      "[Supabase] Successfully saved",
      insertedMarks?.length || 0,
      "mark entries:",
      { midterm: midtermCount, terminal: terminalCount },
    );

    // Verify what was actually saved by showing a sample
    if (insertedMarks && insertedMarks.length > 0) {
      console.log(
        "[Supabase] Sample saved mark (verification):",
        JSON.stringify(insertedMarks[0], null, 2),
      );
      if (insertedMarks.length > 1) {
        console.log(
          "[Supabase] Another saved mark (verification):",
          JSON.stringify(insertedMarks[1], null, 2),
        );
      }
    }

    // 🔥 VERIFICATION: Check what exists in DB for this exam/subject now
    const { data: allMarksForExamSubject } = await supabase
      .from("marks")
      .select("id, student_id, type, status")
      .eq("exam_id", exam_id)
      .eq("subject_id", subject_id);

    const dbMidtermCount =
      allMarksForExamSubject?.filter(
        (m) => m.type === "midterm",
      ).length || 0;
    const dbTerminalCount =
      allMarksForExamSubject?.filter(
        (m) => m.type === "terminal",
      ).length || 0;
    console.log(
      "[Supabase] 📊 Total marks in DB for this exam/subject:",
      {
        midterm: dbMidtermCount,
        terminal: dbTerminalCount,
        total: allMarksForExamSubject?.length || 0,
      },
    );

    return c.json({
      success: true,
      marks: { id: exam_id + "_" + subject_id },
      message: "Marks saved successfully",
    });
  } catch (error) {
    console.error(
      "[Supabase] Error in save marks endpoint:",
      error,
    );
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to save marks",
      },
      500,
    );
  }
});

// 🔥 Get pending marks approvals (separated by type: midterm/terminal)
app.get(
  "/make-server-1ddd013a/marks/pending-approvals",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // ✅ FIX: Use verifyUserAuth instead of supabase.auth.getUser(accessToken)
      const {
        data: { user },
        error: authError,
      } = await verifyUserAuth(accessToken);
      if (!user?.id) {
        console.error("[Pending Approvals] Auth error:", authError?.message || "User not found");
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check permissions
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      const authorizedRoles = [
        "principal",
        "super_admin",
        "director",
        "it_admin",
      ];
      if (!profile || !authorizedRoles.includes(profile.role)) {
        return c.json(
          { success: false, error: "Insufficient permissions" },
          403,
        );
      }

      // 🔥 Get session and term from query parameters
      const session = c.req.query("session");
      const term = c.req.query("term");

      console.log(
        "[Pending Approvals] Fetching pending marks...", { session, term }
      );

      // 🔥 Fetch ALL pending marks with "pending_approval" status
      let pendingMarksQuery = supabase
        .from("marks")
        .select("*")
        .eq("status", "pending_approval");
      
      // 🔥 Filter by session and term if provided
      if (session) {
        pendingMarksQuery = pendingMarksQuery.eq("session", session);
      }
      if (term) {
        pendingMarksQuery = pendingMarksQuery.eq("term", term);
      }
      
      pendingMarksQuery = pendingMarksQuery.order("created_at", { ascending: false });

      const { data: pendingMarks, error } = await pendingMarksQuery;

      if (error) {
        console.error(
          "[Pending Approvals] Query Error:",
          error,
        );
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      console.log(
        `[Pending Approvals] Found ${pendingMarks?.length || 0} submitted marks`,
      );

      // Log first mark to see structure
      if (pendingMarks && pendingMarks.length > 0) {
        console.log(
          "[Pending Approvals] Sample mark:",
          JSON.stringify(pendingMarks[0], null, 2),
        );
      }

      // Now fetch related data for each unique combination
      const examIds = [
        ...new Set(
          pendingMarks?.map((m) => m.exam_id).filter(Boolean) ||
            [],
        ),
      ];
      const subjectIds = [
        ...new Set(
          pendingMarks
            ?.map((m) => m.subject_id)
            .filter(Boolean) || [],
        ),
      ];
      const classIds = [
        ...new Set(
          pendingMarks
            ?.map((m) => m.class_id)
            .filter(Boolean) || [],
        ),
      ];
      const teacherIds = [
        ...new Set(
          pendingMarks
            ?.map((m) => m.submitted_by)
            .filter(Boolean) || [],
        ),
      ];

      console.log("[Pending Approvals] IDs to fetch:", {
        exams: examIds,
        subjects: subjectIds,
        classes: classIds,
        teachers: teacherIds,
      });

      // Fetch exams (use 'session' not 'academic_year')
      const { data: exams, error: examsError } = await supabase
        .from("exams")
        .select("id, name, session, term")
        .in("id", examIds);

      if (examsError)
        console.error(
          "[Pending Approvals] Exams fetch error:",
          examsError,
        );
      console.log(
        `[Pending Approvals] Fetched ${exams?.length || 0} exams`,
      );

      // Fetch subjects
      const { data: subjects, error: subjectsError } =
        await supabase
          .from("subjects")
          .select("id, name")
          .in("id", subjectIds);

      if (subjectsError)
        console.error(
          "[Pending Approvals] Subjects fetch error:",
          subjectsError,
        );
      console.log(
        `[Pending Approvals] Fetched ${subjects?.length || 0} subjects`,
      );

      // Fetch classes (use 'section_id' not 'section')
      const { data: classes, error: classesError } =
        await supabase
          .from("classes")
          .select("id, name, level, section_id")
          .in("id", classIds);

      if (classesError)
        console.error(
          "[Pending Approvals] Classes fetch error:",
          classesError,
        );
      console.log(
        `[Pending Approvals] Fetched ${classes?.length || 0} classes`,
      );

      // Fetch sections to map section_id to section name
      const sectionIds = [
        ...new Set(
          classes?.map((c) => c.section_id).filter(Boolean) ||
            [],
        ),
      ];
      const { data: sections, error: sectionsError } =
        await supabase
          .from("sections")
          .select("id, name")
          .in("id", sectionIds);

      if (sectionsError)
        console.error(
          "[Pending Approvals] Sections fetch error:",
          sectionsError,
        );
      console.log(
        `[Pending Approvals] Fetched ${sections?.length || 0} sections`,
      );

      // Fetch teachers (use first_name, middle_name, last_name not full_name)
      const { data: teachers, error: teachersError } =
        await supabase
          .from("profiles")
          .select("id, first_name, middle_name, last_name")
          .in("id", teacherIds);

      if (teachersError)
        console.error(
          "[Pending Approvals] Teachers fetch error:",
          teachersError,
        );
      console.log(
        `[Pending Approvals] Fetched ${teachers?.length || 0} teachers`,
      );

      // Create lookup maps
      const examsMap = new Map(
        exams?.map((e) => [e.id, e]) || [],
      );
      const subjectsMap = new Map(
        subjects?.map((s) => [s.id, s]) || [],
      );
      const sectionsMap = new Map(
        sections?.map((sec) => [sec.id, sec]) || [],
      );
      const classesMap = new Map(
        classes?.map((c) => [c.id, c]) || [],
      );
      const teachersMap = new Map(
        teachers?.map((t) => [
          t.id,
          {
            id: t.id,
            full_name: [
              t.first_name,
              t.middle_name,
              t.last_name,
            ]
              .filter(Boolean)
              .join(" "),
          },
        ]) || [],
      );

      // Fetch all student IDs from pending marks
      const studentIds = [
        ...new Set(
          pendingMarks
            ?.map((m) => m.student_id)
            .filter(Boolean) || [],
        ),
      ];
      console.log(
        `[Pending Approvals] Fetching ${studentIds.length} student profiles...`,
      );

      // Fetch student profiles
      const { data: students, error: studentsError } =
        await supabase
          .from("profiles")
          .select("id, first_name, middle_name, last_name")
          .in("id", studentIds);

      if (studentsError)
        console.error(
          "[Pending Approvals] Students fetch error:",
          studentsError,
        );
      console.log(
        `[Pending Approvals] Fetched ${students?.length || 0} student profiles`,
      );

      // Create student lookup map
      const studentsMap = new Map(
        students?.map((s) => [
          s.id,
          {
            id: s.id,
            full_name: [
              s.first_name,
              s.middle_name,
              s.last_name,
            ]
              .filter(Boolean)
              .join(" "),
          },
        ]) || [],
      );

      // 🔥 Group by exam + subject + class + TYPE
      const grouped: Record<string, any> = {};

      pendingMarks?.forEach((mark: any) => {
        const key = `${mark.exam_id}_${mark.subject_id}_${mark.class_id}_${mark.type}`;

        if (!grouped[key]) {
          const exam = examsMap.get(mark.exam_id);
          const subject = subjectsMap.get(mark.subject_id);
          const classData = classesMap.get(mark.class_id);
          const teacher = teachersMap.get(mark.submitted_by);

          // Log if any lookup failed
          if (!exam)
            console.warn(
              `[Pending Approvals] No exam found for ID: ${mark.exam_id}`,
            );
          if (!subject)
            console.warn(
              `[Pending Approvals] No subject found for ID: ${mark.subject_id}`,
            );
          if (!classData)
            console.warn(
              `[Pending Approvals] No class found for ID: ${mark.class_id}`,
            );
          if (!teacher)
            console.warn(
              `[Pending Approvals] No teacher found for ID: ${mark.submitted_by}`,
            );

          // Get section name from section_id
          const section = classData?.section_id
            ? sectionsMap.get(classData.section_id)
            : null;
          const sectionName = section?.name || "";

          grouped[key] = {
            id: key,
            exam_id: mark.exam_id,
            subject_id: mark.subject_id,
            class_id: mark.class_id,
            type: mark.type, // 🔥 midterm or terminal
            subject: subject?.name || "Unknown Subject",
            class: classData
              ? `${classData.name || ""} ${sectionName}`.trim()
              : "Unknown Class",
            teacher: teacher?.full_name || "Unknown Teacher",
            teacherId: mark.submitted_by,
            academicYear: exam?.session || "", // Use 'session' not 'academic_year'
            term: exam?.term || "",
            exam: exam?.name || "",
            submittedAt: new Date(mark.created_at),
            status: "pending_approval",
            studentCount: 0,
            studentMarks: [], // ✅ NEW: Detailed student marks array
          };
        }

        grouped[key].studentCount++;

        // ✅ NEW: Add detailed student marks data
        const student = studentsMap.get(mark.student_id);
        const studentMark = {
          student_id: mark.student_id,
          student_name: student?.full_name || "Unknown Student",
          // Include all marks columns based on type
          ...(mark.type === "midterm"
            ? {
                midterm_ca1: mark.midterm_ca1,
                midterm_ca2: mark.midterm_ca2,
                midterm_exam: mark.midterm_exam,
                midterm_total: mark.midterm_total,
              }
            : {
                terminal_ca1: mark.terminal_ca1,
                terminal_ca2: mark.terminal_ca2,
                terminal_exam: mark.terminal_exam,
                terminal_total: mark.terminal_total,
              }),
        };

        grouped[key].studentMarks.push(studentMark);
      });

      const approvals = Object.values(grouped);
      console.log(
        `[Pending Approvals] Grouped into ${approvals.length} approval items with detailed student marks`,
      );

      return c.json({ success: true, approvals });
    } catch (error) {
      console.error("[Pending Approvals] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch pending approvals",
        },
        500,
      );
    }
  },
);

// Review marks (approve/reject)
app.post("/make-server-1ddd013a/marks/review", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Check permissions
    const { data: profile } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .single();

    // ✅ FIX: Allow IT Admin to approve marks
    const authorizedRoles = [
      "principal",
      "super_admin",
      "it_admin",
    ];
    if (!profile || !authorizedRoles.includes(profile.role)) {
      return c.json(
        { success: false, error: "Insufficient permissions" },
        403,
      );
    }

    const body = await c.req.json();
    const { marks_id, action, comment } = body;

    if (!marks_id || !action) {
      return c.json(
        {
          success: false,
          error: "Missing required fields: marks_id, action",
        },
        400,
      );
    }

    if (
      action !== "approve" &&
      action !== "reject" &&
      action !== "unlock"
    ) {
      return c.json(
        {
          success: false,
          error:
            'Invalid action. Must be "approve", "reject", or "unlock"',
        },
        400,
      );
    }

    const newStatus =
      action === "approve"
        ? "approved"
        : action === "reject"
          ? "rejected"
          : "submitted"; // unlock changes status back to submitted

    // 🔥 Parse marks_id: exam_id_subject_id_class_id_type
    // Format: xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx_xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx_xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx_midterm
    console.log("[Review Marks] Parsing marks_id:", marks_id);

    const parts = marks_id.split("_");
    if (parts.length === 4) {
      // 🔥 NEW FORMAT: exam_id_subject_id_class_id_type (separate approvals for midterm/terminal)
      const [exam_id, subject_id, class_id, type] = parts;
      console.log(
        `[Review Marks] Approving ${type} marks for exam:${exam_id}, subject:${subject_id}, class:${class_id}`,
      );

      // ✅ Build update object with rejection comment if provided
      const updateData: any = {
        status: newStatus,
        approved_by: user.id,
      };

      // Add rejection comment for reject action
      if (action === "reject" && comment) {
        updateData.rejection_comment = comment;
      }

      const { data: marks, error } = await supabase
        .from("marks")
        .update(updateData)
        .eq("exam_id", exam_id)
        .eq("subject_id", subject_id)
        .eq("class_id", class_id)
        .eq("type", type) // 🔥 CRITICAL: Only update marks of this type (midterm or terminal)
        .select();

      if (error) {
        console.error(
          "[Supabase] Error reviewing marks:",
          error,
        );
        return c.json(
          {
            success: false,
            error: `Failed to review marks: ${error.message}`,
          },
          500,
        );
      }

      console.log(
        "[Supabase] Updated",
        marks?.length || 0,
        type,
        "marks to",
        newStatus,
      );

      return c.json({
        success: true,
        message: `${marks?.length || 0} ${type} marks ${newStatus}`,
        marksCount: marks?.length || 0,
      });
    } else if (parts.length === 2) {
      // OLD FORMAT: exam_id_subject_id (backward compatibility - updates ALL types)
      const [exam_id, subject_id] = parts;
      console.log(
        `[Review Marks] OLD FORMAT - Approving ALL marks for exam:${exam_id}, subject:${subject_id}`,
      );

      // ✅ Build update object with rejection comment if provided
      const updateDataOld: any = {
        status: newStatus,
        approved_by: user.id,
      };

      // Add rejection comment for reject action
      if (action === "reject" && comment) {
        updateDataOld.rejection_comment = comment;
      }

      const { data: marks, error } = await supabase
        .from("marks")
        .update(updateDataOld)
        .eq("exam_id", exam_id)
        .eq("subject_id", subject_id)
        .select();

      if (error) {
        console.error(
          "[Supabase] Error reviewing marks:",
          error,
        );
        return c.json(
          {
            success: false,
            error: `Failed to review marks: ${error.message}`,
          },
          500,
        );
      }

      console.log(
        "[Supabase] Updated",
        marks?.length || 0,
        "marks to",
        newStatus,
      );

      return c.json({
        success: true,
        message: `${marks?.length || 0} marks ${newStatus}`,
        marksCount: marks?.length || 0,
      });
    } else {
      return c.json(
        {
          success: false,
          error:
            "Invalid marks_id format. Expected: exam_id_subject_id or exam_id_subject_id_class_id_type",
        },
        400,
      );
    }
  } catch (error) {
    console.error(
      "[Supabase] Error in marks review endpoint:",
      error,
    );
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to review marks",
      },
      500,
    );
  }
});

// Get marks statistics
app.get("/make-server-1ddd013a/marks/statistics", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // ✅ FIX: Use verifyUserAuth instead of supabase.auth.getUser(accessToken)
    const {
      data: { user },
      error: authError,
    } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      console.error("[Marks Statistics] Auth error:", authError?.message || "User not found");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // 🔥 Get session and term from query parameters
    const session = c.req.query("session");
    const term = c.req.query("term");

    console.log("[Marks Statistics] Fetching marks...", { session, term });

    // Get all marks
    let marksQuery = supabase
      .from("marks")
      .select("exam_id, subject_id, status");
    
    // 🔥 Filter by session and term if provided
    if (session) {
      marksQuery = marksQuery.eq("session", session);
    }
    if (term) {
      marksQuery = marksQuery.eq("term", term);
    }

    const { data: allMarks, error } = await marksQuery;

    if (error) {
      console.error(
        "[Supabase] Error fetching marks for statistics:",
        error,
      );
      return c.json({
        success: true,
        statistics: {
          total_submissions: 0,
          pending_approvals: 0,
          completed_classes: 0,
          average_progress: 0,
        },
      });
    }

    // Group by exam_id and subject_id to get unique submissions
    const uniqueSubmissions = new Set(
      allMarks?.map((m) => `${m.exam_id}_${m.subject_id}`),
    );
    const totalCount = uniqueSubmissions.size;

    // Count pending (submitted)
    const submittedMarks = allMarks?.filter(
      (m) => m.status === "submitted",
    );
    const uniqueSubmitted = new Set(
      submittedMarks?.map(
        (m) => `${m.exam_id}_${m.subject_id}`,
      ),
    );
    const pendingCount = uniqueSubmitted.size;

    // Count approved
    const approvedMarks = allMarks?.filter(
      (m) => m.status === "approved",
    );
    const uniqueApproved = new Set(
      approvedMarks?.map((m) => `${m.exam_id}_${m.subject_id}`),
    );
    const completedCount = uniqueApproved.size;

    // Calculate average progress
    const averageProgress =
      totalCount > 0
        ? Math.round((completedCount / totalCount) * 100)
        : 0;

    console.log("[Supabase] Statistics:", {
      totalCount,
      pendingCount,
      completedCount,
      averageProgress,
    });

    return c.json({
      success: true,
      statistics: {
        total_submissions: totalCount,
        pending_approvals: pendingCount,
        completed_classes: completedCount,
        average_progress: averageProgress,
      },
    });
  } catch (error) {
    console.error(
      "[Supabase] Error fetching marks statistics:",
      error,
    );
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch statistics",
      },
      500,
    );
  }
});

// Get marks progress tracking (separate midterm and terminal)
app.get("/make-server-1ddd013a/marks-progress", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // ✅ FIX: Use verifyUserAuth instead of supabase.auth.getUser(accessToken)
    const {
      data: { user },
      error: authError,
    } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      console.error("[Marks Progress] Auth error:", authError?.message || "User not found");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // 🔥 Get session and term from query parameters
    const session = c.req.query("session");
    const term = c.req.query("term");

    console.log(
      "[Marks Progress] Calculating progress tracking data...", { session, term }
    );

    // First, get all active exams
    // 🔥 Filter by session and term if provided
    let examsQuery = supabase
        .from("exams")
        .select("id, name, session, term, status")
        .eq("status", "active");
    
    if (session) {
      examsQuery = examsQuery.eq("session", session);
    }
    if (term) {
      examsQuery = examsQuery.eq("term", term);
    }

    const { data: activeExams, error: examsError } = await examsQuery;

    if (examsError) {
      console.error(
        "[Marks Progress] Error fetching active exams:",
        examsError,
      );
      return c.json(
        {
          success: false,
          error: "Failed to fetch active exams",
        },
        500,
      );
    }

    console.log(
      `[Marks Progress] Found ${activeExams?.length || 0} active exams`,
    );

    // If no active exams, return empty progress
    if (!activeExams || activeExams.length === 0) {
      console.log("[Marks Progress] No active exams found");
      return c.json({
        success: true,
        classProgresses: [],
        message:
          'No active exams. Please set an exam status to "active" in Exam Management.',
      });
    }

    // Get all classes
    const { data: classes, error: classesError } =
      await supabase
        .from("classes")
        .select("id, name, sections(name)")
        .order("name", { ascending: true });

    if (classesError) {
      console.error(
        "[Marks Progress] Error fetching classes:",
        classesError,
      );
      return c.json(
        { success: false, error: "Failed to fetch classes" },
        500,
      );
    }

    // Get all subject assignments (teacher-subject-class)
    const {
      data: subjectAssignments,
      error: assignmentsError,
    } = await supabase.from("subject_assignments").select(`
          id,
          teacher_id,
          subject_id,
          class_id,
          profiles:teacher_id(id, first_name, last_name),
          subjects(id, name),
          classes(id, name)
        `);

    if (assignmentsError) {
      console.error(
        "[Marks Progress] Error fetching subject assignments:",
        assignmentsError,
      );
      return c.json(
        {
          success: false,
          error: "Failed to fetch subject assignments",
        },
        500,
      );
    }

    console.log(
      `[Marks Progress] Found ${subjectAssignments?.length || 0} subject assignments`,
    );

    // Process each class
    const classProgresses = await Promise.all(
      (classes || []).map(async (cls) => {
        // Get total students in this class
        const { data: students } = await supabase
          .from("profiles")
          .select("id")
          .eq("class_id", cls.id)
          .eq("role", "student")
          .or("is_graduated.is.null,is_graduated.eq.false");

        const totalStudents = students?.length || 0;
        const studentIds = students?.map((s) => s.id) || [];

        console.log(
          `[Marks Progress] Class ${cls.name}: ${totalStudents} students`,
        );

        // Get assignments for this class
        const relevantSubjects =
          subjectAssignments?.filter(
            (assignment: any) => assignment.class_id === cls.id,
          ) || [];

        console.log(
          `[Marks Progress] Class ${cls.name}: ${relevantSubjects.length} assignments`,
        );

        // Calculate progress for each subject assignment
        const subjectProgressesWithNulls = await Promise.all(
          relevantSubjects.map(async (assignment: any) => {
            const subject = assignment.subjects;
            const teacher = assignment.profiles;

            if (!subject) {
              console.log(
                `[Marks Progress] Skipping assignment with missing subject`,
              );
              return null;
            }

            // If no students, still show the assignment but with 0% progress
            if (totalStudents === 0) {
              console.log(
                `[Marks Progress] ${assignment.subjects?.name} for ${cls.name} - no students (showing anyway)`,
              );

              const teacherName = teacher
                ? `${teacher.first_name} ${teacher.last_name}`
                : "Unassigned";

              return {
                subjectId: subject.id,
                subjectName: subject.name,
                teacher: teacherName,
                teacherId: assignment.teacher_id || "",
                status: "not_started" as const,
                midtermProgress: 0,
                terminalProgress: 0,
                overallProgress: 0,
                totalStudents: 0,
                examProgresses: [],
                lastUpdated: new Date().toISOString(),
                dueDate: new Date(
                  Date.now() + 7 * 24 * 60 * 60 * 1000,
                ).toISOString(),
              };
            }

            // For each active exam, check how many students have marks
            const examProgresses: any[] = [];
            let allMarksForStatus: any[] = [];
            let midtermMarksCount = 0;
            let terminalMarksCount = 0;

            for (const exam of activeExams) {
              const { data: marksForExam, error: marksError } =
                await supabase
                  .from("marks")
                  .select("student_id, status, exam_id, type")
                  .eq("subject_id", subject.id)
                  .eq("exam_id", exam.id)
                  .in("student_id", studentIds);

              if (marksError) {
                console.error(
                  `[Marks Progress] Error fetching marks for ${subject.name} - ${exam.name}:`,
                  marksError,
                );
                continue;
              }

              // Count students with midterm and terminal marks separately
              const midtermMarks =
                marksForExam?.filter(
                  (m) => m.type === "midterm",
                ) || [];
              const terminalMarks =
                marksForExam?.filter(
                  (m) => m.type === "terminal",
                ) || [];

              const midtermStudents = new Set(
                midtermMarks.map((m) => m.student_id),
              ).size;
              const terminalStudents = new Set(
                terminalMarks.map((m) => m.student_id),
              ).size;

              // Track total students with marks for this type
              if (midtermStudents > midtermMarksCount) {
                midtermMarksCount = midtermStudents;
              }
              if (terminalStudents > terminalMarksCount) {
                terminalMarksCount = terminalStudents;
              }

              // Count unique students with marks for this exam (any type)
              const studentsWithMarks = new Set(
                marksForExam?.map((m) => m.student_id) || [],
              ).size;
              const progress =
                totalStudents > 0
                  ? Math.round(
                      (studentsWithMarks / totalStudents) * 100,
                    )
                  : 0;

              examProgresses.push({
                examId: exam.id,
                examName: exam.name,
                studentsWithMarks,
                progress,
              });

              // Collect all marks for status determination
              if (marksForExam) {
                allMarksForStatus = [
                  ...allMarksForStatus,
                  ...marksForExam,
                ];
              }
            }

            // Calculate separate midterm and terminal progress
            const midtermProgress =
              totalStudents > 0
                ? Math.round(
                    (midtermMarksCount / totalStudents) * 100,
                  )
                : 0;
            const terminalProgress =
              totalStudents > 0
                ? Math.round(
                    (terminalMarksCount / totalStudents) * 100,
                  )
                : 0;

            // Calculate overall progress (average across all active exams)
            const overallProgress =
              examProgresses.length > 0
                ? Math.round(
                    examProgresses.reduce(
                      (sum, ep) => sum + ep.progress,
                      0,
                    ) / examProgresses.length,
                  )
                : 0;

            // Determine status based on all marks
            let status:
              | "not_started"
              | "draft"
              | "submitted"
              | "approved" = "not_started";

            if (allMarksForStatus.length > 0) {
              // If ALL marks are approved, status is approved
              const allApproved = allMarksForStatus.every(
                (m) => m.status === "approved",
              );
              const someApproved = allMarksForStatus.some(
                (m) => m.status === "approved",
              );
              const someSubmitted = allMarksForStatus.some(
                (m) => m.status === "submitted",
              );
              const someDraft = allMarksForStatus.some(
                (m) => m.status === "draft",
              );

              if (allApproved) {
                status = "approved";
              } else if (someApproved || someSubmitted) {
                status = "submitted";
              } else if (someDraft) {
                status = "draft";
              }
            }

            console.log(
              `[Marks Progress] ${subject.name} in ${cls.name}:`,
              {
                totalStudents,
                activeExams: examProgresses.length,
                overallProgress,
                status,
                examProgresses,
              },
            );

            // Get last updated time
            const { data: latestMark } = await supabase
              .from("marks")
              .select("updated_at")
              .eq("subject_id", subject.id)
              .in("student_id", studentIds)
              .order("updated_at", { ascending: false })
              .limit(1);

            const teacherName = teacher
              ? `${teacher.first_name} ${teacher.last_name}`
              : "Unassigned";

            return {
              subjectId: subject.id,
              subjectName: subject.name,
              teacher: teacherName,
              teacherId: assignment.teacher_id || "",
              status,
              midtermProgress, // Separate midterm progress
              terminalProgress, // Separate terminal progress
              overallProgress,
              totalStudents,
              examProgresses, // Include per-exam breakdown
              lastUpdated:
                latestMark?.[0]?.updated_at ||
                new Date().toISOString(),
              dueDate: new Date(
                Date.now() + 7 * 24 * 60 * 60 * 1000,
              ).toISOString(),
            };
          }),
        );

        // Filter out null subjects (classes with no students)
        const subjectProgresses =
          subjectProgressesWithNulls.filter((s) => s !== null);

        // Calculate class-level statistics
        const totalTeachers = new Set(
          relevantSubjects
            .map((a: any) => a.teacher_id)
            .filter(Boolean),
        ).size;
        const submittedTeachers = new Set(
          subjectProgresses
            .filter(
              (s) =>
                s.status === "submitted" ||
                s.status === "approved",
            )
            .map((s) => s.teacherId)
            .filter(Boolean),
        ).size;
        // Pending = teachers with draft marks or in progress (not submitted/approved)
        // Don't count teachers with no marks at all
        const pendingTeachers = new Set(
          subjectProgresses
            .filter(
              (s) =>
                s.status === "draft" ||
                (s.status !== "submitted" &&
                  s.status !== "approved" &&
                  s.overallProgress > 0),
            )
            .map((s) => s.teacherId)
            .filter(Boolean),
        ).size;

        // Calculate overall class progress
        const overallProgress =
          subjectProgresses.length > 0
            ? Math.round(
                subjectProgresses.reduce(
                  (sum, s) => sum + s.overallProgress,
                  0,
                ) / subjectProgresses.length,
              )
            : 0;

        console.log(
          `[Marks Progress] Class ${cls.name} summary:`,
          {
            subjects: subjectProgresses.length,
            overallProgress,
            totalTeachers,
            submittedTeachers,
          },
        );

        // Note: cls.name already includes the section
        const className = cls.name;

        return {
          classId: cls.id,
          className,
          subjects: subjectProgresses,
          overallProgress,
          totalTeachers,
          submittedTeachers,
          pendingTeachers,
        };
      }),
    );

    console.log(
      "[Marks Progress] Calculated progress for",
      classProgresses.length,
      "classes",
    );

    return c.json({
      success: true,
      classProgresses,
    });
  } catch (error) {
    console.error(
      "[Marks Progress] Error calculating progress:",
      error,
    );
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to calculate progress",
      },
      500,
    );
  }
});

// Debug endpoint for marks progress
app.get(
  "/make-server-1ddd013a/debug-marks-progress",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const url = new URL(c.req.url);
      const className = url.searchParams.get("class") || "SS1";
      const subjectName =
        url.searchParams.get("subject") || "Data Processing";

      console.log(
        `[Debug] Looking for marks in ${className} for ${subjectName}`,
      );

      // Get the class
      const { data: classes } = await supabase
        .from("classes")
        .select("id, name")
        .ilike("name", `%${className}%`);

      // Get the subject
      const { data: subjects } = await supabase
        .from("subjects")
        .select("id, name")
        .ilike("name", `%${subjectName}%`);

      if (!classes || classes.length === 0) {
        return c.json({
          success: false,
          error: `Class "${className}" not found`,
        });
      }

      if (!subjects || subjects.length === 0) {
        return c.json({
          success: false,
          error: `Subject "${subjectName}" not found`,
        });
      }

      const classData = classes[0];
      const subjectData = subjects[0];

      // Get students in this class
      const { data: students } = await supabase
        .from("profiles")
        .select("id, first_name, last_name, role")
        .eq("class_id", classData.id)
        .eq("role", "student")
        .or("is_graduated.is.null,is_graduated.eq.false");

      const studentIds = students?.map((s) => s.id) || [];

      // Get all marks for this subject and these students
      const { data: allMarks } = await supabase
        .from("marks")
        .select("*")
        .eq("subject_id", subjectData.id)
        .in("student_id", studentIds);

      // Get all active exams
      const { data: activeExams } = await supabase
        .from("exams")
        .select("id, name, status")
        .eq("status", "active");

      // Get midterm marks
      const { data: midtermMarks } = await supabase
        .from("marks")
        .select("*")
        .eq("subject_id", subjectData.id)
        .eq("type", "midterm")
        .in("student_id", studentIds);

      // Get terminal marks
      const { data: terminalMarks } = await supabase
        .from("marks")
        .select("*")
        .eq("subject_id", subjectData.id)
        .eq("type", "terminal")
        .in("student_id", studentIds);

      // Calculate per-exam progress
      const examBreakdown =
        activeExams?.map((exam) => {
          const marksForExam =
            allMarks?.filter((m) => m.exam_id === exam.id) ||
            [];
          const studentsWithMarks = new Set(
            marksForExam.map((m) => m.student_id),
          ).size;
          const progress = students?.length
            ? Math.round(
                (studentsWithMarks / students.length) * 100,
              )
            : 0;

          return {
            exam: exam.name,
            examId: exam.id,
            marksCount: marksForExam.length,
            studentsWithMarks,
            progress,
          };
        }) || [];

      return c.json({
        success: true,
        class: classData,
        subject: subjectData,
        students: students?.map((s) => ({
          id: s.id,
          name: `${s.first_name} ${s.last_name}`,
        })),
        totalStudents: students?.length || 0,
        studentIds,
        activeExams: activeExams || [],
        allMarks: allMarks?.length || 0,
        midtermMarks: midtermMarks?.length || 0,
        terminalMarks: terminalMarks?.length || 0,
        midtermDetails: midtermMarks,
        terminalDetails: terminalMarks,
        examBreakdown,
        calculations: {
          studentsWithMidterm: new Set(
            midtermMarks?.map((m) => m.student_id) || [],
          ).size,
          studentsWithTerminal: new Set(
            terminalMarks?.map((m) => m.student_id) || [],
          ).size,
          midtermProgress: students?.length
            ? Math.round(
                (new Set(
                  midtermMarks?.map((m) => m.student_id) || [],
                ).size /
                  students.length) *
                  100,
              )
            : 0,
          terminalProgress: students?.length
            ? Math.round(
                (new Set(
                  terminalMarks?.map((m) => m.student_id) || [],
                ).size /
                  students.length) *
                  100,
              )
            : 0,
          overallProgress:
            examBreakdown.length > 0
              ? Math.round(
                  examBreakdown.reduce(
                    (sum, eb) => sum + eb.progress,
                    0,
                  ) / examBreakdown.length,
                )
              : 0,
        },
      });
    } catch (error) {
      console.error("[Debug] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to debug",
        },
        500,
      );
    }
  },
);

// ==================== UPLOAD SETTINGS & DEADLINE ENDPOINTS ====================

// Get upload settings
app.get("/make-server-1ddd013a/upload-settings", async (c) => {
  try {
    // Get global settings from KV store
    const globalSettings = await kv.get(
      "upload_global_settings",
    );

    // Get deadlines from database
    const { data: deadlines, error: deadlinesError } =
      await supabase
        .from("upload_deadlines")
        .select("*")
        .order("deadline", { ascending: true });

    if (deadlinesError) {
      console.error(
        "[Upload Settings] Error fetching deadlines:",
        deadlinesError,
      );
    }

    // Transform database deadlines to frontend format
    const formattedDeadlines = (deadlines || []).map((d) => ({
      id: d.id,
      term: d.term,
      session: d.session,
      uploadType: d.upload_type,
      deadline: d.deadline,
      enabled: d.enabled,
      description: d.description || "",
    }));

    const defaultGlobal = {
      uploadsEnabled: true,
      maxFileSize: 50,
      maxFilesPerUpload: 5,
      allowedExtensions: [
        ".pdf",
        ".doc",
        ".docx",
        ".ppt",
        ".pptx",
        ".jpg",
        ".png",
        ".mp4",
      ],
      requireApproval: false,
      emailNotifications: true,
      autoDeleteOldFiles: false,
      fileRetentionDays: 365,
    };

    return c.json({
      success: true,
      settings: {
        global: globalSettings || defaultGlobal,
        deadlines: formattedDeadlines,
      },
    });
  } catch (error) {
    console.error(
      "[Upload Settings] Error fetching settings:",
      error,
    );
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch settings",
      },
      500,
    );
  }
});

// Save upload settings
app.post("/make-server-1ddd013a/upload-settings", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken)
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );

    const {
      data: { user },
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id)
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );

    // Check if user is admin/principal
    const { data: profile } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .single();

    if (
      !profile ||
      !["principal", "director", "admin", "it_admin"].includes(
        profile.role,
      )
    ) {
      return c.json(
        { success: false, error: "Insufficient permissions" },
        403,
      );
    }

    const body = await c.req.json();
    const { global, deadlines } = body;

    console.log(
      "[Upload Settings] Saving settings by user:",
      user.id,
    );
    console.log(
      "[Upload Settings] Deadlines to save:",
      deadlines.length,
    );

    // Save global settings to KV store
    await kv.set("upload_global_settings", global);

    // Save deadlines to database
    // Delete all existing deadlines first, then insert new ones
    const { error: deleteError } = await supabase
      .from("upload_deadlines")
      .delete()
      .neq("id", "00000000-0000-0000-0000-000000000000"); // Delete all

    if (deleteError) {
      console.error(
        "[Upload Settings] Error deleting old deadlines:",
        deleteError,
      );
      // Continue anyway - insert might still work
    }

    // Insert new deadlines
    if (deadlines && deadlines.length > 0) {
      const deadlinesToInsert = deadlines.map((d: any) => ({
        term: d.term,
        session: d.session,
        upload_type: d.uploadType,
        deadline: d.deadline,
        enabled: d.enabled,
        description: d.description || null,
        created_by: user.id,
        updated_by: user.id,
      }));

      const { error: insertError } = await supabase
        .from("upload_deadlines")
        .insert(deadlinesToInsert);

      if (insertError) {
        console.error(
          "[Upload Settings] Error inserting deadlines:",
          insertError,
        );
        return c.json(
          {
            success: false,
            error: `Failed to save deadlines: ${insertError.message}`,
          },
          500,
        );
      }

      console.log(
        "[Upload Settings] Successfully saved",
        deadlines.length,
        "deadlines",
      );
    }

    return c.json({
      success: true,
      message: `Settings saved successfully. ${deadlines.length} deadline(s) configured.`,
    });
  } catch (error) {
    console.error(
      "[Upload Settings] Error saving settings:",
      error,
    );
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to save settings",
      },
      500,
    );
  }
});

// Check if upload is allowed (for teacher dashboard)
app.post(
  "/make-server-1ddd013a/check-upload-deadline",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken)
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );

      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id)
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );

      // Get user role
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      const userRole = profile?.role || "teacher";

      const body = await c.req.json();
      const { term, session, type } = body; // type: 'e-notes' | 'exam_question' | etc

      console.log("=== DEADLINE CHECK START ===");
      console.log(
        "[Deadline Check] Request:",
        JSON.stringify({ term, session, type, userRole }),
      );

      // Check if uploads are globally disabled
      const globalSettings = await kv.get(
        "upload_global_settings",
      );
      if (globalSettings && !globalSettings.uploadsEnabled) {
        console.log(
          "[Deadline Check] Uploads globally disabled",
        );
        return c.json({
          success: true,
          allowed: false,
          reason:
            "Uploads are currently disabled by the administration",
        });
      }

      // Get deadlines from database
      const { data: deadlines, error: deadlineError } =
        await supabase
          .from("upload_deadlines")
          .select("*")
          .eq("enabled", true);

      if (deadlineError) {
        console.error(
          "[Deadline Check] Error fetching deadlines:",
          deadlineError,
        );
        // Fail open - allow upload if we can't check deadlines
        return c.json({
          success: true,
          allowed: true,
          reason: "Unable to check deadlines",
        });
      }

      console.log(
        "[Deadline Check] Found",
        deadlines?.length || 0,
        "active deadlines",
      );

      if (!deadlines || deadlines.length === 0) {
        console.log(
          "[Deadline Check] No active deadlines configured",
        );
        return c.json({
          success: true,
          allowed: true,
          reason: "No deadline set for this upload type",
          deadline: null,
          isExpired: false,
        });
      }

      // Find matching deadline for this term/session/type
      const matchingDeadline = deadlines.find(
        (d) =>
          d.term === term &&
          d.session === session &&
          (d.upload_type === type || d.upload_type === "all"),
      );

      if (!matchingDeadline) {
        console.log("[NO MATCH] No deadline found for:", {
          term,
          session,
          type,
        });
        return c.json({
          success: true,
          allowed: true,
          reason: "No deadline set for this upload type",
          deadline: null,
          isExpired: false,
        });
      }

      console.log("[MATCH FOUND] Deadline:", matchingDeadline);

      // Check if deadline is expired
      const now = new Date();
      const deadlineDate = new Date(matchingDeadline.deadline);
      const isExpired = now > deadlineDate;

      console.log("[Deadline Check] Now:", now.toISOString());
      console.log(
        "[Deadline Check] Deadline:",
        deadlineDate.toISOString(),
      );
      console.log("[Deadline Check] Is Expired:", isExpired);
      console.log("[Deadline Check] User Role:", userRole);

      // Auto-disable expired deadlines in the database
      if (isExpired && matchingDeadline.enabled) {
        console.log(
          "[Deadline Check] 🔄 Auto-disabling expired deadline in database...",
        );
        try {
          await supabase
            .from("upload_deadlines")
            .update({ enabled: false })
            .eq("id", matchingDeadline.id);
          console.log(
            "[Deadline Check] ✅ Expired deadline auto-disabled",
          );
        } catch (disableError) {
          console.error(
            "[Deadline Check] ⚠️ Failed to auto-disable deadline:",
            disableError,
          );
          // Continue anyway - the deadline check logic still works
        }
      }

      // Teachers cannot upload after deadline
      // Admins can upload even after deadline (on behalf of teachers)
      if (userRole === "teacher" && isExpired) {
        console.log(
          "[Deadline Check] ❌ TEACHER + EXPIRED → DISABLED",
        );
        return c.json({
          success: true,
          allowed: false,
          reason: `Upload deadline expired on ${deadlineDate.toLocaleString()}`,
          deadline: matchingDeadline.deadline,
          isExpired: true,
        });
      }

      // Deadline exists but not expired OR user is admin
      console.log(
        "[Deadline Check] ✅ ALLOWED → Button ENABLED",
      );
      return c.json({
        success: true,
        allowed: true,
        reason: isExpired
          ? "Admin can upload past deadline"
          : null,
        deadline: matchingDeadline.deadline,
        isExpired: isExpired,
      });
    } catch (error) {
      console.error("[Deadline Check] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to check deadline",
        },
        500,
      );
    }
  },
);

