// Promote students from one class to another
app.post(
  "/make-server-1ddd013a/promote-students",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        !profile ||
        !["principal", "director", "it_admin"].includes(
          profile.role,
        )
      ) {
        return c.json(
          {
            success: false,
            error: "Unauthorized - Admin access required",
          },
          403,
        );
      }

      const body = await c.req.json();
      const {
        from_class_id,
        to_class_id,
        session,
        is_graduation,
        current_session: bodyCurrentSession,
        new_session: bodyNewSession,
      } = body;

      // Use the session fields from the request body
      // Fall back to KV store for current_session if not provided
      let currentSession = bodyCurrentSession;
      if (!currentSession) {
        const currentSessionData = await kv.get(
          "current_session",
        );
        currentSession = currentSessionData || session;
      }
      
      // Use new_session from body, fallback to session parameter
      const newSession = bodyNewSession || session;

      console.log("[Promotion] Promoting students:", {
        from_class_id,
        to_class_id,
        currentSession,
        newSession,
        is_graduation,
      });

      if (!from_class_id || !newSession) {
        return c.json(
          { success: false, error: "Missing required fields" },
          400,
        );
      }

      // Get all students in the from_class
      const { data: students, error: studentsError } =
        await supabase
          .from("profiles")
          .select("id, admission_number, first_name, middle_name, last_name, email, phone, gender, date_of_birth, class_id")
          .eq("role", "student")
          .eq("class_id", from_class_id)
          .or("is_graduated.is.null,is_graduated.eq.false");

      if (studentsError) {
        console.error(
          "[Promotion] Error fetching students:",
          studentsError,
        );
        return c.json(
          {
            success: false,
            error: `Failed to fetch students: ${studentsError.message}`,
          },
          500,
        );
      }

      if (!students || students.length === 0) {
        return c.json(
          {
            success: false,
            error: "No students found in this class",
          },
          400,
        );
      }

      console.log(
        `[Promotion] Found ${students.length} students to promote`,
      );

      // Update all students' class_id and is_graduated flag
      const updates = students.map((student) => ({
        id: student.id,
        class_id: to_class_id, // NULL for graduating students
        is_graduated: is_graduation ? true : false, // Set graduated flag
      }));

      const { error: updateError } = await supabase
        .from("profiles")
        .upsert(updates);

      if (updateError) {
        console.error(
          "[Promotion] Error updating students:",
          updateError,
        );
        return c.json(
          {
            success: false,
            error: `Failed to update students: ${updateError.message}`,
          },
          500,
        );
      }

      // Extract student IDs early for use in graduation and promotion checks
      const studentIds = students.map((s) => s.id);

      // If this is a graduation, also add records to graduated_students table
      if (is_graduation) {
        console.log(
          `[Promotion] Processing graduation for ${students.length} students`,
        );

        // 🔥 DELETE all student_subjects for graduating students
        console.log(`[Promotion] Deleting student_subjects for ${studentIds.length} graduating students`);
        const { error: deleteSubjectsError } = await supabase
          .from('student_subjects')
          .delete()
          .in('student_id', studentIds);

        if (deleteSubjectsError) {
          console.error('[Promotion] Error deleting student_subjects:', deleteSubjectsError);
          console.warn('[Promotion] Graduated students may still have subject assignments');
        } else {
          console.log(`[Promotion] Successfully deleted student_subjects for graduating students`);
        }

        // Check if graduated_students table exists and insert records
        try {
          const graduationRecords = students.map((student) => ({
            student_id: student.id,
            admission_number: student.admission_number,
            first_name: student.first_name,
            middle_name: student.middle_name || null,
            last_name: student.last_name,
            email: student.email || null,
            phone: student.phone || null,
            gender: student.gender || null,
            date_of_birth: student.date_of_birth || null,
            graduation_session: newSession,
            graduation_class: from_class_id,
            graduated_by: user.id,
          }));

          // Check for existing graduation records to avoid duplicates
          const { data: existingGraduations } = await supabase
            .from("graduated_students")
            .select("student_id")
            .in("student_id", studentIds)
            .eq("graduation_session", newSession);

          const existingGradIds = new Set(
            existingGraduations?.map((g) => g.student_id) || [],
          );
          const newGraduationRecords = graduationRecords.filter(
            (g) => !existingGradIds.has(g.student_id),
          );

          if (newGraduationRecords.length > 0) {
            const { error: gradError } = await supabase
              .from("graduated_students")
              .insert(newGraduationRecords);

            if (gradError) {
              console.error(
                "[Promotion] Error inserting graduation records:",
                gradError,
              );
              console.warn(
                "[Promotion] Students marked as graduated but graduation records not saved",
              );
            } else {
              console.log(
                `[Promotion] Successfully created ${newGraduationRecords.length} graduation records`,
              );
            }
          }
        } catch (gradError) {
          console.error(
            "[Promotion] Error processing graduations:",
            gradError,
          );
          console.warn(
            "[Promotion] Students marked as graduated but graduation records may not be saved",
          );
        }
      }

      // Check for existing promotion records to avoid duplicates
      // Query for any students who already have a promotion record for this session combination
      const { data: existingPromotions } = await supabase
        .from("promotions")
        .select("student_id, current_session, new_session")
        .in("student_id", studentIds)
        .eq("current_session", currentSession)
        .eq("new_session", newSession);

      console.log(
        `[Promotion] Found ${existingPromotions?.length || 0} existing promotion records`,
      );

      // Filter out students who already have a promotion record
      const existingStudentIds = new Set(
        existingPromotions?.map((p) => p.student_id) || [],
      );
      const studentsToRecord = students.filter(
        (student) => !existingStudentIds.has(student.id),
      );

      console.log(
        `[Promotion] Recording promotions for ${studentsToRecord.length} students (${existingStudentIds.size} already recorded)`,
      );

      // Record promotions in the promotions table (only for students without existing records)
      if (studentsToRecord.length > 0) {
        const promotionRecords = studentsToRecord.map((student) => ({
          student_id: student.id,
          from_class_id,
          to_class_id: to_class_id || null,
          current_session: currentSession,
          new_session: newSession,
          is_graduation: is_graduation || false,
          promotion_type: "regular",
          promoted_by: user.id,
          promoted_at: new Date().toISOString(),
        }));

        const { error: promotionsError } = await supabase
          .from("promotions")
          .insert(promotionRecords);

        if (promotionsError) {
          console.error(
            "[Promotion] Error recording promotions:",
            promotionsError,
          );
          // Don't fail the whole operation if promotion records fail
          // The students have already been promoted
          console.warn(
            "[Promotion] Students promoted but promotion records not saved",
          );
        }
      } else {
        console.log(
          "[Promotion] All students already have promotion records - skipping insert",
        );
      }

      console.log(
        `[Promotion] Successfully promoted ${students.length} students`,
      );

      return c.json({
        success: true,
        promoted_count: students.length,
        message: is_graduation
          ? `${students.length} students graduated successfully`
          : `${students.length} students promoted successfully`,
      });
    } catch (error) {
      console.error("[Promotion] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to promote students",
        },
        500,
      );
    }
  },
);

// Get recent promotions (for revert functionality)
app.get(
  "/make-server-1ddd013a/recent-promotions",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        !profile ||
        !["principal", "director", "it_admin"].includes(
          profile.role,
        )
      ) {
        return c.json(
          {
            success: false,
            error: "Unauthorized - Admin access required",
          },
          403,
        );
      }

      console.log(
        "[Recent Promotions] Fetching recent promotions...",
      );

      // Get recent promotions (last 30 days, not reverted)
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

      const { data: promotions, error: promotionsError } =
        await supabase
          .from("promotions")
          .select(
            `
        id,
        from_class_id,
        to_class_id,
        current_session,
        new_session,
        is_graduation,
        promoted_at,
        promoted_by,
        is_reverted
      `,
          )
          .gte("promoted_at", thirtyDaysAgo.toISOString())
          .order("promoted_at", { ascending: false })
          .limit(50);

      if (promotionsError) {
        console.error(
          "[Recent Promotions] Error fetching promotions:",
          promotionsError,
        );
        return c.json(
          {
            success: false,
            error: `Failed to fetch promotions: ${promotionsError.message}`,
          },
          500,
        );
      }

      // Get class names and promoted_by names
      const classIds = new Set<string>();
      const userIds = new Set<string>();

      promotions?.forEach((p) => {
        if (p.from_class_id) classIds.add(p.from_class_id);
        if (p.to_class_id) classIds.add(p.to_class_id);
        if (p.promoted_by) userIds.add(p.promoted_by);
      });

      // Fetch classes
      const { data: classes } = await supabase
        .from("classes")
        .select("id, name")
        .in("id", Array.from(classIds));

      const classMap = new Map(
        classes?.map((c) => [c.id, c.name]) || [],
      );

      // Fetch users
      const { data: users } = await supabase
        .from("profiles")
        .select("id, first_name, last_name")
        .in("id", Array.from(userIds));

      const userMap = new Map(
        users?.map((u) => [
          u.id,
          `${u.first_name} ${u.last_name}`,
        ]) || [],
      );

      // Count students for each promotion
      const promotionsWithDetails = await Promise.all(
        (promotions || []).map(async (promotion) => {
          // Count how many students were promoted
          let query = supabase
            .from("promotions")
            .select("id", { count: "exact", head: true })
            .eq("from_class_id", promotion.from_class_id)
            .eq("current_session", promotion.current_session)
            .eq("new_session", promotion.new_session)
            .gte(
              "promoted_at",
              new Date(promotion.promoted_at).toISOString(),
            )
            .lte(
              "promoted_at",
              new Date(
                new Date(promotion.promoted_at).getTime() +
                  60000,
              ).toISOString(),
            ); // Within 1 minute

          // Handle null to_class_id for graduations
          if (promotion.to_class_id === null) {
            query = query.is("to_class_id", null);
          } else {
            query = query.eq("to_class_id", promotion.to_class_id);
          }

          const { count } = await query;

          return {
            id: promotion.id,
            from_class_id: promotion.from_class_id,
            to_class_id: promotion.to_class_id,
            from_class_name: classMap.get(
              promotion.from_class_id,
            ),
            to_class_name: promotion.to_class_id
              ? classMap.get(promotion.to_class_id)
              : null,
            student_count: count || 0,
            current_session: promotion.current_session,
            new_session: promotion.new_session,
            is_graduation: promotion.is_graduation,
            promoted_at: promotion.promoted_at,
            promoted_by_name: userMap.get(
              promotion.promoted_by,
            ),
            is_reverted: promotion.is_reverted || false,
          };
        }),
      );

      // Group by promotion batch (same from_class, to_class, session, time)
      const groupedPromotions = new Map<
        string,
        (typeof promotionsWithDetails)[0]
      >();

      promotionsWithDetails.forEach((p) => {
        const key = `${p.from_class_id}-${p.to_class_id}-${p.current_session}-${p.new_session}`;
        if (!groupedPromotions.has(key)) {
          groupedPromotions.set(key, p);
        }
      });

      const uniquePromotions = Array.from(
        groupedPromotions.values(),
      );

      console.log(
        "[Recent Promotions] Found promotions:",
        uniquePromotions.length,
      );

      return c.json({
        success: true,
        promotions: uniquePromotions,
      });
    } catch (error) {
      console.error("[Recent Promotions] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch recent promotions",
        },
        500,
      );
    }
  },
);

// Revert a promotion (move students back to original class)
app.post(
  "/make-server-1ddd013a/revert-promotion",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        !profile ||
        !["principal", "director", "it_admin"].includes(
          profile.role,
        )
      ) {
        return c.json(
          {
            success: false,
            error: "Unauthorized - Admin access required",
          },
          403,
        );
      }

      const body = await c.req.json();
      const { promotion_id } = body;

      if (!promotion_id) {
        return c.json(
          { success: false, error: "Missing promotion_id" },
          400,
        );
      }

      console.log(
        "[Revert Promotion] Reverting promotion:",
        promotion_id,
      );

      // Get the promotion record
      const { data: promotion, error: promotionError } =
        await supabase
          .from("promotions")
          .select("*")
          .eq("id", promotion_id)
          .single();

      if (promotionError || !promotion) {
        console.error(
          "[Revert Promotion] Promotion not found:",
          promotionError,
        );
        return c.json(
          {
            success: false,
            error: "Promotion record not found",
          },
          404,
        );
      }

      // Allow reverting multiple times for testing/fixing mistakes
      // if (promotion.is_reverted) {
      //   return c.json(
      //     { success: false, error: "This promotion has already been reverted" },
      //     400
      //   );
      // }

      if (promotion.is_reverted) {
        console.log(
          "[Revert Promotion] ⚠️ Reverting an already reverted promotion (allowed for testing)",
        );
      }

      // Get all students who were part of this promotion batch
      let promotionQuery = supabase
        .from("promotions")
        .select("student_id, from_class_id, to_class_id")
        .eq("from_class_id", promotion.from_class_id)
        .eq("current_session", promotion.current_session)
        .eq("new_session", promotion.new_session)
        .gte(
          "promoted_at",
          new Date(promotion.promoted_at).toISOString(),
        )
        .lte(
          "promoted_at",
          new Date(
            new Date(promotion.promoted_at).getTime() + 60000,
          ).toISOString(),
        ); // Within 1 minute of original promotion

      // Handle null to_class_id for graduations
      if (promotion.to_class_id === null) {
        promotionQuery = promotionQuery.is("to_class_id", null);
      } else {
        promotionQuery = promotionQuery.eq(
          "to_class_id",
          promotion.to_class_id,
        );
      }

      const { data: promotionRecords, error: recordsError } =
        await promotionQuery;

      if (
        recordsError ||
        !promotionRecords ||
        promotionRecords.length === 0
      ) {
        console.error(
          "[Revert Promotion] Error finding promotion records:",
          recordsError,
        );
        console.log("[Revert Promotion] Query params:", {
          from_class_id: promotion.from_class_id,
          to_class_id: promotion.to_class_id,
          current_session: promotion.current_session,
          new_session: promotion.new_session,
          promoted_at: promotion.promoted_at,
        });
        return c.json(
          {
            success: false,
            error: "No promotion records found to revert",
          },
          404,
        );
      }

      console.log(
        `[Revert Promotion] Found ${promotionRecords.length} students to revert`,
      );
      console.log(
        `[Revert Promotion] Student IDs to revert:`,
        promotionRecords.map((r) => r.student_id),
      );

      // Move students back to their original class
      const studentIds = promotionRecords.map(
        (r) => r.student_id,
      );

      console.log(
        `[Revert Promotion] ⬅️ Moving ${studentIds.length} students back to class:`,
        promotion.from_class_id,
      );
      console.log(
        `[Revert Promotion] FROM class (current):`,
        promotion.to_class_id || "GRADUATED",
      );
      console.log(
        `[Revert Promotion] TO class (original):`,
        promotion.from_class_id,
      );

      const { data: updateData, error: updateError } =
        await supabase
          .from("profiles")
          .update({ class_id: promotion.from_class_id })
          .in("id", studentIds)
          .select("id, first_name, last_name, class_id");

      if (updateError) {
        console.error(
          "[Revert Promotion] ❌ Error reverting students:",
          updateError,
        );
        console.error(
          "[Revert Promotion] Error details:",
          JSON.stringify(updateError, null, 2),
        );
        return c.json(
          {
            success: false,
            error: `Failed to revert students: ${updateError.message}`,
          },
          500,
        );
      }

      console.log(
        `[Revert Promotion] ✅ Successfully updated ${updateData?.length || 0} students`,
      );
      console.log(
        `[Revert Promotion] Updated students:`,
        updateData?.map((s) => ({
          name: `${s.first_name || ""} ${s.last_name || ""}`.trim(),
          class_id: s.class_id,
        })),
      );

      // Mark all promotion records as reverted
      let markQuery = supabase
        .from("promotions")
        .update({
          is_reverted: true,
          reverted_by: user.id,
          reverted_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq("from_class_id", promotion.from_class_id)
        .eq("current_session", promotion.current_session)
        .eq("new_session", promotion.new_session)
        .gte(
          "promoted_at",
          new Date(promotion.promoted_at).toISOString(),
        )
        .lte(
          "promoted_at",
          new Date(
            new Date(promotion.promoted_at).getTime() + 60000,
          ).toISOString(),
        );

      // Handle null to_class_id for graduations
      if (promotion.to_class_id === null) {
        markQuery = markQuery.is("to_class_id", null);
      } else {
        markQuery = markQuery.eq(
          "to_class_id",
          promotion.to_class_id,
        );
      }

      const { error: markError } = await markQuery;

      if (markError) {
        console.error(
          "[Revert Promotion] Error marking as reverted:",
          markError,
        );
        // Don't fail - students are already moved back
      }

      console.log(
        `[Revert Promotion] 🎉 Successfully reverted ${studentIds.length} students`,
      );
      console.log(
        `[Revert Promotion] ========================================`,
      );

      return c.json({
        success: true,
        reverted_count:
          studentIds.length || updateData?.length || 0,
        message: `${studentIds.length} students returned to original class`,
      });
    } catch (error) {
      console.error("[Revert Promotion] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to revert promotion",
        },
        500,
      );
    }
  },
);

