// Get uploads organized by NEW hierarchical folder structure
// Structure: Session -> Term -> Level (Junior/Senior) -> Class -> Subject -> Type (Exam Questions/E-Notes) -> Week (for E-Notes)
app.get("/make-server-1ddd013a/uploads/browse", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    console.log(
      "[Browse Uploads] Fetching uploads for user:",
      user.id,
    );

    // Get user profile
    const { data: profile } = await supabase
      .from("profiles")
      .select("role, class_id")
      .eq("id", user.id)
      .single();

    if (!profile) {
      return c.json(
        { success: false, error: "Profile not found" },
        404,
      );
    }

    // Fetch academic sessions and terms from settings
    const { data: academicCalendar } = await supabase
      .from("academic_calendar")
      .select("*")
      .order("created_at", { ascending: false });

    const { data: terms } = await supabase
      .from("academic_terms")
      .select("*")
      .order("term_name");

    // Fetch all classes with sections
    const { data: classes } = await supabase
      .from("classes")
      .select("id, name, level, section")
      .order("name");

    // Fetch all subjects with their level classification
    const { data: subjects } = await supabase
      .from("subjects")
      .select("id, name, level")
      .order("name");

    // Build uploads query based on role
    let query = supabase
      .from("uploads")
      .select("*")
      .order("created_at", { ascending: false });

    // Students only see uploads for their class
    if (profile.role === "student" && profile.class_id) {
      query = query.eq("class_id", profile.class_id); // Filter by student's class
    }

    const { data: uploadsData, error } = await query;

    if (error) {
      console.error("[Browse Uploads] Database error:", error);
      return c.json(
        { success: false, error: error.message },
        500,
      );
    }

    let uploads = uploadsData || [];

    console.log(
      `[Browse Uploads] 🔍 BEFORE filtering: ${uploads.length} uploads`,
    );
    console.log(
      `[Browse Uploads] 👤 User: ${profile.role}, Class ID: ${profile.class_id || "N/A"}`,
    );

    // Log what class IDs are in the uploads
    if (uploads.length > 0) {
      const classIds = [
        ...new Set(uploads.map((u) => u.class_id)),
      ];
      console.log(
        `[Browse Uploads] 📚 Upload class IDs found:`,
        classIds,
      );
    }

    // ✅ JAVASCRIPT FILTER: Filter out corrupted sessions (access tokens, invalid formats, etc.)
    const beforeFilterCount = uploads.length;
    uploads = uploads.filter((upload) => {
      const session = upload.session;
      // Valid session format: YYYY/YYYY (e.g., "2025/2026")
      const isValid =
        session &&
        typeof session === "string" &&
        /^\d{4}\/\d{4}$/.test(session);

      if (!isValid) {
        console.log(
          `[Browse Uploads] ⚠️  FILTERED OUT: upload ${upload.id} with bad session: "${String(session).substring(0, 50)}..."`,
        );
      }

      return isValid;
    });

    console.log(
      `[Browse Uploads] 🧹 Filtered out ${beforeFilterCount - uploads.length} corrupted uploads`,
    );

    console.log(
      `[Browse Uploads] ✅ AFTER filtering: ${uploads.length} valid uploads with proper sessions`,
    );

    if (uploads.length > 0) {
      // Show unique sessions found
      const uniqueSessions = [
        ...new Set(uploads.map((u) => u.session)),
      ];
      console.log(
        "[Browse Uploads] 📅 Valid sessions found:",
        uniqueSessions,
      );
      console.log("[Browse Uploads] 📄 Sample valid upload:", {
        session: uploads[0].session,
        term: uploads[0].term,
        type: uploads[0].type,
        class_id: uploads[0].class_id,
      });
    } else {
      console.log(
        "[Browse Uploads] ❌ NO VALID UPLOADS FOUND!",
      );
      console.log("[Browse Uploads] 🔴 PROBLEM DIAGNOSIS:");
      console.log("  → Student's class_id:", profile.class_id);
      console.log(
        "  → Uploads fetched before filter:",
        beforeFilterCount,
      );
      console.log("  → This means:");
      if (beforeFilterCount === 0) {
        console.log(
          "    ❌ NO uploads exist for this student's class_id in database",
        );
        console.log(
          "    💡 FIX: Check if student is assigned to correct class",
        );
        console.log(
          "    💡 FIX: Check if uploads have correct class_id",
        );
      } else {
        console.log(
          "    ❌ All uploads have CORRUPTED sessions (access tokens, etc.)",
        );
        console.log(
          "    💡 FIX: Clean up corrupted session data in uploads table",
        );
      }
    }

    // Manually fetch related data if uploads exist
    if (uploads.length > 0) {
      const teacherIds = [
        ...new Set(
          uploads.map((u) => u.teacher_id).filter(Boolean),
        ),
      ];
      const subjectIds = [
        ...new Set(
          uploads.map((u) => u.subject_id).filter(Boolean),
        ),
      ];
      const classIds = [
        ...new Set(
          uploads.map((u) => u.class_id).filter(Boolean),
        ),
      ];

      // Fetch teachers
      const { data: teachers } = await supabase
        .from("profiles")
        .select("id, first_name, last_name")
        .in("id", teacherIds);

      // Fetch subjects for uploads
      const { data: uploadSubjects } = await supabase
        .from("subjects")
        .select("id, name, level")
        .in("id", subjectIds);

      // Fetch classes for uploads
      const { data: uploadClasses } = await supabase
        .from("classes")
        .select("id, name, level, section")
        .in("id", classIds);

      // Create lookup maps
      const teacherMap = new Map(
        teachers?.map((t) => [t.id, t]) || [],
      );
      const subjectMap = new Map(
        uploadSubjects?.map((s) => [s.id, s]) || [],
      );
      const classMap = new Map(
        uploadClasses?.map((c) => [c.id, c]) || [],
      );

      // Enrich uploads with related data
      uploads = uploads.map((upload) => ({
        ...upload,
        uploader: teacherMap.get(upload.teacher_id) || null,
        subject: subjectMap.get(upload.subject_id) || null,
        class: classMap.get(upload.class_id) || null,
      }));
    }

    // Build folder structure DIRECTLY from actual uploads
    const organized: any = {};

    // Now populate with actual upload data - only valid sessions after JavaScript filter
    for (const upload of uploads) {
      const session = upload.session || "2024/2025";
      const term = upload.term || "First Term";
      const classData = upload.class;
      const level = classData?.level || "junior"; // junior or senior
      const className = classData
        ? `${classData.name}${classData.section ? ` ${classData.section}` : ""}`
        : "General";
      const subjectData = upload.subject;
      const subjectName = subjectData?.name || "General";
      const uploadType = upload.type || "resource"; // enote or exam_question
      const week = upload.week || 1;

      // Build nested structure
      if (!organized[session]) {
        organized[session] = {};
      }
      if (!organized[session][term]) {
        organized[session][term] = {};
      }
      if (!organized[session][term][level]) {
        organized[session][term][level] = {};
      }
      if (!organized[session][term][level][className]) {
        organized[session][term][level][className] = {};
      }
      if (
        !organized[session][term][level][className][subjectName]
      ) {
        organized[session][term][level][className][
          subjectName
        ] = {
          "exam-questions": [],
          "e-notes": {},
          assignment: {},
          "other-resources": [],
        };
      }

      // Generate resource object
      const typeLabel =
        uploadType === "enote"
          ? "E-Notes"
          : uploadType === "exam_question"
            ? "Exam Questions"
            : uploadType === "assignment"
              ? "Assignment"
              : uploadType === "other_resources"
                ? "Other Resources"
                : "Resource";
      const generatedTitle = `${subjectName} - ${typeLabel}${upload.week ? ` (Week ${upload.week})` : ""}`;
      const fileName = upload.file_url
        ? upload.file_url.split("/").pop()?.split("?")[0]
        : "file";

      const resource = {
        id: upload.id,
        title: upload.title || generatedTitle, // ✅ Use actual title from database, fallback to generated
        fileName: upload.file_name || fileName, // ✅ Use actual filename from database
        fileType: upload.file_type || "pdf",
        fileSize: upload.file_size || 0,
        uploadedBy:
          `${upload.uploader?.first_name || ""} ${upload.uploader?.last_name || ""}`.trim() ||
          "Unknown",
        uploadedAt: upload.created_at,
        downloadCount: upload.download_count || 0,
        description: upload.description || "",
        version: upload.version || 1,
        url: upload.file_url,
      };

      // Organize by type - handle both singular and plural forms
      // Database uses: 'enote', 'exam_question', 'assignment', 'other_resources'
      if (
        uploadType === "exam_question" ||
        uploadType === "exam-question"
      ) {
        organized[session][term][level][className][subjectName][
          "exam-questions"
        ].push(resource);
      } else if (
        uploadType === "e-note" ||
        uploadType === "enote" ||
        uploadType === "e-notes"
      ) {
        if (
          !organized[session][term][level][className][
            subjectName
          ]["e-notes"][week]
        ) {
          organized[session][term][level][className][
            subjectName
          ]["e-notes"][week] = [];
        }
        organized[session][term][level][className][subjectName][
          "e-notes"
        ][week].push(resource);
      } else if (uploadType === "assignment") {
        if (
          !organized[session][term][level][className][
            subjectName
          ]["assignment"][week]
        ) {
          organized[session][term][level][className][
            subjectName
          ]["assignment"][week] = [];
        }
        organized[session][term][level][className][subjectName][
          "assignment"
        ][week].push(resource);
      } else if (
        uploadType === "other_resources" ||
        uploadType === "resource"
      ) {
        // Map old "resource" to "other-resources" for backwards compatibility
        organized[session][term][level][className][subjectName][
          "other-resources"
        ].push(resource);
      }
    }

    // Log the organized structure for debugging
    const sessionsFromUploads = Object.keys(organized)
      .sort()
      .reverse();

    if (sessionsFromUploads.length === 0) {
      console.log(
        "[Browse Uploads] ⚠️  WARNING: No sessions found in organized structure!",
      );
      console.log(
        "[Browse Uploads] This means NO valid uploads exist for this student's class.",
      );
      console.log("[Browse Uploads] Possible reasons:");
      console.log(
        "  - No uploads have been created for class_id:",
        profile.class_id,
      );
      console.log(
        "  - All uploads for this class have corrupted sessions",
      );
      console.log(
        "  - Student is not assigned to a class (class_id is null)",
      );
    } else {
      console.log(
        "[Browse Uploads] 📅 Sessions extracted from valid uploads:",
        sessionsFromUploads,
      );
    }

    for (const session of Object.keys(organized)) {
      console.log(
        `[Browse Uploads] Session "${session}" has terms:`,
        Object.keys(organized[session]),
      );
      for (const term of Object.keys(organized[session])) {
        const levels = Object.keys(organized[session][term]);
        console.log(
          `[Browse Uploads]   Term "${term}" has levels:`,
          levels,
        );
        for (const level of levels) {
          const classes = Object.keys(
            organized[session][term][level],
          );
          console.log(
            `[Browse Uploads]     Level "${level}" has classes:`,
            classes,
          );
        }
      }
    }

    // Return hierarchical metadata for navigation
    // IMPORTANT: Frontend uses folderStructure.organized to extract sessions, NOT folderStructure.sessions
    const folderStructure = {
      sessions: sessionsFromUploads, // For reference only - frontend uses organized directly
      terms: terms?.map((t) => t.name) || [],
      levels: ["junior", "senior"],
      classes: classes || [],
      subjects: subjects || [],
      organized: organized,
    };

    console.log(
      "[Browse Uploads] �� Returning",
      sessionsFromUploads.length,
      "sessions:",
      sessionsFromUploads,
    );
    return c.json({ success: true, folderStructure });
  } catch (error) {
    console.error("[Browse Uploads] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch uploads",
      },
      500,
    );
  }
});

