// NEW: Get academic sessions and terms from academic_calendar table
app.get(
  "/make-server-1ddd013a/uploads/sessions-terms",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      console.log(
        "[Sessions/Terms] Fetching all sessions and terms",
      );

      // ✅ FIX: Fetch ALL sessions and ALL terms from their respective tables
      // Don't limit to academic_calendar as that only has active session-term combinations
      const [
        { data: allSessions, error: sessionsError },
        { data: allTerms, error: termsError }
      ] = await Promise.all([
        supabase
          .from("academic_sessions")
          .select("session_name")
          .order("session_name", { ascending: false }),
        supabase
          .from("academic_terms")
          .select("term_name")
          .order("term_name", { ascending: true })
      ]);

      if (sessionsError || termsError) {
        console.error("[Sessions/Terms] Error:", sessionsError || termsError);
        return c.json(
          { success: false, error: (sessionsError || termsError)?.message },
          500,
        );
      }

      // Extract unique sessions
      const uniqueSessions = allSessions?.map(s => s.session_name).filter(Boolean) || [];

      // Create session-terms mapping: Each session has ALL available terms
      const sessionTerms: Record<string, string[]> = {};
      const allTermNames = allTerms?.map(t => t.term_name).filter(Boolean) || [];
      
      uniqueSessions.forEach((session) => {
        sessionTerms[session] = allTermNames;
      });

      console.log(
        "[Sessions/Terms] ✅ Found sessions:",
        uniqueSessions,
      );
      console.log(
        "[Sessions/Terms] ✅ Session-Terms mapping:",
        sessionTerms,
      );

      return c.json({
        success: true,
        sessions: uniqueSessions,
        sessionTerms: sessionTerms,
      });
    } catch (error) {
      console.error("[Sessions/Terms] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch sessions/terms",
        },
        500,
      );
    }
  },
);

// NEW: Get uploads filtered by session, term, and resource type
// This replaces the complex organized structure with simple filtering
app.post("/make-server-1ddd013a/uploads/files", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      console.error(
        "[Upload Files] ❌ No access token provided",
      );
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      console.error("[Upload Files] ❌ No user found");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    console.log("[Upload Files] 👤 User ID:", user.id);

    // Get user profile with detailed logging
    const { data: profile, error: profileError } =
      await supabase
        .from("profiles")
        .select("id, role, class_id, first_name, last_name")
        .eq("id", user.id)
        .single();

    if (profileError) {
      console.error(
        "[Upload Files] ❌ Profile fetch error:",
        profileError,
      );
      return c.json(
        {
          success: false,
          error:
            "Profile fetch failed: " + profileError.message,
        },
        500,
      );
    }

    if (!profile) {
      console.error(
        "[Upload Files] ❌ Profile not found for user:",
        user.id,
      );
      return c.json(
        { success: false, error: "Profile not found" },
        404,
      );
    }

    console.log("[Upload Files] 👤 Profile found:", {
      id: profile.id,
      role: profile.role,
      class_id: profile.class_id,
      name: `${profile.first_name} ${profile.last_name}`,
    });

    const body = await c.req.json();
    const { session, term, resourceType, week } = body;

    console.log("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    console.log("[Upload Files] 📥 FETCHING FILES");
    console.log("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    console.log("[Upload Files] Request:", {
      session,
      term,
      resourceType,
      week,
    });
    console.log("[Upload Files] User:", {
      role: profile.role,
      class_id: profile.class_id,
    });

    // Map frontend resource type to backend type (match actual database values)
    const typeMap: Record<string, string> = {
      "Exam Questions": "exam_question", // Database uses underscore, no 's'
      "E-Notes": "enote", // Database uses 'enote' (NOT 'e-note'!)
      Assignments: "assignment", // Database uses this
      Resources: "other_resources", // Old name - map to new type
      "Other Resources": "other_resources", // NEW - Database uses this
    };
    const backendType = typeMap[resourceType] || resourceType;
    console.log("[Upload Files] Type mapping:", {
      frontend: resourceType,
      backend: backendType,
    });

    // DEBUG: Check what e-notes exist in the database
    const { data: allENotes, error: debugError } =
      await supabase
        .from("uploads")
        .select(
          "id, title, type, session, term, week, class_id",
        )
        .eq("type", "e-note");

    console.log("���━━ DATABASE DEBUG ━━���");
    console.log(
      "[Upload Files] 🔍 ALL E-NOTES in database:",
      allENotes?.length || 0,
    );
    if (allENotes && allENotes.length > 0) {
      console.log("[Upload Files] 📋 E-Notes found:");
      allENotes.forEach((note, idx) => {
        console.log(
          `  ${idx + 1}. "${note.title}" - Session: "${note.session}", Term: "${note.term}", Week: ${note.week}, Class: "${note.class_id}"`,
        );
      });
    }
    console.log("━━━━━━━━━━━━━━━━━━━━━");

    // Build query
    console.log("━━━ BUILDING QUERY ━━━");
    console.log("[Upload Files] Query filters will be:");
    console.log(`  session = "${session}"`);
    console.log(`  term = "${term}"`);
    console.log(`  type = "${backendType}"`);
    if (week !== undefined && week !== null) {
      console.log(`  week = ${week} (${typeof week})`);
    }
    if (profile.role === "student" && profile.class_id) {
      console.log(
        `  class_id = "${profile.class_id}" (student filter)`,
      );
    }
    console.log("━━━━━━━━━━━━━━━━━━━━━");

    let query = supabase
      .from("uploads")
      .select("*")
      .eq("session", session)
      .eq("term", term)
      .eq("type", backendType)
      .order("created_at", { ascending: false });

    // Filter by week if provided (for E-Notes and Assignments)
    if (week !== undefined && week !== null) {
      console.log("[Upload Files] 📅 Week filter applied:", {
        weekValue: week,
        weekType: typeof week,
        isNumber: typeof week === "number",
      });
      query = query.eq("week", week);
    } else {
      console.log(
        "[Upload Files] ℹ️ No week filter (week is undefined/null)",
      );
    }

    // Students only see uploads for their class
    if (profile.role === "student" && profile.class_id) {
      console.log(
        "[Upload Files] 🎓 Student filter applied - class_id:",
        profile.class_id,
      );
      query = query.eq("class_id", profile.class_id);
    } else {
      console.log(
        "[Upload Files] 👨‍🏫 No class filter (teacher/admin)",
      );
    }

    const { data: uploads, error } = await query;

    if (error) {
      console.error("[Upload Files] ❌ Database error:", error);
      return c.json(
        { success: false, error: error.message },
        500,
      );
    }

    console.log("━━━ QUERY RESULTS ━━━");
    console.log(
      `[Upload Files] ✅ Query successful - Found ${uploads?.length || 0} uploads`,
    );

    if (uploads && uploads.length > 0) {
      console.log("[Upload Files] ��� Files found:");
      uploads.forEach((upload, idx) => {
        console.log(`  ${idx + 1}. "${upload.title}"`);
        console.log(
          `     Type: "${upload.type}", Week: ${upload.week}, Class: "${upload.class_id}"`,
        );
        console.log(
          `     Session: "${upload.session}", Term: "${upload.term}"`,
        );
      });

      // Show all weeks found in results
      const weeksFound = [
        ...new Set(uploads.map((u) => u.week)),
      ].filter((w) => w !== null && w !== undefined);
      console.log(
        "[Upload Files] 📅 Weeks in results:",
        weeksFound,
      );
    } else {
      console.log("[Upload Files] ❌ NO UPLOADS FOUND!");
      console.log("[Upload Files] 🔍 Possible reasons:");
      console.log(
        "  1. Session/Term mismatch (check exact spelling/spacing)",
      );
      console.log(
        "  2. Type mismatch (should be 'e-note' in database)",
      );
      console.log(
        "  3. Week mismatch (should be numeric: 1, 2, 3, etc.)",
      );
      console.log(
        "  4. Class ID mismatch (student's class doesn't match upload)",
      );
      console.log(
        "  5. No files uploaded yet for these filters",
      );
    }
    console.log("━━━━━━━━━━━━━━━━━━━━━");

    // Fetch related data
    console.log(
      "[Upload Files] 🔄 Fetching related data (teacher names, subject info, etc.)...",
    );
    const files = await Promise.all(
      (uploads || []).map(async (upload) => {
        // Get teacher name
        let teacherName = "Unknown";
        if (upload.teacher_id) {
          const { data: teacher } = await supabase
            .from("profiles")
            .select("first_name, last_name")
            .eq("id", upload.teacher_id)
            .single();
          if (teacher) {
            teacherName = `${teacher.first_name} ${teacher.last_name}`;
          }
        }

        // Get admin name if uploaded by admin
        if (upload.admin_id) {
          const { data: admin } = await supabase
            .from("profiles")
            .select("first_name, last_name")
            .eq("id", upload.admin_id)
            .single();
          if (admin) {
            teacherName = `${admin.first_name} ${admin.last_name} (Admin)`;
          }
        }

        // Get subject name and code
        let subjectName = "Unknown Subject";
        let subjectCode = "";
        if (upload.subject_id) {
          const { data: subject } = await supabase
            .from("subjects")
            .select("name, code")
            .eq("id", upload.subject_id)
            .single();
          if (subject) {
            subjectName = subject.name;
            subjectCode = subject.code || "";
          }
        }

        // Get class name
        let className = "";
        if (upload.class_id) {
          const { data: classData } = await supabase
            .from("classes")
            .select("name")
            .eq("id", upload.class_id)
            .single();
          if (classData) {
            className = classData.name;
          }
        }

        return {
          id: upload.id,
          title: upload.title,
          fileName: upload.file_name,
          fileType:
            upload.file_name?.split(".").pop() || "unknown",
          fileSize: upload.file_size || 0,
          uploadedBy: teacherName,
          uploadedAt: upload.created_at,
          downloadCount: upload.download_count || 0,
          description: upload.description,
          version: upload.version || 1,
          url: upload.file_url,
          subjectName: subjectName,
          subjectCode: subjectCode,
          className: className,
        };
      }),
    );

    console.log(
      "[Upload Files] ✅ Successfully formatted",
      files.length,
      "files",
    );
    console.log("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");

    return c.json({
      success: true,
      files: files,
    });
  } catch (error) {
    console.error("[Upload Files] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch files",
      },
      500,
    );
  }
});

