// Get teachers list for admin upload on behalf
app.get(
  "/make-server-1ddd013a/teachers-for-upload",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Verify user is admin/principal/IT admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        profile?.role !== "admin" &&
        profile?.role !== "principal" &&
        profile?.role !== "it_admin"
      ) {
        return c.json(
          {
            success: false,
            error:
              "Access denied - Admin/Principal/IT Admin only",
          },
          403,
        );
      }

      console.log("[Teachers For Upload] Fetching teachers...");

      // Fetch all teachers
      const { data: teachers, error } = await supabase
        .from("profiles")
        .select("id, first_name, middle_name, last_name, email")
        .eq("role", "teacher")
        .order("first_name");

      if (error) {
        console.error("[Teachers For Upload] Error:", error);
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      const teachersList = (teachers || []).map((t) => ({
        id: t.id,
        name: `${t.first_name} ${t.middle_name || ""} ${t.last_name}`
          .replace(/\s+/g, " ")
          .trim(),
        email: t.email,
      }));

      console.log(
        "[Teachers For Upload] Found teachers:",
        teachersList.length,
      );

      return c.json({ success: true, teachers: teachersList });
    } catch (error) {
      console.error("[Teachers For Upload] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch teachers",
        },
        500,
      );
    }
  },
);

