// GET /uploads/compliance - Fetch teacher compliance data
app.get(
  "/make-server-1ddd013a/uploads/compliance",
  async (c) => {
    try {
      console.log(
        "[Compliance] Fetching teacher compliance data...",
      );

      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Verify user is admin (admin, principal, or it_admin)
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        profile?.role !== "admin" &&
        profile?.role !== "principal" &&
        profile?.role !== "it_admin"
      ) {
        return c.json(
          { success: false, error: "Forbidden - Admin only" },
          403,
        );
      }

      // Fetch all teachers
      const { data: teachers, error: teachersError } =
        await supabase
          .from("profiles")
          .select(
            "id, first_name, middle_name, last_name, email",
          )
          .eq("role", "teacher")
          .order("first_name", { ascending: true });

      if (teachersError) {
        console.error(
          "[Compliance] Error fetching teachers:",
          teachersError,
        );
        return c.json(
          { success: false, error: teachersError.message },
          500,
        );
      }

      console.log(
        `[Compliance] Found ${teachers?.length || 0} teachers`,
      );

      // Get query parameters for filtering
      const session = c.req.query("session");
      const term = c.req.query("term");

      console.log("[Compliance] 🔍 Filters:", { session, term });

      // Fetch all uploads with optional filtering
      let uploadsQuery = supabase
        .from("uploads")
        .select(
          "id, title, teacher_id, subject_id, type, week, term, session, created_at, uploaded_by_admin, admin_id",
        );

      // Filter by session and term if provided
      if (session) {
        console.log(`[Compliance] 🔍 Filtering by session: "${session}"`);
        uploadsQuery = uploadsQuery.eq("session", session);
      }
      if (term) {
        console.log(`[Compliance] 🔍 Filtering by term: "${term}"`);
        uploadsQuery = uploadsQuery.eq("term", term);
      }

      const { data: uploads, error: uploadsError } =
        await uploadsQuery;

      console.log(`[Compliance] ✅ Found ${uploads?.length || 0} uploads after filtering`);

      if (uploadsError) {
        console.error(
          "[Compliance] Error fetching uploads:",
          uploadsError,
        );
        return c.json(
          { success: false, error: uploadsError.message },
          500,
        );
      }

      // Fetch all subjects
      const { data: subjects, error: subjectsError } =
        await supabase
          .from("subjects")
          .select("id, name");

      if (subjectsError) {
        console.error(
          "[Compliance] Error fetching subjects:",
          subjectsError,
        );
        return c.json(
          { success: false, error: subjectsError.message },
          500,
        );
      }

      // Fetch subject assignments to get teacher-subject relationships
      const { data: assignments, error: assignmentsError } =
        await supabase
          .from("subject_assignments")
          .select("teacher_id, subject_id, class_id");

      if (assignmentsError) {
        console.error(
          "[Compliance] Error fetching assignments:",
          assignmentsError,
        );
        return c.json(
          { success: false, error: assignmentsError.message },
          500,
        );
      }

      console.log(`[Compliance] ✅ Found ${assignments?.length || 0} subject assignments`);

      // Fetch current deadlines to determine requirements - filter by session/term
      let deadlinesQuery = supabase
        .from("upload_deadlines")
        .select("*")
        .eq("enabled", true);

      if (session) {
        console.log(`[Compliance] 🔍 Filtering deadlines by session: "${session}"`);
        deadlinesQuery = deadlinesQuery.eq("session", session);
      }
      if (term) {
        console.log(`[Compliance] 🔍 Filtering deadlines by term: "${term}"`);
        deadlinesQuery = deadlinesQuery.eq("term", term);
      }

      const { data: deadlines, error: deadlinesError } = await deadlinesQuery;
      
      console.log(`[Compliance] ✅ Found ${deadlines?.length || 0} deadlines after filtering`);

      // Build compliance data for each teacher
      const complianceData =
        teachers?.map((teacher) => {
          const teacherName =
            `${teacher.first_name || ""} ${teacher.middle_name || ""} ${teacher.last_name || ""}`
              .trim()
              .replace(/\s+/g, " ");

          // Get subject assignments for this teacher
          const teacherAssignments =
            assignments?.filter(
              (a) => a.teacher_id === teacher.id,
            ) || [];
          
          // Get unique subjects taught by this teacher
          const teacherSubjectIds = [...new Set(teacherAssignments.map(a => a.subject_id))];
          const teacherSubjects = subjects?.filter(s => teacherSubjectIds.includes(s.id)) || [];

          // Get uploads by this teacher
          const teacherUploads =
            uploads?.filter(
              (u) => u.teacher_id === teacher.id,
            ) || [];

          // Calculate basic stats based on actual deadlines
          const now = new Date();
          const submitted = teacherUploads.length;

          // Calculate required uploads based on active deadlines for this teacher's subjects
          let totalRequired = 0;
          let overdue = 0;

          if (
            deadlines &&
            deadlines.length > 0 &&
            teacherSubjects.length > 0
          ) {
            // For each subject taught by this teacher
            teacherSubjects.forEach((subject) => {
              // For each active deadline
              deadlines.forEach((deadline) => {
                // Check if this deadline applies to this subject (or all subjects if no subject specified)
                const deadlineApplies =
                  !deadline.subject_id ||
                  deadline.subject_id === subject.id;

                if (deadlineApplies) {
                  totalRequired++;

                  // Check if teacher has uploaded for this deadline
                  const hasUpload = teacherUploads.some(
                    (upload) =>
                      upload.subject_id === subject.id &&
                      upload.type === deadline.upload_type &&
                      upload.week === deadline.week_number &&
                      upload.term === deadline.term &&
                      upload.session === deadline.session,
                  );

                  // If no upload and deadline passed, it's overdue
                  if (
                    !hasUpload &&
                    new Date(deadline.deadline) < now
                  ) {
                    overdue++;
                  }
                }
              });
            });
          } else if (!session && !term) {
            // ONLY use fallback estimate if NO filters are applied
            // If session/term filters are active but no deadlines found, totalRequired should be 0
            totalRequired = teacherSubjects.length * 3;
          }
          // Otherwise totalRequired remains 0 (no deadlines for filtered session/term)

          const pending = Math.max(
            0,
            totalRequired - submitted,
          );
          const complianceRate =
            totalRequired > 0
              ? Math.round((submitted / totalRequired) * 100)
              : 100;

          // Determine status (overdue takes priority)
          let status:
            | "compliant"
            | "partial"
            | "non-compliant"
            | "overdue" = "compliant";
          if (overdue > 0) {
            status = "overdue";
          } else if (complianceRate < 50) {
            status = "non-compliant";
          } else if (complianceRate < 90) {
            status = "partial";
          }

          // Get last submission date
          const lastSubmission =
            teacherUploads.length > 0
              ? new Date(
                  teacherUploads.sort(
                    (a, b) =>
                      new Date(b.created_at).getTime() -
                      new Date(a.created_at).getTime(),
                  )[0].created_at,
                )
              : undefined;

          // Build upload summaries
          const uploadSummaries = teacherUploads
            .slice(0, 5)
            .map((upload) => ({
              id: upload.id,
              title: upload.title || "Untitled",
              subject:
                subjects?.find(
                  (s) => s.id === upload.subject_id,
                )?.name || "Unknown",
              week: upload.week || 0,
              term: upload.term || "",
              session: upload.session || "",
              uploadType: upload.type || "",
              status: "submitted" as const,
              submittedAt: new Date(upload.created_at),
              deadline: new Date(), // Would come from deadlines
              uploadedByAdmin:
                upload.uploaded_by_admin || false,
              adminId: upload.admin_id,
            }));

          return {
            teacherId: teacher.id,
            teacherName,
            email: teacher.email || "",
            subjects: teacherSubjects.map((s) => s.name),
            totalRequired,
            submitted,
            pending,
            overdue,
            complianceRate,
            lastSubmission,
            status,
            uploads: uploadSummaries,
          };
        }) || [];

      console.log(
        `[Compliance] Returning compliance data for ${complianceData.length} teachers`,
      );

      return c.json({
        success: true,
        complianceData,
      });
    } catch (error) {
      console.error("[Compliance] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch compliance data",
        },
        500,
      );
    }
  },
);

