// GET /students-with-profiles - Fetch all students with complete profile data from KV store
app.get(
  "/make-server-1ddd013a/students-with-profiles",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Get class_id filter if provided
      const url = new URL(c.req.url);
      const classIdFilter = url.searchParams.get("class_id");

      // Fetch all students from profiles table (exclude graduated students)
      let query = supabase
        .from("profiles")
        .select(
          "id, first_name, middle_name, last_name, email, class_id",
        )
        .eq("role", "student")
        .or("is_graduated.is.null,is_graduated.eq.false");

      if (classIdFilter) {
        query = query.eq("class_id", classIdFilter);
      }

      const { data: students, error: studentsError } =
        await query;

      if (studentsError) {
        return c.json(
          {
            success: false,
            error: `Failed to fetch students: ${studentsError.message}`,
          },
          500,
        );
      }

      // Fetch classes for display names
      const { data: classes } = await supabase
        .from("classes")
        .select("id, name, sections(name)");

      const classMap: Record<string, string> = {};
      classes?.forEach((cls: any) => {
        // Note: cls.name already includes the section
        const display_name = cls.name;
        classMap[cls.id] = display_name;
      });

      // Fetch complete profile data from KV store for each student
      const studentsWithProfiles = await Promise.all(
        (students || []).map(async (student) => {
          const kvData =
            (await kv.get(`student_profile_${student.id}`)) ||
            {};
          return {
            id: student.id,
            first_name: student.first_name,
            middle_name: student.middle_name,
            last_name: student.last_name,
            email: student.email,
            class_id: student.class_id,
            class_name: student.class_id
              ? classMap[student.class_id]
              : "Unassigned",
            gender: kvData.gender || "",
            phone: kvData.phone || "",
            address: kvData.address || "",
            parent_name: kvData.parent_name || "",
            parent_phone: kvData.parent_phone || "",
            state_of_origin: kvData.state_of_origin || "",
            lga: kvData.lga || "",
            date_of_birth: kvData.date_of_birth || "",
          };
        }),
      );

      return c.json({
        success: true,
        students: studentsWithProfiles,
        total: studentsWithProfiles.length,
      });
    } catch (error) {
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch students with profiles",
        },
        500,
      );
    }
  },
);

// GET /classes-stats - Fetch classes with student counts
app.get("/make-server-1ddd013a/classes-stats", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Fetch all classes
    const { data: classes, error: classesError } =
      await supabase
        .from("classes")
        .select("id, name, level, sections(name)")
        .order("name", { ascending: true });

    if (classesError) {
      return c.json(
        {
          success: false,
          error: `Failed to fetch classes: ${classesError.message}`,
        },
        500,
      );
    }

    // Fetch all students
    const { data: students, error: studentsError } =
      await supabase
        .from("profiles")
        .select("id, class_id")
        .eq("role", "student")
        .or("is_graduated.is.null,is_graduated.eq.false");

    if (studentsError) {
      return c.json(
        {
          success: false,
          error: `Failed to fetch students: ${studentsError.message}`,
        },
        500,
      );
    }

    // Count students per class
    const classStudentCount: Record<string, number> = {};
    let studentsWithClass = 0;
    let studentsWithoutClass = 0;
    
    students?.forEach((student) => {
      if (student.class_id) {
        classStudentCount[student.class_id] =
          (classStudentCount[student.class_id] || 0) + 1;
        studentsWithClass++;
      } else {
        studentsWithoutClass++;
      }
    });

    // Map classes with student counts and display names
    const classesWithStats = (classes || []).map(
      (cls: any) => ({
        class_id: cls.id,
        // Note: cls.name already includes the section
        class_name: cls.name,
        level: cls.level,
        student_count: classStudentCount[cls.id] || 0,
      }),
    );

    return c.json({
      success: true,
      classes: classesWithStats,
      total: classesWithStats.length,
      total_students: students?.length || 0,
      students_with_class: studentsWithClass,
      students_without_class: studentsWithoutClass,
    });
  } catch (error) {
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch classes stats",
      },
      500,
    );
  }
});

// GET /students-debug - Debug endpoint to verify student counts in database
app.get("/make-server-1ddd013a/students-debug", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Query 1: All students (including graduated)
    const { data: allStudents, error: allError } =
      await supabase
        .from("profiles")
        .select("id, first_name, last_name, class_id, is_graduated")
        .eq("role", "student");

    // Query 2: Active students only (non-graduated)
    const { data: activeStudents, error: activeError } =
      await supabase
        .from("profiles")
        .select("id, first_name, last_name, class_id, is_graduated")
        .eq("role", "student")
        .or("is_graduated.is.null,is_graduated.eq.false");

    // Query 3: Count by class_id
    const classBreakdown: Record<string, number> = {};
    let withClass = 0;
    let withoutClass = 0;
    let graduated = 0;
    
    activeStudents?.forEach((student) => {
      if (student.class_id) {
        classBreakdown[student.class_id] = (classBreakdown[student.class_id] || 0) + 1;
        withClass++;
      } else {
        withoutClass++;
      }
    });

    allStudents?.forEach((student) => {
      if (student.is_graduated) {
        graduated++;
      }
    });

    return c.json({
      success: true,
      summary: {
        total_all_students: allStudents?.length || 0,
        total_active_students: activeStudents?.length || 0,
        total_graduated_students: graduated,
        active_with_class: withClass,
        active_without_class: withoutClass,
      },
      class_breakdown: classBreakdown,
      sample_students: activeStudents?.slice(0, 5).map(s => ({
        id: s.id,
        name: `${s.first_name} ${s.last_name}`,
        class_id: s.class_id || 'null',
        is_graduated: s.is_graduated || false,
      })),
      sql_queries: {
        total_students: "SELECT COUNT(*) FROM profiles WHERE role = 'student' AND (is_graduated IS NULL OR is_graduated = false);",
        with_class: "SELECT COUNT(*) FROM profiles WHERE role = 'student' AND (is_graduated IS NULL OR is_graduated = false) AND class_id IS NOT NULL;",
        without_class: "SELECT COUNT(*) FROM profiles WHERE role = 'student' AND (is_graduated IS NULL OR is_graduated = false) AND class_id IS NULL;",
        by_class: "SELECT class_id, COUNT(*) as count FROM profiles WHERE role = 'student' AND (is_graduated IS NULL OR is_graduated = false) AND class_id IS NOT NULL GROUP BY class_id;",
      }
    });
  } catch (error) {
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch student debug info",
      },
      500,
    );
  }
});

// GET /students-by-class - Fetch students for a specific class (for marks entry)
// SESSION-AWARE: Returns UNION of current students + students with existing marks
app.get(
  "/make-server-1ddd013a/students-by-class",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const classId = c.req.query("class_id");
      const examId = c.req.query("exam_id");
      const subjectId = c.req.query("subject_id");

      if (!classId) {
        return c.json(
          {
            success: false,
            error: "class_id parameter is required",
          },
          400,
        );
      }

      console.log("[Students By Class] Session-aware fetch:", {
        classId,
        examId,
        subjectId,
      });

      // STRATEGY: UNION of two sets
      // SET A: Current students in the class (for new marks entry)
      // SET B: Students with existing marks for this exam/subject (historical - may be promoted)

      const studentMap = new Map();

      // SET A: Fetch current students in the class (exclude graduated students)
      const { data: currentStudents, error: currentError } =
        await supabase
          .from("profiles")
          .select(
            `
        id,
        first_name,
        middle_name,
        last_name,
        email,
        class_id,
        admission_number
      `,
          )
          .eq("role", "student")
          .eq("class_id", classId)
          .or("is_graduated.is.null,is_graduated.eq.false")
          .order("first_name", { ascending: true });

      if (currentError) {
        console.error(
          "[Students By Class] Error fetching current students:",
          currentError,
        );
        return c.json(
          {
            success: false,
            error: `Failed to fetch students: ${currentError.message}`,
          },
          500,
        );
      }

      // Add current students to map (will be filtered by subject offerings if subjectId provided)
      currentStudents?.forEach((student) => {
        studentMap.set(student.id, student);
      });

      console.log(
        `[Students By Class] Found ${currentStudents?.length || 0} current students in class ${classId}`,
      );

      // ✅ SUBJECT OFFERING FILTER: If subject_id provided, filter current students by offerings
      if (
        subjectId &&
        currentStudents &&
        currentStudents.length > 0
      ) {
        console.log(
          `[Students By Class] Filtering students by subject offerings for subject: ${subjectId}`,
        );

        // Get current session from KV store
        const currentSessionData =
          await kv.get("active_session");

        // Build query to find which students offer this subject
        let query = supabase
          .from("student_subjects")
          .select("student_id")
          .eq("subject_id", subjectId)
          .eq("class_id", classId)
          .eq("status", "active");

        // Only filter by session if one is configured in KV store
        // If no session is configured, count ALL active student subject assignments
        if (currentSessionData) {
          query = query.eq("session", currentSessionData);
          console.log(
            `[Students By Class] Filtering by session: ${currentSessionData}`,
          );
        } else {
          console.log(
            "[Students By Class] No active session configured - filtering by all active assignments",
          );
        }

        const { data: studentSubjects, error: offeringsError } =
          await query;

        if (offeringsError) {
          console.warn(
            "[Students By Class] Could not filter by subject offerings:",
            offeringsError,
          );
          // Continue without filtering - IT Admin may not have configured offerings yet
        } else if (
          studentSubjects &&
          studentSubjects.length > 0
        ) {
          const offeringStudentIds = new Set(
            studentSubjects.map((ss) => ss.student_id),
          );

          // Remove current students who don't offer this subject
          let removedCount = 0;
          for (const [
            studentId,
            student,
          ] of studentMap.entries()) {
            // Only filter current students (those with class_id matching classId)
            if (
              student.class_id === classId &&
              !offeringStudentIds.has(studentId)
            ) {
              studentMap.delete(studentId);
              removedCount++;
            }
          }

          console.log(
            `[Students By Class] ��� Filtered to ${offeringStudentIds.size} students offering this subject (removed ${removedCount} non-offering students)`,
          );
        } else {
          const sessionInfo = currentSessionData
            ? `for session ${currentSessionData}`
            : "(no session filter)";
          console.warn(
            `[Students By Class] ⚠️ No students configured to offer subject ${subjectId} in class ${classId} ${sessionInfo}`,
          );
          console.warn(
            "[Students By Class] Please configure subject offerings in Subject Offerings Management",
          );
          // ✅ STRICT MODE: Clear all current students if no offerings configured
          // Teachers should only see students assigned to their subject
          console.warn(
            "[Students By Class] 🚫 STRICT MODE: Clearing all current students - only showing students with existing marks",
          );
          // Remove all current students (keep only those with historical marks)
          for (const [
            studentId,
            student,
          ] of studentMap.entries()) {
            if (student.class_id === classId) {
              studentMap.delete(studentId);
            }
          }
        }
      }

      // SET B: If exam_id and subject_id provided, fetch students with existing marks
      // This handles the PROMOTED STUDENTS case - they have marks but are no longer in the class
      // ⚠️ CRITICAL FIX: Only fetch students whose marks are for THIS CLASS
      if (examId && subjectId) {
        console.log(
          `[Students By Class] Fetching historical students with marks for exam: ${examId}, subject: ${subjectId}, class: ${classId}`,
        );

        // Get marks for this exam/subject/class combination (both midterm and terminal)
        // ✅ CRITICAL: Filter by class_id to prevent cross-class student leakage
        const { data: existingMarks, error: marksError } =
          await supabase
            .from("marks")
            .select("student_id")
            .eq("exam_id", examId)
            .eq("subject_id", subjectId)
            .eq("class_id", classId);

        if (marksError) {
          console.error(
            "[Students By Class] Error fetching historical marks:",
            marksError,
          );
          // Don't fail - just continue with current students
        } else if (existingMarks && existingMarks.length > 0) {
          // Get unique student IDs from marks
          const historicalStudentIds = [
            ...new Set(existingMarks.map((m) => m.student_id)),
          ];

          console.log(
            `[Students By Class] Found ${historicalStudentIds.length} unique students with existing marks`,
          );

          // Fetch profiles for these historical students (if not already in map)
          const missingStudentIds = historicalStudentIds.filter(
            (id) => !studentMap.has(id),
          );

          if (missingStudentIds.length > 0) {
            console.log(
              `[Students By Class] Fetching ${missingStudentIds.length} promoted students with historical marks`,
            );

            const {
              data: historicalStudents,
              error: histError,
            } = await supabase
              .from("profiles")
              .select(
                `
              id,
              first_name,
              middle_name,
              last_name,
              email,
              class_id,
              admission_number
            `,
              )
              .in("id", missingStudentIds)
              .eq("role", "student");

            if (histError) {
              console.error(
                "[Students By Class] Error fetching historical student profiles:",
                histError,
              );
            } else {
              // Add historical students to map
              historicalStudents?.forEach((student) => {
                studentMap.set(student.id, student);
              });

              console.log(
                `[Students By Class] Added ${historicalStudents?.length || 0} promoted students to results`,
              );
            }
          }
        }
      }

      // Convert map to array and sort by name
      const allStudents = Array.from(studentMap.values()).sort(
        (a, b) => a.first_name.localeCompare(b.first_name),
      );

      console.log(
        `[Students By Class] TOTAL: Returning ${allStudents.length} students (current + historical)`,
      );

      return c.json({
        success: true,
        students: allStudents,
        total_students: allStudents.length,
        breakdown: {
          current: currentStudents?.length || 0,
          historical:
            allStudents.length - (currentStudents?.length || 0),
        },
      });
    } catch (error) {
      console.error("[Students By Class] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch students",
        },
        500,
      );
    }
  },
);

