// GET /teacher-class-info - Check if teacher is a class teacher
app.get(
  "/make-server-1ddd013a/teacher-class-info",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is assigned as class_teacher_id in any class
      // ✅ FIX: Add retry logic for connection errors (broken pipe)
      let classes = null;
      let classError = null;
      let retries = 3;

      while (retries > 0) {
        const result = await supabase
          .from("classes")
          .select("id, name, level")
          .eq("class_teacher_id", user.id)
          .limit(1);

        classes = result.data;
        classError = result.error;

        if (!classError) break;

        // If it's a connection error, retry
        if (
          classError.message?.includes("connection") ||
          classError.message?.includes("pipe")
        ) {
          console.log(
            `[Teacher Class Info] Connection error, retrying... (${retries} attempts left)`,
          );
          retries--;
          await new Promise((resolve) =>
            setTimeout(resolve, 500),
          ); // Wait 500ms before retry
        } else {
          break;
        }
      }

      if (classError) {
        console.error(
          "[Teacher Class Info] Error:",
          classError,
        );
        return c.json(
          { success: false, error: classError.message },
          500,
        );
      }

      const isClassTeacher = classes && classes.length > 0;

      return c.json({
        success: true,
        isClassTeacher,
        classInfo: isClassTeacher ? classes[0] : null,
      });
    } catch (error) {
      console.error("[Teacher Class Info] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to check class teacher status",
        },
        500,
      );
    }
  },
);

// GET /teacher-overview - Get teacher dashboard overview stats
app.get("/make-server-1ddd013a/teacher-overview", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // ✅ FIX: Use verifyUserAuth instead of supabase.auth.getUser(accessToken)
    const {
      data: { user },
      error: authError,
    } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      console.error("[Teacher Overview] Auth error:", authError?.message || "User not found");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // 🔥 Get session and term from query parameters
    const session = c.req.query("session");
    const term = c.req.query("term");

    console.log(
      "[Teacher Overview] Fetching assignments for teacher:",
      user.id,
      { session, term }
    );

    // Get subject assignments for this teacher
    const { data: assignments, error: assignmentsError } =
      await supabase
        .from("subject_assignments")
        .select(
          `
        subject_id,
        class_id,
        subjects (id, name)
      `,
        )
        .eq("teacher_id", user.id);

    if (assignmentsError) {
      console.error(
        "[Teacher Overview] Error fetching assignments:",
        assignmentsError,
      );
    }

    console.log(
      "[Teacher Overview] Found assignments:",
      assignments?.length || 0,
    );

    // Get unique subjects taught by this teacher
    const uniqueSubjects = new Map();
    const uniqueClasses = new Set();

    (assignments || []).forEach((assignment: any) => {
      if (assignment.subjects) {
        uniqueSubjects.set(
          assignment.subject_id,
          assignment.subjects,
        );
      }
      uniqueClasses.add(assignment.class_id);
    });

    const subjects = Array.from(uniqueSubjects.values());
    const uniqueClassIds = Array.from(uniqueClasses);

    console.log(
      "[Teacher Overview] Unique subjects:",
      subjects.length,
    );
    console.log(
      "[Teacher Overview] Unique classes:",
      uniqueClassIds.length,
    );

    // Check if class teacher
    const { data: classTeacherInfo } = await supabase
      .from("classes")
      .select("id, name, sections(name)")
      .eq("class_teacher_id", user.id)
      .limit(1)
      .single();

    // Get student count if class teacher
    let studentCount = 0;
    if (classTeacherInfo) {
      const { count } = await supabase
        .from("profiles")
        .select("id", { count: "exact", head: true })
        .eq("role", "student")
        .eq("class_id", classTeacherInfo.id)
        .or("is_graduated.is.null,is_graduated.eq.false");
      studentCount = count || 0;
    }

    // Get pending marks (marks in draft, submitted, or pending_approval status)
    // 🔥 Filter by session and term if provided
    let pendingMarksQuery = supabase
      .from("marks")
      .select("id")
      .in("subject_id", subjects?.map((s) => s.id) || [])
      .in("status", ["draft", "submitted", "pending_approval"]);
    
    if (session) {
      pendingMarksQuery = pendingMarksQuery.eq("session", session);
    }
    if (term) {
      pendingMarksQuery = pendingMarksQuery.eq("term", term);
    }

    const { data: pendingMarks } = await pendingMarksQuery;

    // Format class name with section if available
    // Note: classTeacherInfo.name already includes the section
    const formattedClassName = classTeacherInfo
      ? classTeacherInfo.name
      : "";

    // Get school settings
    const schoolSettings = await kv.get("school_settings");

    return c.json({
      success: true,
      stats: {
        totalSubjects: subjects?.length || 0,
        totalClasses: uniqueClassIds.length,
        pendingMarks: pendingMarks?.length || 0,
        upcomingClasses: 0, // Can be enhanced with timetable data
        isClassTeacher: !!classTeacherInfo,
        className: formattedClassName,
        studentCount,
      },
      recentActivities: [], // Can be enhanced with activity log
      schoolInfo: schoolSettings ? {
        school_name: schoolSettings.school_name,
        logo_url: schoolSettings.logo_url,
        motto: schoolSettings.motto
      } : null,
    });
  } catch (error) {
    console.error("[Teacher Overview] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch overview",
      },
      500,
    );
  }
});

// GET /teacher-broadsheet - Get comprehensive marks broadsheet for all classes a teacher teaches
app.get("/make-server-1ddd013a/teacher-broadsheet", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const teacherId = c.req.query("teacher_id");
    const session = c.req.query("session");
    const term = c.req.query("term");
    const exam = c.req.query("exam");
    const type = c.req.query("type"); // midterm or terminal

    if (!session || !term || !exam || !type) {
      return c.json(
        { success: false, error: "Missing required parameters: session, term, exam, type" },
        400,
      );
    }

    console.log(`[Teacher Broadsheet] Fetching for teacher ${teacherId || user.id}:`, { session, term, exam, type });

    // Get all classes this teacher teaches (via subject_assignments)
    // Using same structure as /my-subjects endpoint
    const { data: assignments, error: assignError } = await supabase
      .from("subject_assignments")
      .select(`
        subject_id,
        class_id,
        subjects (id, name),
        classes (id, name, level, sections(name))
      `)
      .eq("teacher_id", teacherId || user.id);

    if (assignError) {
      console.error("[Teacher Broadsheet] Error fetching assignments:", assignError);
      return c.json(
        { success: false, error: "Failed to fetch teacher assignments" },
        500,
      );
    }

    console.log(`[Teacher Broadsheet] Found ${assignments?.length || 0} assignments`);

    // Group by class + subject combination (each subject gets its own broadsheet)
    // This prevents confusion when a teacher teaches multiple subjects in the same class
    const broadsheetSections = [];
    
    (assignments || []).forEach((assignment: any) => {
      const classId = assignment.class_id;
      const subjectId = assignment.subject_id;
      const className = assignment.classes?.name || 'Unknown Class';
      const subjectName = assignment.subjects?.name || 'Unknown Subject';
      
      // Each class+subject combination is a separate broadsheet section
      broadsheetSections.push({
        classId,
        className,
        subjectId,
        subjectName,
      });
    });

    console.log(`[Teacher Broadsheet] Created ${broadsheetSections.length} broadsheet sections (class+subject combinations)`);

    // Build broadsheet for each class + subject combination
    const broadsheet = [];
    
    for (const section of broadsheetSections) {
      console.log(`[Teacher Broadsheet] Processing ${section.className} - ${section.subjectName}`);

      // Get students assigned to this specific subject in this class
      const { data: studentSubjects, error: studentSubjectsError } = await supabase
        .from("student_subjects")
        .select("student_id")
        .eq("class_id", section.classId)
        .eq("subject_id", section.subjectId)
        .eq("status", "active");

      if (studentSubjectsError) {
        console.error(`[Teacher Broadsheet] Error fetching student subjects:`, studentSubjectsError);
        continue;
      }

      // Get unique student IDs
      const uniqueStudentIds = [...new Set(studentSubjects?.map((ss: any) => ss.student_id) || [])];

      if (uniqueStudentIds.length === 0) {
        console.log(`[Teacher Broadsheet] No students assigned to ${section.subjectName} in ${section.className}`);
        // Still add the section but with empty students array
        broadsheet.push({
          classId: section.classId,
          className: section.className,
          subjectId: section.subjectId,
          subjectName: section.subjectName,
          students: [],
        });
        continue;
      }

      console.log(`[Teacher Broadsheet] Found ${uniqueStudentIds.length} students for ${section.subjectName}`);

      // Now get student details for these IDs
      const { data: students, error: studentsError } = await supabase
        .from("profiles")
        .select("id, first_name, middle_name, last_name")
        .in("id", uniqueStudentIds)
        .eq("role", "student")
        .or("is_graduated.is.null,is_graduated.eq.false")
        .order("last_name", { ascending: true })
        .order("first_name", { ascending: true });

      if (studentsError) {
        console.error(`[Teacher Broadsheet] Error fetching students:`, studentsError);
        continue;
      }

      console.log(`[Teacher Broadsheet] Found ${students?.length || 0} student profiles`);

      // For each student, get marks for THIS subject only
      const studentsWithMarks = [];
      
      for (const student of students || []) {
        const studentName = `${student.first_name} ${student.middle_name || ''} ${student.last_name}`.trim();

        // Fetch marks for this student + subject + session + term + exam + type
        const { data: marks } = await supabase
          .from("marks")
          .select("*")
          .eq("student_id", student.id)
          .eq("subject_id", section.subjectId)
          .eq("session", session)
          .eq("term", term)
          .eq("exam", exam)
          .limit(1)
          .maybeSingle();

        let ca1 = null;
        let ca2 = null;
        let examMark = null;
        let total = null;

        if (marks) {
          if (type === 'midterm') {
            ca1 = marks.midterm_ca1;
            ca2 = marks.midterm_ca2;
            examMark = marks.midterm_exam;
            
            // Calculate total
            const scores = [ca1, ca2, examMark].filter(v => v !== null);
            if (scores.length > 0) {
              total = scores.reduce((sum, v) => sum + v, 0);
            }
          } else if (type === 'terminal') {
            ca1 = marks.terminal_ca1;
            ca2 = marks.terminal_ca2;
            examMark = marks.terminal_exam;
            
            // Calculate total
            const scores = [ca1, ca2, examMark].filter(v => v !== null);
            if (scores.length > 0) {
              total = scores.reduce((sum, v) => sum + v, 0);
            }
          }
        }

        studentsWithMarks.push({
          studentId: student.id,
          studentName,
          ca1,
          ca2,
          exam: examMark,
          total,
        });
      }

      broadsheet.push({
        classId: section.classId,
        className: section.className,
        subjectId: section.subjectId,
        subjectName: section.subjectName,
        students: studentsWithMarks,
      });
    }

    console.log(`[Teacher Broadsheet] ✅ Generated broadsheet for ${broadsheet.length} sections`);

    return c.json({
      success: true,
      broadsheet,
    });
  } catch (error) {
    console.error("[Teacher Broadsheet] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch broadsheet",
      },
      500,
    );
  }
});

// GET /my-class - Get class teacher's class information and students
app.get("/make-server-1ddd013a/my-class", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Get the class where this teacher is the class teacher
    const { data: classInfo, error: classError } =
      await supabase
        .from("classes")
        .select("id, name, level, sections(name)")
        .eq("class_teacher_id", user.id)
        .limit(1)
        .single();

    if (classError || !classInfo) {
      return c.json(
        {
          success: false,
          error: "You are not assigned as a class teacher",
        },
        404,
      );
    }

    // Format class display name with section
    // Note: classInfo.name already includes the section
    const displayName = classInfo.name;

    const formattedClassInfo = {
      ...classInfo,
      name: displayName,
      display_name: displayName,
    };

    // Get students in this class
    const { data: students, error: studentsError } =
      await supabase
        .from("profiles")
        .select("id, first_name, middle_name, last_name, email")
        .eq("role", "student")
        .eq("class_id", classInfo.id)
        .or("is_graduated.is.null,is_graduated.eq.false")
        .order("first_name", { ascending: true });

    if (studentsError) {
      console.error(
        "[My Class] Error fetching students:",
        studentsError,
      );
      return c.json(
        { success: false, error: studentsError.message },
        500,
      );
    }

    // Fetch student profile photos from KV store
    const studentsWithPhotos = await Promise.all(
      (students || []).map(async (student) => {
        const profileKey = `student_profile_${student.id}`;
        const profile = (await kv.get(profileKey)) as any;
        return {
          ...student,
          photo_url: profile?.photo_url || ''
        };
      })
    );

    return c.json({
      success: true,
      classInfo: formattedClassInfo,
      students: studentsWithPhotos,
    });
  } catch (error) {
    console.error("[My Class] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch class data",
      },
      500,
    );
  }
});

// GET /my-subjects - Get teacher's assigned subjects
app.get("/make-server-1ddd013a/my-subjects", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      console.log("[My Subjects] No access token provided");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      console.log("[My Subjects] Invalid user from token");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    console.log(
      "[My Subjects] Fetching subjects for teacher:",
      user.id,
    );

    // Get subject assignments for this teacher with subject and class details
    const { data: assignments, error: assignmentsError } =
      await supabase
        .from("subject_assignments")
        .select(
          `
          subject_id,
          class_id,
          subjects (id, name, code),
          classes (id, name, level, sections(name))
        `,
        )
        .eq("teacher_id", user.id);

    if (assignmentsError) {
      console.error(
        "[My Subjects] Error fetching assignments:",
        assignmentsError,
      );
      return c.json(
        { success: false, error: assignmentsError.message },
        500,
      );
    }

    console.log(
      "[My Subjects] Found assignments:",
      assignments?.length || 0,
    );

    // Group assignments by subject
    const subjectsMap = new Map();

    (assignments || []).forEach((assignment: any) => {
      if (assignment.subjects && assignment.classes) {
        const subjectId = assignment.subject_id;

        if (!subjectsMap.has(subjectId)) {
          subjectsMap.set(subjectId, {
            id: assignment.subjects.id,
            name: assignment.subjects.name,
            code: assignment.subjects.code,
            classes: [],
          });
        }

        // Add class with display_name
        const classData = {
          id: assignment.classes.id,
          name: assignment.classes.name,
          level: assignment.classes.level,
          // Note: assignment.classes.name already includes the section
          display_name: assignment.classes.name,
        };

        subjectsMap.get(subjectId).classes.push(classData);
      }
    });

    const subjectsWithClasses = Array.from(
      subjectsMap.values(),
    ).sort((a, b) => a.name.localeCompare(b.name));

    console.log(
      "[My Subjects] Returning subjects with classes:",
      JSON.stringify(subjectsWithClasses, null, 2),
    );

    return c.json({
      success: true,
      subjects: subjectsWithClasses,
    });
  } catch (error) {
    console.error("[My Subjects] Unexpected error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch subjects",
      },
      500,
    );
  }
});

// GET /teacher-list - Get list of all teachers (for teachers to view)
app.get("/make-server-1ddd013a/teacher-list", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Get all teachers
    const { data: teachers, error: teachersError } =
      await supabase
        .from("profiles")
        .select("id, first_name, middle_name, last_name, email")
        .eq("role", "teacher")
        .order("first_name", { ascending: true });

    if (teachersError) {
      console.error("[Teacher List] Error:", teachersError);
      return c.json(
        { success: false, error: teachersError.message },
        500,
      );
    }

    // For each teacher, get their subjects from assignments and if they're a class teacher
    const teachersWithInfo = await Promise.all(
      (teachers || []).map(async (teacher) => {
        // Get subject assignments for this teacher
        const { data: assignments } = await supabase
          .from("subject_assignments")
          .select("subject_id, subjects(name)")
          .eq("teacher_id", teacher.id);

        // Get unique subjects
        const uniqueSubjects = new Map();
        (assignments || []).forEach((assignment: any) => {
          if (assignment.subjects) {
            uniqueSubjects.set(
              assignment.subject_id,
              assignment.subjects.name,
            );
          }
        });

        // Check if class teacher
        const { data: classTeacher } = await supabase
          .from("classes")
          .select("name")
          .eq("class_teacher_id", teacher.id)
          .limit(1)
          .single();

        return {
          ...teacher,
          subjects: Array.from(uniqueSubjects.values()),
          isClassTeacher: !!classTeacher,
          className: classTeacher?.name || null,
        };
      }),
    );

    return c.json({
      success: true,
      teachers: teachersWithInfo,
    });
  } catch (error) {
    console.error("[Teacher List] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch teachers",
      },
      500,
    );
  }
});

