      if (updateData.amount) updateData.amount = parseFloat(updateData.amount);
      if (updateData.amount_paid) updateData.amount_paid = parseFloat(updateData.amount_paid);
      if (updateData.part_payment_number) updateData.part_payment_number = parseInt(updateData.part_payment_number);

      // Update payment (PATCH endpoint)
      const { data: updatedPayment, error: updateError } =
        await supabase
          .from("payments")
          .update({
            ...updateData,
            updated_at: new Date().toISOString(),
          })
          .eq("id", paymentId)
          .select("id, student_id, student_type, academic_year, term, amount, amount_paid, payment_date, payment_method, receipt_number, notes, part_payment_number, proof_of_payment_url, entered_by, approval_status, approved_by, created_at, updated_at")
