// GET /finance/student-discounts - Get all student discounts for a session
app.get(
  "/make-server-1ddd013a/finance/student-discounts",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Verify user is director or finance_admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        !profile ||
        !["director", "finance_admin"].includes(profile.role)
      ) {
        return c.json(
          { success: false, error: "Access denied" },
          403,
        );
      }

      const session_id = c.req.query("session_id");
      const term_id = c.req.query("term_id");

      // Support both old format (session string) and new format (session_id + term_id)
      let key: string;
      if (session_id && term_id) {
        // NEW: Fee items discount (per session+term)
        key = `fee_item_discounts:${session_id}:${term_id}`;
        console.log(
          "[Student Discounts] Fetching fee item discounts for session/term:",
          session_id,
          term_id,
        );
      } else {
        // OLD: Fallback to legacy format for old fee structure
        const session = c.req.query("session") || "2024/2025";
        key = `student_discounts:${session}`;
        console.log(
          "[Student Discounts] Fetching legacy discounts for session:",
          session,
        );
      }

      // Get discounts from KV store
      const discountsData = (await kv.get(key)) || {};

      // Get student details for each discount
      const discountsWithDetails = await Promise.all(
        Object.entries(discountsData).map(
          async ([student_id, discount]: [string, any]) => {
            const { data: student } = await supabase
              .from("profiles")
              .select(
                "first_name, last_name, class_id, student_type",
              )
              .eq("id", student_id)
              .single();

            // Get class name
            let className = null;
            if (student?.class_id) {
              const { data: classData } = await supabase
                .from("classes")
                .select("name, sections(name)")
                .eq("id", student.class_id)
                .single();

              if (classData) {
                // Note: classData.name already includes the section
                className = classData.name;
              }
            }

            return {
              student_id,
              student_name: student
                ? `${student.first_name} ${student.last_name}`
                : null,
              student_class: className,
              student_type: student?.student_type,
              discount_percentage: discount.percentage,
              reason: discount.reason,
              added_by: discount.added_by,
              added_at: discount.added_at,
            };
          },
        ),
      );

      return c.json({
        success: true,
        discounts: discountsWithDetails.filter(
          (d) => d.student_name,
        ), // Only return valid students
      });
    } catch (error) {
      console.error("[Student Discounts] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch student discounts",
        },
        500,
      );
    }
  },
);

