// GET /finance/student-discount/:studentId - Get discount for specific student
app.get(
  "/make-server-1ddd013a/finance/student-discount/:studentId",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const studentId = c.req.param("studentId");
      const session = c.req.query("session") || "2024/2025";
      const term = c.req.query("term") || "First Term";

      console.log(
        "[Student Discounts] Fetching discount for student:",
        studentId, session, term
      );

      // Get session ID and term ID for new discount system
      // Use session and term names directly as IDs
      const session_id = session;
      const term_id = term;

      let discount = null;

      // NEW SYSTEM: Use fee_item_discounts
      const newDiscountKey = `fee_item_discounts:${session_id}:${term_id}`;
      const discountsData = (await kv.get(newDiscountKey)) || {};
      discount = discountsData[studentId];

      // Fallback to old system if not found in new system
      if (!discount) {
        const oldKey = `student_discounts:${session}`;
        const oldDiscounts = (await kv.get(oldKey)) || {};
        discount = oldDiscounts[studentId];
      }

      if (!discount) {
        return c.json({
          success: true,
          has_discount: false,
          discount: null,
        });
      }

      return c.json({
        success: true,
        has_discount: true,
        discount: {
          percentage: discount.percentage,
          reason: discount.reason,
          added_at: discount.added_at,
        },
      });
    } catch (error) {
      console.error("[Student Discounts] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch student discount",
        },
        500,
      );
    }
  },
);

// GET /finance/fee-items/:studentId - Get assigned fee items for a student
app.get(
  "/make-server-1ddd013a/finance/fee-items/:studentId",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const studentId = c.req.param("studentId");
      const session = c.req.query("session");
      const term = c.req.query("term");

      console.log("[Finance] Fetching fee items for student:", {
        studentId,
        session,
        term,
      });

      if (!session || !term) {
        return c.json(
          {
            success: false,
            error: "Missing required parameters: session, term",
          },
          400,
        );
      }

      // Use session and term names directly as IDs
      const session_id = session;
      const term_id = term;

      // Get assigned fee items for this student
      const assignmentKey = `student_fee_assignments:${session_id}:${term_id}`;
      const assignments = (await kv.get(assignmentKey)) || {};
      const studentAssignment = assignments[studentId];

      if (!studentAssignment || !studentAssignment.fee_item_ids || studentAssignment.fee_item_ids.length === 0) {
        return c.json({
          success: true,
          fee_items: [],
        });
      }

      // Get fee items from fee_structure table by IDs (no need to filter by session/term since we have specific IDs)
      const { data: assignedFeeItems } = await supabase
        .from("fee_structure")
        .select("id, item_name, amount, is_tuition, is_compulsory")
        .in("id", studentAssignment.fee_item_ids);

      // Get student discount from NEW system
      const discountKey = `fee_item_discounts:${session_id}:${term_id}`;
      const discountsData = (await kv.get(discountKey)) || {};
      const studentDiscount = discountsData[studentId];

      console.log("[Finance] Student discount from NEW system:", studentDiscount);

      // Apply discount to tuition items
      const feeItemsWithDiscounts = assignedFeeItems.map((item: any) => {
        if (item.is_tuition && studentDiscount && studentDiscount.percentage > 0) {
          return {
            ...item,
            original_amount: item.amount,
            amount: item.amount * (1 - studentDiscount.percentage / 100),
            discount_applied: studentDiscount.percentage,
          };
        }
        return item;
      });

      console.log("[Finance] Returning fee items:", feeItemsWithDiscounts);

      return c.json({
        success: true,
        fee_items: feeItemsWithDiscounts,
      });
    } catch (error) {
      console.error("[Finance] Error fetching fee items:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch fee items",
        },
        500,
      );
    }
  },
);

// PUT /finance/student-type/:studentId - Update student type (Day/Boarding)
app.put(
  "/make-server-1ddd013a/finance/student-type/:studentId",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Verify user is finance admin or IT admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        !profile ||
        (profile.role !== "finance_admin" &&
          profile.role !== "it_admin")
      ) {
        return c.json(
          {
            success: false,
            error:
              "Only Finance Admin or IT Admin can update student type",
          },
          403,
        );
      }

      const studentId = c.req.param("studentId");
      const body = await c.req.json();
      const { student_type } = body;

      if (!student_type || (student_type !== "Day" && student_type !== "Boarding")) {
        return c.json(
          {
            success: false,
            error: "student_type must be either 'Day' or 'Boarding'",
          },
          400,
        );
      }

      console.log(
        "[Student Type Update] Updating student type:",
        {
          studentId,
          student_type,
        },
      );

      // Update student type in profiles table
      const { data: updateData, error: updateError } =
        await supabase
          .from("profiles")
          .update({ student_type })
          .eq("id", studentId)
          .eq("role", "student")
          .select()
          .single();

      if (updateError) {
        console.error(
          "[Student Type Update] Update error:",
          updateError,
        );
        return c.json(
          {
            success: false,
            error: `Failed to update student type: ${updateError.message}`,
          },
          500,
        );
      }

      if (!updateData) {
        return c.json(
          {
            success: false,
            error: "Student not found or not authorized to update",
          },
          404,
        );
      }

      console.log(
        "[Student Type Update] Updated successfully:",
        updateData,
      );

      return c.json({
        success: true,
        message: `Student type updated to ${student_type} successfully`,
        student: updateData,
      });
    } catch (error) {
      console.error("[Student Type Update] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to update student type",
        },
        500,
      );
    }
  },
);

// GET /finance/students-expected-fees - Get total expected fees from ALL students
app.get(
  "/make-server-1ddd013a/finance/students-expected-fees",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Verify user is director or finance admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        !profile ||
        !["director", "finance_admin"].includes(profile.role)
      ) {
        return c.json(
          { success: false, error: "Access denied" },
          403,
        );
      }

      const academicYear =
        c.req.query("academic_year") || "2025/2026";
      const term = c.req.query("term") || "First Term";

      console.log("[Students Expected Fees] Calculating for:", {
        academicYear,
        term,
      });

      // Get session and term IDs
      const { data: sessionData } = await supabase
        .from("academic_sessions")
        .select("id")
        .eq("session_name", academicYear)
        .maybeSingle();

      const { data: termData } = await supabase
        .from("academic_terms")
        .select("id")
        .eq("term_name", term)
        .maybeSingle();

      if (!sessionData || !termData) {
        return c.json({
          success: false,
          error: "Session or term not found",
        }, 404);
      }

      // Get all active students (not graduated)
      const { data: allStudents, error: studentsError } =
        await supabase
          .from("profiles")
          .select("id")
          .eq("role", "student")
          .or("is_graduated.is.null,is_graduated.eq.false");

      if (studentsError) {
        console.error(
          "[Students Expected Fees] Error fetching students:",
          studentsError,
        );
        return c.json(
          { success: false, error: "Failed to fetch students" },
          500,
        );
      }

      console.log(
        "[Students Expected Fees] Found students:",
        allStudents?.length || 0,
      );

      // Get clearance records from student_clearance table
      const { data: clearanceRecords } = await supabase
        .from("student_clearance")
        .select("required_amount")
        .eq("session_id", sessionData.id)
        .eq("term_id", termData.id);

      console.log(
        "[Students Expected Fees] Clearance records found:",
        clearanceRecords?.length || 0,
      );

      // Sum all required amounts
      const totalExpected = (clearanceRecords || []).reduce(
        (sum, record) => sum + (record.required_amount || 0),
        0
      );

      console.log(
        "[Students Expected Fees] Total expected:",
        totalExpected,
      );

      return c.json({
        success: true,
        total_expected: totalExpected,
        student_count: allStudents?.length || 0,
        academic_year: academicYear,
        term: term,
      });
    } catch (error) {
      console.error("[Students Expected Fees] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to calculate expected fees",
        },
        500,
      );
    }
  },
);

