// GET /finance/fee-items
app.get("/make-server-1ddd013a/finance/fee-items", async (c) => {
  try {
    const accessToken = c.req.header("Authorization")?.split(" ")[1];
    if (!accessToken) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: { user } } = await supabase.auth.getUser(accessToken);
    if (!user?.id) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: profile } = await supabase.from("profiles").select("role").eq("id", user.id).single();
    if (!profile || !["director", "finance_admin"].includes(profile.role)) {
      return c.json({ success: false, error: "Access denied" }, 403);
    }
    const sessionId = c.req.query("session_id");
    const termId = c.req.query("term_id");
    const classLevel = c.req.query("class_level");
    let query = supabase.from("fee_structure").select("*").order("is_tuition", { ascending: false }).order("item_name", { ascending: true });
    if (sessionId) query = query.eq("session_id", sessionId);
    if (termId) query = query.eq("term_id", termId);
    if (classLevel) query = query.eq("class_level", classLevel);
    const { data: feeItems, error } = await query;
    if (error) return c.json({ success: false, error: error.message }, 500);
    return c.json({ success: true, fee_items: feeItems || [] });
  } catch (error) {
    console.error("[Fee Items] Error:", error);
    return c.json({ success: false, error: error instanceof Error ? error.message : "Failed to fetch fee items" }, 500);
  }
});

// POST /finance/fee-items
app.post("/make-server-1ddd013a/finance/fee-items", async (c) => {
  try {
    const accessToken = c.req.header("Authorization")?.split(" ")[1];
    if (!accessToken) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: { user } } = await supabase.auth.getUser(accessToken);
    if (!user?.id) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: profile } = await supabase.from("profiles").select("role").eq("id", user.id).single();
    if (!profile || profile.role !== "director") {
      return c.json({ success: false, error: "Only directors can create fee items" }, 403);
    }
    const body = await c.req.json();
    const { item_name, amount, is_tuition, is_compulsory, session_id, term_id, class_level, student_type } = body;
    if (!item_name || !amount || !session_id || !term_id || !student_type) {
      return c.json({ success: false, error: "Missing required fields: item_name, amount, session_id, term_id, student_type" }, 400);
    }
    if (is_tuition) {
      const { data: existing } = await supabase.from("fee_structure").select("id").eq("session_id", session_id).eq("term_id", term_id).eq("class_level", class_level || "ALL").eq("student_type", student_type).eq("is_tuition", true).single();
      if (existing) return c.json({ success: false, error: "Tuition already exists for this session/term/class/student type" }, 400);
    }
    const { data: newItem, error } = await supabase.from("fee_structure").insert({
      item_name, amount: parseFloat(amount), is_tuition: is_tuition || false,
      is_compulsory: is_compulsory || false, session_id, term_id, class_level: class_level || "ALL",
      student_type: student_type, created_by: user.id
    }).select().single();
    if (error) return c.json({ success: false, error: error.message }, 500);
    return c.json({ success: true, fee_item: newItem, message: "Fee item created successfully" });
  } catch (error) {
    console.error("[Fee Items] Error:", error);
    return c.json({ success: false, error: error instanceof Error ? error.message : "Failed to create fee item" }, 500);
  }
});

