// DELETE /finance/fee-items/:id
app.delete("/make-server-1ddd013a/finance/fee-items/:id", async (c) => {
  try {
    const accessToken = c.req.header("Authorization")?.split(" ")[1];
    if (!accessToken) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: { user } } = await supabase.auth.getUser(accessToken);
    if (!user?.id) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: profile } = await supabase.from("profiles").select("role").eq("id", user.id).single();
    if (!profile || profile.role !== "director") {
      return c.json({ success: false, error: "Only directors can delete fee items" }, 403);
    }
    const id = c.req.param("id");
    const { data: assignments } = await supabase.from("fees").select("id").eq("fee_item_id", id).eq("is_active", true).limit(1);
    if (assignments && assignments.length > 0) {
      return c.json({ success: false, error: "Cannot delete - assigned to students" }, 400);
    }
    const { error } = await supabase.from("fee_structure").delete().eq("id", id);
    if (error) return c.json({ success: false, error: error.message }, 500);
    return c.json({ success: true, message: "Fee item deleted successfully" });
  } catch (error) {
    console.error("[Fee Items] Error:", error);
    return c.json({ success: false, error: error instanceof Error ? error.message : "Failed to delete fee item" }, 500);
  }
});

// GET /finance/student-fee-assignments - Get all students with their fee assignments
app.get("/make-server-1ddd013a/finance/student-fee-assignments", async (c) => {
  try {
    const accessToken = c.req.header("Authorization")?.split(" ")[1];
    if (!accessToken) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: { user } } = await supabase.auth.getUser(accessToken);
    if (!user?.id) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: profile } = await supabase.from("profiles").select("role").eq("id", user.id).single();
    if (!profile || !["director", "finance_admin"].includes(profile.role)) {
      return c.json({ success: false, error: "Access denied" }, 403);
    }

    const session_id = c.req.query("session_id");
    const term_id = c.req.query("term_id");

    console.log("[Student Fee Assignments] Fetching all students for session/term:", session_id, term_id);

    // Fetch all students (ONLY active students - not graduated)
    const { data: students, error: studentsError } = await supabase
      .from("profiles")
      .select("id, first_name, last_name, class_id, student_type")
      .eq("role", "student")
      .or("is_graduated.is.null,is_graduated.eq.false")
      .order("first_name");

    if (studentsError) {
      console.error("[Student Fee Assignments] Error fetching students:", studentsError);
      return c.json({ success: false, error: studentsError.message }, 500);
    }

    console.log(`[Student Fee Assignments] Found ${students?.length || 0} students`);

    // Fetch discounts for this session+term
    const discountKey = session_id && term_id ? `fee_item_discounts:${session_id}:${term_id}` : null;
    const discountsData = discountKey ? (await kv.get(discountKey)) || {} : {};

    console.log(`[Student Fee Assignments] Discount key: ${discountKey}`);
    console.log(`[Student Fee Assignments] Discounts data:`, JSON.stringify(discountsData));
    console.log(`[Student Fee Assignments] Loaded ${Object.keys(discountsData).length} discounts`);

    // Fetch assignments from KV store
    const assignmentKey = session_id && term_id ? `student_fee_assignments:${session_id}:${term_id}` : null;
    const assignmentsData = assignmentKey ? (await kv.get(assignmentKey)) || {} : {};

    console.log(`[Student Fee Assignments] Assignment key: ${assignmentKey}`);
    console.log(`[Student Fee Assignments] Assignments data:`, JSON.stringify(assignmentsData));
    console.log(`[Student Fee Assignments] Loaded assignments for ${Object.keys(assignmentsData).length} students`);

    // Fetch all fee items from fee_structure table
    let allFeeItems: any[] = [];
    if (session_id && term_id) {
      const { data: feeItemsData } = await supabase
        .from("fee_structure")
        .select("id, item_name, amount, is_tuition, is_compulsory, student_type, class_level")
        .eq("session_id", session_id)
        .eq("term_id", term_id);
      allFeeItems = feeItemsData || [];
    }

    console.log(`[Student Fee Assignments] Loaded ${allFeeItems.length} fee items from fee_structure table`);

    // Enrich each student with their assignments
    const enrichedStudents = await Promise.all(
      (students || []).map(async (student: any) => {
        // Get class name
        let className = null;
        if (student.class_id) {
          const { data: classData } = await supabase
            .from("classes")
            .select("name")
            .eq("id", student.class_id)
            .single();
          className = classData?.name || null;
        }

        // Get assigned fee item IDs from KV store
        const studentAssignment = assignmentsData[student.id];
        const assignedItemIds = studentAssignment?.fee_item_ids || [];

        // Calculate total with discount
        let totalRequired = 0;
        const assignedItems: any[] = [];
        const discount = discountsData[student.id]?.percentage || 0;

        assignedItemIds.forEach((itemId: string) => {
          const feeItem = allFeeItems.find((item: any) => item.id === itemId);
          if (!feeItem) return;

          let itemAmount = feeItem.amount;
          // Apply discount ONLY to tuition items
          if (feeItem.is_tuition && discount > 0) {
            itemAmount = itemAmount * (1 - discount / 100);
          }

          totalRequired += itemAmount;

          assignedItems.push({
            fee_item_id: feeItem.id,
            item_name: feeItem.item_name,
            amount: feeItem.amount,
            is_tuition: feeItem.is_tuition,
            is_compulsory: feeItem.is_compulsory,
          });
        });

        return {
          id: student.id,
          first_name: student.first_name,
          last_name: student.last_name,
          class_name: className,
          student_type: student.student_type,
          assigned_items: assignedItems,
          total_required: totalRequired,
          discount_percentage: discount,
        };
      })
    );

    console.log(`[Student Fee Assignments] Enriched ${enrichedStudents.length} students with assignments`);

    // Return with aggressive cache-busting headers
    const response = c.json({
      success: true,
      students: enrichedStudents,
      _timestamp: Date.now(),
    });
    
    response.headers.set('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    response.headers.set('Pragma', 'no-cache');
    response.headers.set('Expires', '0');
    
    return response;
  } catch (error) {
    console.error("[Student Fee Assignments] Error:", error);
    return c.json(
      {
        success: false,
        error: error instanceof Error ? error.message : "Failed to fetch student fee assignments",
      },
      500
    );
  }
});

// GET /finance/student-fee-assignments/:studentId
app.get("/make-server-1ddd013a/finance/student-fee-assignments/:studentId", async (c) => {
  try {
    const accessToken = c.req.header("Authorization")?.split(" ")[1];
    if (!accessToken) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: { user } } = await supabase.auth.getUser(accessToken);
    if (!user?.id) return c.json({ success: false, error: "Unauthorized" }, 401);
    const studentId = c.req.param("studentId");
    const sessionId = c.req.query("session_id");
    const termId = c.req.query("term_id");

    if (!sessionId || !termId) {
      return c.json({ success: false, error: "session_id and term_id are required" }, 400);
    }

    // Get assignments from KV store
    const assignmentKey = `student_fee_assignments:${sessionId}:${termId}`;
    const assignmentsData = (await kv.get(assignmentKey)) || {};
    const studentAssignment = assignmentsData[studentId];
    const assignedItemIds = studentAssignment?.fee_item_ids || [];

    // Get fee items from fee_structure table
    const { data: feeItemsData } = await supabase
      .from("fee_structure")
      .select("id, item_name, amount, is_tuition, is_compulsory")
      .eq("session_id", sessionId)
      .eq("term_id", termId);
    const allFeeItems = feeItemsData || [];

    // Get discount
    const discountKey = `fee_item_discounts:${sessionId}:${termId}`;
    const discountsData = (await kv.get(discountKey)) || {};
    const discount = discountsData[studentId]?.percentage || 0;

    // Build assignments array
    const assignments: any[] = [];
    let tuitionAmount = 0, tuitionDiscount = 0, discountedTuition = 0, otherFeesTotal = 0, grandTotal = 0;

    assignedItemIds.forEach((itemId: string) => {
      const feeItem = allFeeItems.find((item: any) => item.id === itemId);
      if (!feeItem) return;

      let itemAmount = feeItem.amount;
      if (feeItem.is_tuition) {
        tuitionAmount = feeItem.amount;
        tuitionDiscount = discount;
        if (discount > 0) {
          itemAmount = feeItem.amount * (1 - discount / 100);
        }
        discountedTuition = itemAmount;
        grandTotal += itemAmount;
      } else {
        otherFeesTotal += feeItem.amount;
        grandTotal += feeItem.amount;
      }

      assignments.push({
        fee_item_id: feeItem.id,
        item_name: feeItem.item_name,
        amount: feeItem.amount,
        is_tuition: feeItem.is_tuition,
        is_compulsory: feeItem.is_compulsory,
      });
    });

    return c.json({
      success: true, assignments,
      summary: { tuition_amount: tuitionAmount, tuition_discount_percentage: tuitionDiscount,
        discounted_tuition: discountedTuition, other_fees_total: otherFeesTotal, grand_total: grandTotal, items_count: assignments.length }
    });
  } catch (error) {
    console.error("[Student Fee Assignments] Error:", error);
    return c.json({ success: false, error: error instanceof Error ? error.message : "Failed to fetch" }, 500);
  }
});

// POST /finance/student-fee-assignments
app.post("/make-server-1ddd013a/finance/student-fee-assignments", async (c) => {
  try {
    const accessToken = c.req.header("Authorization")?.split(" ")[1];
    if (!accessToken) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: { user } } = await supabase.auth.getUser(accessToken);
    if (!user?.id) return c.json({ success: false, error: "Unauthorized" }, 401);
    const { data: profile } = await supabase.from("profiles").select("role").eq("id", user.id).single();
    if (!profile || profile.role !== "finance_admin") {
      return c.json({ success: false, error: "Only finance admins can assign fees" }, 403);
    }
    const body = await c.req.json();
    const { student_id, fee_item_ids, session_id, term_id } = body;
    if (!student_id || !fee_item_ids || !Array.isArray(fee_item_ids) || !session_id || !term_id) {
      return c.json({ success: false, error: "Missing required fields: student_id, fee_item_ids, session_id, term_id" }, 400);
    }

    console.log("[Student Fee Assignments] Assigning items:", { student_id, fee_item_ids, session_id, term_id });

    // Store assignments in KV store (NOT in fees table - that's for payments only)
    const assignmentKey = `student_fee_assignments:${session_id}:${term_id}`;
    const existingAssignments = (await kv.get(assignmentKey)) || {};
    
    // Update or create assignment for this student
    existingAssignments[student_id] = {
      fee_item_ids,
      assigned_by: user.id,
      assigned_at: new Date().toISOString(),
    };

    await kv.set(assignmentKey, existingAssignments);

    console.log("[Student Fee Assignments] Successfully assigned fee items to student");

    return c.json({ 
      success: true, 
      message: "Fee items assigned successfully",
      assignment: {
        student_id,
        fee_item_ids,
        session_id,
        term_id,
      }
    });
  } catch (error) {
    console.error("[Student Fee Assignments] Error:", error);
    return c.json({ success: false, error: error instanceof Error ? error.message : "Failed to assign" }, 500);
  }
});

