// Student Overview
app.get("/make-server-1ddd013a/student-overview", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Get student profile
    const { data: student } = await supabase
      .from("profiles")
      .select(
        "first_name, last_name, middle_name, email, class_id",
      )
      .eq("id", user.id)
      .single();

    // Get class info with section
    let classInfo = null;
    if (student?.class_id) {
      const { data: classData } = await supabase
        .from("classes")
        .select("name, level, sections(name)")
        .eq("id", student.class_id)
        .single();

      if (classData) {
        // Create display name that combines class name and section
        // Note: classData.name already includes the section
        const displayName = classData.name;

        classInfo = {
          name: displayName,
          level: classData.level,
        };
      }
    }

    // Get current session and term from database tables (not KV store)
    const { data: currentSession } = await supabase
      .from("academic_sessions")
      .select("*")
      .eq("is_current", true)
      .single();
    
    const { data: currentTerm } = await supabase
      .from("academic_terms")
      .select("*")
      .eq("is_current", true)
      .single();

    // Get subjects that the student is actually studying from student_subjects table
    let subjectsCount = 0;
    
    if (currentSession) {
      const { count, error: subjectsError } = await supabase
        .from("student_subjects")
        .select("id", { count: "exact" })
        .eq("student_id", user.id)
        .eq("session", currentSession.session_name);
      
      // If student_subjects table doesn't exist yet, fall back to subject_assignments
      if (subjectsError?.code === "42P01" && student?.class_id) {
        const { count: fallbackCount } = await supabase
          .from("subject_assignments")
          .select("id", { count: "exact" })
          .eq("class_id", student.class_id);
        subjectsCount = fallbackCount || 0;
      } else {
        subjectsCount = count || 0;
      }
    } else if (student?.class_id) {
      // Fallback if no current session: use subject_assignments
      const { count } = await supabase
        .from("subject_assignments")
        .select("id", { count: "exact" })
        .eq("class_id", student.class_id);
      subjectsCount = count || 0;
    }

    // Get upcoming exams for the student's class filtered by current session and term
    let upcomingExamsCount = 0;
    if (student?.class_id && currentSession && currentTerm) {
      const { count } = await supabase
        .from("exams")
        .select("id", { count: "exact" })
        .eq("session", currentSession.session_name)
        .eq("term", currentTerm.term_name)
        .gte("end_datetime", new Date().toISOString());
      upcomingExamsCount = count || 0;
    }

    // Get published results count filtered by current session and term
    let resultsAvailableCount = 0;
    if (currentSession && currentTerm) {
      const { count } = await supabase
        .from("results")
        .select("id", { count: "exact" })
        .eq("student_id", user.id)
        .eq("session", currentSession.session_name)
        .eq("term", currentTerm.term_name);
      resultsAvailableCount = count || 0;
    }

    // Calculate real attendance for CURRENT session and term only
    let attendancePercentage = 0;
    if (student?.class_id) {
      console.log('[Student Overview] Current session:', currentSession);
      console.log('[Student Overview] Current term:', currentTerm);
      
      if (currentSession && currentTerm) {
        // Get school calendar (total school days) to calculate percentage correctly
        const calendarKey = `school_calendar:${currentSession.session_name}:${currentTerm.term_name}`;
        const calendarData = await kv.get(calendarKey);
        
        let totalSchoolDays = 0;
        if (calendarData) {
          const calendar = typeof calendarData === "string" ? JSON.parse(calendarData) : calendarData;
          totalSchoolDays = calendar.total_school_days || 0;
          console.log('[Student Overview] Total school days:', totalSchoolDays);
        }
        
        if (totalSchoolDays > 0) {
          // Get attendance records for the current session and term only
          const { data: attendanceRecords } = await supabase
            .from("attendance")
            .select("status")
            .eq("student_id", user.id)
            .eq("session", currentSession.session_name)
            .eq("term", currentTerm.term_name);

          console.log('[Student Overview] Attendance query - Session:', currentSession.session_name, 'Term:', currentTerm.term_name);
          console.log('[Student Overview] Attendance records count:', attendanceRecords?.length);
          console.log('[Student Overview] Attendance records:', attendanceRecords);

          // Calculate even if no records yet (will be 0/67 = 0%)
          const presentCount = attendanceRecords?.filter(
            (record) => record.status?.toLowerCase() === "present",
          ).length || 0;
          
          const absentCount = attendanceRecords?.filter(
            (record) => record.status?.toLowerCase() === "absent",
          ).length || 0;
          
          // FIXED: Calculate percentage using total_school_days, not total records
          attendancePercentage = Math.round(
            (presentCount / totalSchoolDays) * 100 * 10
          ) / 10; // Round to 1 decimal place
          
          console.log('[Student Overview] ============ ATTENDANCE CALCULATION ============');
          console.log('[Student Overview] Present count:', presentCount);
          console.log('[Student Overview] Absent count:', absentCount);
          console.log('[Student Overview] Total school days:', totalSchoolDays);
          console.log('[Student Overview] Calculated percentage:', attendancePercentage);
          console.log('[Student Overview] =================================================');
        } else {
          console.log('[Student Overview] No school calendar configured - attendance will show 0');
        }
      }
    }

    const stats = {
      totalSubjects: subjectsCount || 0,
      upcomingExams: upcomingExamsCount || 0,
      resultsAvailable: resultsAvailableCount || 0,
      attendance: attendancePercentage,
    };

    // Get recent activities (CBT exams, results, gate clock-in/out, exams, and uploads)
    const recentActivities = [];

    if (student?.class_id) {
      // 1. Get CBT exams for student's class (show all recent exams, not just current session/term)
      // Extract base class name from the student's full class name (e.g., "SS1" from "SS1 - Diamond")
      const studentClassName = classInfo?.name || "";
      const baseClass = studentClassName.split(' - ')[0].trim().toUpperCase();
      
      console.log('[Student Overview] Fetching CBT exams for class:', baseClass);
      
      const { data: cbtExams, error: cbtError } = await supabase
        .from("cbt_exams")
        .select("id, title, subject, scheduled_start, scheduled_end, duration_minutes, status")
        .ilike("class", baseClass)
        .in("status", ["scheduled", "active"])
        .order("scheduled_start", { ascending: false })
        .limit(5);

      console.log('[Student Overview] CBT exams query error:', cbtError);
      console.log('[Student Overview] CBT exams found:', cbtExams?.length || 0);
      console.log('[Student Overview] CBT exams data:', cbtExams);

      if (cbtExams) {
        for (const exam of cbtExams) {
          const subjectName = exam.subject || "Unknown Subject";
          const startTime = new Date(exam.scheduled_start);
          const endTime = new Date(exam.scheduled_end);
          const now = new Date();
          
          let status = "";
          if (now < startTime) {
            status = "Upcoming";
          } else if (now >= startTime && now <= endTime) {
            status = "Ongoing";
          } else {
            status = "Completed";
          }

          // Only add upcoming and ongoing exams to recent activities (not completed)
          if (status === "Upcoming" || status === "Ongoing") {
            console.log('[Student Overview] Adding CBT exam to activities:', {
              title: exam.title,
              subject: subjectName,
              status,
              scheduled_start: exam.scheduled_start
            });

            recentActivities.push({
              type: "cbt_exam",
              description: `CBT: ${subjectName} - ${exam.title} (${status})`,
              date: exam.scheduled_start,
              metadata: {
                exam_id: exam.id,
                status: status
              }
            });
          } else {
            console.log('[Student Overview] Skipping completed CBT exam:', {
              title: exam.title,
              subject: subjectName,
              status
            });
          }
        }
      }

      // 2. Get published terminal/midterm results
      if (currentSession && currentTerm) {
        const { data: publishedResults } = await supabase
          .from("results")
          .select("id, exam_type, session, term, student_id, created_at")
          .eq("student_id", user.id)
          .eq("session", currentSession.session_name)
          .eq("term", currentTerm.term_name)
          .in("exam_type", ["midterm", "terminal"])
          .order("created_at", { ascending: false })
          .limit(2);

        if (publishedResults) {
          for (const result of publishedResults) {
            const resultType = result.exam_type === "midterm" ? "Mid-Term" : "Terminal";
            recentActivities.push({
              type: "result_published",
              description: `${resultType} Results Available for ${result.term}`,
              date: result.created_at,
              metadata: {
                exam_type: result.exam_type,
                session: result.session,
                term: result.term
              }
            });
          }
        }
      }

      // 3. Get recent gate clock-in/out activities
      const { data: gateActivities } = await supabase
        .from("gate_attendance")
        .select("id, clock_in_time, clock_out_time, attendance_date")
        .eq("student_id", user.id)
        .order("attendance_date", { ascending: false })
        .limit(5);

      if (gateActivities) {
        for (const activity of gateActivities) {
          if (activity.clock_in_time) {
            recentActivities.push({
              type: "clock_in",
              description: `Clocked in at ${new Date(activity.clock_in_time).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })}`,
              date: activity.clock_in_time,
              metadata: {
                attendance_date: activity.attendance_date
              }
            });
          }
          if (activity.clock_out_time) {
            recentActivities.push({
              type: "clock_out",
              description: `Clocked out at ${new Date(activity.clock_out_time).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })}`,
              date: activity.clock_out_time,
              metadata: {
                attendance_date: activity.attendance_date
              }
            });
          }
        }
      }

      // 4. Get recent exams
      const { data: recentExams } = await supabase
        .from("exams")
        .select("exam_name, exam_date, status, subjects(name)")
        .eq("class_id", student.class_id)
        .order("exam_date", { ascending: false })
        .limit(3);

      if (recentExams) {
        for (const exam of recentExams) {
          const subjectName =
            exam.subjects?.name || "Unknown Subject";
          recentActivities.push({
            type:
              exam.status === "published" ? "result" : "exam",
            description:
              exam.status === "published"
                ? `${subjectName} ${exam.exam_name} results published`
                : `${subjectName} ${exam.exam_name} scheduled`,
            date: exam.exam_date,
          });
        }
      }

      // 5. Get recent uploads for the student's class
      const { data: recentUploads } = await supabase
        .from("uploads")
        .select("title, type, created_at, subjects(name)")
        .eq("class_id", student.class_id)
        .eq("status", "approved")
        .order("created_at", { ascending: false })
        .limit(2);

      if (recentUploads) {
        for (const upload of recentUploads) {
          const subjectName =
            upload.subjects?.name || "Unknown Subject";
          const typeLabel =
            upload.type === "enote"
              ? "E-Notes"
              : upload.type === "exam_question"
                ? "Exam Questions"
                : upload.type === "assignment"
                  ? "Assignment"
                  : "Resource";
          recentActivities.push({
            type: "upload",
            description: `New ${typeLabel} uploaded for ${subjectName}`,
            date: upload.created_at,
          });
        }
      }
    }

    // Sort by date and limit to 10 most recent
    recentActivities.sort(
      (a, b) =>
        new Date(b.date).getTime() - new Date(a.date).getTime(),
    );
    const limitedActivities = recentActivities.slice(0, 10);

    console.log('[Student Overview] Total activities before limit:', recentActivities.length);
    console.log('[Student Overview] Final activities being sent:', limitedActivities);

    // Get school settings
    const schoolSettings = await kv.get("school_settings");

    return c.json({
      success: true,
      data: {
        studentInfo: {
          ...student,
          class_name: classInfo?.name,
          class_level: classInfo?.level,
        },
        stats,
        recentActivities: limitedActivities,
        currentSession: currentSession ? {
          session_name: currentSession.session_name,
          id: currentSession.id
        } : null,
        currentTerm: currentTerm ? {
          term_name: currentTerm.term_name,
          id: currentTerm.id
        } : null,
        schoolInfo: schoolSettings ? {
          school_name: schoolSettings.school_name,
          logo_url: schoolSettings.logo_url,
          motto: schoolSettings.motto
        } : null,
      },
      debug: {
        class_id: student.class_id,
        total_activities: recentActivities.length,
        cbt_exams_count: recentActivities.filter((a: any) => a.type === 'cbt_exam').length,
        all_activities: recentActivities,
        attendance_debug: {
          current_session: currentSession?.session_name,
          current_term: currentTerm?.term_name,
          attendance_percentage: attendancePercentage
        }
      }
    });
  } catch (error) {
    console.error("[Student Overview] Error:", error);
    return c.json(
      { success: false, error: "Failed to fetch overview" },
      500,
    );
  }
});

// Student Class Info
app.get("/make-server-1ddd013a/student-class", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Get student's class_id
    const { data: student } = await supabase
      .from("profiles")
      .select("class_id")
      .eq("id", user.id)
      .single();

    if (!student?.class_id) {
      return c.json(
        { success: false, error: "Not assigned to a class" },
        404,
      );
    }

    // Get class info with section
    const { data: classInfo } = await supabase
      .from("classes")
      .select(
        "id, name, level, class_teacher_id, sections(name)",
      )
      .eq("id", student.class_id)
      .single();

    // Get class teacher info
    let classTeacherInfo = null;
    if (classInfo?.class_teacher_id) {
      const { data: teacher } = await supabase
        .from("profiles")
        .select("first_name, last_name, email")
        .eq("id", classInfo.class_teacher_id)
        .single();

      if (teacher) {
        // Fetch teacher profile photo from KV store
        // Check multiple possible keys for backwards compatibility
        let teacherProfileKey = `teacher_profile_${classInfo.class_teacher_id}`;
        let teacherProfile = (await kv.get(teacherProfileKey)) as any;
        
        // Fallback 1: check profile_ key (used by ProfileSettings component)
        if (!teacherProfile?.photo_url) {
          teacherProfile = (await kv.get(`profile_${classInfo.class_teacher_id}`)) as any;
        }
        
        // Fallback 2: check student_profile_ for backwards compatibility (teachers who uploaded before fix)
        if (!teacherProfile?.photo_url) {
          teacherProfile = (await kv.get(`student_profile_${classInfo.class_teacher_id}`)) as any;
        }
        
        classTeacherInfo = {
          name: `${teacher.first_name} ${teacher.last_name}`,
          email: teacher.email,
          photo_url: teacherProfile?.photo_url || '',
        };
      }
    }

    // Get classmates
    const { data: classmates } = await supabase
      .from("profiles")
      .select("id, first_name, last_name, middle_name, email")
      .eq("class_id", student.class_id)
      .eq("role", "student")
      .neq("id", user.id)
      .or("is_graduated.is.null,is_graduated.eq.false")
      .order("first_name", { ascending: true });

    // Fetch classmate photos from KV store
    const classmatesWithPhotos = await Promise.all(
      (classmates || []).map(async (classmate) => {
        const profileKey = `student_profile_${classmate.id}`;
        const profile = (await kv.get(profileKey)) as any;
        return {
          ...classmate,
          photo_url: profile?.photo_url || ''
        };
      })
    );

    // Create display name that combines class name and section
    // Note: classInfo.name already includes the section
    const displayName = classInfo?.name;

    return c.json({
      success: true,
      data: {
        classInfo: {
          id: classInfo?.id,
          name: displayName,
          level: classInfo?.level,
          class_teacher_name: classTeacherInfo?.name,
          class_teacher_email: classTeacherInfo?.email,
          class_teacher_photo_url: classTeacherInfo?.photo_url,
        },
        classmates: classmatesWithPhotos,
      },
    });
  } catch (error) {
    console.error("[Student Class] Error:", error);
    return c.json(
      { success: false, error: "Failed to fetch class data" },
      500,
    );
  }
});

