// Student Timetable
app.get(
  "/make-server-1ddd013a/student-timetable",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Get student's class_id
      const { data: student } = await supabase
        .from("profiles")
        .select("class_id")
        .eq("id", user.id)
        .single();

      if (!student?.class_id) {
        console.log('[Student Timetable] No class_id found for student');
        return c.json({ success: true, timetable: [] });
      }

      // Get student's class name with section
      const { data: classData } = await supabase
        .from("classes")
        .select("name")
        .eq("id", student.class_id)
        .single();

      if (!classData?.name) {
        console.log('[Student Timetable] Class not found');
        return c.json({ success: true, timetable: [] });
      }

      console.log('[Student Timetable] Student class:', classData.name);

      // Get the latest PUBLISHED timetable settings
      const { data: latestSettings } = await supabase
        .from("timetable_settings")
        .select("id, is_published")
        .eq("is_published", true)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (!latestSettings) {
        console.log('[Student Timetable] No published timetable found');
        return c.json({ success: true, timetable: [] });
      }

      console.log('[Student Timetable] Using published timetable settings ID:', latestSettings.id);

      // Fetch timetable slots for this class
      // slot_name format is like "SS3 Silver-Monday-1" or "JSS1-Tuesday-3"
      const { data: timetableSlots, error: slotsError } = await supabase
        .from("timetable_time_slots")
        .select("*")
        .eq("timetable_settings_id", latestSettings.id);

      if (slotsError) {
        console.error('[Student Timetable] Error fetching slots:', slotsError);
        return c.json({ success: false, error: "Failed to fetch timetable" }, 500);
      }

      // Filter slots that match the student's class (slot_name starts with class name)
      const classSlots = (timetableSlots || []).filter(slot => {
        const slotName = slot.slot_name || '';
        // Check if slot_name starts with the class name (e.g., "SS3 Silver-Monday-1" matches "SS3 Silver")
        return slotName.toLowerCase().startsWith(classData.name.toLowerCase() + '-');
      });

      console.log('[Student Timetable] Found', classSlots.length, 'slots for class', classData.name);

      // Parse slots and enrich with subject and teacher information
      const enrichedEntries = await Promise.all(
        classSlots.map(async (slot) => {
          // Parse slot_name: "ClassName-Day-Period"
          const parts = slot.slot_name.split('-');
          const day = parts[parts.length - 2]; // Second to last is day
          const period = parseInt(parts[parts.length - 1]); // Last is period

          let subjectName = '';
          let subjectCode = '';
          let teacherName = '';

          // Check if this is a paired subject slot
          if (slot.pairs_id) {
            // Get both subjects from the pair
            const { data: pairData } = await supabase
              .from("subject_pairs")
              .select("subject_1_id, subject_2_id")
              .eq("id", slot.pairs_id)
              .single();

            if (pairData) {
              // Fetch both subjects
              const { data: subject1 } = await supabase
                .from("subjects")
                .select("name, code")
                .eq("id", pairData.subject_1_id)
                .single();

              const { data: subject2 } = await supabase
                .from("subjects")
                .select("name, code")
                .eq("id", pairData.subject_2_id)
                .single();

              // Combine subject names with "/"
              if (subject1 && subject2) {
                subjectName = `${subject1.name}/${subject2.name}`;
                subjectCode = subject1.code && subject2.code 
                  ? `${subject1.code}/${subject2.code}` 
                  : '';
              }
            }
          } else if (slot.subject_config_id) {
            // Get subject info from subject_config_id (single subject)
            const { data: subjectConfig } = await supabase
              .from("subject_configs")
              .select("subject_id")
              .eq("id", slot.subject_config_id)
              .single();

            if (subjectConfig?.subject_id) {
              const { data: subject } = await supabase
                .from("subjects")
                .select("name, code")
                .eq("id", subjectConfig.subject_id)
                .single();

              if (subject) {
                subjectName = subject.name;
                subjectCode = subject.code || '';
              }
            }
          }

          // Get teacher info
          if (slot.teacher_id) {
            const { data: teacher } = await supabase
              .from("profiles")
              .select("first_name, last_name")
              .eq("id", slot.teacher_id)
              .single();

            if (teacher) {
              teacherName = `${teacher.first_name} ${teacher.last_name}`;
            }
          }

          return {
            id: slot.id,
            day: day,
            period: period,
            start_time: slot.start_time || '',
            end_time: slot.end_time || '',
            subject_name: subjectName,
            subject_code: subjectCode,
            teacher_name: teacherName,
          };
        }),
      );

      console.log('[Student Timetable] Returning', enrichedEntries.length, 'enriched entries');

      return c.json({
        success: true,
        timetable: enrichedEntries,
      });
    } catch (error) {
      console.error("[Student Timetable] Error:", error);
      return c.json(
        { success: false, error: "Failed to fetch timetable" },
        500,
      );
    }
  },
);

