// Generate Result PIN
app.post(
  "/make-server-1ddd013a/generate-result-pin",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Generate 8-character alphanumeric PIN
      const characters = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // Removed ambiguous characters
      let pin = "";
      for (let i = 0; i < 8; i++) {
        pin += characters.charAt(
          Math.floor(Math.random() * characters.length),
        );
      }

      // Get current term and session from admin settings
      const sessions = await kv.get("academic_sessions");
      const terms = await kv.get("academic_terms");

      // Find the current session and term marked by admin
      const currentSession = sessions?.find(
        (s: any) => s.is_current,
      );
      const currentTerm = terms?.find((t: any) => t.is_current);

      if (!currentSession || !currentTerm) {
        return c.json(
          {
            success: false,
            error:
              "No current session or term set by admin. Please contact school administration.",
          },
          400,
        );
      }

      const session = currentSession.session_name;
      const term = currentTerm.term_name;

      // Check if student already has an active PIN for this term/session
      const { data: existingPins } = await supabase
        .from("pins")
        .select("*")
        .eq("student_id", user.id)
        .eq("term", term)
        .eq("session", session)
        .eq("active", true);

      if (existingPins && existingPins.length > 0) {
        // Check if any of the active PINs are not expired
        const now = new Date();
        const hasValidActivePin = existingPins.some(
          (p: any) => {
            const expiresAt = new Date(p.expires_at);
            const isNotExpired = expiresAt > now;
            const hasUsesRemaining = (p.usage_count || 0) < 3;
            return isNotExpired && hasUsesRemaining;
          },
        );

        if (hasValidActivePin) {
          const activePin = existingPins.find((p: any) => {
            const expiresAt = new Date(p.expires_at);
            const isNotExpired = expiresAt > now;
            const hasUsesRemaining = (p.usage_count || 0) < 3;
            return isNotExpired && hasUsesRemaining;
          });

          const usageCount = activePin?.usage_count || 0;
          const remainingUses = 3 - usageCount;
          const expiryDate = new Date(
            activePin?.expires_at,
          ).toLocaleDateString();

          return c.json(
            {
              success: false,
              error: `Sorry, you currently still have an active PIN. You can only generate a new PIN when your current PIN expires or is fully used.\n\nYour active PIN has ${remainingUses} use(s) remaining and expires on ${expiryDate}.`,
              hasActivePin: true,
              activePin: {
                pin_code: activePin?.pin_code,
                usage_count: usageCount,
                remaining_uses: remainingUses,
                expires_at: activePin?.expires_at,
              },
            },
            400,
          );
        }
      }

      // Set expiry date (30 days from now)
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + 30);

      // Insert PIN into pins table
      const { data: newPin, error: insertError } =
        await supabase
          .from("pins")
          .insert({
            student_id: user.id,
            pin_code: pin,
            term: term,
            session: session,
            active: true,
            expires_at: expiresAt.toISOString(),
            usage_count: 0, // Initialize usage count
          })
          .select()
          .single();

      if (insertError) {
        console.error(
          "[Generate Result PIN] Insert error:",
          insertError,
        );
        return c.json(
          { success: false, error: "Failed to generate PIN" },
          500,
        );
      }

      return c.json({
        success: true,
        pin: newPin,
      });
    } catch (error) {
      console.error("[Generate Result PIN] Error:", error);
      return c.json(
        { success: false, error: "Failed to generate PIN" },
        500,
      );
    }
  },
);

