// Delete User
app.post("/make-server-1ddd013a/users/delete", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);

    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Check if user is IT admin (it_admin role)
    const { data: adminProfile, error: profileError } =
      await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

    if (profileError || adminProfile?.role !== "it_admin") {
      return c.json(
        {
          success: false,
          error: "Access denied. IT Admin role required.",
        },
        403,
      );
    }

    const body = await c.req.json();
    const { user_id } = body;

    if (!user_id) {
      return c.json(
        { success: false, error: "User ID is required" },
        400,
      );
    }

    // Prevent deleting yourself
    if (user_id === user.id) {
      return c.json(
        {
          success: false,
          error: "You cannot delete your own account",
        },
        400,
      );
    }

    // Delete user from Supabase Auth
    const { error: deleteAuthError } =
      await supabase.auth.admin.deleteUser(user_id);

    if (deleteAuthError) {
      console.error(
        "[Delete User] Auth delete error:",
        deleteAuthError,
      );
      return c.json(
        {
          success: false,
          error: "Failed to delete user from authentication",
        },
        500,
      );
    }

    // Delete extended profile data from KV store
    try {
      await kv.del(`user_profile_${user_id}`);
    } catch (kvError) {
      console.error("[Delete User] KV delete error:", kvError);
      // Continue even if KV delete fails
    }

    // ✅ AUTO-CLEANUP: Delete student_subjects for deleted user
    console.log("[Delete User] 🧹 Auto-cleanup: Deleting student_subjects for deleted user...");
    const { error: cleanupError } = await supabase
      .from("student_subjects")
      .delete()
      .eq("student_id", user_id);
    
    if (cleanupError) {
      console.error("[Delete User] ⚠️ Failed to cleanup student_subjects:", cleanupError);
      // Don't fail the whole operation
    } else {
      console.log("[Delete User] ✅ Cleaned up student_subjects for deleted user");
    }

    // Note: Profile in profiles table will be automatically deleted via CASCADE
    // since it's linked to auth.users

    return c.json({ success: true });
  } catch (error) {
    console.error("[Delete User] Error:", error);
    return c.json(
      { success: false, error: "Failed to delete user" },
      500,
    );
  }
});

// Reset User Password
app.post(
  "/make-server-1ddd013a/users/reset-password",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);

      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is IT admin (it_admin role)
      const { data: adminProfile, error: profileError } =
        await supabase
          .from("profiles")
          .select("role")
          .eq("id", user.id)
          .single();

      if (profileError || adminProfile?.role !== "it_admin") {
        return c.json(
          {
            success: false,
            error: "Access denied. IT Admin role required.",
          },
          403,
        );
      }

      const body = await c.req.json();
      const { user_id, new_password } = body;

      if (!user_id || !new_password) {
        return c.json(
          {
            success: false,
            error: "User ID and new password are required",
          },
          400,
        );
      }

      if (new_password.length < 8) {
        return c.json(
          {
            success: false,
            error: "Password must be at least 8 characters",
          },
          400,
        );
      }

      // Update password using admin API
      const { error: updateError } =
        await supabase.auth.admin.updateUserById(user_id, {
          password: new_password,
        });

      if (updateError) {
        console.error("[Reset Password] Error:", updateError);
        return c.json(
          { success: false, error: "Failed to reset password" },
          500,
        );
      }

      return c.json({ success: true });
    } catch (error) {
      console.error("[Reset Password] Error:", error);
      return c.json(
        { success: false, error: "Failed to reset password" },
        500,
      );
    }
  },
);

