// Upload School Asset (Logo or Stamp)
app.post(
  "/make-server-1ddd013a/upload-school-asset",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id)
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );

      // Create bucket if it doesn't exist
      const bucketName = "make-1ddd013a-school-assets";
      const { data: buckets } =
        await supabase.storage.listBuckets();
      const bucketExists = buckets?.some(
        (bucket) => bucket.name === bucketName,
      );

      if (!bucketExists) {
        await supabase.storage.createBucket(bucketName, {
          public: true,
          fileSizeLimit: 5242880, // 5MB
          allowedMimeTypes: ["image/*"],
        });
        console.log(
          `[Upload Asset] Created bucket: ${bucketName}`,
        );
      }

      // Get form data
      const formData = await c.req.formData();
      const file = formData.get("file") as File;
      const type = formData.get("type") as string; // 'logo' or 'stamp'

      if (!file) {
        return c.json(
          { success: false, error: "No file provided" },
          400,
        );
      }

      // Generate unique filename
      const timestamp = Date.now();
      const fileExt = file.name.split(".").pop();
      const fileName = `${type}-${timestamp}.${fileExt}`;

      // Convert File to ArrayBuffer
      const arrayBuffer = await file.arrayBuffer();
      const buffer = new Uint8Array(arrayBuffer);

      // Upload to Supabase Storage
      const { data: uploadData, error: uploadError } =
        await supabase.storage
          .from(bucketName)
          .upload(fileName, buffer, {
            contentType: file.type,
            upsert: true,
          });

      if (uploadError) {
        console.error(
          "[Upload Asset] Upload error:",
          uploadError,
        );
        return c.json(
          { success: false, error: "Failed to upload file" },
          500,
        );
      }

      // Get public URL
      const {
        data: { publicUrl },
      } = supabase.storage
        .from(bucketName)
        .getPublicUrl(fileName);

      console.log(
        `[Upload Asset] Successfully uploaded ${type}: ${publicUrl}`,
      );

      return c.json({ success: true, url: publicUrl });
    } catch (error) {
      console.error("[Upload Asset] Error:", error);
      return c.json(
        { success: false, error: "Failed to upload asset" },
        500,
      );
    }
  },
);

