app.get(
  "/make-server-1ddd013a/student-profile/:studentId/basic",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id)
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );

      const studentId = c.req.param("studentId");

      console.log(
        "[Get Student Basic Profile] Auth user.id:",
        user.id,
      );
      console.log(
        "[Get Student Basic Profile] Auth user.email:",
        user.email,
      );
      console.log(
        "[Get Student Basic Profile] Requested studentId:",
        studentId,
      );

      // Query profiles table using SERVICE ROLE to bypass RLS
      const { data: profileData, error: profileError } =
        await supabase
          .from("profiles")
          .select(
            "id, email, first_name, middle_name, last_name, role",
          )
          .eq("id", studentId)
          .single();

      console.log(
        "[Get Student Basic Profile] Profile found:",
        !!profileData,
      );
      console.log(
        "[Get Student Basic Profile] Profile data:",
        profileData,
      );
      console.log(
        "[Get Student Basic Profile] Error:",
        profileError,
      );

      if (profileError) {
        console.error(
          "[Get Student Basic Profile] Database error:",
          profileError,
        );
        return c.json(
          {
            success: false,
            error: `Database error: ${profileError.message}`,
          },
          500,
        );
      }

      if (!profileData) {
        console.log(
          "[Get Student Basic Profile] No profile found in profiles table",
        );
        return c.json(
          {
            success: false,
            error: "Profile not found",
          },
          404,
        );
      }

      // Verify the user is accessing their own profile (or is admin)
      if (profileData.email !== user.email) {
        // Check if user is admin
        const { data: userProfile } = await supabase
          .from("profiles")
          .select("role")
          .eq("email", user.email)
          .single();

        if (
          !userProfile ||
          !["principal", "it_admin", "finance_admin"].includes(
            userProfile.role,
          )
        ) {
          console.log(
            "[Get Student Basic Profile] Access denied - not own profile and not admin",
          );
          return c.json(
            { success: false, error: "Unauthorized" },
            403,
          );
        }
      }

      return c.json({
        success: true,
        profile: profileData,
      });
    } catch (error) {
      console.error(
        "[Get Student Basic Profile] Error:",
        error,
      );
      return c.json(
        {
          success: false,
          error: `Failed to fetch basic profile: ${error.message}`,
        },
        500,
      );
    }
  },
);

