// Update Student Profile (Extended)
app.post("/make-server-1ddd013a/student-profile", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    const {
      data: { user },
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id)
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );

    const body = await c.req.json();
    const studentId = body.student_id;

    console.log(
      "[Update Student Profile] Auth user.id:",
      user.id,
    );
    console.log(
      "[Update Student Profile] Requested studentId:",
      studentId,
    );

    if (!studentId) {
      return c.json(
        { success: false, error: "Student ID is required" },
        400,
      );
    }

    // Get the user's profile to check their actual profile ID
    const { data: userProfileData } = await supabase
      .from("profiles")
      .select("id, role, email")
      .eq("email", user.email)
      .single();

    console.log(
      "[Update Student Profile] User's profile ID:",
      userProfileData?.id,
    );
    console.log(
      "[Update Student Profile] User's role:",
      userProfileData?.role,
    );

    // Only allow users to update their own profile (unless admin)
    // Compare using the profile ID from profiles table, not auth user ID
    if (userProfileData?.id !== studentId) {
      if (
        !userProfileData ||
        !["principal", "it_admin", "finance_admin"].includes(
          userProfileData.role,
        )
      ) {
        console.log(
          "[Update Student Profile] Access denied - not own profile and not admin",
        );
        return c.json(
          {
            success: false,
            error:
              "Unauthorized - You can only update your own profile",
          },
          403,
        );
      } else {
        console.log(
          "[Update Student Profile] Admin update granted",
        );
      }
    } else {
      console.log(
        "[Update Student Profile] Own profile update granted",
      );
    }

    // ✅ CRITICAL: Update profiles table first if name/email fields are provided
    if (body.first_name || body.middle_name || body.last_name || body.email) {
      const updateFields: any = {};
      if (body.first_name) updateFields.first_name = body.first_name;
      if (body.middle_name !== undefined) updateFields.middle_name = body.middle_name;
      if (body.last_name) updateFields.last_name = body.last_name;
      if (body.email) updateFields.email = body.email;

      const { error: profilesUpdateError } = await supabase
        .from('profiles')
        .update(updateFields)
        .eq('id', studentId);

      if (profilesUpdateError) {
        console.error('[Update Student Profile] ❌ Failed to update profiles table:', profilesUpdateError);
        return c.json(
          { success: false, error: 'Failed to update profile in database' },
          500
        );
      }

      console.log('[Update Student Profile] ✅ Profiles table updated successfully');

      // Also update auth email if it changed
      if (body.email) {
        const { error: emailUpdateError } = await supabase.auth.admin.updateUserById(
          studentId,
          { email: body.email }
        );
        
        if (emailUpdateError) {
          console.error('[Update Student Profile] ⚠️ Failed to update auth email:', emailUpdateError);
          // Don't fail the whole operation, just log it
        } else {
          console.log('[Update Student Profile] ✅ Auth email updated successfully');
        }
      }
    }

    // Save extended fields to KV store
    // Use role-based key: teacher_profile_${id} for teachers, student_profile_${id} for students
    const profileKey = userProfileData?.role === 'teacher' 
      ? `teacher_profile_${studentId}` 
      : `student_profile_${studentId}`;
    
    await kv.set(profileKey, {
      gender: body.gender || "",
      phone: body.phone || "",
      address: body.address || "",
      parent_name: body.parent_name || "",
      parent_phone: body.parent_phone || "",
      state_of_origin: body.state_of_origin || "",
      lga: body.lga || "",
      photo_url: body.photo_url || "",
      health_report_url: body.health_report_url || "",
      updated_at: new Date().toISOString(),
    });

    console.log(
      `[Update Profile] Profile updated for ${userProfileData?.role || 'student'} ${studentId}`,
    );

    return c.json({ success: true });
  } catch (error) {
    console.error("[Update Student Profile] Error:", error);
    return c.json(
      {
        success: false,
        error: "Failed to update student profile",
      },
      500,
    );
  }
});

// Upload Student Profile File (Photo, Health Report)
app.post(
  "/make-server-1ddd013a/student-profile/upload",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id)
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );

      const formData = await c.req.formData();
      const file = formData.get("file") as File;
      const type = formData.get("type") as string; // 'photo' or 'health_report'
      const studentId = formData.get("student_id") as string;

      if (!file || !type || !studentId) {
        return c.json(
          {
            success: false,
            error: "File, type, and student_id are required",
          },
          400,
        );
      }

      // Validate type
      if (!["photo", "health_report"].includes(type)) {
        return c.json(
          { success: false, error: "Invalid file type" },
          400,
        );
      }

      console.log(
        "[Upload Student Profile File] Auth user.id:",
        user.id,
      );
      console.log(
        "[Upload Student Profile File] Requested studentId:",
        studentId,
      );
      console.log(
        "[Upload Student Profile File] File type:",
        type,
      );

      // Get the user's profile to check their actual profile ID
      const { data: userProfileData } = await supabase
        .from("profiles")
        .select("id, role, email")
        .eq("email", user.email)
        .single();

      console.log(
        "[Upload Student Profile File] User's profile ID:",
        userProfileData?.id,
      );

      // Only allow users to upload to their own profile (unless admin)
      // Compare using the profile ID from profiles table, not auth user ID
      if (userProfileData?.id !== studentId) {
        if (
          !userProfileData ||
          !["principal", "it_admin", "finance_admin"].includes(
            userProfileData.role,
          )
        ) {
          console.log(
            "[Upload Student Profile File] Access denied - not own profile and not admin",
          );
          return c.json(
            {
              success: false,
              error:
                "Unauthorized - You can only upload to your own profile",
            },
            403,
          );
        } else {
          console.log(
            "[Upload Student Profile File] Admin upload granted",
          );
        }
      } else {
        console.log(
          "[Upload Student Profile File] Own profile upload granted",
        );
      }

      // Create bucket if it doesn't exist
      const bucketName = "make-1ddd013a-student-files";
      const { data: buckets } =
        await supabase.storage.listBuckets();
      const bucketExists = buckets?.some(
        (bucket) => bucket.name === bucketName,
      );

      if (!bucketExists) {
        await supabase.storage.createBucket(bucketName, {
          public: true,
        });
      }

      // Upload file
      const fileExt = file.name.split(".").pop();
      const fileName = `${studentId}/${type}_${Date.now()}.${fileExt}`;
      const fileBuffer = await file.arrayBuffer();

      const { error: uploadError } = await supabase.storage
        .from(bucketName)
        .upload(fileName, fileBuffer, {
          contentType: file.type,
          upsert: true,
        });

      if (uploadError) {
        console.error(
          "[Upload Student File] Upload error:",
          uploadError,
        );
        return c.json(
          { success: false, error: "Failed to upload file" },
          500,
        );
      }

      // Get public URL
      const {
        data: { publicUrl },
      } = supabase.storage
        .from(bucketName)
        .getPublicUrl(fileName);

      // Update the profile in KV store with the new URL
      // Use role-based key: teacher_profile_${id} for teachers, student_profile_${id} for students
      const profileKey = userProfileData?.role === 'teacher' 
        ? `teacher_profile_${studentId}` 
        : `student_profile_${studentId}`;
      
      const existingProfile = (await kv.get(profileKey)) || {};
      await kv.set(profileKey, {
        ...existingProfile,
        [`${type}_url`]: publicUrl,
        updated_at: new Date().toISOString(),
      });

      console.log(
        `[Upload Profile File] Successfully uploaded ${type} for ${userProfileData?.role || 'student'} ${studentId}: ${publicUrl}`,
      );

      return c.json({ success: true, url: publicUrl });
    } catch (error) {
      console.error("[Upload Student File] Error:", error);
      return c.json(
        { success: false, error: "Failed to upload file" },
        500,
      );
    }
  },
);

