// Get Session Settings - Fetch from academic_sessions and academic_terms tables
app.get("/make-server-1ddd013a/session-settings", async (c) => {
  try {
    console.log(
      "[Session Settings] Fetching from academic_sessions and academic_terms tables...",
    );

    // 🔥 CLEANUP: Ensure only one session and one term has is_current = true
    const { data: currentSessions } = await supabase
      .from("academic_sessions")
      .select("*")
      .eq("is_current", true);
    
    if (currentSessions && currentSessions.length > 1) {
      console.log(`[Session Settings] ⚠️ Found ${currentSessions.length} sessions with is_current=true. Fixing...`);
      // Keep the most recent one, disable others
      const mostRecentSession = currentSessions.sort((a, b) => 
        new Date(b.start_date).getTime() - new Date(a.start_date).getTime()
      )[0];
      
      await supabase
        .from("academic_sessions")
        .update({ is_current: false })
        .neq("id", mostRecentSession.id);
      
      console.log(`[Session Settings] ✅ Fixed: Only "${mostRecentSession.session_name}" is now current`);
    }

    const { data: currentTerms } = await supabase
      .from("academic_terms")
      .select("*")
      .eq("is_current", true);
    
    if (currentTerms && currentTerms.length > 1) {
      console.log(`[Session Settings] ⚠️ Found ${currentTerms.length} terms with is_current=true. Fixing...`);
      // Keep the most recent one, disable others
      const mostRecentTerm = currentTerms.sort((a, b) => 
        new Date(b.start_date).getTime() - new Date(a.start_date).getTime()
      )[0];
      
      await supabase
        .from("academic_terms")
        .update({ is_current: false })
        .neq("id", mostRecentTerm.id);
      
      console.log(`[Session Settings] ✅ Fixed: Only "${mostRecentTerm.term_name}" is now current`);
    }

    // Fetch all sessions
    const { data: sessions, error: sessionsError } =
      await supabase
        .from("academic_sessions")
        .select("*")
        .order("start_date", { ascending: false });

    if (sessionsError) {
      console.error(
        "[Session Settings] Sessions error:",
        sessionsError,
      );
      return c.json(
        {
          success: false,
          error: `Failed to fetch sessions: ${sessionsError.message}`,
        },
        500,
      );
    }

    // Fetch all terms
    const { data: terms, error: termsError } = await supabase
      .from("academic_terms")
      .select("*")
      .order("start_date", { ascending: true });

    if (termsError) {
      console.error(
        "[Session Settings] Terms error:",
        termsError,
      );
      return c.json(
        {
          success: false,
          error: `Failed to fetch terms: ${termsError.message}`,
        },
        500,
      );
    }

    console.log(
      "[Session Settings] Found:",
      sessions?.length || 0,
      "sessions,",
      terms?.length || 0,
      "terms",
    );

    return c.json({
      success: true,
      sessions: sessions || [],
      terms: terms || [],
    });
  } catch (error) {
    console.error("[Session Settings] Error:", error);
    return c.json(
      {
        success: false,
        error: "Failed to fetch session settings",
      },
      500,
    );
  }
});

// Update Session Settings - Save to academic_sessions and academic_terms tables
app.post(
  "/make-server-1ddd013a/update-session-settings",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (
        !profile ||
        !["principal", "director", "it_admin"].includes(
          profile.role,
        )
      ) {
        return c.json(
          {
            success: false,
            error: "Unauthorized - Admin access required",
          },
          403,
        );
      }

      const body = await c.req.json();
      const { sessions, terms } = body;

      console.log(
        "[Update Session Settings] Updating sessions and terms...",
      );
      console.log(
        "[Update Session Settings] Sessions:",
        JSON.stringify(sessions),
      );
      console.log(
        "[Update Session Settings] Terms:",
        JSON.stringify(terms),
      );

      // Validate input
      if (!sessions || !Array.isArray(sessions)) {
        return c.json(
          {
            success: false,
            error: "Invalid sessions data - must be an array",
          },
          400,
        );
      }

      if (!terms || !Array.isArray(terms)) {
        return c.json(
          {
            success: false,
            error: "Invalid terms data - must be an array",
          },
          400,
        );
      }

      // Helper function to convert empty strings to null for date fields
      const cleanDate = (
        date: string | null | undefined,
      ): string | null => {
        if (!date || date.trim() === "") return null;
        return date;
      };

      // Helper function to create detailed error messages
      const formatDbError = (error: any, context: string): string => {
        if (error.code === "42P01") {
          return `Database table does not exist. Please run the SQL setup script (RESTRUCTURE_ACADEMIC_CALENDAR.sql) to create the academic_sessions and academic_terms tables.`;
        }
        if (error.code === "23505") {
          return `${context}: Duplicate entry. A record with this name already exists.`;
        }
        if (error.code === "23503") {
          return `${context}: Referenced record does not exist.`;
        }
        if (error.message) {
          return `${context}: ${error.message}`;
        }
        return `${context}: Unknown error`;
      };

      // Process sessions
      for (const session of sessions || []) {
        // Skip sessions without required fields
        if (
          !session.session_name ||
          !cleanDate(session.start_date) ||
          !cleanDate(session.end_date)
        ) {
          console.log(
            "[Update Session Settings] Skipping incomplete session:",
            session.session_name,
          );
          continue;
        }

        // 🔥 If this session is being set as current, set all other sessions to is_current = false
        if (session.is_current) {
          console.log(`[Update Session Settings] Setting session "${session.session_name}" as current, disabling others...`);
          await supabase
            .from("academic_sessions")
            .update({ is_current: false })
            .neq("id", session.id || "");
        }

        if (session.id) {
          // Update existing session
          const { error } = await supabase
            .from("academic_sessions")
            .update({
              session_name: session.session_name,
              start_date: cleanDate(session.start_date),
              end_date: cleanDate(session.end_date),
              is_current: session.is_current,
              status: session.is_current
                ? "active"
                : session.status || "inactive",
            })
            .eq("id", session.id);

          if (error) {
            console.error(
              "[Update Session Settings] Error updating session:",
              error,
            );
            return c.json(
              {
                success: false,
                error: formatDbError(
                  error,
                  `Failed to update session "${session.session_name}"`,
                ),
                details: error,
                errorCode: error.code,
              },
              500,
            );
          }
        } else {
          // Insert new session
          const { error } = await supabase
            .from("academic_sessions")
            .insert({
              session_name: session.session_name,
              start_date: cleanDate(session.start_date),
              end_date: cleanDate(session.end_date),
              is_current: session.is_current,
              status: session.is_current
                ? "active"
                : "inactive",
            });

          if (error) {
            console.error(
              "[Update Session Settings] Error inserting session:",
              error,
            );
            return c.json(
              {
                success: false,
                error: formatDbError(
                  error,
                  `Failed to insert session "${session.session_name}"`,
                ),
                details: error,
                errorCode: error.code,
              },
              500,
            );
          }
        }
      }

      // Process terms
      for (const term of terms || []) {
        // Skip terms without required fields
        if (
          !term.term_name ||
          !cleanDate(term.start_date) ||
          !cleanDate(term.end_date)
        ) {
          console.log(
            "[Update Session Settings] Skipping incomplete term:",
            term.term_name,
          );
          continue;
        }

        // 🔥 If this term is being set as current, set all other terms to is_current = false
        if (term.is_current) {
          console.log(`[Update Session Settings] Setting term "${term.term_name}" as current, disabling others...`);
          await supabase
            .from("academic_terms")
            .update({ is_current: false })
            .neq("id", term.id || "");
        }

        if (term.id) {
          // Update existing term
          const { error } = await supabase
            .from("academic_terms")
            .update({
              term_name: term.term_name,
              start_date: cleanDate(term.start_date),
              end_date: cleanDate(term.end_date),
              next_term_begins: cleanDate(
                term.next_term_begins,
              ),
              number_of_weeks: term.number_of_weeks || 12,
              is_current: term.is_current,
              status: term.is_current
                ? "active"
                : term.status || "inactive",
            })
            .eq("id", term.id);

          if (error) {
            console.error(
              "[Update Session Settings] Error updating term:",
              error,
            );
            return c.json(
              {
                success: false,
                error: formatDbError(
                  error,
                  `Failed to update term "${term.term_name}"`,
                ),
                details: error,
                errorCode: error.code,
              },
              500,
            );
          }
        } else {
          // Insert new term
          const { error } = await supabase
            .from("academic_terms")
            .insert({
              term_name: term.term_name,
              start_date: cleanDate(term.start_date),
              end_date: cleanDate(term.end_date),
              next_term_begins: cleanDate(
                term.next_term_begins,
              ),
              number_of_weeks: term.number_of_weeks || 12,
              is_current: term.is_current,
              status: term.is_current ? "active" : "inactive",
            });

          if (error) {
            console.error(
              "[Update Session Settings] Error inserting term:",
              error,
            );
            return c.json(
              {
                success: false,
                error: formatDbError(
                  error,
                  `Failed to insert term "${term.term_name}"`,
                ),
                details: error,
                errorCode: error.code,
              },
              500,
            );
          }
        }
      }

      // Update academic_calendar table with current session and term
      const currentSession = sessions?.find(
        (s: any) => s.is_current,
      );
      const currentTerm = terms?.find((t: any) => t.is_current);

      if (currentSession && currentTerm) {
        // Get their IDs (either from the object or fetch from DB)
        let sessionId = currentSession.id;
        let termId = currentTerm.id;

        // If no ID, fetch from database
        if (!sessionId) {
          const { data: sessionData } = await supabase
            .from("academic_sessions")
            .select("id")
            .eq("session_name", currentSession.session_name)
            .single();
          sessionId = sessionData?.id;
        }

        if (!termId) {
          const { data: termData } = await supabase
            .from("academic_terms")
            .select("id")
            .eq("term_name", currentTerm.term_name)
            .single();
          termId = termData?.id;
        }

        if (sessionId && termId) {
          // Delete existing calendar entry
          await supabase
            .from("academic_calendar")
            .delete()
            .neq("id", "00000000-0000-0000-0000-000000000000");

          // Insert new calendar entry
          const { error: calendarError } = await supabase
            .from("academic_calendar")
            .insert({
              session_id: sessionId,
              term_id: termId,
            });

          if (calendarError) {
            console.error(
              "[Update Session Settings] Error updating academic_calendar:",
              calendarError,
            );
          } else {
            console.log(
              "[Update Session Settings] Updated academic_calendar with current session and term",
            );
          }
        }
      }

      console.log(
        "[Update Session Settings] Successfully updated all settings",
      );
      return c.json({ success: true });
    } catch (error) {
      console.error("[Update Session Settings] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to update session settings",
        },
        500,
      );
    }
  },
);

