// Set current session
app.post(
  "/make-server-1ddd013a/set-current-session",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const { session_id } = await c.req.json();

      console.log(
        "[Set Current Session] Setting session as current:",
        session_id,
      );

      // The database trigger will automatically handle setting this to current
      // and making all others not current
      const { error } = await supabase
        .from("academic_sessions")
        .update({ is_current: true })
        .eq("id", session_id);

      if (error) {
        console.error("[Set Current Session] Error:", error);
        return c.json(
          { success: false, error: error.message },
          400,
        );
      }

      // Update academic_calendar table
      const { data: currentTerm } = await supabase
        .from("academic_terms")
        .select("id")
        .eq("is_current", true)
        .single();

      if (currentTerm) {
        await supabase
          .from("academic_calendar")
          .delete()
          .neq("id", "00000000-0000-0000-0000-000000000000");
        await supabase.from("academic_calendar").insert({
          session_id: session_id,
          term_id: currentTerm.id,
        });
      }

      console.log(
        "[Set Current Session] Successfully set current session",
      );
      return c.json({ success: true });
    } catch (error) {
      console.error("[Set Current Session] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to set current session",
        },
        500,
      );
    }
  },
);

// Set current term
app.post(
  "/make-server-1ddd013a/set-current-term",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const { term_id } = await c.req.json();

      console.log(
        "[Set Current Term] Setting term as current:",
        term_id,
      );

      // The database trigger will automatically handle setting this to current
      // and making all others not current
      const { error } = await supabase
        .from("academic_terms")
        .update({ is_current: true })
        .eq("id", term_id);

      if (error) {
        console.error("[Set Current Term] Error:", error);
        return c.json(
          { success: false, error: error.message },
          400,
        );
      }

      // Update academic_calendar table
      const { data: currentSession } = await supabase
        .from("academic_sessions")
        .select("id")
        .eq("is_current", true)
        .single();

      if (currentSession) {
        await supabase
          .from("academic_calendar")
          .delete()
          .neq("id", "00000000-0000-0000-0000-000000000000");
        await supabase.from("academic_calendar").insert({
          session_id: currentSession.id,
          term_id: term_id,
        });
      }

      console.log(
        "[Set Current Term] Successfully set current term",
      );
      return c.json({ success: true });
    } catch (error) {
      console.error("[Set Current Term] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to set current term",
        },
        500,
      );
    }
  },
);

