// Get Marks Completion Status for Publishing Control
app.get("/make-server-1ddd013a/marks-completion", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // ✅ FIX: Use verifyUserAuth instead of supabase.auth.getUser(accessToken)
    const {
      data: { user },
      error: authError,
    } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      console.error("[Marks Completion] Auth error:", authError?.message || "User not found");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const url = new URL(c.req.url);
    const session = url.searchParams.get("session");
    const term = url.searchParams.get("term");
    const type = url.searchParams.get("type"); // ✅ NEW: Get type parameter (midterm/terminal)

    if (!session || !term) {
      return c.json(
        {
          success: false,
          error: "Session and term are required",
        },
        400,
      );
    }

    if (!type || (type !== "midterm" && type !== "terminal")) {
      return c.json(
        {
          success: false,
          error: "Type must be 'midterm' or 'terminal'",
        },
        400,
      );
    }

    console.log(
      "[Marks Completion] Checking for session:",
      session,
      "term:",
      term,
      "type:",
      type,
    );

    // Get exams for this session and term (active or completed)
    // ✅ FIX: Include both 'active' and 'completed' exams for result publishing
    // Excludes only 'draft' exams
    const { data: exams, error: examsError } = await supabase
      .from("exams")
      .select("id, name, status")
      .eq("session", session)
      .eq("term", term)
      .in("status", ["active", "completed"]);

    if (examsError) {
      console.error(
        "[Marks Completion] Error fetching exams:",
        examsError,
      );
      return c.json(
        { success: false, error: "Failed to fetch exams" },
        500,
      );
    }

    const examIds = exams?.map((e) => e.id) || [];
    console.log(
      "[Marks Completion] Found exams:",
      examIds,
      "Exam names:",
      exams?.map((e) => e.name),
      "Statuses:",
      exams?.map((e) => e.status),
    );

    if (!exams || exams.length === 0) {
      console.log(
        "[Marks Completion] No exams found (status: active/completed)",
      );
      // If no active exams, all marks are considered complete
      return c.json({
        success: true,
        subjects: [],
        all_complete: true,
        marks_exist: false,
        message:
          "No exams found for this session/term. Please ensure exam status is 'active' or 'completed'.",
      });
    }

    // ✅ Fetch ALL subject assignments - we'll show ALL subjects and their completion status
    const { data: assignments, error: assignmentsError } =
      await supabase
        .from("subject_assignments")
        .select(
          `
          *,
          subjects (id, name, code, level),
          classes (id, name, level, sections (name)),
          profiles (id, first_name, last_name)
        `,
        )
        .order("created_at", { ascending: false });

    if (assignmentsError) {
      console.error(
        "[Marks Completion] Error fetching subject assignments:",
        assignmentsError,
      );
      return c.json(
        {
          success: false,
          error: "Failed to fetch subject assignments",
        },
        500,
      );
    }

    console.log(
      "[Marks Completion] Found",
      assignments?.length || 0,
      "total subject assignments",
    );

    if (!assignments || assignments.length === 0) {
      console.log(
        `[Marks Completion] No subject assignments found`,
      );
      return c.json({
        success: true,
        subjects: [],
        total_checks: 0,
        completed_checks: 0,
        all_complete: false,
        marks_exist: false,
        message: `No subject assignments found`,
      });
    }

    // Group assignments by subject to build the completion data structure
    // Each subject will have marks info for only the classes it's assigned to
    const subjectMap = new Map<string, any>();

    for (const assignment of assignments) {
      const subjectId = assignment.subject_id;
      const subject = (assignment as any).subjects;
      const classInfo = (assignment as any).classes;
      const teacher = (assignment as any).profiles;

      if (!subject || !classInfo) {
        console.warn(
          "[Marks Completion] Skipping assignment with missing data:",
          assignment.id,
        );
        continue;
      }

      // Initialize subject entry if it doesn't exist
      if (!subjectMap.has(subjectId)) {
        subjectMap.set(subjectId, {
          id: subject.id,
          name: subject.name,
          code: subject.code,
          level: subject.level || "junior",
          teacher_name: teacher
            ? `${teacher.first_name} ${teacher.last_name}`
            : "No teacher assigned",
          class_marks: {},
          assignments: [], // Track which classes this subject is assigned to
        });
      }

      // Add this class to the subject's assignments
      const subjectData = subjectMap.get(subjectId);
      subjectData.assignments.push({
        class_id: classInfo.id,
        class_name: classInfo.name,
        section_name: (classInfo as any).sections?.name || null,
      });
    }

    console.log(
      `[Marks Completion] Processing ${subjectMap.size} unique subjects with assignments`,
    );

    // Check marks for each subject-class combination
    const subjectCompletion = await Promise.all(
      Array.from(subjectMap.values()).map(
        async (subjectData) => {
          const classMarks: Record<
            string,
            {
              has_marks: boolean;
              count: number;
              status:
                | "complete"
                | "pending"
                | "partial"
                | "not_started";
              total_students: number;
              students_with_marks: number;
              students_with_approved: number;
              entry_rate: number;
              approval_rate: number;
            }
          > = {};

          // Only check marks for classes where this subject is actually assigned
          for (const classAssignment of subjectData.assignments) {
            // Create standardized display name for class WITH section
            // For junior classes: convert "JSS 1" -> "JS1", "JSS1" -> "JS1"
            // For senior classes: convert "SSS 1" -> "SS1", "SSS1" -> "SS1"
            let baseClassName =
              classAssignment.class_name.trim();

            // Standardize to JS1/JS2/JS3 format (remove spaces and extra 'S')
            baseClassName = baseClassName
              .replace(/JSS\s*([123])/, "JS$1")
              .replace(/SSS\s*([123])/, "SS$1")
              .replace(/JS\s*([123])/, "JS$1")
              .replace(/SS\s*([123])/, "SS$1");

            // IMPORTANT: Include section name if present (e.g., "JS3 Diamond")
            const className = classAssignment.section_name
              ? `${baseClassName} ${classAssignment.section_name}`
              : baseClassName;

            console.log(`[Marks Completion] Processing:`, {
              subject: subjectData.name,
              class_id: classAssignment.class_id,
              original_class_name: classAssignment.class_name,
              section_name:
                classAssignment.section_name || "none",
              normalized_base: baseClassName,
              final_display_name: className,
            });

            // ✅ CRITICAL FIX: Get ONLY students assigned to this subject via student_subjects table
            // Filter by session to get only current session students
            const { data: studentSubjects } = await supabase
              .from("student_subjects")
              .select("student_id")
              .eq("class_id", classAssignment.class_id)
              .eq("subject_id", subjectData.id)
              .eq("session", session)
              .eq("status", "active");

            const studentIds =
              studentSubjects?.map((ss) => ss.student_id) || [];
            const totalStudents = studentIds.length;

            console.log(
              `[Marks Completion] ${subjectData.name} - ${classAssignment.class_name} (${session}): ${totalStudents} students assigned to this subject`,
            );

            // Skip if no students in this class
            if (totalStudents === 0) {
              classMarks[className] = {
                has_marks: false, // ✅ FIX: Empty class should NOT show as complete
                count: 0,
                status: "not_started", // ✅ FIX: Show as not started (red X)
                total_students: 0,
                students_with_marks: 0,
                students_with_approved: 0,
                entry_rate: 0, // ✅ FIX: 0% not 100%
                approval_rate: 0, // ✅ FIX: 0% not 100%
              };
              continue;
            }

            // Get ALL marks for this subject+exam combination (any status) - ONLY for students in this class
            const { data: allMarks, error: allMarksError } =
              await supabase
                .from("marks")
                .select("id, student_id, status, exam_id")
                .eq("subject_id", subjectData.id)
                .in("exam_id", examIds)
                .in("student_id", studentIds)
                .eq("type", type); // ✅ CRITICAL FIX: Filter by type (midterm/terminal)

            if (allMarksError) {
              console.error(
                `[Marks Completion] Error fetching all marks for ${subjectData.name} - ${className}:`,
                allMarksError,
              );
            }

            // Get only APPROVED marks - ONLY for students in this class
            const {
              data: approvedMarks,
              error: approvedMarksError,
            } = await supabase
              .from("marks")
              .select("id, student_id, exam_id")
              .eq("subject_id", subjectData.id)
              .in("exam_id", examIds)
              .eq("status", "approved")
              .in("student_id", studentIds)
              .eq("type", type); // ✅ CRITICAL FIX: Filter by type (midterm/terminal)

            if (approvedMarksError) {
              console.error(
                `[Marks Completion] Error fetching approved marks for ${subjectData.name} - ${className}:`,
                approvedMarksError,
              );
            }

            // Build a map of student -> exam_ids for all marks
            const studentMarksMap = new Map<
              string,
              Set<string>
            >();
            allMarks?.forEach((mark) => {
              if (!studentMarksMap.has(mark.student_id)) {
                studentMarksMap.set(mark.student_id, new Set());
              }
              studentMarksMap
                .get(mark.student_id)!
                .add(mark.exam_id);
            });

            // Build a map of student -> exam_ids for approved marks
            const studentApprovedMap = new Map<
              string,
              Set<string>
            >();
            approvedMarks?.forEach((mark) => {
              if (!studentApprovedMap.has(mark.student_id)) {
                studentApprovedMap.set(
                  mark.student_id,
                  new Set(),
                );
              }
              studentApprovedMap
                .get(mark.student_id)!
                .add(mark.exam_id);
            });

            // Count students who have marks for ALL required exams
            const requiredExamCount = examIds.length;
            let studentsWithCompleteMarks = 0;
            let studentsWithCompleteApproved = 0;

            studentIds.forEach((studentId) => {
              const studentExams =
                studentMarksMap.get(studentId);
              const studentApprovedExams =
                studentApprovedMap.get(studentId);

              // Check if student has marks for all exams
              if (
                studentExams &&
                studentExams.size >= requiredExamCount
              ) {
                studentsWithCompleteMarks++;
              }

              // Check if student has approved marks for all exams
              if (
                studentApprovedExams &&
                studentApprovedExams.size >= requiredExamCount
              ) {
                studentsWithCompleteApproved++;
              }
            });

            // For backward compatibility, also track unique students (regardless of exam coverage)
            const uniqueStudentsWithMarks = new Set(
              allMarks?.map((m) => m.student_id) || [],
            );
            const studentsWithMarks =
              uniqueStudentsWithMarks.size;

            const uniqueStudentsWithApproved = new Set(
              approvedMarks?.map((m) => m.student_id) || [],
            );
            const studentsWithApproved =
              uniqueStudentsWithApproved.size;

            // Use the stricter check: students must have marks for ALL exams
            const studentsWithMarksToUse =
              studentsWithCompleteMarks;
            const studentsWithApprovedToUse =
              studentsWithCompleteApproved;

            // Calculate rates using the stricter check (must have ALL exams)
            const entryRate =
              totalStudents > 0
                ? Math.round(
                    (studentsWithMarksToUse / totalStudents) *
                      100,
                  )
                : 0;
            const approvalRate =
              totalStudents > 0
                ? Math.round(
                    (studentsWithApprovedToUse /
                      totalStudents) *
                      100,
                  )
                : 0;

            // Determine status
            let status:
              | "complete"
              | "pending"
              | "partial"
              | "not_started";
            if (approvalRate === 100) {
              status = "complete";
            } else if (
              entryRate === 100 &&
              approvalRate < 100
            ) {
              status = "pending"; // All marks entered, waiting for approval
            } else if (studentsWithMarksToUse > 0) {
              status = "partial"; // Some marks entered
            } else {
              status = "not_started"; // No marks at all
            }

            // Debug logging
            console.log(
              `[Marks Completion] ${subjectData.name} - ${className}:`,
              {
                totalStudents,
                requiredExamCount,
                studentsWithCompleteMarks,
                studentsWithCompleteApproved,
                entryRate,
                approvalRate,
                status,
                allMarksCount: allMarks?.length || 0,
                approvedMarksCount: approvedMarks?.length || 0,
                examIds,
              },
            );

            classMarks[className] = {
              has_marks: approvalRate === 100, // Only true if 100% approved
              count: allMarks?.length || 0,
              status,
              total_students: totalStudents,
              students_with_marks: studentsWithMarksToUse,
              students_with_approved: studentsWithApprovedToUse,
              entry_rate: entryRate,
              approval_rate: approvalRate,
            };
          }

          return {
            id: subjectData.id,
            name: subjectData.name,
            code: subjectData.code,
            level: subjectData.level || "junior",
            teacher_name: subjectData.teacher_name,
            class_marks: classMarks,
          };
        },
      ),
    );

    console.log(
      "[Marks Completion] Subject completion:",
      subjectCompletion,
    );

    // Calculate overall completion
    let totalChecks = 0;
    let completedChecks = 0;
    let totalMarksCount = 0; // ✅ Track if ANY marks exist

    subjectCompletion.forEach((subject) => {
      Object.values(subject.class_marks).forEach((mark) => {
        totalChecks++;
        if (mark.has_marks) completedChecks++;
        totalMarksCount += mark.count; // ✅ Sum up all marks
      });
    });

    const marksExist = totalMarksCount > 0; // ✅ NEW: Check if ANY marks exist for this type

    console.log(
      `[Marks Completion] Type: ${type}, Total marks count: ${totalMarksCount}, Marks exist: ${marksExist}`,
    );

    return c.json({
      success: true,
      subjects: subjectCompletion,
      total_checks: totalChecks,
      completed_checks: completedChecks,
      all_complete:
        totalChecks > 0 && totalChecks === completedChecks,
      marks_exist: marksExist, // ✅ NEW: Return whether ANY marks exist
    });
  } catch (error) {
    console.error("[Marks Completion] Error:", error);
    return c.json(
      {
        success: false,
        error: "Failed to check marks completion",
      },
      500,
    );
  }
});

// ✅ NEW: Cleanup orphaned student_subjects records
app.post("/make-server-1ddd013a/cleanup-orphaned-assignments", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      console.error("[Cleanup] Auth error:", authError?.message || "User not found");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Check if user is admin, principal_admin, or it_admin
    const { data: profile } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .single();

    const allowedRoles = ["admin", "principal_admin", "it_admin"];
    if (!profile?.role || !allowedRoles.includes(profile.role)) {
      return c.json(
        { success: false, error: "Only admins can cleanup orphaned records" },
        403,
      );
    }

    console.log("[Cleanup] Starting comprehensive cleanup of orphaned student_subjects records...");

    // Get all student_subjects records with class info
    const { data: allAssignments } = await supabase
      .from("student_subjects")
      .select("id, student_id, class_id, session, status");

    if (!allAssignments) {
      return c.json({
        success: true,
        deleted_count: 0,
        message: "No student_subjects records found",
      });
    }

    console.log(`[Cleanup] Checking ${allAssignments.length} student_subjects records...`);

    // Check for graduated students
    const { data: graduatedStudents } = await supabase
      .from("graduated_students")
      .select("student_id");
    
    const graduatedStudentIds = new Set(
      graduatedStudents?.map(g => g.student_id) || []
    );

    // Check each assignment for orphaned status
    const orphanedIds: string[] = [];
    const orphanedReasons: Record<string, string> = {};
    
    for (const assignment of allAssignments) {
      let isOrphaned = false;
      let reason = "";

      // Check 1: Student profile deleted
      const { data: profile } = await supabase
        .from("profiles")
        .select("id, class_id, role")
        .eq("id", assignment.student_id)
        .single();

      if (!profile) {
        isOrphaned = true;
        reason = "Student profile deleted";
      }
      // Check 2: Student graduated
      else if (graduatedStudentIds.has(assignment.student_id)) {
        isOrphaned = true;
        reason = "Student graduated";
      }
      // Check 3: Student promoted/moved (class_id mismatch)
      else if (profile.class_id !== assignment.class_id) {
        isOrphaned = true;
        reason = `Student moved from class ${assignment.class_id} to ${profile.class_id}`;
      }
      // Check 4: Student is not actually a student anymore (role changed)
      else if (profile.role !== "student") {
        isOrphaned = true;
        reason = `User role changed to ${profile.role}`;
      }

      if (isOrphaned) {
        console.log(`[Cleanup] Orphaned: ${assignment.id} - ${reason}`);
        orphanedIds.push(assignment.id);
        orphanedReasons[assignment.id] = reason;
      }
    }

    console.log(`[Cleanup] Found ${orphanedIds.length} orphaned records to delete`);

    // Delete orphaned records
    let deletedCount = 0;
    if (orphanedIds.length > 0) {
      const { error: deleteError } = await supabase
        .from("student_subjects")
        .delete()
        .in("id", orphanedIds);

      if (deleteError) {
        console.error("[Cleanup] Delete error:", deleteError);
        return c.json(
          { success: false, error: deleteError.message },
          500,
        );
      }

      deletedCount = orphanedIds.length;
    }

    console.log(`[Cleanup] Successfully deleted ${deletedCount} orphaned records`);

    // Count reasons
    const reasonCounts: Record<string, number> = {};
    Object.values(orphanedReasons).forEach(reason => {
      const key = reason.includes("moved") ? "Promoted/Moved" : 
                  reason.includes("graduated") ? "Graduated" :
                  reason.includes("deleted") ? "Deleted" :
                  reason.includes("role") ? "Role Changed" : "Other";
      reasonCounts[key] = (reasonCounts[key] || 0) + 1;
    });

    return c.json({
      success: true,
      deleted_count: deletedCount,
      message: `Cleaned up ${deletedCount} orphaned student assignment(s)`,
      breakdown: reasonCounts,
    });
  } catch (error) {
    console.error("[Cleanup] Error:", error);
    return c.json(
      {
        success: false,
        error: error instanceof Error ? error.message : "Unknown error",
      },
      500,
    );
  }
});

// Debug Endpoint: Check student_subjects for class mismatches
app.get("/make-server-1ddd013a/debug-student-subjects", async (c) => {
  try {
    const accessToken = c.req.header("Authorization")?.split(" ")[1];
    const { data: { user } } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json({ success: false, error: "Unauthorized" }, 401);
    }

    // Get current session
    const { data: currentSession } = await supabase
      .from("academic_sessions")
      .select("session_name")
      .eq("is_current", true)
      .single();

    // Get all student_subjects with profile info
    const { data: studentSubjects } = await supabase
      .from("student_subjects")
      .select("id, student_id, class_id, subject_id, session, status")
      .eq("session", currentSession?.session_name || "2024/2025")
      .limit(50);

    const analysis: any[] = [];
    
    for (const ss of studentSubjects || []) {
      const { data: profile } = await supabase
        .from("profiles")
        .select("id, class_id, role, first_name, last_name")
        .eq("id", ss.student_id)
        .single();

      const { data: classInfo } = await supabase
        .from("classes")
        .select("name")
        .eq("id", ss.class_id)
        .single();

      const { data: currentClassInfo } = await supabase
        .from("classes")
        .select("name")
        .eq("id", profile?.class_id || "")
        .single();

      const { data: subjectInfo } = await supabase
        .from("subjects")
        .select("name")
        .eq("id", ss.subject_id)
        .single();

      const isGraduated = await supabase
        .from("graduated_students")
        .select("id")
        .eq("student_id", ss.student_id)
        .single();

      analysis.push({
        student_subject_id: ss.id,
        student_id: ss.student_id,
        student_name: profile ? `${profile.first_name} ${profile.last_name}` : "DELETED",
        subject: subjectInfo?.name || "Unknown",
        assigned_class: classInfo?.name || "Unknown",
        current_class: currentClassInfo?.name || profile?.class_id || "NO CLASS",
        is_mismatch: profile?.class_id !== ss.class_id,
        role: profile?.role || "DELETED",
        is_graduated: !!isGraduated.data,
        status: ss.status
      });
    }

    const mismatches = analysis.filter(a => a.is_mismatch || a.role !== "student" || a.is_graduated);

    return c.json({
      success: true,
      total_records: analysis.length,
      mismatches: mismatches.length,
      details: analysis,
      mismatch_details: mismatches
    });
  } catch (error) {
    console.error("[Debug Student Subjects] Error:", error);
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : "Unknown error"
    }, 500);
  }
});

// Debug Endpoint: Check specific subject marks
app.get(
  "/make-server-1ddd013a/debug-subject-marks",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id)
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );

      const url = new URL(c.req.url);
      const subjectName =
        url.searchParams.get("subject") || "Data Processing";
      const className = url.searchParams.get("class") || "SS1";
      const session = url.searchParams.get("session");
      const term = url.searchParams.get("term");

      if (!session || !term) {
        return c.json(
          {
            success: false,
            error: "Session and term are required",
          },
          400,
        );
      }

      // Get subject - try exact match first, then pattern match
      let subjectQuery = await supabase
        .from("subjects")
        .select("id, name, code")
        .eq("name", subjectName)
        .maybeSingle();

      let subject = subjectQuery.data;

      // If exact match fails, try pattern match
      if (!subject) {
        subjectQuery = await supabase
          .from("subjects")
          .select("id, name, code")
          .ilike("name", `%${subjectName}%`)
          .limit(1)
          .maybeSingle();
        subject = subjectQuery.data;
      }

      if (!subject) {
        // Get all subjects to help with debugging
        const { data: allSubjects } = await supabase
          .from("subjects")
          .select("name")
          .limit(20);

        return c.json(
          {
            success: false,
            error: `Subject "${subjectName}" not found`,
            available_subjects:
              allSubjects?.map((s) => s.name) || [],
            hint: "Check the available_subjects array for valid subject names",
          },
          404,
        );
      }

      // Get class - try exact match first, then pattern match
      let classQuery = await supabase
        .from("classes")
        .select("id, name")
        .eq("name", className)
        .maybeSingle();

      let classData = classQuery.data;

      // If exact match fails, try pattern match
      if (!classData) {
        classQuery = await supabase
          .from("classes")
          .select("id, name")
          .ilike("name", `%${className}%`)
          .limit(1)
          .maybeSingle();
        classData = classQuery.data;
      }

      if (!classData) {
        // Get all classes to help with debugging
        const { data: allClasses } = await supabase
          .from("classes")
          .select("name")
          .limit(20);

        return c.json(
          {
            success: false,
            error: `Class "${className}" not found`,
            available_classes:
              allClasses?.map((c) => c.name) || [],
            hint: "Check the available_classes array for valid class names",
          },
          404,
        );
      }

      // Get ACTIVE exams only
      const { data: exams } = await supabase
        .from("exams")
        .select("id, name, status")
        .eq("session", session)
        .eq("term", term)
        .eq("status", "active");

      const examIds = exams?.map((e) => e.id) || [];

      if (!exams || exams.length === 0) {
        return c.json(
          {
            success: false,
            error: `No active exams found for ${session} - ${term}`,
            hint: 'Please set at least one exam to "active" status in Exam Management',
          },
          404,
        );
      }

      // Get students in class
      const { data: students } = await supabase
        .from("profiles")
        .select("id, first_name, last_name")
        .eq("class_id", classData.id)
        .eq("role", "student")
        .or("is_graduated.is.null,is_graduated.eq.false");

      const studentIds = students?.map((s) => s.id) || [];

      // Get all marks
      const { data: allMarks } = await supabase
        .from("marks")
        .select(
          "id, student_id, exam_id, status, type, midterm_ca1, midterm_ca2, midterm_exam, midterm_total, terminal_ca1, terminal_ca2, terminal_exam, terminal_total",
        )
        .eq("subject_id", subject.id)
        .in("exam_id", examIds)
        .in("student_id", studentIds);

      // Group by student
      const marksByStudent = new Map<string, any[]>();
      allMarks?.forEach((mark) => {
        const student = students?.find(
          (s) => s.id === mark.student_id,
        );
        const exam = exams?.find((e) => e.id === mark.exam_id);
        const key = mark.student_id;
        if (!marksByStudent.has(key)) {
          marksByStudent.set(key, []);
        }
        marksByStudent.get(key)!.push({
          ...mark,
          student_name: student
            ? `${student.first_name} ${student.last_name}`
            : "Unknown",
          exam_name: exam?.name || "Unknown",
        });
      });

      // Calculate summary statistics
      const totalMarks = allMarks?.length || 0;
      const approvedMarks =
        allMarks?.filter((m) => m.status === "approved")
          .length || 0;
      const studentsWithMarks = marksByStudent.size;
      const studentsWithoutMarks =
        studentIds.length - marksByStudent.size;

      // Calculate students with complete approved marks (approved marks for ALL active exams)
      const studentsWithCompleteMarks = Array.from(
        marksByStudent.values(),
      ).filter(
        (marks) =>
          marks.filter((m) => m.status === "approved")
            .length === exams.length,
      ).length;

      return c.json({
        success: true,
        subject: subject.name,
        class: classData.name,
        session,
        term,
        total_students: students?.length || 0,
        exams: exams?.map((e) => ({ id: e.id, name: e.name })),
        marks_by_student: Array.from(
          marksByStudent.entries(),
        ).map(([studentId, marks]) => ({
          student_id: studentId,
          student_name: marks[0]?.student_name,
          marks: marks.map((m) => ({
            exam: m.exam_name,
            status: m.status,
            ca1: m.ca1,
            ca2: m.ca2,
            exam_score: m.exam_score,
            total: m.total,
          })),
          exams_count: marks.length,
          approved_count: marks.filter(
            (m) => m.status === "approved",
          ).length,
        })),
        summary: {
          total_marks: totalMarks,
          approved_marks: approvedMarks,
          students_with_marks: studentsWithMarks,
          students_without_marks: studentsWithoutMarks,
          students_with_complete_approved_marks:
            studentsWithCompleteMarks,
          active_exams_count: exams.length,
        },
      });
    } catch (error) {
      console.error("[Debug Subject Marks] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to debug subject marks",
        },
        500,
      );
    }
  },
);

