// Toggle Result Publishing
app.post(
  "/make-server-1ddd013a/toggle-result-publishing",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id)
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );

      const body = await c.req.json();
      const { session_name, term_name, type } = body; // ✅ NEW: Include type

      if (
        !type ||
        (type !== "midterm" && type !== "terminal")
      ) {
        return c.json(
          {
            success: false,
            error: "Type must be 'midterm' or 'terminal'",
          },
          400,
        );
      }

      const configs = await kv.get("result_publishing_configs");
      const configsList = configs || [];

      // ✅ NEW: Find config by session, term, AND type
      const existingIndex = configsList.findIndex(
        (c: any) =>
          c.session_name === session_name &&
          c.term_name === term_name &&
          c.type === type,
      );

      if (existingIndex >= 0) {
        configsList[existingIndex].is_published =
          !configsList[existingIndex].is_published;
        await kv.set("result_publishing_configs", configsList);

        console.log(
          `[Toggle Publishing] Toggled ${type} for ${session_name} - ${term_name} to ${configsList[existingIndex].is_published}`,
        );

        return c.json({
          success: true,
          is_published: configsList[existingIndex].is_published,
        });
      } else {
        // ✅ NEW: Include type when creating new config
        configsList.push({
          session_name,
          term_name,
          type,
          is_published: true,
        });
        await kv.set("result_publishing_configs", configsList);

        console.log(
          `[Toggle Publishing] Created new ${type} publishing config for ${session_name} - ${term_name}`,
        );

        return c.json({ success: true, is_published: true });
      }
    } catch (error) {
      console.error("[Toggle Publishing] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to toggle publishing",
        },
        500,
      );
    }
  },
);

