// Approve Teacher Comment
app.post(
  "/make-server-1ddd013a/approve-teacher-comment",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id)
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );

      const body = await c.req.json();
      const {
        class_id,
        session,
        term,
        exam,
        type,
        student_id,
      } = body;

      if (
        !class_id ||
        !session ||
        !term ||
        !exam ||
        !type ||
        !student_id
      ) {
        return c.json(
          {
            success: false,
            error: "Missing required parameters",
          },
          400,
        );
      }

      // Use class_id directly in the key
      const key = `teacher_comments:class:${class_id}:${session}:${term}:${exam}:${type}`;
      const data = await kv.get(key);

      if (!data || !data.comments) {
        return c.json(
          { success: false, error: "Comments not found" },
          404,
        );
      }

      // Update the specific comment
      const updatedComments = data.comments.map((c: any) => {
        if (c.student_id === student_id) {
          return {
            ...c,
            status: "approved",
            reviewed_at: new Date().toISOString(),
            reviewed_by: user.id,
            rejection_reason: undefined,
          };
        }
        return c;
      });

      await kv.set(key, {
        ...data,
        comments: updatedComments,
      });

      console.log(
        `[Approve Comment] Approved comment for student ${student_id}`,
      );

      return c.json({ success: true });
    } catch (error) {
      console.error("[Approve Comment] Error:", error);
      return c.json(
        { success: false, error: "Failed to approve comment" },
        500,
      );
    }
  },
);

