// Migrate Teacher Comments to New Key Structure
app.post(
  "/make-server-1ddd013a/migrate-teacher-comments",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id)
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );

      // Check if user is principal
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (profile?.role !== "principal") {
        return c.json(
          {
            success: false,
            error: "Only principals can run migrations",
          },
          403,
        );
      }

      console.log(
        "[Migration] Starting teacher comments migration...",
      );
      console.log("[Migration] User ID:", user.id);
      console.log("[Migration] User role:", profile?.role);

      // Query the kv_store table directly to get all keys
      const { data: allKeyData, error: queryError } =
        await supabase
          .from("kv_store_1ddd013a")
          .select("key, value")
          .like("key", "teacher_comments:%");

      if (queryError) {
        console.error(
          "[Migration] Error querying keys:",
          queryError,
        );
        return c.json(
          {
            success: false,
            error: "Failed to query keys",
            details: queryError.message,
          },
          500,
        );
      }

      console.log(
        `[Migration] Found ${allKeyData?.length || 0} total teacher comment keys`,
      );
      if (allKeyData && allKeyData.length > 0) {
        console.log(
          "[Migration] Sample keys:",
          allKeyData.map((k) => k.key).slice(0, 5),
        );
      }

      let migratedCount = 0;
      let skippedCount = 0;
      const errors: string[] = [];

      for (const row of allKeyData || []) {
        const oldKey = row.key;
        console.log(`[Migration] Processing key: ${oldKey}`);

        // Skip if already in new format (contains ':class:')
        if (oldKey.includes(":class:")) {
          console.log(
            `[Migration] Skipping - already in new format`,
          );
          skippedCount++;
          continue;
        }

        // Parse old key format: teacher_comments:${teacher_id}:${session}:${term}:${exam}:${type}
        const parts = oldKey.split(":");
        console.log(
          `[Migration] Key parts (${parts.length}):`,
          parts,
        );

        if (parts.length !== 6) {
          const error = `Invalid key format (expected 6 parts, got ${parts.length}): ${oldKey}`;
          console.log(`[Migration] ${error}`);
          errors.push(error);
          continue;
        }

        const [prefix, teacherId, session, term, exam, type] =
          parts;
        console.log(
          `[Migration] Parsed - Teacher ID: ${teacherId}, Session: ${session}, Term: ${term}, Exam: ${exam}, Type: ${type}`,
        );

        // Find which class this teacher is assigned to
        const { data: teacherClass, error: classError } =
          await supabase
            .from("classes")
            .select("id, name")
            .eq("class_teacher_id", teacherId)
            .limit(1)
            .maybeSingle();

        console.log(
          `[Migration] Class lookup for teacher ${teacherId}:`,
          teacherClass,
          classError,
        );

        if (classError || !teacherClass) {
          const error = `No class found for teacher ${teacherId} (key: ${oldKey})`;
          console.log(`[Migration] ${error}`);
          errors.push(error);
          continue;
        }

        // Create new key with class_id
        const newKey = `teacher_comments:class:${teacherClass.id}:${session}:${term}:${exam}:${type}`;

        // Get the old data from the row
        const oldData = row.value;

        if (!oldData) {
          errors.push(`No data found for key: ${oldKey}`);
          continue;
        }

        // Copy to new key with updated structure
        await kv.set(newKey, {
          ...oldData,
          class_id: teacherClass.id,
          migrated_from: oldKey,
          migrated_at: new Date().toISOString(),
        });

        console.log(
          `[Migration] Migrated ${oldKey} -> ${newKey} (${teacherClass.name})`,
        );
        migratedCount++;

        // Optionally delete old key (commented out for safety)
        // await kv.del(oldKey);
      }

      console.log(
        `[Migration] Complete. Migrated: ${migratedCount}, Skipped: ${skippedCount}, Errors: ${errors.length}`,
      );

      return c.json({
        success: true,
        migrated: migratedCount,
        skipped: skippedCount,
        errors,
        message: `Successfully migrated ${migratedCount} teacher comment sets. Old keys preserved for safety.`,
      });
    } catch (error) {
      console.error("[Migration] Error:", error);
      return c.json(
        {
          success: false,
          error: "Migration failed",
          details: String(error),
        },
        500,
      );
    }
  },
);

