// GET all PINs with student information (for admin)
app.get("/make-server-1ddd013a/pins/all", async (c) => {
  try {
    console.log("[Pins] Fetching all PINs...");

    // Get all pins from the database
    const { data: pins, error: pinsError } = await supabase
      .from("pins")
      .select("*")
      .order("created_at", { ascending: false });

    if (pinsError) {
      console.error("[Pins] Error fetching pins:", pinsError);
      return c.json(
        { success: false, error: "Failed to fetch pins" },
        500,
      );
    }

    console.log(`[Pins] Found ${pins?.length || 0} pins`);

    // Enrich pins with student information
    const enrichedPins = await Promise.all(
      (pins || []).map(async (pin) => {
        // Get student info
        const { data: student } = await supabase
          .from("profiles")
          .select(
            "first_name, middle_name, last_name, class_id",
          )
          .eq("id", pin.student_id)
          .single();

        let studentClass = "N/A";
        if (student?.class_id) {
          const { data: classData } = await supabase
            .from("classes")
            .select("name, sections(name)")
            .eq("id", student.class_id)
            .single();

          if (classData) {
            // Note: classData.name already includes the section
            studentClass = classData.name;
          }
        }

        const studentName = student
          ? `${student.first_name} ${student.middle_name || ""} ${student.last_name}`.trim()
          : "Unknown Student";

        return {
          ...pin,
          student_name: studentName,
          student_class: studentClass,
        };
      }),
    );

    return c.json({
      success: true,
      pins: enrichedPins,
    });
  } catch (error) {
    console.error("[Pins] Error:", error);
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to fetch pins",
      },
      500,
    );
  }
});

