// Director Marks Compliance - Simplified View
app.get(
  "/make-server-1ddd013a/director-marks-compliance",
  async (c) => {
    try {
      console.log(
        "[Director Marks Compliance] Request received",
      );

      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);

      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Verify director role
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      if (profile?.role !== "director") {
        return c.json(
          {
            success: false,
            error: "Access denied. Director only.",
          },
          403,
        );
      }

      console.log(
        "[Director Marks Compliance] Fetching marks statistics...",
      );

      // Get active term
      const activeTerm = await kv.get("active_term");
      if (!activeTerm) {
        return c.json({
          success: true,
          stats: {
            totalExams: 0,
            completedExams: 0,
            pendingApprovals: 0,
            approvedExams: 0,
          },
        });
      }

      // Get all exams for active term
      const { data: exams } = await supabase
        .from("exams")
        .select("id, exam_type")
        .eq("term", activeTerm.term)
        .eq("session", activeTerm.session)
        .eq("status", "active");

      if (!exams || exams.length === 0) {
        return c.json({
          success: true,
          stats: {
            totalExams: 0,
            completedExams: 0,
            pendingApprovals: 0,
            approvedExams: 0,
          },
        });
      }

      let completedExams = 0;
      let pendingApprovals = 0;
      let approvedExams = 0;

      for (const exam of exams) {
        // Check completion status
        const completionKey = `marks_completion_${exam.id}`;
        const completion = await kv.get(completionKey);

        if (completion?.is_complete) {
          completedExams++;

          // Check approval status
          const approvalKey = `marks_approval_${exam.exam_type}_${activeTerm.term}_${activeTerm.session}`;
          const approval = await kv.get(approvalKey);

          if (approval?.status === "approved") {
            approvedExams++;
          } else {
            pendingApprovals++;
          }
        }
      }

      const stats = {
        totalExams: exams.length,
        completedExams,
        pendingApprovals,
        approvedExams,
      };

      console.log("[Director Marks Compliance] Stats:", stats);

      return c.json({
        success: true,
        stats,
      });
    } catch (error) {
      console.error(
        "[Director Marks Compliance] Error:",
        error,
      );
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Unknown error",
        },
        500,
      );
    }
  },
);

