// Get timetable settings
app.get(
  "/make-server-1ddd013a/timetable-settings",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Fetch timetable settings from database (stored as JSONB)
      const { data: settings, error } = await supabase
        .from("timetable_settings")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(1)
        .single();

      if (error && error.code !== "PGRST116") {
        console.error(
          "[Timetable Settings] Database error:",
          error,
        );
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      return c.json({
        success: true,
        settings: settings?.config || null,
      });
    } catch (error) {
      console.error("[Timetable Settings] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch settings",
        },
        500,
      );
    }
  },
);

// Save timetable settings
app.post(
  "/make-server-1ddd013a/timetable-settings",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const body = await c.req.json();
      const { settings } = body;

      if (!settings) {
        return c.json(
          { success: false, error: "Settings are required" },
          400,
        );
      }

      // Upsert settings and return the ID
      const { data, error } = await supabase
        .from("timetable_settings")
        .upsert({
          config: settings,
          updated_by: user.id,
          updated_at: new Date().toISOString(),
        })
        .select('id')
        .single();

      if (error) {
        console.error(
          "[Timetable Settings] Save error:",
          error,
        );
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      return c.json({ success: true, id: data?.id });
    } catch (error) {
      console.error("[Timetable Settings] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to save settings",
        },
        500,
      );
    }
  },
);

