// Save timetable slots
app.post("/make-server-1ddd013a/timetable-slots", async (c) => {
  try {
    const accessToken = c.req.header("Authorization")?.split(" ")[1];
    if (!accessToken) {
      return c.json({ success: false, error: "Unauthorized" }, 401);
    }

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return c.json({ success: false, error: "Unauthorized" }, 401);
    }

    const body = await c.req.json();
    const { slots, settingsId } = body;

    if (!slots || !Array.isArray(slots)) {
      return c.json({ success: false, error: "Slots are required" }, 400);
    }

    if (!settingsId) {
      return c.json({ success: false, error: "Settings ID is required" }, 400);
    }

    // Filter out slots that don't have subject_config_id or pairs_id
    const slotsWithIds = slots.filter((slot: any) => 
      slot.subject_config_id !== null || slot.pairs_id !== null
    );

    console.log(`[Timetable] Received ${slots.length} slots, ${slotsWithIds.length} slots with IDs`);
    
    // Debug: Check for any non-null pairs_id values
    const slotsWithPairs = slotsWithIds.filter((slot: any) => slot.pairs_id !== null);
    if (slotsWithPairs.length > 0) {
      console.log(`[Timetable] ⚠️  Found ${slotsWithPairs.length} slots with pairs_id:`, slotsWithPairs.slice(0, 3));
    }
    
    if (slotsWithIds.length === 0) {
      return c.json({ success: false, error: "No valid slots to save" }, 400);
    }

    // Verify all subject_config_ids exist in the database
    const configIds = slotsWithIds
      .filter((slot: any) => slot.subject_config_id)
      .map((slot: any) => slot.subject_config_id);
    
    // Verify all pairs_id values exist in subject_pairs table
    const pairIds = slotsWithIds
      .filter((slot: any) => slot.pairs_id)
      .map((slot: any) => slot.pairs_id);
    
    let validPairIds = new Set<string>();
    if (pairIds.length > 0) {
      const { data: existingPairs } = await supabase
        .from("subject_pairs")
        .select("id")
        .in("id", pairIds);
      
      validPairIds = new Set(existingPairs?.map(p => p.id) || []);
      console.log(`[Timetable] Checked ${pairIds.length} pair IDs, ${validPairIds.size} are valid in subject_pairs table`);
    }
    
    if (configIds.length > 0) {
      const { data: existingConfigs } = await supabase
        .from("subject_configs")
        .select("id")
        .in("id", configIds);
      
      const validConfigIds = new Set(existingConfigs?.map(c => c.id) || []);
      console.log(`[Timetable] Checked ${configIds.length} config IDs, ${validConfigIds.size} are valid`);
      
      // Filter to only keep slots with valid config IDs or valid pairs_id
      const validSlots = slotsWithIds.filter((slot: any) => {
        // If has pairs_id, it must exist in subject_pairs table
        if (slot.pairs_id && !validPairIds.has(slot.pairs_id)) {
          console.warn(`[Timetable] Rejecting slot with invalid pairs_id: ${slot.pairs_id}`);
          return false;
        }
        // If has subject_config_id, it must exist in subject_configs table
        if (slot.subject_config_id && !validConfigIds.has(slot.subject_config_id)) {
          console.warn(`[Timetable] Rejecting slot with invalid subject_config_id: ${slot.subject_config_id}`);
          return false;
        }
        // Must have at least one valid ID
        return (slot.subject_config_id && validConfigIds.has(slot.subject_config_id)) ||
               (slot.pairs_id && validPairIds.has(slot.pairs_id));
      });
      
      if (validSlots.length === 0) {
        return c.json({ 
          success: false, 
          error: "No valid slots found. Subject configurations may have been deleted." 
        }, 400);
      }
      
      console.log(`[Timetable] ${validSlots.length} valid slots after verification`);

      // Delete existing slots for this settings
      const { error: deleteError } = await supabase
        .from("timetable_time_slots")
        .delete()
        .eq("timetable_settings_id", settingsId);

      if (deleteError) {
        console.error("[Timetable] Delete error:", deleteError);
        return c.json({ success: false, error: deleteError.message }, 500);
      }

      // Log first slot for debugging
      console.log("[Timetable] Sample slot:", validSlots[0]);

      // Insert new slots
      const { error: insertError } = await supabase
        .from("timetable_time_slots")
        .insert(validSlots);

      if (insertError) {
        console.error("[Timetable] Insert error:", insertError);
        return c.json({ success: false, error: insertError.message }, 500);
      }

      console.log(`[Timetable] Successfully saved ${validSlots.length} slots`);
      return c.json({ success: true, saved: validSlots.length });
    } else {
      // No config IDs, only pairs - save directly
      const { error: deleteError } = await supabase
        .from("timetable_time_slots")
        .delete()
        .eq("timetable_settings_id", settingsId);

      if (deleteError) {
        console.error("[Timetable] Delete error:", deleteError);
        return c.json({ success: false, error: deleteError.message }, 500);
      }

      const { error: insertError } = await supabase
        .from("timetable_time_slots")
        .insert(slotsWithIds);

      if (insertError) {
        console.error("[Timetable] Insert error:", insertError);
        return c.json({ success: false, error: insertError.message }, 500);
      }

      console.log(`[Timetable] Successfully saved ${slotsWithIds.length} slots (pairs only)`);
      return c.json({ success: true, saved: slotsWithIds.length });
    }


  } catch (error) {
    console.error("[Timetable] Error:", error);
    return c.json(
      {
        success: false,
        error: error instanceof Error ? error.message : "Failed to save timetable slots",
      },
      500
    );
  }
});

