// Save subject configurations
app.post("/make-server-1ddd013a/subject-configs", async (c) => {
  try {
    console.log(
      "=== [Subject Configs POST] Request received ===",
    );
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      console.log("[Subject Configs POST] No access token");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      console.log("[Subject Configs POST] Invalid user");
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const body = await c.req.json();
    const { configs } = body;
    console.log(
      `[Subject Configs POST] Received ${configs?.length || 0} configs to save`,
    );
    console.log(
      "[Subject Configs POST] Configs to save:",
      JSON.stringify(configs, null, 2),
    );

    if (!Array.isArray(configs)) {
      console.log(
        "[Subject Configs POST] Invalid configs format - not an array",
      );
      return c.json(
        { success: false, error: "Invalid configs format" },
        400,
      );
    }

    // Filter out null/undefined configs and validate
    const validConfigs = configs.filter(config => {
      if (!config) {
        console.warn("[Subject Configs POST] Skipping null/undefined config");
        return false;
      }
      if (!config.subjectId) {
        console.warn("[Subject Configs POST] Skipping config without subjectId:", config);
        return false;
      }
      return true;
    });

    console.log(
      `[Subject Configs POST] Filtered ${configs.length} configs to ${validConfigs.length} valid configs`,
    );

    if (validConfigs.length === 0) {
      console.warn("[Subject Configs POST] No valid configs to save");
      return c.json(
        { success: false, error: "No valid configurations provided" },
        400,
      );
    }

    // Save each config
    console.log(
      "[Subject Configs POST] Starting to save configs...",
    );
    for (const config of validConfigs) {
      const key = `subject_config:${config.subjectId}`;
      console.log(
        `[Subject Configs POST] Saving config with key: ${key}`,
      );
      console.log(
        `[Subject Configs POST] Config data:`,
        JSON.stringify(config, null, 2),
      );
      await kv.set(key, config);
      console.log(
        `[Subject Configs POST] Successfully saved config for subject: ${config.subjectName} (${config.subjectId})`,
      );
    }

    console.log(
      "[Subject Configs POST] All configs saved successfully",
    );

    // Verify by reading back
    console.log(
      "[Subject Configs POST] Verifying saved configs...",
    );
    const savedConfigs = await kv.getByPrefix(
      "subject_config:",
    );
    console.log(
      `[Subject Configs POST] Verification: Found ${savedConfigs.length} configs in KV store after save`,
    );

    // Return the saved configs so frontend can verify
    const savedConfigValues =
      savedConfigs.map((item) => item.value) || [];
    console.log(
      "[Subject Configs POST] Returning saved configs for verification",
    );

    return c.json({
      success: true,
      savedCount: validConfigs.length,
      verifiedCount: savedConfigs.length,
      configs: savedConfigValues, // Return the configs that were actually saved
    });
  } catch (error) {
    console.error("[Subject Configs POST] Save error:", error);
    console.error(
      "[Subject Configs POST] Error stack:",
      error instanceof Error ? error.stack : "No stack",
    );
    return c.json(
      {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to save subject configurations",
      },
      500,
    );
  }
});

