// Send Upload Reminder to Teacher
app.post(
  "/make-server-1ddd013a/send-upload-reminder",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
      } = await supabase.auth.getUser(accessToken);

      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const body = await c.req.json();
      const { teacherId, uploadId } = body;

      if (!teacherId) {
        return c.json(
          { success: false, error: "Teacher ID is required" },
          400,
        );
      }

      // Get teacher details
      const { data: teacher, error: teacherError } =
        await supabase
          .from("users")
          .select("email, first_name, last_name")
          .eq("id", teacherId)
          .single();

      if (teacherError || !teacher) {
        console.error(
          "[Send Reminder] Teacher not found:",
          teacherError,
        );
        return c.json(
          { success: false, error: "Teacher not found" },
          404,
        );
      }

      // Log the reminder (in a real app, this would send an email/notification)
      console.log(
        `[Send Reminder] Reminder sent to ${teacher.first_name} ${teacher.last_name} (${teacher.email})`,
      );
      console.log(
        `[Send Reminder] Upload ID: ${uploadId || "General reminder"}`,
      );

      // In production, you would integrate with an email service here:
      // - SendGrid, AWS SES, Resend, etc.
      // - Or use Supabase's built-in email templates

      // Store reminder in KV for tracking
      const reminderKey = `upload_reminder:${teacherId}:${Date.now()}`;
      await kv.set(reminderKey, {
        teacher_id: teacherId,
        teacher_email: teacher.email,
        upload_id: uploadId,
        sent_by: user.id,
        sent_at: new Date().toISOString(),
        type: uploadId ? "specific_upload" : "general",
      });

      return c.json({
        success: true,
        message: `Reminder sent to ${teacher.first_name} ${teacher.last_name}`,
        teacher: {
          name: `${teacher.first_name} ${teacher.last_name}`,
          email: teacher.email,
        },
      });
    } catch (error) {
      console.error("[Send Reminder] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to send reminder",
        },
        500,
      );
    }
  },
);

