// GET marks/pending-approval-count - Get count of pending marks approvals for admin dashboard
app.get(
  "/make-server-1ddd013a/marks/pending-approval-count",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // ✅ FIX: Use verifyUserAuth instead of supabase.auth.getUser(accessToken)
      const {
        data: { user },
        error: authError,
      } = await verifyUserAuth(accessToken);
      if (!user?.id) {
        // Don't log as error - this is expected when session expires or on initial load
        // The frontend handles this gracefully by setting count to 0
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // 🔥 Get session and term from query parameters
      const session = c.req.query("session");
      const term = c.req.query("term");

      console.log(
        "[Pending Approval Count] Fetching pending marks count...", { session, term }
      );

      // Count marks with status 'pending_approval' for both midterm and terminal
      let countQuery = supabase
        .from("marks")
        .select("*", { count: "exact", head: true })
        .in("status", ["pending_approval"]);
      
      // 🔥 Filter by session and term if provided
      if (session) {
        countQuery = countQuery.eq("session", session);
      }
      if (term) {
        countQuery = countQuery.eq("term", term);
      }

      const { count, error } = await countQuery;

      if (error) {
        console.error("[Pending Approval Count] Error:", error);
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      console.log(
        "[Pending Approval Count] Found",
        count || 0,
        "pending approvals",
      );

      return c.json({
        success: true,
        count: count || 0,
      });
    } catch (error) {
      console.error("[Pending Approval Count] Error:", error);
      return c.json(
        {
          success: false,
          error:
            error instanceof Error
              ? error.message
              : "Failed to fetch pending approval count",
        },
        500,
      );
    }
  },
);

// ==================== ATTENDANCE ENDPOINTS ====================

// GET attendance for a specific class on a specific date (for teachers)
app.get("/make-server-1ddd013a/attendance", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const url = new URL(c.req.url);
    const classId = url.searchParams.get("class_id");
    const date = url.searchParams.get("date");
    const session = url.searchParams.get("session");
    const term = url.searchParams.get("term");
    const studentId = url.searchParams.get("student_id");

    console.log("[Attendance] Fetching attendance:", {
      classId,
      date,
      session,
      term,
      studentId,
    });

    let query = supabase.from("attendance").select("*");

    if (classId) query = query.eq("class_id", classId);
    if (date) query = query.eq("date", date);
    if (session) query = query.eq("session", session);
    if (term) query = query.eq("term", term);
    if (studentId) query = query.eq("student_id", studentId);

    query = query.order("date", { ascending: false });

    const { data: attendance, error } = await query;

    if (error) {
      console.error("[Attendance] Error fetching:", error);
      return c.json(
        { success: false, error: error.message },
        500,
      );
    }

    return c.json({
      success: true,
      attendance: attendance || [],
    });
  } catch (error) {
    console.error("[Attendance] Error:", error);
    return c.json(
      { success: false, error: "Failed to fetch attendance" },
      500,
    );
  }
});

// POST mark attendance for multiple students
app.post("/make-server-1ddd013a/attendance/mark", async (c) => {
  try {
    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    if (!accessToken) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);
    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    const body = await c.req.json();
    const {
      classId,
      date,
      session,
      term,
      weekNumber,
      records,
    } = body;

    console.log("[Attendance] Marking attendance:", {
      classId,
      date,
      session,
      term,
      weekNumber,
      recordsCount: records?.length,
      userId: user.id,
    });

    if (
      !classId ||
      !date ||
      !session ||
      !term ||
      !weekNumber ||
      !records ||
      !Array.isArray(records)
    ) {
      return c.json(
        { success: false, error: "Missing required fields" },
        400,
      );
    }

    // Verify user is a teacher
    const { data: teacherProfile, error: profileError } =
      await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

    if (profileError || !teacherProfile) {
      return c.json(
        { success: false, error: "Teacher profile not found" },
        404,
      );
    }

    if (teacherProfile.role !== "teacher") {
      return c.json(
        {
          success: false,
          error: "Only teachers can mark attendance",
        },
        403,
      );
    }

    // Verify teacher is assigned as class teacher for this class
    const { data: classData, error: classError } =
      await supabase
        .from("classes")
        .select("class_teacher_id, name")
        .eq("id", classId)
        .single();

    if (classError || !classData) {
      console.error(
        "[Attendance Mark] Class not found:",
        classId,
        classError,
      );
      return c.json(
        { success: false, error: "Class not found" },
        404,
      );
    }

    console.log(
      "[Attendance Mark] Checking class teacher assignment:",
      {
        classId,
        className: classData.name,
        class_teacher_id: classData.class_teacher_id,
        current_user_id: user.id,
        matches: classData.class_teacher_id === user.id,
      },
    );

    if (classData.class_teacher_id !== user.id) {
      return c.json(
        {
          success: false,
          error:
            "You are not assigned as a class teacher for this class",
          debug: {
            class_teacher_id: classData.class_teacher_id,
            your_id: user.id,
            class_name: classData.name,
          },
        },
        403,
      );
    }

    // Prepare attendance records
    const attendanceRecords = records.map((record: any) => ({
      student_id: record.studentId,
      class_id: classId,
      date: date,
      status: record.status,
      marked_by: user.id,
      session: session,
      term: term,
      week_number: weekNumber,
      notes: record.notes || null,
    }));

    console.log('[Attendance Mark] Prepared records for upsert:', {
      count: attendanceRecords.length,
      date: date,
      session: session,
      term: term,
      firstRecord: attendanceRecords[0]
    });

    // Upsert attendance records (insert or update if exists)
    const { data, error } = await supabase
      .from("attendance")
      .upsert(attendanceRecords, {
        onConflict: "student_id,date",
        ignoreDuplicates: false,
      })
      .select();

    if (error) {
      console.error("[Attendance] Error marking:", error);
      return c.json(
        { success: false, error: error.message },
        500,
      );
    }

    console.log(
      "[Attendance] Successfully marked:",
      data?.length || 0,
      "records",
    );

    // CRITICAL: Invalidate cached attendance summaries for affected students
    // This ensures students and teachers see updated attendance data immediately
    console.log(
      "[Attendance] Invalidating cached summaries for",
      records.length,
      "students...",
    );
    const invalidationPromises = records.map(
      async (record: any) => {
        const summaryKey = `attendance_summary:${record.studentId}:${session}:${term}`;
        try {
          await kv.del(summaryKey);
          console.log(
            "[Attendance] Invalidated cache for student:",
            record.studentId,
          );
        } catch (error) {
          console.error(
            "[Attendance] Failed to invalidate cache for student:",
            record.studentId,
            error,
          );
        }
      },
    );
    await Promise.all(invalidationPromises);
    console.log("[Attendance] Cache invalidation complete");

    return c.json({ success: true, attendance: data });
  } catch (error) {
    console.error("[Attendance] Error:", error);
    return c.json(
      { success: false, error: "Failed to mark attendance" },
      500,
    );
  }
});

// GET attendance summary for a student (for report cards and student dashboard)
app.get(
  "/make-server-1ddd013a/attendance/summary",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const url = new URL(c.req.url);
      const studentId = url.searchParams.get("student_id");
      const session = url.searchParams.get("session");
      const term = url.searchParams.get("term");

      console.log("[Attendance Summary] Request:", {
        studentId,
        session,
        term,
      });

      if (!studentId || !session || !term) {
        return c.json(
          {
            success: false,
            error: "Missing required parameters",
          },
          400,
        );
      }

      // Fetch all attendance records for the student in the session/term
      const { data: attendance, error } = await supabase
        .from("attendance")
        .select("*")
        .eq("student_id", studentId)
        .eq("session", session)
        .eq("term", term)
        .order("date", { ascending: true });

      if (error) {
        console.error("[Attendance Summary] Error:", error);
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      // Calculate summary statistics
      // CRITICAL FIX: Normalize status to lowercase (DB has "Present", "Absent", etc.)
      const total = attendance?.length || 0;
      const present =
        attendance?.filter(
          (a) => a.status.toLowerCase() === "present",
        ).length || 0;
      const absent =
        attendance?.filter(
          (a) => a.status.toLowerCase() === "absent",
        ).length || 0;
      const late =
        attendance?.filter(
          (a) => a.status.toLowerCase() === "late",
        ).length || 0;
      const excused =
        attendance?.filter(
          (a) => a.status.toLowerCase() === "excused",
        ).length || 0;
      const percentage =
        total > 0 ? Math.round((present / total) * 100) : 0;

      // Group by week
      const byWeek: Record<number, any> = {};
      attendance?.forEach((record) => {
        const week = record.week_number;
        if (!byWeek[week]) {
          byWeek[week] = {
            weekNumber: week,
            total: 0,
            present: 0,
            absent: 0,
            late: 0,
            excused: 0,
            records: [],
          };
        }
        byWeek[week].total++;
        // CRITICAL FIX: Normalize status to lowercase before using as key
        const normalizedStatus = record.status.toLowerCase();
        byWeek[week][normalizedStatus]++;
        byWeek[week].records.push(record);
      });

      const summary = {
        total,
        present,
        absent,
        late,
        excused,
        percentage,
        byWeek: Object.values(byWeek).sort(
          (a: any, b: any) => a.weekNumber - b.weekNumber,
        ),
        records: attendance || [],
      };

      console.log("[Attendance Summary] Summary:", {
        total,
        present,
        absent,
        percentage,
      });
      return c.json({ success: true, summary });
    } catch (error) {
      console.error("[Attendance Summary] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to fetch attendance summary",
        },
        500,
      );
    }
  },
);

// GET attendance statistics for a class (for principal/IT admin)
app.get(
  "/make-server-1ddd013a/attendance/class-stats",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Verify user is admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      const allowedRoles = [
        "principal",
        "it_admin",
        "director",
      ];
      if (
        !profile?.role ||
        !allowedRoles.includes(profile.role)
      ) {
        return c.json(
          {
            success: false,
            error: "Access denied. Admin only.",
          },
          403,
        );
      }

      const url = new URL(c.req.url);
      const classId = url.searchParams.get("class_id");
      const session = url.searchParams.get("session");
      const term = url.searchParams.get("term");

      console.log(
        "[Class Attendance Stats] ===== REQUEST DEBUG =====",
      );
      console.log("[Class Attendance Stats] Request params:", {
        classId,
        session,
        term,
      });
      console.log(
        "[Class Attendance Stats] Session type:",
        typeof session,
      );
      console.log(
        "[Class Attendance Stats] Term type:",
        typeof term,
      );

      if (!classId || !session || !term) {
        return c.json(
          {
            success: false,
            error: "Missing required parameters",
          },
          400,
        );
      }

      // First, check what attendance records exist for this class (without session/term filter)
      const { data: allClassAttendance } = await supabase
        .from("attendance")
        .select("id, student_id, session, term, date, status")
        .eq("class_id", classId)
        .order("created_at", { ascending: false })
        .limit(100);

      console.log(
        "[Class Attendance Stats] ===== DATABASE ANALYSIS =====",
      );
      console.log(
        "[Class Attendance Stats] Total attendance records for this class:",
        allClassAttendance?.length || 0,
      );

      if (allClassAttendance && allClassAttendance.length > 0) {
        const uniqueSessions = [
          ...new Set(allClassAttendance.map((r) => r.session)),
        ];
        const uniqueTerms = [
          ...new Set(allClassAttendance.map((r) => r.term)),
        ];

        console.log(
          "[Class Attendance Stats] Unique sessions in DB:",
          uniqueSessions,
        );
        console.log(
          "[Class Attendance Stats] Unique terms in DB:",
          uniqueTerms,
        );
        console.log(
          "[Class Attendance Stats] Sample record:",
          allClassAttendance[0],
        );

        console.log(
          "[Class Attendance Stats] ===== QUERY COMPARISON =====",
        );
        console.log(
          "[Class Attendance Stats] Looking for session:",
          `"${session}"`,
        );
        console.log(
          "[Class Attendance Stats] Looking for term:",
          `"${term}"`,
        );

        // Check for exact matches
        const sessionMatch = uniqueSessions.includes(session);
        const termMatch = uniqueTerms.includes(term);

        console.log(
          "[Class Attendance Stats] Session match found:",
          sessionMatch,
        );
        console.log(
          "[Class Attendance Stats] Term match found:",
          termMatch,
        );

        if (!sessionMatch) {
          console.error(
            "[Class Attendance Stats] ❌ SESSION MISMATCH!",
          );
          console.error(
            "[Class Attendance Stats] Database has:",
            uniqueSessions,
          );
          console.error(
            "[Class Attendance Stats] Query wants:",
            session,
          );
        }

        if (!termMatch) {
          console.error(
            "[Class Attendance Stats] ❌ TERM MISMATCH!",
          );
          console.error(
            "[Class Attendance Stats] Database has:",
            uniqueTerms,
          );
          console.error(
            "[Class Attendance Stats] Query wants:",
            term,
          );
        }
      } else {
        console.warn(
          "[Class Attendance Stats] ⚠️ NO ATTENDANCE RECORDS found for class_id:",
          classId,
        );
      }

      // Fetch all attendance for the class with filters
      const { data: attendance, error } = await supabase
        .from("attendance")
        .select(
          `
        *,
        profiles!attendance_student_id_fkey(
          id,
          first_name,
          middle_name,
          last_name
        )
      `,
        )
        .eq("class_id", classId)
        .eq("session", session)
        .eq("term", term);

      if (error) {
        console.error("[Class Attendance Stats] Error:", error);
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      console.log(
        "[Class Attendance Stats] ===== QUERY RESULTS =====",
      );
      console.log(
        "[Class Attendance Stats] Filtered records count:",
        attendance?.length || 0,
      );

      // CRITICAL FIX: Get school calendar to calculate attendance percentage correctly
      const calendarKey = `school_calendar:${session}:${term}`;
      const calendarData = await kv.get(calendarKey);

      let totalSchoolDays = 0;
      if (calendarData) {
        const calendar =
          typeof calendarData === "string"
            ? JSON.parse(calendarData)
            : calendarData;
        totalSchoolDays = calendar.total_school_days || 0;
        console.log(
          "[Class Attendance Stats] Found school calendar:",
          {
            session,
            term,
            totalSchoolDays,
            calendarKey,
          },
        );
      } else {
        console.warn(
          "[Class Attendance Stats] No calendar data found for key:",
          calendarKey,
        );
        console.warn(
          "[Class Attendance Stats] Will return error - calendar must be configured",
        );
      }

      if (totalSchoolDays === 0) {
        console.error(
          "[Class Attendance Stats] School calendar not configured!",
        );
        return c.json(
          {
            success: false,
            error: `School calendar not configured for ${session} - ${term}. Please set total school days in Settings → Attendance Settings.`,
            stats: [],
            diagnostics: {
              queryParams: { classId, session, term },
              recordsFound: attendance?.length || 0,
              allSessionsInDb: allClassAttendance
                ? [
                    ...new Set(
                      allClassAttendance.map((r) => r.session),
                    ),
                  ]
                : [],
              allTermsInDb: allClassAttendance
                ? [
                    ...new Set(
                      allClassAttendance.map((r) => r.term),
                    ),
                  ]
                : [],
              calendarMissing: true,
            },
          },
          400,
        );
      }

      // Calculate stats per student
      const studentStats: Record<string, any> = {};

      attendance?.forEach((record) => {
        const studentId = record.student_id;
        if (!studentStats[studentId]) {
          studentStats[studentId] = {
            studentId,
            studentName: record.profiles
              ? `${record.profiles.first_name} ${record.profiles.middle_name || ""} ${record.profiles.last_name}`.trim()
              : "Unknown",
            totalDays: totalSchoolDays, // Use school calendar days
            present: 0,
            absent: 0,
            late: 0,
            excused: 0,
            percentage: 0,
          };
        }

        // CRITICAL FIX: Normalize status to lowercase before using as key
        // Database has "Present", "Absent", "Late", "Excused" (capitalized)
        // But our stats object uses lowercase keys
        const normalizedStatus = record.status.toLowerCase();
        studentStats[studentId][normalizedStatus]++;
      });

      // FIXED: Calculate percentages using total_school_days instead of record count
      Object.values(studentStats).forEach((stats: any) => {
        stats.percentage =
          totalSchoolDays > 0
            ? Math.round(
                (stats.present / totalSchoolDays) * 100 * 10,
              ) / 10 // Round to 1 decimal like student summary
            : 0;
      });

      const statsArray = Object.values(studentStats).sort(
        (a: any, b: any) =>
          a.studentName.localeCompare(b.studentName),
      );

      console.log(
        "[Class Attendance Stats] ===== FINAL RESULTS =====",
      );
      console.log(
        "[Class Attendance Stats] Students with attendance:",
        statsArray.length,
      );
      console.log(
        "[Class Attendance Stats] Total school days:",
        totalSchoolDays,
      );
      console.log(
        "[Class Attendance Stats] Total attendance records:",
        attendance?.length || 0,
      );

      if (statsArray.length > 0) {
        console.log(
          "[Class Attendance Stats] Sample student stats:",
          statsArray[0],
        );
        console.log(
          "[Class Attendance Stats] Sample calculation: present/totalSchoolDays =",
          statsArray[0].present,
          "/",
          totalSchoolDays,
          "=",
          statsArray[0].percentage + "%",
        );
      }

      // Add diagnostic info to response
      return c.json({
        success: true,
        stats: statsArray,
        totalSchoolDays: totalSchoolDays, // Include this for frontend display
        rawAttendance: attendance,
        diagnostics: {
          queryParams: { classId, session, term },
          recordsFound: attendance?.length || 0,
          studentsProcessed: statsArray.length,
          totalSchoolDays: totalSchoolDays,
          allSessionsInDb: allClassAttendance
            ? [
                ...new Set(
                  allClassAttendance.map((r) => r.session),
                ),
              ]
            : [],
          allTermsInDb: allClassAttendance
            ? [
                ...new Set(
                  allClassAttendance.map((r) => r.term),
                ),
              ]
            : [],
        },
      });
    } catch (error) {
      console.error("[Class Attendance Stats] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to fetch class attendance stats",
        },
        500,
      );
    }
  },
);

// GET teacher's class assignment (diagnostic endpoint)
app.get(
  "/make-server-1ddd013a/attendance/my-class-assignment",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      console.log(
        "[Class Assignment] Checking for user:",
        user.id,
      );

      // Get teacher profile
      const { data: profile, error: profileError } =
        await supabase
          .from("profiles")
          .select("id, first_name, last_name, role, class_id")
          .eq("id", user.id)
          .single();

      if (profileError || !profile) {
        return c.json(
          { success: false, error: "Profile not found" },
          404,
        );
      }

      // Get all classes where this teacher is the class teacher
      const { data: assignedClasses, error: classError } =
        await supabase
          .from("classes")
          .select(
            "id, name, level, section_id, sections(name), class_teacher_id",
          )
          .eq("class_teacher_id", user.id);

      console.log(
        "[Class Assignment] Found classes:",
        assignedClasses,
      );

      if (classError) {
        console.error(
          "[Class Assignment] Query error:",
          classError,
        );
      }

      return c.json({
        success: true,
        profile: {
          id: profile.id,
          name: `${profile.first_name} ${profile.last_name}`,
          role: profile.role,
          class_id_in_profile: profile.class_id,
        },
        assigned_classes: assignedClasses || [],
        has_class_assignment:
          assignedClasses && assignedClasses.length > 0,
      });
    } catch (error) {
      console.error("[Class Assignment] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to check class assignment",
        },
        500,
      );
    }
  },
);

// GET students for a class (helper endpoint for attendance marking)
app.get(
  "/make-server-1ddd013a/attendance/class-students",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const url = new URL(c.req.url);
      const classId = url.searchParams.get("class_id");

      if (!classId) {
        return c.json(
          { success: false, error: "class_id is required" },
          400,
        );
      }

      console.log(
        "[Class Students] Fetching for class:",
        classId,
        "User:",
        user.id,
      );

      // Verify user is a teacher
      const { data: teacherProfile, error: profileError } =
        await supabase
          .from("profiles")
          .select("role")
          .eq("id", user.id)
          .single();

      if (profileError || !teacherProfile) {
        return c.json(
          {
            success: false,
            error: "Teacher profile not found",
          },
          404,
        );
      }

      if (teacherProfile.role !== "teacher") {
        return c.json(
          {
            success: false,
            error: "Only teachers can access this",
          },
          403,
        );
      }

      // Verify teacher is assigned as class teacher for this class
      const { data: classData, error: classError } =
        await supabase
          .from("classes")
          .select("class_teacher_id, name")
          .eq("id", classId)
          .single();

      if (classError || !classData) {
        console.error(
          "[Class Students] Class not found:",
          classId,
          classError,
        );
        return c.json(
          { success: false, error: "Class not found" },
          404,
        );
      }

      console.log(
        "[Class Students] Checking class teacher assignment:",
        {
          classId,
          className: classData.name,
          class_teacher_id: classData.class_teacher_id,
          current_user_id: user.id,
          matches: classData.class_teacher_id === user.id,
        },
      );

      if (classData.class_teacher_id !== user.id) {
        return c.json(
          {
            success: false,
            error:
              "You are not assigned as a class teacher for this class",
            debug: {
              class_teacher_id: classData.class_teacher_id,
              your_id: user.id,
              class_name: classData.name,
            },
          },
          403,
        );
      }

      // Fetch students in the class
      const { data: students, error } = await supabase
        .from("profiles")
        .select("id, first_name, middle_name, last_name, email")
        .eq("class_id", classId)
        .eq("role", "student")
        .or("is_graduated.is.null,is_graduated.eq.false")
        .order("first_name", { ascending: true });

      if (error) {
        console.error("[Class Students] Error:", error);
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      console.log(
        "[Class Students] Found:",
        students?.length || 0,
        "students",
      );
      return c.json({
        success: true,
        students: students || [],
      });
    } catch (error) {
      console.error("[Class Students] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to fetch class students",
        },
        500,
      );
    }
  },
);

