// GET attendance records (for viewing)
app.get(
  "/make-server-1ddd013a/attendance/records",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const url = new URL(c.req.url);
      const class_id = url.searchParams.get("class_id");
      const session = url.searchParams.get("session");
      const term = url.searchParams.get("term");
      const student_id = url.searchParams.get("student_id");

      console.log("[Get Attendance] Params:", {
        class_id,
        session,
        term,
        student_id,
      });

      // Build query
      let query = supabase.from("attendance").select(`
        *,
        student:student_id (
          id,
          first_name,
          middle_name,
          last_name,
          email
        ),
        teacher:marked_by (
          id,
          first_name,
          last_name
        )
      `);

      // Apply filters
      if (class_id) query = query.eq("class_id", class_id);
      if (session) query = query.eq("session", session);
      if (term) query = query.eq("term", term);
      if (student_id)
        query = query.eq("student_id", student_id);

      // Order by date descending
      query = query.order("date", { ascending: false });

      const { data: attendanceRecords, error } = await query;

      if (error) {
        console.error("[Get Attendance] Error:", error);
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      console.log(
        "[Get Attendance] Found:",
        attendanceRecords?.length || 0,
        "records",
      );
      return c.json({
        success: true,
        records: attendanceRecords || [],
      });
    } catch (error) {
      console.error("[Get Attendance] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to fetch attendance records",
        },
        500,
      );
    }
  },
);

// GET: School-wide Attendance Aggregation (for Director/IT Admin)
app.get(
  "/make-server-1ddd013a/attendance/school-wide",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is Director, Principal, or IT Admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      const allowedRoles = ["director", "admin", "principal", "it_admin"];
      if (!profile || !allowedRoles.includes(profile.role)) {
        return c.json(
          { success: false, error: "Access denied. Director/Principal/IT Admin only." },
          403,
        );
      }

      const url = new URL(c.req.url);
      const date = url.searchParams.get("date");
      const session = url.searchParams.get("session");
      const term = url.searchParams.get("term");

      if (!date || !session || !term) {
        return c.json(
          {
            success: false,
            error: "Missing required parameters: date, session, term",
          },
          400,
        );
      }

      console.log("[School-Wide Attendance] Fetching for:", {
        date,
        session,
        term,
      });

      // First, get total active students (non-graduated) for accurate percentage calculation
      const { data: allActiveStudents, error: studentsError } = await supabase
        .from("profiles")
        .select("id", { count: "exact" })
        .eq("role", "student")
        .or("is_graduated.is.null,is_graduated.eq.false");

      if (studentsError) {
        console.error("[School-Wide Attendance] Error fetching students:", studentsError);
      }

      const totalActiveStudents = allActiveStudents?.length || 0;
      console.log("[School-Wide Attendance] Total active students:", totalActiveStudents);

      // Get all attendance records for the specified date, session, and term
      const { data: attendanceRecords, error: attendanceError } = await supabase
        .from("attendance")
        .select(`
          *,
          student:student_id (
            id,
            first_name,
            last_name,
            class_id
          ),
          class:class_id (
            id,
            name
          )
        `)
        .eq("date", date)
        .eq("session", session)
        .eq("term", term);

      if (attendanceError) {
        console.error("[School-Wide Attendance] Error:", attendanceError);
        return c.json(
          { success: false, error: attendanceError.message },
          500,
        );
      }

      console.log("[School-Wide Attendance] Raw records fetched:", attendanceRecords?.length);
      console.log("[School-Wide Attendance] Sample records:", attendanceRecords?.slice(0, 3).map(r => ({
        id: r.id,
        status: r.status,
        date: r.date,
        student_name: `${r.student?.first_name} ${r.student?.last_name}`,
        class_name: r.class?.name
      })));

      // Calculate aggregated statistics (normalize to lowercase to handle "Present"/"present", etc.)
      const totalRecords = attendanceRecords?.length || 0;
      const presentCount = attendanceRecords?.filter(r => r.status?.toLowerCase() === "present").length || 0;
      const absentCount = attendanceRecords?.filter(r => r.status?.toLowerCase() === "absent").length || 0;
      const lateCount = attendanceRecords?.filter(r => r.status?.toLowerCase() === "late").length || 0;
      const excusedCount = attendanceRecords?.filter(r => r.status?.toLowerCase() === "excused").length || 0;

      // Group by class
      const byClass: Record<string, any> = {};
      attendanceRecords?.forEach(record => {
        const className = record.class?.name || "Unknown";
        if (!byClass[className]) {
          byClass[className] = {
            className,
            total: 0,
            present: 0,
            absent: 0,
            late: 0,
            excused: 0,
          };
        }
        byClass[className].total++;
        const statusLower = record.status?.toLowerCase();
        if (statusLower === "present") byClass[className].present++;
        if (statusLower === "absent") byClass[className].absent++;
        if (statusLower === "late") byClass[className].late++;
        if (statusLower === "excused") byClass[className].excused++;
      });

      const classSummary = Object.values(byClass).map((cls: any) => ({
        ...cls,
        attendance_percentage: cls.total > 0 ? ((cls.present + cls.late) / cls.total * 100).toFixed(1) : "0.0",
      }));

      // Calculate attendance percentage based on TOTAL ACTIVE STUDENTS, not just marked
      // This accounts for students whose attendance wasn't recorded
      const attendancePercentage = totalActiveStudents > 0
        ? ((presentCount + lateCount) / totalActiveStudents * 100).toFixed(1)
        : "0.0";

      // Log unique status values for debugging
      const uniqueStatuses = [...new Set(attendanceRecords?.map(r => r.status) || [])];
      
      console.log("[School-Wide Attendance] Summary:", {
        totalActiveStudents,
        totalRecords,
        presentCount,
        absentCount,
        lateCount,
        excusedCount,
        attendancePercentage: `${attendancePercentage}% (${presentCount + lateCount}/${totalActiveStudents})`,
        uniqueStatuses,
      });

      return c.json({
        success: true,
        data: {
          date,
          session,
          term,
          summary: {
            total_active_students: totalActiveStudents,
            total_students_marked: totalRecords,
            present: presentCount,
            absent: absentCount,
            late: lateCount,
            excused: excusedCount,
            attendance_percentage: parseFloat(attendancePercentage),
          },
          by_class: classSummary,
          raw_records: attendanceRecords || [],
        },
      });
    } catch (error) {
      console.error("[School-Wide Attendance] Error:", error);
      return c.json(
        { success: false, error: "Failed to fetch school-wide attendance" },
        500,
      );
    }
  },
);

