// GET: Calculate student attendance summary
app.get(
  "/make-server-1ddd013a/attendance/summary/student",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const url = new URL(c.req.url);
      const student_id = url.searchParams.get("student_id");
      const session = url.searchParams.get("session");
      const term = url.searchParams.get("term");

      if (!student_id || !session || !term) {
        return c.json(
          {
            success: false,
            error: "student_id, session, and term are required",
          },
          400,
        );
      }

      console.log("[Attendance Summary] Calculating for:", {
        student_id,
        session,
        term,
      });

      // First, check if summary exists in cache
      const summaryKey = `attendance_summary:${student_id}:${session}:${term}`;
      const cachedSummary = await kv.get(summaryKey);

      if (cachedSummary) {
        console.log(
          "[Attendance Summary] Returning cached summary:",
          cachedSummary.attendance_percentage + "%",
        );
        return c.json({
          success: true,
          summary: cachedSummary,
          from_cache: true,
        });
      }

      // Calculate fresh summary
      console.log(
        "[Attendance Summary] Calculating fresh summary...",
      );

      // Get student info
      const { data: student } = await supabase
        .from("profiles")
        .select(
          "id, first_name, middle_name, last_name, class_id",
        )
        .eq("id", student_id)
        .single();

      if (!student) {
        return c.json(
          { success: false, error: "Student not found" },
          404,
        );
      }

      // Get class info
      let className = "N/A";
      if (student.class_id) {
        const { data: classInfo } = await supabase
          .from("classes")
          .select("name")
          .eq("id", student.class_id)
          .single();

        if (classInfo) {
          className = classInfo.name;
        }
      }

      // Get school calendar (total school days)
      const calendarKey = `school_calendar:${session}:${term}`;
      const calendarData = await kv.get(calendarKey);

      let totalSchoolDays = 0;
      if (calendarData) {
        // Parse if it's a string (KV store might return string or object)
        const calendar =
          typeof calendarData === "string"
            ? JSON.parse(calendarData)
            : calendarData;
        totalSchoolDays = calendar.total_school_days || 0;
        console.log(
          "[Attendance Summary] Found school calendar:",
          {
            session,
            term,
            totalSchoolDays,
            calendarKey,
          },
        );
      } else {
        console.warn(
          "[Attendance Summary] No calendar data found for key:",
          calendarKey,
        );
      }

      // Count attendance records first (even if no calendar is configured)
      const { data: attendanceRecords } = await supabase
        .from("attendance")
        .select("status, date")
        .eq("student_id", student_id)
        .eq("session", session)
        .eq("term", term);

      const records = attendanceRecords || [];
      
      // If no calendar configured, use a default (67 days is standard Nigerian term)
      if (totalSchoolDays === 0) {
        console.warn(
          "[Attendance Summary] No school calendar configured - using default 67 days",
        );
        totalSchoolDays = 67;
      }
      
      console.log('[Attendance Summary] Raw attendance records for student:', student_id);
      console.log('[Attendance Summary] Total records found:', records.length);
      console.log('[Attendance Summary] Records:', records);

      // Count by status (normalized to lowercase)
      const counts = {
        present: 0,
        absent: 0,
        late: 0,
        excused: 0,
      };

      records.forEach((record) => {
        const status = record.status?.toLowerCase() || 'absent';
        if (status in counts) {
          counts[status]++;
        } else {
          console.warn('[Attendance Summary] Unknown status:', record.status);
        }
      });

      console.log("[Attendance Summary] Counts:", counts);
      console.log("[Attendance Summary] Total school days:", totalSchoolDays);
      console.log("[Attendance Summary] Days present:", counts.present);

      // Calculate attendance percentage
      const attendancePercentage =
        totalSchoolDays > 0
          ? Math.round(
              (counts.present / totalSchoolDays) * 100 * 10,
            ) / 10 // Round to 1 decimal
          : 0;

      // Get grading config
      const gradingConfigData = await kv.get(
        "attendance_grading_config",
      );
      let gradingConfig;

      if (gradingConfigData) {
        gradingConfig =
          typeof gradingConfigData === "string"
            ? JSON.parse(gradingConfigData)
            : gradingConfigData;
      } else {
        // Default grading config
        gradingConfig = {
          grades: [
            {
              min: 95,
              max: 100,
              grade: "Excellent",
              remark: "Outstanding attendance! Keep it up!",
            },
            {
              min: 90,
              max: 94,
              grade: "Very Good",
              remark: "Very good attendance record.",
            },
            {
              min: 85,
              max: 89,
              grade: "Good",
              remark:
                "Good attendance. Maintain this standard.",
            },
            {
              min: 80,
              max: 84,
              grade: "Fair",
              remark: "Fair attendance. Try to improve.",
            },
            {
              min: 75,
              max: 79,
              grade: "Poor",
              remark:
                "Poor attendance. Significant improvement needed.",
            },
            {
              min: 0,
              max: 74,
              grade: "Unsatisfactory",
              remark:
                "Unsatisfactory. This may affect promotion.",
            },
          ],
          intervention_threshold: 85,
        };
      }

      // Determine grade and remark
      let attendanceGrade = "N/A";
      let attendanceRemark = "";

      for (const gradeLevel of gradingConfig.grades) {
        if (
          attendancePercentage >= gradeLevel.min &&
          attendancePercentage <= gradeLevel.max
        ) {
          attendanceGrade = gradeLevel.grade;
          attendanceRemark = gradeLevel.remark;
          break;
        }
      }

      // Check if flagged for intervention
      const flagged =
        attendancePercentage <
        (gradingConfig.intervention_threshold || 85);

      // Build summary
      const summary = {
        student_id: student.id,
        student_name:
          `${student.first_name} ${student.middle_name || ""} ${student.last_name}`.trim(),
        class_id: student.class_id,
        class_name: className,
        session,
        term,

        // Core counts
        total_school_days: totalSchoolDays,
        days_present: counts.present,
        days_absent: counts.absent,
        days_late: counts.late,
        days_excused: counts.excused,

        // Calculated
        attendance_percentage: attendancePercentage,
        attendance_grade: attendanceGrade,
        attendance_remark: attendanceRemark,

        // Flags
        flagged: flagged,

        // Metadata
        last_updated: new Date().toISOString(),
        calculated_at: new Date().toISOString(),
      };

      // Cache the summary (kv.set handles JSON serialization automatically)
      await kv.set(summaryKey, summary);

      console.log(
        "[Attendance Summary] Summary calculated and cached:",
        {
          percentage: attendancePercentage,
          grade: attendanceGrade,
          flagged,
        },
      );

      return c.json({
        success: true,
        summary,
        from_cache: false,
      });
    } catch (error) {
      console.error("[Attendance Summary] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to calculate attendance summary",
        },
        500,
      );
    }
  },
);

