// Database Setup: Create graduated_students table if it doesn't exist
app.post(
  "/make-server-1ddd013a/setup-graduated-students-table",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      const allowedRoles = ["principal", "it_admin"];
      if (!profile || !allowedRoles.includes(profile.role)) {
        return c.json(
          {
            success: false,
            error: "Only admins can run database setup",
          },
          403,
        );
      }

      console.log("[DB Setup] Verifying graduated_students table...");

      // Try to insert a test record to verify table exists
      const testRecord = {
        student_id: user.id, // Use admin's ID for test
        first_name: 'Test',
        last_name: 'Setup',
        graduation_session: '2024/2025',
        graduation_class: 'Test Class',
        graduation_date: new Date().toISOString(),
        fees_clearance_required: true,
        fees_cleared: true,
        outstanding_balance: 0,
        is_active: false, // Mark as inactive test record
      };

      const { error: insertError } = await supabase
        .from('graduated_students')
        .insert(testRecord);

      if (insertError) {
        console.error("[DB Setup] Table verification failed:", insertError);
        return c.json({
          success: false,
          error: "The graduated_students table does not exist or has schema issues.",
          details: insertError.message,
          instructions: `Please create the table in Supabase Dashboard > SQL Editor with this SQL:

CREATE TABLE IF NOT EXISTS graduated_students (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  middle_name TEXT,
  admission_number TEXT,
  graduation_session TEXT NOT NULL,
  graduation_class TEXT NOT NULL,
  graduation_date TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  email TEXT,
  phone TEXT,
  gender TEXT,
  date_of_birth DATE,
  fees_clearance_required BOOLEAN DEFAULT true,
  fees_cleared BOOLEAN DEFAULT false,
  outstanding_balance NUMERIC DEFAULT 0,
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(student_id, graduation_session)
);

CREATE INDEX IF NOT EXISTS idx_graduated_students_student_id ON graduated_students(student_id);
CREATE INDEX IF NOT EXISTS idx_graduated_students_session ON graduated_students(graduation_session);
CREATE INDEX IF NOT EXISTS idx_graduated_students_graduation_date ON graduated_students(graduation_date DESC);

-- Enable RLS
ALTER TABLE graduated_students ENABLE ROW LEVEL SECURITY;

-- Policy: Admins can do everything
CREATE POLICY admin_all_access ON graduated_students
  FOR ALL USING (
    EXISTS (
      SELECT 1 FROM profiles
      WHERE profiles.id = auth.uid()
      AND profiles.role IN ('it_admin', 'principal', 'director')
    )
  );

-- Policy: Graduated students can view their own records
CREATE POLICY student_view_own ON graduated_students
  FOR SELECT USING (student_id = auth.uid());`
        }, 500);
      }

      // Delete test record
      const { error: deleteError } = await supabase
        .from('graduated_students')
        .delete()
        .eq('student_id', user.id)
        .eq('is_active', false);

      if (deleteError) {
        console.warn("[DB Setup] Could not delete test record:", deleteError);
      }

      console.log("[DB Setup] ✅ Table verified successfully");

      return c.json({
        success: true,
        message: "graduated_students table is ready and working correctly"
      });

    } catch (error) {
      console.error("[DB Setup] Error:", error);
      return c.json(
        { success: false, error: "Failed to verify table" },
        500,
      );
    }
  }
);

// POST: Promote students from one class to another
app.post(
  "/make-server-1ddd013a/promote-students",
  async (c) => {
    try {
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is admin
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      const allowedRoles = ["principal", "it_admin"];
      if (!profile || !allowedRoles.includes(profile.role)) {
        return c.json(
          {
            success: false,
            error: "Only admins can promote students",
          },
          403,
        );
      }

      const body = await c.req.json();
      const {
        from_class_id,
        to_class_id,
        session,
        current_session,
        new_session,
        is_graduation,
      } = body;

      console.log("[Promotion] Promoting students:", {
        from_class_id,
        to_class_id,
        session,
        current_session,
        new_session,
        is_graduation,
        admin_id: user.id,
      });

      if (!from_class_id || !session) {
        return c.json(
          {
            success: false,
            error: "from_class_id and session are required",
          },
          400,
        );
      }

      if (!is_graduation && !to_class_id) {
        return c.json(
          {
            success: false,
            error:
              "to_class_id is required for non-graduating students",
          },
          400,
        );
      }

      // Get all students in the source class with full details (exclude already graduated students)
      const { data: students, error: fetchError } =
        await supabase
          .from("profiles")
          .select(
            "id, first_name, last_name, middle_name, class_id, admission_number, email, phone, gender, date_of_birth",
          )
          .eq("class_id", from_class_id)
          .eq("role", "student")
          .or("is_graduated.is.null,is_graduated.eq.false");

      if (fetchError) {
        console.error(
          "[Promotion] Error fetching students:",
          fetchError,
        );
        return c.json(
          { success: false, error: "Failed to fetch students" },
          500,
        );
      }

      if (!students || students.length === 0) {
        return c.json(
          {
            success: false,
            error: "No students found in this class",
          },
          404,
        );
      }

      console.log(
        "[Promotion] Found",
        students.length,
        "students to promote",
      );

      if (is_graduation) {
        // Get graduation class name
        const { data: graduationClass } = await supabase
          .from("classes")
          .select("name")
          .eq("id", from_class_id)
          .single();

        const graduationClassName =
          graduationClass?.name || "Unknown Class";
        console.log(
          "[Promotion] Graduation class:",
          graduationClassName,
        );

        // IMPORTANT: For graduation, use the session from the request body
        // This is the session students are graduating FROM (e.g., 2025/2026)
        // The 'session' parameter contains the current session they're completing
        // NOT the new_session (which is for students being promoted to next class)
        const sessionForGraduation = current_session || session;
        
        console.log(
          "[Promotion] 📅 Using graduation session:",
          sessionForGraduation,
          "from request body (current_session or session parameter)",
        );

        console.log(
          "[Promotion] Using graduation session:",
          sessionForGraduation,
        );

        // Mark students as graduated - use student IDs from the fetched array
        const studentIds = students.map((s) => s.id);
        console.log(
          "[Promotion] Marking",
          studentIds.length,
          "students as graduated:",
          studentIds,
        );
        
        // Use SERVICE_ROLE_KEY to bypass RLS
        const adminSupabase = createClient(
          Deno.env.get('SUPABASE_URL') ?? '',
          Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
        );
        
        const { error: updateError } = await adminSupabase
          .from("profiles")
          .update({
            class_id: null,
            status: "graduated",
            is_graduated: true,
            graduation_session: sessionForGraduation,
            updated_at: new Date().toISOString(),
          })
          .in("id", studentIds);

        if (updateError) {
          console.error(
            "[Promotion] Error graduating students:",
            updateError,
          );
          console.error("[Promotion] Full error details:", JSON.stringify(updateError, null, 2));
          return c.json(
            {
              success: false,
              error: `Failed to graduate students: ${updateError.message}`,
              details: updateError,
            },
            500,
          );
        }

        // Verify the update worked
        const { data: verifyStudents } = await adminSupabase
          .from("profiles")
          .select("id, is_graduated, status, class_id")
          .in("id", studentIds);
        console.log(
          "[Promotion] 🔍 Verification after update:",
          verifyStudents,
        );

        console.log(
          "[Promotion] ✅ Graduated",
          students.length,
          "students for session",
          sessionForGraduation,
        );

        // Create graduated_students records
        console.log(
          "[Promotion] Creating graduated_students records...",
        );
        const graduatedStudentsRecords = students.map(
          (student) => ({
            student_id: student.id,
            admission_number: student.admission_number,
            first_name: student.first_name,
            last_name: student.last_name,
            middle_name: student.middle_name || null,
            graduation_session: sessionForGraduation,
            graduation_class: from_class_id,
            email: student.email || null,
            phone: student.phone || null,
            gender: student.gender || null,
            date_of_birth: student.date_of_birth || null,
            graduated_by: user.id,
          }),
        );

        console.log(
          "[Promotion] 📝 Prepared graduated_students records:",
          graduatedStudentsRecords.length,
          "records",
        );
        console.log("[Promotion] Sample record:", graduatedStudentsRecords[0]);

        const { data: createdRecords, error: graduatedError } =
          await adminSupabase
            .from("graduated_students")
            .upsert(graduatedStudentsRecords, {
              onConflict: 'student_id,graduation_session',
              ignoreDuplicates: false
            })
            .select();

        if (graduatedError) {
          console.error(
            "[Promotion] Error creating graduated_students records:",
            graduatedError,
          );
          console.error("[Promotion] Full error details:", JSON.stringify(graduatedError, null, 2));
          // CRITICAL: Return error instead of just logging
          return c.json(
            {
              success: false,
              error: `Failed to create graduated_students records: ${graduatedError.message}`,
              details: graduatedError,
            },
            500,
          );
        } else {
          console.log(
            `[Promotion] ✅ Created ${createdRecords?.length || 0} graduated_students records`,
          );
        }

        // Record graduations in the promotions table
        console.log("[Promotion] Recording graduation in promotions table...");
        
        // Check for existing records first (reuse studentIds already declared above)
        const { data: existingRecords } = await adminSupabase
          .from("promotions")
          .select("student_id")
          .in("student_id", studentIds)
          .eq("current_session", current_session)
          .eq("new_session", new_session)
          .eq("is_graduation", true);
        
        const existingStudentIds = new Set((existingRecords || []).map(r => r.student_id));
        const studentsToRecord = students.filter(s => !existingStudentIds.has(s.id));
        
        if (studentsToRecord.length === 0) {
          console.log("[Promotion] All students already have promotion records, skipping...");
        } else {
          const promotionRecords = studentsToRecord.map((student) => ({
            student_id: student.id,
            from_class_id,
            to_class_id: null,
            current_session: current_session,
            new_session: new_session,
            is_graduation: true,
            promotion_type: "bulk_graduation",
            promoted_by: user.id,
            promoted_at: new Date().toISOString(),
          }));

          console.log(
            "[Promotion] Inserting",
            promotionRecords.length,
            "new records to promotions table",
          );
          const { error: promotionsTableError } = await adminSupabase
            .from("promotions")
            .insert(promotionRecords);

          if (promotionsTableError) {
            console.error(
              "[Promotion] Error recording in promotions table:",
              promotionsTableError,
            );
            // Don't fail the whole operation if this fails
            console.warn(
              "[Promotion] Students graduated but promotions table records not saved",
            );
          } else {
            console.log(
              `[Promotion] ✅ Recorded ${promotionRecords.length} promotion records`,
            );
          }
        }

        // Create promotion history record in KV store
        const promotionKey = `promotion_history:${sessionForGraduation}:${from_class_id}`;
        await kv.set(
          promotionKey,
          JSON.stringify({
            from_class_id,
            to_class_id: null,
            session: sessionForGraduation,
            current_session: current_session,
            new_session: new_session,
            student_count: students.length,
            is_graduation: true,
            promoted_at: new Date().toISOString(),
            promoted_by: user.id,
          }),
        );

        // ✅ AUTO-CLEANUP: Delete all student_subjects for graduated students
        console.log("[Promotion] 🧹 Auto-cleanup: Deleting student_subjects for graduated students...");
        const { error: cleanupError } = await adminSupabase
          .from("student_subjects")
          .delete()
          .in("student_id", studentIds);
        
        if (cleanupError) {
          console.error("[Promotion] ⚠️ Failed to cleanup student_subjects:", cleanupError);
          // Don't fail the whole operation
        } else {
          console.log(`[Promotion] ✅ Cleaned up student_subjects for ${studentIds.length} graduated students`);
        }

        return c.json({
          success: true,
          message: "Students graduated successfully",
          promoted_count: students.length,
          is_graduation: true,
          session: sessionForGraduation,
        });
      } else {
        // Promote students to next class - use student IDs from the fetched array
        const studentIds = students.map((s) => s.id);
        
        // Use SERVICE_ROLE_KEY to bypass RLS
        const adminSupabase = createClient(
          Deno.env.get('SUPABASE_URL') ?? '',
          Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
        );
        
        const { error: updateError } = await adminSupabase
          .from("profiles")
          .update({
            class_id: to_class_id,
            updated_at: new Date().toISOString(),
          })
          .in("id", studentIds);

        if (updateError) {
          console.error(
            "[Promotion] Error promoting students:",
            updateError,
          );
          return c.json(
            {
              success: false,
              error: "Failed to promote students",
            },
            500,
          );
        }

        console.log(
          "[Promotion] ✅ Promoted",
          students.length,
          "students to new class",
        );

        // Invalidate attendance summaries for all promoted students
        console.log(
          "[Promotion] Invalidating attendance caches...",
        );
        const invalidationPromises = students.map(
          async (student) => {
            // Clear all terms for the session
            const terms = [
              "First Term",
              "Second Term",
              "Third Term",
            ];
            for (const term of terms) {
              const summaryKey = `attendance_summary:${student.id}:${session}:${term}`;
              try {
                await kv.del(summaryKey);
              } catch (error) {
                console.error(
                  "[Promotion] Failed to invalidate cache:",
                  summaryKey,
                  error,
                );
              }
            }
          },
        );
        await Promise.all(invalidationPromises);

        // Record promotions in the promotions table
        console.log("[Promotion] Recording promotions in promotions table...");
        
        // Check for existing records first (reuse studentIds already declared above)
        const { data: existingRecords } = await adminSupabase
          .from("promotions")
          .select("student_id")
          .in("student_id", studentIds)
          .eq("current_session", current_session)
          .eq("new_session", new_session)
          .eq("is_graduation", false);
        
        const existingStudentIds = new Set((existingRecords || []).map(r => r.student_id));
        const studentsToRecord = students.filter(s => !existingStudentIds.has(s.id));
        
        if (studentsToRecord.length === 0) {
          console.log("[Promotion] All students already have promotion records, skipping...");
        } else {
          const promotionRecords = studentsToRecord.map((student) => ({
            student_id: student.id,
            from_class_id,
            to_class_id,
            current_session: current_session,
            new_session: new_session,
            is_graduation: false,
            promotion_type: "bulk_promotion",
            promoted_by: user.id,
            promoted_at: new Date().toISOString(),
          }));

          const { error: promotionsTableError } = await adminSupabase
            .from("promotions")
            .insert(promotionRecords);

          if (promotionsTableError) {
            console.error(
              "[Promotion] Error recording in promotions table:",
              promotionsTableError,
            );
            // Don't fail the whole operation if this fails
            console.warn(
              "[Promotion] Students promoted but promotions table records not saved",
            );
          } else {
            console.log(
              `[Promotion] ✅ Recorded ${promotionRecords.length} promotion records`,
            );
          }
        }

        // Create promotion history record
        const promotionKey = `promotion_history:${session}:${from_class_id}`;
        await kv.set(
          promotionKey,
          JSON.stringify({
            from_class_id,
            to_class_id,
            session,
            student_count: students.length,
            is_graduation: false,
            promoted_at: new Date().toISOString(),
            promoted_by: user.id,
          }),
        );

        // ✅ AUTO-CLEANUP: Delete old student_subjects for the OLD class (from_class_id)
        // Students are moving to a new class, so their old subject assignments are invalid
        console.log("[Promotion] 🧹 Auto-cleanup: Deleting old student_subjects for promoted students...");
        const { error: cleanupError } = await adminSupabase
          .from("student_subjects")
          .delete()
          .in("student_id", studentIds)
          .eq("class_id", from_class_id);
        
        if (cleanupError) {
          console.error("[Promotion] ⚠️ Failed to cleanup old student_subjects:", cleanupError);
          // Don't fail the whole operation
        } else {
          console.log(`[Promotion] ✅ Cleaned up old student_subjects for ${studentIds.length} promoted students`);
        }

        return c.json({
          success: true,
          message: "Students promoted successfully",
          promoted_count: students.length,
          is_graduation: false,
          session,
        });
      }
    } catch (error) {
      console.error("[Promotion] Error:", error);
      return c.json(
        { success: false, error: "Failed to promote students" },
        500,
      );
    }
  },
);

// Get user profile (for promotion banner when RLS blocks client access)
app.get(
  "/make-server-1ddd013a/user-profile/:userId",
  async (c) => {
    try {
      // Verify authentication
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json({ error: "Unauthorized" }, 401);
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json({ error: "Unauthorized" }, 401);
      }

      const userId = c.req.param("userId");

      // Only allow users to fetch their own profile
      if (user.id !== userId) {
        return c.json(
          {
            error:
              "Forbidden - can only access your own profile",
          },
          403,
        );
      }

      // Fetch profile using service role (bypasses RLS)
      const { data: profile, error } = await supabase
        .from("profiles")
        .select(
          "id, first_name, last_name, email, role, class_id",
        )
        .eq("id", userId)
        .single();

      if (error) {
        console.error(
          "[UserProfile] Error fetching profile:",
          error,
        );
        return c.json({ error: "Profile not found" }, 404);
      }

      return c.json(profile);
    } catch (error) {
      console.error("[UserProfile] Error:", error);
      return c.json({ error: "Failed to fetch profile" }, 500);
    }
  },
);

// Get class names for promotion banner (bypasses RLS)
app.post(
  "/make-server-1ddd013a/promotion-classes",
  async (c) => {
    try {
      // Verify authentication
      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      if (!accessToken) {
        return c.json({ error: "Unauthorized" }, 401);
      }

      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id) {
        return c.json({ error: "Unauthorized" }, 401);
      }

      const body = await c.req.json();
      const { from_class_id, to_class_id } = body;

      console.log("[PromotionClasses] Fetching class names:", {
        from_class_id,
        to_class_id,
      });

      const result: { from_class?: string; to_class?: string } =
        {};

      // Fetch FROM class name
      if (from_class_id) {
        const { data: fromClass, error: fromError } =
          await supabase
            .from("classes")
            .select("name")
            .eq("id", from_class_id)
            .single();

        if (fromError) {
          console.error(
            "[PromotionClasses] Error fetching from_class:",
            fromError,
          );
        } else if (fromClass?.name) {
          result.from_class = fromClass.name;
          console.log(
            "[PromotionClasses] ✅ From class:",
            fromClass.name,
          );
        }
      }

      // Fetch TO class name
      if (to_class_id) {
        const { data: toClass, error: toError } = await supabase
          .from("classes")
          .select("name")
          .eq("id", to_class_id)
          .single();

        if (toError) {
          console.error(
            "[PromotionClasses] Error fetching to_class:",
            toError,
          );
        } else if (toClass?.name) {
          result.to_class = toClass.name;
          console.log(
            "[PromotionClasses] ✅ To class:",
            toClass.name,
          );
        }
      }

      console.log("[PromotionClasses] Final result:", result);
      return c.json(result);
    } catch (error) {
      console.error("[PromotionClasses] Error:", error);
      return c.json(
        { error: "Failed to fetch class names" },
        500,
      );
    }
  },
);

