// Alumni Login - Verify alumni credentials (name + graduation session)
app.post("/make-server-1ddd013a/alumni/login", async (c) => {
  try {
    const body = await c.req.json();
    const { first_name, last_name, graduation_session } = body;

    console.log("[Alumni Login] Attempt:", {
      first_name,
      last_name,
      graduation_session,
    });

    if (!first_name || !last_name || !graduation_session) {
      return c.json(
        {
          success: false,
          error:
            "First name, last name, and graduation session are required",
        },
        400,
      );
    }

    // Search for graduated student by name and graduation session
    // Check first_name OR middle_name to handle cases where student uses their middle name
    const { data: allAlumni, error } = await supabase
      .from("graduated_students")
      .select("*")
      .ilike("last_name", last_name.trim())
      .eq("graduation_session", graduation_session);

    console.log("[Alumni Login] Query result:", { allAlumni, error });

    if (error) {
      console.error("[Alumni Login] Database error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to verify alumni credentials",
        },
        500,
      );
    }

    // Filter by first name OR middle name (case-insensitive)
    const alumni = allAlumni?.find((alum: any) => {
      const firstNameMatch = alum.first_name?.toLowerCase().trim() === first_name.toLowerCase().trim();
      const middleNameMatch = alum.middle_name?.toLowerCase().trim() === first_name.toLowerCase().trim();
      return firstNameMatch || middleNameMatch;
    });

    if (!alumni) {
      console.log("[Alumni Login] No matching alumni found. Available alumni for this session:");
      if (allAlumni && allAlumni.length > 0) {
        allAlumni.forEach((alum: any) => {
          console.log(`  - ${alum.first_name} ${alum.middle_name || ''} ${alum.last_name}`.trim());
        });
      }
      return c.json(
        {
          success: false,
          error:
            "No matching alumni record found. Please check your name and graduation session. Try using your full first name or middle name as it appears in school records.",
        },
        404,
      );
    }

    console.log("[Alumni Login] Alumni found:", alumni.id);

    return c.json({
      success: true,
      alumni: {
        id: alumni.id,
        student_id: alumni.student_id,
        first_name: alumni.first_name,
        last_name: alumni.last_name,
        middle_name: alumni.middle_name,
        admission_number: alumni.admission_number,
        graduation_session: alumni.graduation_session,
        graduation_class: alumni.graduation_class,
        fees_clearance_required: alumni.fees_clearance_required,
        fees_cleared: alumni.fees_cleared,
        outstanding_balance: alumni.outstanding_balance,
      },
    });
  } catch (error) {
    console.error("[Alumni Login] Error:", error);
    return c.json(
      {
        success: false,
        error: "Failed to process alumni login",
      },
      500,
    );
  }
});

// Alumni - Verify transcript PIN and access transcript
app.post(
  "/make-server-1ddd013a/alumni/verify-pin",
  async (c) => {
    try {
      const body = await c.req.json();
      const { alumni_id, pin_code } = body;

      console.log("[Alumni Verify PIN] Attempt:", {
        alumni_id,
        pin_code,
      });

      if (!alumni_id || !pin_code) {
        return c.json(
          {
            success: false,
            error: "Alumni ID and PIN code are required",
          },
          400,
        );
      }

      // Get alumni record
      const { data: alumni, error: alumniError } =
        await supabase
          .from("graduated_students")
          .select("*")
          .eq("id", alumni_id)
          .single();

      if (alumniError || !alumni) {
        console.error(
          "[Alumni Verify PIN] Alumni not found:",
          alumniError,
        );
        return c.json(
          {
            success: false,
            error: "Alumni record not found",
          },
          404,
        );
      }

      // Check fees clearance
      if (
        alumni.fees_clearance_required &&
        !alumni.fees_cleared
      ) {
        console.log("[Alumni Verify PIN] Fees not cleared");
        return c.json(
          {
            success: false,
            error: "Fees clearance required",
            fees_required: true,
            outstanding_balance: alumni.outstanding_balance,
          },
          403,
        );
      }

      // Verify PIN
      const { data: pin, error: pinError } = await supabase
        .from("transcript_pins")
        .select("*")
        .eq("graduated_student_id", alumni_id)
        .eq("pin_code", pin_code)
        .maybeSingle();

      if (pinError) {
        console.error(
          "[Alumni Verify PIN] PIN lookup error:",
          pinError,
        );
        return c.json(
          {
            success: false,
            error: "Failed to verify PIN",
          },
          500,
        );
      }

      if (!pin) {
        console.log("[Alumni Verify PIN] Invalid PIN");
        return c.json(
          {
            success: false,
            error: "Invalid PIN",
          },
          403,
        );
      }

      // Check if PIN has reached maximum uses
      const maxUses = pin.max_uses || 3; // Default to 3 if not set
      const usesCount = pin.uses_count || 0;
      
      if (usesCount >= maxUses) {
        console.log("[Alumni Verify PIN] PIN has reached maximum uses:", {
          usesCount,
          maxUses,
        });
        return c.json(
          {
            success: false,
            error: `This PIN has already been used ${usesCount} time(s) and has reached its maximum usage limit`,
          },
          403,
        );
      }

      // Check if PIN has expired
      if (pin.expires_at) {
        const now = new Date();
        const expiresAt = new Date(pin.expires_at);
        if (now > expiresAt) {
          console.log("[Alumni Verify PIN] PIN expired");
          return c.json(
            {
              success: false,
              error: "PIN has expired",
            },
            403,
          );
        }
      }

      // Increment uses count and update is_used if max reached
      const newUsesCount = usesCount + 1;
      const shouldMarkAsUsed = newUsesCount >= maxUses;

      const { error: updateError } = await supabase
        .from("transcript_pins")
        .update({
          uses_count: newUsesCount,
          is_used: shouldMarkAsUsed,
        })
        .eq("id", pin.id);

      if (updateError) {
        console.error(
          "[Alumni Verify PIN] Failed to update PIN usage:",
          updateError,
        );
        // Continue even if update fails - don't block transcript access
      } else {
        console.log("[Alumni Verify PIN] Updated PIN usage:", {
          pin_id: pin.id,
          old_uses: usesCount,
          new_uses: newUsesCount,
          is_used: shouldMarkAsUsed,
        });
      }

      // Record the transcript access request
      const { error: requestError } = await supabase
        .from("transcript_requests")
        .insert({
          graduated_student_id: alumni_id,
          pin_id: pin.id,
        });

      if (requestError) {
        console.error(
          "[Alumni Verify PIN] Failed to record request:",
          requestError,
        );
        // Don't fail the request if logging fails
      }

      console.log(
        "[Alumni Verify PIN] Success for alumni:",        alumni_id,
      );

      // Fetch academic records for transcript
      const { data: academicRecords, error: recordsError } =
        await supabase
          .from("marks")
          .select(
            `
          *,
          exams (
            id,
            name,
            session,
            term
          ),
          subjects (
            id,
            name,
            code
          )
        `,
          )
          .eq("student_id", alumni.student_id)
          .eq("status", "approved")
          .order("created_at", { ascending: true });

      if (recordsError) {
        console.error(
          "[Alumni Verify PIN] Error fetching records:",
          recordsError,
        );
      }

      // Group records by year/session and transform data
      const groupedRecords: Record<string, any[]> = {};
      const transformedRecords = academicRecords?.map((record) => ({
        id: record.id,
        subject: record.subjects?.name || 'Unknown Subject',
        subject_code: record.subjects?.code || '',
        ca1: record.terminal_ca1 || 0,
        ca2: record.terminal_ca2 || 0,
        exam_score: record.terminal_exam || 0,
        total: record.terminal_total || 0,
        grade: record.grade || 'N/A',
        exams: {
          session: record.exams?.session || 'Unknown',
          term: record.exams?.term || 'Unknown',
          name: record.exams?.name || 'Unknown',
        },
      })) || [];

      transformedRecords.forEach((record) => {
        const session = record.exams?.session || "Unknown";
        if (!groupedRecords[session]) {
          groupedRecords[session] = [];
        }
        groupedRecords[session].push(record);
      });

      // Return transcript data
      return c.json({
        success: true,
        message: "PIN verified successfully",
        alumni: {
          id: alumni.id,
          student_id: alumni.student_id,
          first_name: alumni.first_name,
          last_name: alumni.last_name,
          middle_name: alumni.middle_name,
          admission_number: alumni.admission_number,
          graduation_session: alumni.graduation_session,
          graduation_class: alumni.graduation_class,
          graduation_number: alumni.graduation_number,
          email: alumni.email,
          phone: alumni.phone,
          date_of_birth: alumni.date_of_birth,
          gender: alumni.gender,
        },
        pin: {
          id: pin.id,
          pin_code: pin.pin_code,
          generated_at: pin.generated_at,
          expires_at: pin.expires_at,
          uses_count: newUsesCount,
          max_uses: maxUses,
          remaining_uses: maxUses - newUsesCount,
        },
        academic_records: transformedRecords,
        grouped_records: groupedRecords,
        total_records: transformedRecords.length,
      });
    } catch (error) {
      console.error("[Alumni Verify PIN] Error:", error);
      return c.json(
        {
          success: false,
          error: "Failed to verify PIN",
        },
        500,
      );
    }
  },
);

