// Helper function to generate secure transcript PIN
function generateTranscriptPin(): string {
  const characters = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // Exclude confusing chars
  let pin = "";
  for (let i = 0; i < 12; i++) {
    if (i > 0 && i % 4 === 0) {
      pin += "-";
    }
    pin += characters.charAt(
      Math.floor(Math.random() * characters.length),
    );
  }
  return pin;
}

// Get all graduated students
app.get(
  "/make-server-1ddd013a/graduated-students",
  async (c) => {
    try {
      console.log(
        "[GraduatedStudents] Fetching all graduated students",
      );

      const accessToken = c.req
        .header("Authorization")
        ?.split(" ")[1];
      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);

      if (!user?.id) {
        console.error(
          "[GraduatedStudents] No user found in token",
        );
        return c.json(
          { success: false, error: "Unauthorized" },
          401,
        );
      }

      // Check if user is admin/director
      const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

      const allowedRoles = [
        "it_admin",
        "director",
        "principal",
      ];
      if (!profile || !allowedRoles.includes(profile.role)) {
        console.error(
          "[GraduatedStudents] Insufficient permissions. User role:",
          profile?.role,
        );
        return c.json(
          { success: false, error: "Insufficient permissions" },
          403,
        );
      }

      // Fetch from graduated_students table (proper architecture)
      // NOTE: Removed .eq("is_active", true) filter to fetch ALL graduated students
      // is_active column is used for future feature to temporarily disable alumni portal access
      
      // Use SERVICE_ROLE_KEY to bypass RLS
      const adminSupabase = createClient(
        Deno.env.get('SUPABASE_URL') ?? '',
        Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
      );
      
      const { data: graduatedStudents, error } = await adminSupabase
        .from("graduated_students")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) {
        console.error(
          "[GraduatedStudents] Error fetching from graduated_students table:",
          error,
        );
        return c.json(
          { success: false, error: error.message },
          500,
        );
      }

      console.log('[GraduatedStudents] Raw graduated students sample:', graduatedStudents?.[0]);
      console.log('[GraduatedStudents] All graduation_class values:', 
        graduatedStudents?.map(s => ({ 
          name: `${s.first_name} ${s.last_name}`, 
          graduation_class: s.graduation_class,
          type: typeof s.graduation_class
        }))
      );

      // Helper function to check if a string is a UUID
      const isUUID = (str: string): boolean => {
        const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
        return uuidRegex.test(str);
      };

      // Separate class IDs (UUIDs) from class names (text)
      const classIdsToFetch: string[] = [];
      const alreadyClassNames: Record<string, string> = {};
      
      graduatedStudents?.forEach(s => {
        if (s.graduation_class) {
          if (isUUID(s.graduation_class)) {
            // It's a UUID, need to fetch the name
            classIdsToFetch.push(s.graduation_class);
          } else {
            // It's already a class name (legacy data)
            alreadyClassNames[s.graduation_class] = s.graduation_class;
          }
        }
      });

      const uniqueClassIds = [...new Set(classIdsToFetch)];
      console.log('[GraduatedStudents] Unique class UUIDs to fetch:', uniqueClassIds);
      console.log('[GraduatedStudents] Already have class names:', Object.keys(alreadyClassNames));

      // Fetch class names for UUIDs
      let classMap: Record<string, string> = { ...alreadyClassNames };
      if (uniqueClassIds.length > 0) {
        const { data: classes, error: classError } = await adminSupabase
          .from("classes")
          .select("id, name")
          .in("id", uniqueClassIds);
        
        console.log('[GraduatedStudents] Classes fetched:', classes);
        if (classError) {
          console.error('[GraduatedStudents] Error fetching classes:', classError);
        }
        
        // Add fetched classes to the map
        if (classes) {
          classes.forEach(cls => {
            classMap[cls.id] = cls.name;
          });
        }
        
        console.log('[GraduatedStudents] Final class map:', classMap);
      }

      // Transform the data to include class name
      const transformedStudents = graduatedStudents?.map(student => {
        const className = student.graduation_class ? classMap[student.graduation_class] : null;
        
        if (student.graduation_class && !className) {
          console.warn(
            `[GraduatedStudents] ⚠️ No class name found for student ${student.first_name} ${student.last_name}`,
            `with class ID: ${student.graduation_class}`
          );
        }
        
        return {
          ...student,
          graduation_class_name: className || student.graduation_class || 'Unknown',
          graduation_class: student.graduation_class // Keep the ID for reference
        };
      }) || [];

      console.log(
        `[GraduatedStudents] Found ${transformedStudents.length} alumni in graduated_students table`,
      );
      console.log('[GraduatedStudents] Sample transformed student:', transformedStudents[0]);
      console.log('[GraduatedStudents] Transformation summary:', 
        transformedStudents.slice(0, 5).map(s => ({
          name: `${s.first_name} ${s.last_name}`,
          graduation_class_id: s.graduation_class,
          graduation_class_name: s.graduation_class_name
        }))
      );
      return c.json({
        success: true,
        students: transformedStudents,
      });
    } catch (error) {
      console.error("[GraduatedStudents] Error:", error);
      const errorMessage =
        error instanceof Error
          ? error.message
          : "Failed to fetch graduated students";
      return c.json(
        { success: false, error: errorMessage },
        500,
      );
    }
  },
);

