// Get detailed fee history for graduated student
app.get(
  "/make-server-1ddd013a/graduated-students/:id/fee-history",
  async (c) => {
    try {
      const studentId = c.req.param("id");
      console.log("[FeeHistory] Fetching fee history for student:", studentId);

      // Get graduated student details
      const { data: graduatedStudent, error: studentError } = await supabase
        .from("graduated_students")
        .select("*")
        .eq("id", studentId)
        .single();

      if (studentError || !graduatedStudent) {
        console.error("[FeeHistory] Student not found:", studentError);
        return c.json(
          { success: false, error: "Graduated student not found" },
          404
        );
      }

      let studentProfileId: string | undefined;

      // First try using admission_number if available
      if (graduatedStudent.admission_number) {
        const { data: profile } = await supabase
          .from("profiles")
          .select("id")
          .eq("admission_number", graduatedStudent.admission_number)
          .eq("student_type", "graduated")
          .single();

        studentProfileId = profile?.id;

        // If not found as graduated, check if they still exist as regular student
        if (!studentProfileId) {
          const { data: regularProfile } = await supabase
            .from("profiles")
            .select("id")
            .eq("admission_number", graduatedStudent.admission_number)
            .in("student_type", ["boarding", "day"])
            .single();
          
          studentProfileId = regularProfile?.id;
        }
      }

      // If still not found, try using student_id directly
      if (!studentProfileId && graduatedStudent.student_id) {
        console.log("[FeeHistory] Trying to find profile by student_id:", graduatedStudent.student_id);
        const { data: profileById } = await supabase
          .from("profiles")
          .select("id")
          .eq("id", graduatedStudent.student_id)
          .single();
        
        studentProfileId = profileById?.id;
      }

      if (!studentProfileId) {
        console.error("[FeeHistory] Profile not found for admission number:", graduatedStudent.admission_number);
        return c.json(
          { success: false, error: "Student profile not found" },
          404
        );
      }

      // Fetch ALL payments for this student (approved only)
      const { data: allPayments, error: paymentsError } = await supabase
        .from("payments")
        .select("*")
        .eq("student_id", studentProfileId)
        .eq("approval_status", "approved")
        .order("academic_year", { ascending: true })
        .order("term", { ascending: true });

      if (paymentsError) {
        console.error("[FeeHistory] Error fetching payments:", paymentsError);
        return c.json(
          { success: false, error: paymentsError.message },
          500
        );
      }

      console.log("[FeeHistory] Total payments found:", allPayments?.length || 0);

      // If no payments at all, return empty history
      if (!allPayments || allPayments.length === 0) {
        return c.json({
          success: true,
          feeHistory: [],
          firstRegisteredSession: null,
          firstRegisteredTerm: null,
          graduationSession: graduatedStudent.graduation_session,
          isFullyCleared: false,
          totalOutstanding: 0,
          message: "No fee payment records found for this student"
        });
      }

      // Find the first payment record (earliest session/term)
      const firstPayment = allPayments[0];
      const firstSession = firstPayment.academic_year;
      const firstTerm = firstPayment.term;

      console.log("[FeeHistory] First fee registration:", firstSession, firstTerm);

      // Parse graduation session to determine end point
      const graduationSession = graduatedStudent.graduation_session;
      
      // Get ALL fee structures from KV store
      const allFeeStructures = (await kv.getByPrefix("fee_structure:")) || [];
      console.log("[FeeHistory] Fee structures found:", allFeeStructures?.length || 0);

      // Determine student type from graduation class
      const gradClass = graduatedStudent.graduation_class?.toLowerCase() || "";
      const isBoarding = gradClass.includes("boarding");
      const studentType = isBoarding ? "boarding" : "day";
      
      // Default fee if no fee structure found
      const defaultTermFee = isBoarding ? 150000 : 100000;

      // Build a map of fee structures for quick lookup: session_term_type -> amount
      const feeStructureMap: Record<string, number> = {};
      allFeeStructures.forEach((structure: any) => {
        const key = `${structure.session}_${structure.term}_${structure.student_type}`;
        feeStructureMap[key] = structure.amount || 0;
      });

      console.log("[FeeHistory] Fee structure map entries:", Object.keys(feeStructureMap).length);

      // Generate list of all terms from first registration to graduation
      const termsToCheck = generateTermsList(firstSession, firstTerm, graduationSession);
      
      console.log("[FeeHistory] Terms to check:", termsToCheck.length);

      // Group payments by session-term
      const paymentsByTerm: Record<string, number> = {};
      allPayments.forEach(payment => {
        const key = `${payment.academic_year}_${payment.term}`;
        paymentsByTerm[key] = (paymentsByTerm[key] || 0) + (payment.amount_paid || 0);
      });

      // Build detailed fee history
      const feeHistory = termsToCheck.map(({ session, term }) => {
        const paymentKey = `${session}_${term}`;
        const totalPaid = paymentsByTerm[paymentKey] || 0;
        
        // Look up expected fee from fee structure
        const feeStructureKey = `${session}_${term}_${studentType}`;
        const expectedFee = feeStructureMap[feeStructureKey] || defaultTermFee;
        
        const outstanding = Math.max(0, expectedFee - totalPaid);

        return {
          session,
          term,
          expectedFee,
          totalPaid,
          outstanding,
          isCleared: outstanding === 0
        };
      });

      // Calculate totals
      const totalOutstanding = feeHistory.reduce((sum, item) => sum + item.outstanding, 0);
      const isFullyCleared = totalOutstanding === 0;

      console.log("[FeeHistory] Total outstanding:", totalOutstanding);
      console.log("[FeeHistory] Fully cleared:", isFullyCleared);

      return c.json({
        success: true,
        feeHistory,
        firstRegisteredSession: firstSession,
        firstRegisteredTerm: firstTerm,
        graduationSession,
        isFullyCleared,
        totalOutstanding,
        studentName: `${graduatedStudent.first_name} ${graduatedStudent.last_name}`,
        admissionNumber: graduatedStudent.admission_number
      });

    } catch (error) {
      console.error("[FeeHistory] Error:", error);
      return c.json(
        {
          success: false,
          error: error instanceof Error ? error.message : "Failed to fetch fee history"
        },
        500
      );
    }
  }
);

// Helper function to generate list of terms from start to end
function generateTermsList(
  startSession: string,
  startTerm: string,
  endSession: string
): Array<{ session: string; term: string }> {
  const terms = ["First Term", "Second Term", "Third Term"];
  const result: Array<{ session: string; term: string }> = [];

  // Parse session format "2023/2024"
  const parseSession = (session: string) => {
    const parts = session.split("/");
    return parseInt(parts[0]);
  };

  const startYear = parseSession(startSession);
  const endYear = parseSession(endSession);
  const startTermIndex = terms.indexOf(startTerm);

  let currentYear = startYear;
  let currentTermIndex = startTermIndex;

  // Generate all terms from start to end
  while (currentYear <= endYear) {
    const currentSession = `${currentYear}/${currentYear + 1}`;
    
    // If this is the last session (graduation session), include all terms up to Third Term
    const maxTermIndex = 2; // Always go to Third Term
    
    while (currentTermIndex <= maxTermIndex) {
      result.push({
        session: currentSession,
        term: terms[currentTermIndex]
      });
      
      currentTermIndex++;
    }

    // Move to next session
    currentYear++;
    currentTermIndex = 0; // Reset to First Term for new session

    // Stop if we've passed the end session
    if (currentYear > endYear) break;
  }

  return result;
}

