// Generate new transcript PIN
app.post("/make-server-1ddd013a/transcript-pins", async (c) => {
  try {
    console.log("[TranscriptPins] Generating new PIN");

    const accessToken = c.req
      .header("Authorization")
      ?.split(" ")[1];
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(accessToken);

    if (!user?.id) {
      return c.json(
        { success: false, error: "Unauthorized" },
        401,
      );
    }

    // Check permissions
    const { data: profile } = await supabase
      .from("profiles")
      .select("role")
      .eq("id", user.id)
      .single();

    const allowedRoles = ["it_admin", "director"];
    if (!profile || !allowedRoles.includes(profile.role)) {
      return c.json(
        { success: false, error: "Insufficient permissions" },
        403,
      );
    }

    const body = await c.req.json();
    const {
      graduated_student_id,
      price = 0,
      payment_reference,
      expires_in_days = 90,
    } = body;

    // Validate required fields
    if (!graduated_student_id) {
      return c.json(
        {
          success: false,
          error: "graduated_student_id is required",
        },
        400,
      );
    }

    // Check if graduated student record exists
    const { data: student, error: studentError } =
      await supabase
        .from("graduated_students")
        .select("id")
        .eq("id", graduated_student_id)
        .single();

    if (studentError || !student) {
      console.error(
        "[TranscriptPins] Graduated student not found:",
        graduated_student_id,
        studentError,
      );
      return c.json(
        {
          success: false,
          error: "Graduated student not found",
        },
        404,
      );
    }

    if (!student.is_active) {
      return c.json(
        {
          success: false,
          error: "This alumni record is inactive",
        },
        400,
      );
    }

    // Generate unique PIN
    let pinCode = generateTranscriptPin();
    let attempts = 0;

    // Ensure uniqueness
    while (attempts < 10) {
      const { data: existing } = await supabase
        .from("transcript_pins")
        .select("id")
        .eq("pin_code", pinCode)
        .single();

      if (!existing) break;
      pinCode = generateTranscriptPin();
      attempts++;
    }

    // Calculate expiry date
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + expires_in_days);

    // Create PIN
    const { data: pin, error } = await supabase
      .from("transcript_pins")
      .insert({
        pin_code: pinCode,
        graduated_student_id,
        generated_by: user.id,
        price,
        payment_reference,
        expires_at: expiresAt.toISOString(),
        is_used: false,
      })
      .select()
      .single();

    if (error) {
      console.error(
        "[TranscriptPins] Error creating PIN:",
        error,
      );
      return c.json(
        { success: false, error: error.message },
        500,
      );
    }

    console.log(
      "[TranscriptPins] PIN created successfully:",
      pin.pin_code,
    );
    return c.json({ success: true, pin });
  } catch (error) {
    console.error("[TranscriptPins] Error:", error);
    return c.json(
      {
        success: false,
        error: "Failed to generate transcript PIN",
      },
      500,
    );
  }
});

