// Upload clock-in/out photo
app.post('/make-server-1ddd013a/upload-clock-photo', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const formData = await c.req.formData();
    const file = formData.get('file') as File;
    const studentId = formData.get('studentId') as string;
    const type = formData.get('type') as string; // 'clock-in' or 'clock-out'

    if (!file || !studentId || !type) {
      return c.json({ success: false, error: 'Missing required fields' }, 400);
    }

    // Create bucket if it doesn't exist
    const bucketName = 'make-1ddd013a-clock-photos';
    const { data: buckets } = await supabase.storage.listBuckets();
    const bucketExists = buckets?.some(bucket => bucket.name === bucketName);
    
    if (!bucketExists) {
      await supabase.storage.createBucket(bucketName, { public: false });
    }

    // Upload file
    const today = new Date().toISOString().split('T')[0];
    const timestamp = Date.now();
    const fileName = `${today}/${type}/${studentId}_${timestamp}.jpg`;
    
    const { data: uploadData, error: uploadError } = await supabase.storage
      .from(bucketName)
      .upload(fileName, file, {
        contentType: 'image/jpeg',
        upsert: false
      });

    if (uploadError) {
      console.error('Upload error:', uploadError);
      return c.json({ success: false, error: 'Failed to upload photo' }, 500);
    }

    // Get signed URL (valid for 1 year)
    const { data: signedUrlData } = await supabase.storage
      .from(bucketName)
      .createSignedUrl(fileName, 31536000); // 1 year

    return c.json({ 
      success: true, 
      photoUrl: signedUrlData?.signedUrl || '',
      path: fileName
    });
  } catch (error) {
    console.error('Error uploading clock photo:', error);
    return c.json({ success: false, error: 'Failed to upload photo' }, 500);
  }
});

// Clock in a student
app.post('/make-server-1ddd013a/clock-in', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { studentId, photoUrl, week } = await c.req.json();

    if (!studentId || !photoUrl) {
      return c.json({ success: false, error: 'Missing required fields' }, 400);
    }

    // Get current active session and term from database
    const { data: activeSession } = await supabase
      .from('academic_sessions')
      .select('session_name')
      .eq('is_current', true)
      .single();

    const { data: activeTerm } = await supabase
      .from('academic_terms')
      .select('term_name')
      .eq('is_current', true)
      .single();

    const session = activeSession?.session_name || await kv.get('active_session') || '2024/2025';
    const term = activeTerm?.term_name || await kv.get('active_term') || 'First Term';
    
    console.log('[Clock-In] Using active session:', session, 'term:', term, 'week:', week);

    // Get school start time (default 8:00 AM)
    const settings = await kv.get('settings:academic') || {};
    const schoolStartTime = settings.schoolStartTime || '08:00';

    // Check if student already clocked in today
    const today = new Date().toISOString().split('T')[0];
    const { data: existingRecord } = await supabase
      .from('student_clock_records')
      .select('*')
      .eq('student_id', studentId)
      .eq('date', today)
      .single();

    if (existingRecord) {
      return c.json({ 
        success: false, 
        error: 'Student already clocked in today' 
      }, 400);
    }

    // Get student details with class name
    const { data: studentProfile } = await supabase
      .from('profiles')
      .select(`
        first_name, 
        middle_name, 
        last_name, 
        class_id,
        class:class_id(name)
      `)
      .eq('id', studentId)
      .single();

    if (!studentProfile) {
      return c.json({ success: false, error: 'Student not found' }, 404);
    }

    const className = studentProfile.class?.name || 'Unassigned';

    const now = new Date();
    
    // Check if late (after school start time)
    const currentTime = now.toTimeString().substring(0, 5); // HH:MM
    const isLate = currentTime > schoolStartTime;

    // Insert clock record into database
    const { data: clockRecord, error: insertError } = await supabase
      .from('student_clock_records')
      .insert({
        student_id: studentId,
        date: today,
        clock_in_time: now.toISOString(),
        clock_in_photo_url: photoUrl,
        clock_in_teacher_id: user.id,
        session: session,
        term: term,
        week: week || null,
        late_arrival: isLate,
        auto_marked_present: true
      })
      .select()
      .single();

    if (insertError) {
      console.error('Error inserting clock record:', insertError);
      return c.json({ success: false, error: 'Failed to create clock record' }, 500);
    }

    // Auto-create attendance record
    const attendanceKey = `attendance:${session}:${term}:${className}:${today}:${studentId}`;
    const attendanceRecord = {
      student_id: studentId,
      class_name: className,
      date: today,
      status: isLate ? 'late' : 'present',
      session: session,
      term: term,
      marked_by: user.id,
      marked_at: now.toISOString(),
      source: 'gate_clock_in',
      clock_record_id: clockRecord.id
    };
    await kv.set(attendanceKey, attendanceRecord);

    return c.json({ 
      success: true, 
      record: clockRecord,
      message: isLate ? 'Student clocked in (LATE)' : 'Student clocked in successfully'
    });
  } catch (error) {
    console.error('Error clocking in student:', error);
    return c.json({ success: false, error: 'Failed to clock in student' }, 500);
  }
});

// Clock out a student
app.post('/make-server-1ddd013a/clock-out', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { studentId, photoUrl } = await c.req.json();

    if (!studentId || !photoUrl) {
      return c.json({ success: false, error: 'Missing required fields' }, 400);
    }

    // Get today's clock record
    const today = new Date().toISOString().split('T')[0];
    const { data: existingRecord } = await supabase
      .from('student_clock_records')
      .select('*')
      .eq('student_id', studentId)
      .eq('date', today)
      .single();

    if (!existingRecord) {
      return c.json({ 
        success: false, 
        error: 'No clock-in record found for today' 
      }, 400);
    }

    if (existingRecord.clock_out_time) {
      return c.json({ 
        success: false, 
        error: 'Student already clocked out today' 
      }, 400);
    }

    const now = new Date();

    // Get school end time (default 3:00 PM)
    const settings = await kv.get('settings:academic') || {};
    const schoolEndTime = settings.schoolEndTime || '15:00';
    const currentTime = now.toTimeString().substring(0, 5); // HH:MM
    const isEarly = currentTime < schoolEndTime;

    // Update record with clock-out information
    const { data: updatedRecord, error: updateError } = await supabase
      .from('student_clock_records')
      .update({
        clock_out_time: now.toISOString(),
        clock_out_photo_url: photoUrl,
        clock_out_teacher_id: user.id,
        early_departure: isEarly
      })
      .eq('id', existingRecord.id)
      .select()
      .single();

    if (updateError) {
      console.error('Error updating clock record:', updateError);
      return c.json({ success: false, error: 'Failed to update clock record' }, 500);
    }

    return c.json({ 
      success: true, 
      record: updatedRecord,
      message: isEarly ? 'Student clocked out (EARLY)' : 'Student clocked out successfully'
    });
  } catch (error) {
    console.error('Error clocking out student:', error);
    return c.json({ success: false, error: 'Failed to clock out student' }, 500);
  }
});

// Get today's clock records (for teacher gate duty interface)
app.get('/make-server-1ddd013a/clock-records-today', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const today = new Date().toISOString().split('T')[0];

    // Get all records for today with student and teacher details
    const { data: records, error: recordsError } = await supabase
      .from('student_clock_records')
      .select(`
        *,
        student:student_id(first_name, middle_name, last_name, class_id, class:class_id(name)),
        clock_in_teacher:clock_in_teacher_id(first_name, last_name),
        clock_out_teacher:clock_out_teacher_id(first_name, last_name)
      `)
      .eq('date', today)
      .order('clock_in_time', { ascending: false });

    if (recordsError) {
      console.error('Error fetching records:', recordsError);
      return c.json({ success: false, error: 'Failed to fetch records' }, 500);
    }

    // Get total students count
    const { count } = await supabase
      .from('profiles')
      .select('*', { count: 'exact', head: true })
      .eq('role', 'student');

    const totalStudents = count || 0;
    const clockedIn = records?.length || 0;
    const clockedOut = records?.filter(r => r.clock_out_time).length || 0;
    const lateArrivals = records?.filter(r => r.late_arrival).length || 0;

    // Format records with student and teacher names
    const formattedRecords = (records || []).map(record => ({
      ...record,
      student_name: record.student 
        ? `${record.student.first_name} ${record.student.middle_name || ''} ${record.student.last_name}`.trim()
        : 'Unknown Student',
      class_name: record.student?.class?.name || 'Unassigned',
      clock_in_teacher_name: record.clock_in_teacher
        ? `${record.clock_in_teacher.first_name} ${record.clock_in_teacher.last_name}`
        : 'Unknown',
      clock_out_teacher_name: record.clock_out_teacher
        ? `${record.clock_out_teacher.first_name} ${record.clock_out_teacher.last_name}`
        : null
    }));

    return c.json({
      success: true,
      records: formattedRecords,
      stats: {
        total: totalStudents,
        clockedIn: clockedIn,
        clockedOut: clockedOut,
        lateArrivals: lateArrivals
      }
    });
  } catch (error) {
    console.error('Error fetching today records:', error);
    return c.json({ success: false, error: 'Failed to fetch records' }, 500);
  }
});

// Get clock records for a specific date (for admin monitoring)
app.get('/make-server-1ddd013a/clock-records', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const date = c.req.query('date') || new Date().toISOString().split('T')[0];
    const week = c.req.query('week');
    const term = c.req.query('term');
    const session = c.req.query('session');

    // Build query with optional filters
    let query = supabase
      .from('student_clock_records')
      .select(`
        *,
        student:student_id(first_name, middle_name, last_name, class_id, class:class_id(name)),
        clock_in_teacher:clock_in_teacher_id(first_name, last_name),
        clock_out_teacher:clock_out_teacher_id(first_name, last_name)
      `)
      .eq('date', date);

    // Apply optional filters
    if (week && week !== 'all') {
      query = query.eq('week', week);
    }
    if (term && term !== 'all') {
      query = query.eq('term', term);
    }
    if (session && session !== 'all') {
      query = query.eq('session', session);
    }

    const { data: records, error: recordsError } = await query.order('clock_in_time', { ascending: false });

    if (recordsError) {
      console.error('Error fetching records:', recordsError);
    }

    // Get all students to calculate not arrived (exclude graduated students)
    const { data: allStudents, count: totalStudents } = await supabase
      .from('profiles')
      .select('id, first_name, middle_name, last_name, class_id, class:class_id(name)', { count: 'exact' })
      .eq('role', 'student')
      .or('is_graduated.is.null,is_graduated.eq.false');

    // Format records with student and teacher names
    const formattedRecords = (records || []).map(record => ({
      ...record,
      student_name: record.student 
        ? `${record.student.first_name} ${record.student.middle_name || ''} ${record.student.last_name}`.trim()
        : 'Unknown Student',
      class_name: record.student?.class?.name || 'Unassigned',
      clock_in_teacher_name: record.clock_in_teacher
        ? `${record.clock_in_teacher.first_name} ${record.clock_in_teacher.last_name}`
        : 'Unknown',
      clock_out_teacher_name: record.clock_out_teacher
        ? `${record.clock_out_teacher.first_name} ${record.clock_out_teacher.last_name}`
        : null
    }));

    // Create records for students who haven't clocked in
    const clockedInStudentIds = new Set(formattedRecords.map(r => r.student_id));
    const notArrivedRecords = (allStudents || [])
      .filter(student => !clockedInStudentIds.has(student.id))
      .map(student => ({
        id: `absent_${student.id}`,
        student_id: student.id,
        student_name: `${student.first_name} ${student.middle_name || ''} ${student.last_name}`.trim(),
        class_name: student.class?.name || 'Unassigned',
        date: date,
        clock_in_time: null,
        clock_out_time: null,
        late_arrival: false
      }));

    const allRecordsWithAbsent = [...formattedRecords, ...notArrivedRecords];

    const clockedIn = formattedRecords.length;
    const clockedOut = formattedRecords.filter(r => r.clock_out_time).length;
    const lateArrivals = formattedRecords.filter(r => r.late_arrival).length;
    const notArrived = notArrivedRecords.length;

    // Build list of students not clocked in (absent students)
    const notClockedInStudents = (allStudents || [])
      .filter(student => !clockedInStudentIds.has(student.id))
      .map(student => ({
        id: student.id,
        name: `${student.first_name} ${student.middle_name || ''} ${student.last_name}`.trim(),
        class_name: student.class?.name || 'Unassigned'
      }));

    // Build list of students who clocked in but not clocked out
    const notClockedOutStudents = formattedRecords
      .filter(r => r.clock_in_time && !r.clock_out_time)
      .map(r => ({
        id: r.student_id,
        name: r.student_name,
        class_name: r.class_name,
        clock_in_time: r.clock_in_time
      }));

    // Sort by status (present first, then late, then absent)
    allRecordsWithAbsent.sort((a, b) => {
      if (a.clock_in_time && !b.clock_in_time) return -1;
      if (!a.clock_in_time && b.clock_in_time) return 1;
      if (a.late_arrival && !b.late_arrival) return 1;
      if (!a.late_arrival && b.late_arrival) return -1;
      return (b.clock_in_time || '').localeCompare(a.clock_in_time || '');
    });

    return c.json({
      success: true,
      records: allRecordsWithAbsent,
      stats: {
        totalStudents: totalStudents || 0,
        clockedIn: clockedIn,
        clockedOut: clockedOut,
        lateArrivals: lateArrivals,
        notArrived: notArrived,
        date: date,
        notClockedInStudents: notClockedInStudents,
        notClockedOutStudents: notClockedOutStudents
      }
    });
  } catch (error) {
    console.error('Error fetching clock records:', error);
    return c.json({ success: false, error: 'Failed to fetch records' }, 500);
  }
});

// Get weekly trends
app.get('/make-server-1ddd013a/clock-weekly-trends', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !user) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const trends = [];
    const today = new Date();
    const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

    // Get last 7 days
    for (let i = 6; i >= 0; i--) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      const dateStr = date.toISOString().split('T')[0];
      const dayName = dayNames[date.getDay()];

      // Get records from database for this date
      const { data: records, error: recordsError } = await supabase
        .from('student_clock_records')
        .select('clock_in_time, late_arrival')
        .eq('date', dateStr);

      if (recordsError) {
        console.error(`Error fetching records for ${dateStr}:`, recordsError);
      }
      
      trends.push({
        day: dayName,
        date: dateStr,
        clockedIn: records?.length || 0,
        lateArrivals: records?.filter(r => r.late_arrival).length || 0
      });
    }

    return c.json({ success: true, trends });
  } catch (error) {
    console.error('Error fetching weekly trends:', error);
    return c.json({ success: false, error: 'Failed to fetch trends' }, 500);
  }
});

