// INITIALIZE STORAGE BUCKETS
// ================================================
async function initializeStorageBuckets() {
  try {
    console.log('[Storage] Initializing storage buckets...');
    
    const bucketsToCreate = [
      {
        name: 'make-1ddd013a-cbt-questions',
        options: {
          public: true, // Public bucket for question images
          fileSizeLimit: 5242880, // 5MB
        }
      }
    ];

    const { data: existingBuckets } = await supabase.storage.listBuckets();
    
    for (const bucket of bucketsToCreate) {
      const bucketExists = existingBuckets?.some(b => b.name === bucket.name);
      
      if (!bucketExists) {
        console.log(`[Storage] Creating bucket: ${bucket.name}`);
        const { error } = await supabase.storage.createBucket(bucket.name, bucket.options);
        
        if (error) {
          // Suppress 409 error (bucket already exists) - this is harmless
          if (error.statusCode === '409' || error.message?.includes('already exists')) {
            console.log(`[Storage] ✅ Bucket already exists: ${bucket.name}`);
          } else {
            console.error(`[Storage] Error creating bucket ${bucket.name}:`, error);
          }
        } else {
          console.log(`[Storage] ✅ Bucket created: ${bucket.name}`);
        }
      } else {
        console.log(`[Storage] ✅ Bucket already exists: ${bucket.name}`);
      }
    }
    
    console.log('[Storage] Bucket initialization complete');
  } catch (error) {
    console.error('[Storage] Error initializing buckets:', error);
  }
}

// Initialize buckets on startup
initializeStorageBuckets();

