// ==================== E-LESSON PLAN MODULE ====================

// Helper: Calculate current academic week
function calculateAcademicWeek(termStartDate: string): { weekNumber: number; weekStartDate: string; weekEndDate: string } {
  const start = new Date(termStartDate);
  const today = new Date();
  
  // Get Monday of current week
  const currentDayOfWeek = today.getDay();
  const daysFromMonday = currentDayOfWeek === 0 ? 6 : currentDayOfWeek - 1;
  const monday = new Date(today);
  monday.setDate(today.getDate() - daysFromMonday);
  monday.setHours(0, 0, 0, 0);
  
  // Get Friday of current week
  const friday = new Date(monday);
  friday.setDate(monday.getDate() + 4);
  friday.setHours(23, 59, 59, 999);
  
  // Calculate week number from term start
  const diffTime = monday.getTime() - start.getTime();
  const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
  const weekNumber = Math.floor(diffDays / 7) + 1;
  
  return {
    weekNumber: weekNumber > 0 ? weekNumber : 1,
    weekStartDate: monday.toISOString().split('T')[0],
    weekEndDate: friday.toISOString().split('T')[0]
  };
}

