// GET /lesson-plans - Get lesson plans for teacher or principal
app.get('/make-server-1ddd013a/lesson-plans', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const session = c.req.query('session');
    const term = c.req.query('term');
    const status = c.req.query('status'); // draft, submitted, approved, declined
    const teacherId = c.req.query('teacher_id'); // For principal view

    console.log('[Lesson Plans] Fetching lesson plans...', { session, term, status, teacherId });

    // Get user profile to check role
    const { data: profile } = await supabase
      .from('profiles')
      .select('role')
      .eq('id', user.id)
      .single();

    // Build query based on role
    let lessonPlansKey = '';
    if (profile?.role === 'teacher') {
      lessonPlansKey = `lesson_plans_teacher_${user.id}`;
    } else if (['principal', 'director'].includes(profile?.role || '')) {
      lessonPlansKey = 'lesson_plans_all';
    } else {
      return c.json({ success: false, error: 'Unauthorized role' }, 403);
    }

    // Get lesson plans from KV store
    let lessonPlans = await kv.get(lessonPlansKey) as any[] || [];

    // Filter by query params
    if (session) {
      lessonPlans = lessonPlans.filter((lp: any) => lp.session === session);
    }
    if (term) {
      lessonPlans = lessonPlans.filter((lp: any) => lp.term === term);
    }
    if (status) {
      lessonPlans = lessonPlans.filter((lp: any) => lp.status === status);
    }
    if (teacherId && ['principal', 'director'].includes(profile?.role || '')) {
      lessonPlans = lessonPlans.filter((lp: any) => lp.teacher_id === teacherId);
    }

    // Get teacher and subject details for each lesson plan
    for (const lp of lessonPlans) {
      // Get teacher info
      const { data: teacher } = await supabase
        .from('profiles')
        .select('first_name, last_name, email')
        .eq('id', lp.teacher_id)
        .single();
      
      if (teacher) {
        lp.teacher_name = `${teacher.first_name} ${teacher.last_name}`;
        lp.teacher_email = teacher.email;
      }

      // Get subject info
      const { data: subject } = await supabase
        .from('subjects')
        .select('name')
        .eq('id', lp.subject_id)
        .single();
      
      if (subject) {
        lp.subject_name = subject.name;
      }

      // Get class info
      const { data: classData } = await supabase
        .from('classes')
        .select('name')
        .eq('id', lp.class_id)
        .single();
      
      if (classData) {
        lp.class_name = classData.name;
      }
    }

    return c.json({
      success: true,
      lesson_plans: lessonPlans
    });
  } catch (error) {
    console.error('[Lesson Plans] Error:', error);
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : 'Failed to fetch lesson plans'
    }, 500);
  }
});

// POST /lesson-plans - Create or update lesson plan
app.post('/make-server-1ddd013a/lesson-plans', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const body = await c.req.json();
    const { id, class_id, subject_id, session, term, lesson_data, status, week_number, week_start_date, week_end_date } = body;

    console.log('[Lesson Plans] Saving lesson plan...', { id, status });

    // Get all lesson plans
    const allLessonPlans = await kv.get('lesson_plans_all') as any[] || [];
    const teacherLessonPlans = await kv.get(`lesson_plans_teacher_${user.id}`) as any[] || [];

    const lessonPlan = {
      id: id || crypto.randomUUID(),
      teacher_id: user.id,
      class_id,
      subject_id,
      session,
      term,
      week_number,
      week_start_date,
      week_end_date,
      lesson_data,
      status: status || 'draft',
      submitted_at: status === 'submitted' ? new Date().toISOString() : null,
      created_at: id ? (allLessonPlans.find((lp: any) => lp.id === id)?.created_at || new Date().toISOString()) : new Date().toISOString(),
      updated_at: new Date().toISOString()
    };

    // Update or add lesson plan
    const existingIndex = allLessonPlans.findIndex((lp: any) => lp.id === lessonPlan.id);
    if (existingIndex >= 0) {
      allLessonPlans[existingIndex] = lessonPlan;
    } else {
      allLessonPlans.push(lessonPlan);
    }

    const teacherExistingIndex = teacherLessonPlans.findIndex((lp: any) => lp.id === lessonPlan.id);
    if (teacherExistingIndex >= 0) {
      teacherLessonPlans[teacherExistingIndex] = lessonPlan;
    } else {
      teacherLessonPlans.push(lessonPlan);
    }

    // Save back to KV store
    await kv.set('lesson_plans_all', allLessonPlans);
    await kv.set(`lesson_plans_teacher_${user.id}`, teacherLessonPlans);

    return c.json({
      success: true,
      lesson_plan: lessonPlan,
      message: status === 'submitted' ? 'Lesson plan submitted for approval' : 'Lesson plan saved as draft'
    });
  } catch (error) {
    console.error('[Lesson Plans] Error:', error);
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : 'Failed to save lesson plan'
    }, 500);
  }
});

// POST /lesson-plans/review - Approve or decline lesson plan (Principal only)
app.post('/make-server-1ddd013a/lesson-plans/review', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    // Check if user is principal/director
    const { data: profile } = await supabase
      .from('profiles')
      .select('role')
      .eq('id', user.id)
      .single();

    if (!profile || !['principal', 'director'].includes(profile.role)) {
      return c.json({ success: false, error: 'Only principals can review lesson plans' }, 403);
    }

    const { lesson_plan_id, action, review_notes } = await c.req.json();

    console.log('[Lesson Plan Review]', { lesson_plan_id, action, review_notes });

    // Get all lesson plans
    const allLessonPlans = await kv.get('lesson_plans_all') as any[] || [];

    // Find the lesson plan
    const lessonPlanIndex = allLessonPlans.findIndex((lp: any) => lp.id === lesson_plan_id);
    if (lessonPlanIndex < 0) {
      return c.json({ success: false, error: 'Lesson plan not found' }, 404);
    }

    const lessonPlan = allLessonPlans[lessonPlanIndex];

    // Update status
    lessonPlan.status = action; // 'approved' or 'declined'
    lessonPlan.reviewed_at = new Date().toISOString();
    lessonPlan.reviewed_by = user.id;
    lessonPlan.review_notes = review_notes;

    allLessonPlans[lessonPlanIndex] = lessonPlan;

    // Update teacher's copy
    const teacherLessonPlans = await kv.get(`lesson_plans_teacher_${lessonPlan.teacher_id}`) as any[] || [];
    const teacherIndex = teacherLessonPlans.findIndex((lp: any) => lp.id === lesson_plan_id);
    if (teacherIndex >= 0) {
      teacherLessonPlans[teacherIndex] = lessonPlan;
      await kv.set(`lesson_plans_teacher_${lessonPlan.teacher_id}`, teacherLessonPlans);
    }

    // Save back
    await kv.set('lesson_plans_all', allLessonPlans);

    return c.json({
      success: true,
      message: `Lesson plan ${action}`,
      lesson_plan: lessonPlan
    });
  } catch (error) {
    console.error('[Lesson Plan Review] Error:', error);
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : 'Failed to review lesson plan'
    }, 500);
  }
});

// DELETE /lesson-plans/:id - Delete lesson plan
app.delete('/make-server-1ddd013a/lesson-plans/:id', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const lessonPlanId = c.req.param('id');

    console.log('[Lesson Plans] Deleting lesson plan...', lessonPlanId);

    // Get all lesson plans
    const allLessonPlans = await kv.get('lesson_plans_all') as any[] || [];
    const teacherLessonPlans = await kv.get(`lesson_plans_teacher_${user.id}`) as any[] || [];

    // Filter out the deleted lesson plan
    const updatedAllPlans = allLessonPlans.filter((lp: any) => lp.id !== lessonPlanId);
    const updatedTeacherPlans = teacherLessonPlans.filter((lp: any) => lp.id !== lessonPlanId);

    // Save back
    await kv.set('lesson_plans_all', updatedAllPlans);
    await kv.set(`lesson_plans_teacher_${user.id}`, updatedTeacherPlans);

    return c.json({
      success: true,
      message: 'Lesson plan deleted successfully'
    });
  } catch (error) {
    console.error('[Lesson Plans] Error:', error);
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : 'Failed to delete lesson plan'
    }, 500);
  }
});

// GET /current-week - Get current academic week info
app.get('/make-server-1ddd013a/current-week', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    // Get current session from academic_sessions table
    const { data: currentSession, error: sessionError } = await supabase
      .from('academic_sessions')
      .select('*')
      .eq('is_current', true)
      .single();

    if (sessionError || !currentSession) {
      console.error('[Current Week] Session error:', sessionError);
      return c.json({
        success: false,
        error: 'No current academic session found'
      }, 404);
    }

    // Get current term from academic_terms table
    const { data: currentTerm, error: termError } = await supabase
      .from('academic_terms')
      .select('*')
      .eq('is_current', true)
      .single();

    if (termError || !currentTerm) {
      console.error('[Current Week] Term error:', termError);
      return c.json({
        success: false,
        error: 'No current academic term found'
      }, 404);
    }

    console.log('[Current Week] Found session:', currentSession.session_name, 'term:', currentTerm.term_name);

    // Calculate current week based on term start date
    const weekInfo = calculateAcademicWeek(currentTerm.start_date || new Date().toISOString());

    return c.json({
      success: true,
      week_info: {
        ...weekInfo,
        session: currentSession.session_name,
        term: currentTerm.term_name,
        term_start_date: currentTerm.start_date,
        term_end_date: currentTerm.end_date
      }
    });
  } catch (error) {
    console.error('[Current Week] Error:', error);
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : 'Failed to get current week'
    }, 500);
  }
});

// GET /teacher-submission-status - Get teacher's submission status for all subjects
app.get('/make-server-1ddd013a/teacher-submission-status', async (c) => {
  try {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const { data: { user }, error: authError } = await verifyUserAuth(accessToken);
    if (!user?.id) {
      return c.json({ success: false, error: 'Unauthorized' }, 401);
    }

    const session = c.req.query('session');
    const term = c.req.query('term');
    const weekNumber = parseInt(c.req.query('week_number') || '0');

    // Get teacher's subject assignments
    const { data: assignments } = await supabase
      .from('subject_assignments')
      .select(`
        subject_id,
        class_id,
        subjects (id, name),
        classes (id, name)
      `)
      .eq('teacher_id', user.id);

    // Get unique subject-class combinations
    const subjectClasses = new Map();
    assignments?.forEach((a: any) => {
      const key = `${a.subject_id}_${a.class_id}`;
      if (!subjectClasses.has(key)) {
        subjectClasses.set(key, {
          subject_id: a.subject_id,
          subject_name: a.subjects?.name,
          class_id: a.class_id,
          class_name: a.classes?.name
        });
      }
    });

    // Get teacher's lesson plans
    const teacherLessonPlans = await kv.get(`lesson_plans_teacher_${user.id}`) as any[] || [];

    // Check submission status for each subject-class
    const submissionStatus = Array.from(subjectClasses.values()).map((sc: any) => {
      const submitted = teacherLessonPlans.find((lp: any) => 
        lp.subject_id === sc.subject_id &&
        lp.class_id === sc.class_id &&
        lp.session === session &&
        lp.term === term &&
        lp.week_number === weekNumber &&
        ['submitted', 'approved', 'declined'].includes(lp.status)
      );

      return {
        ...sc,
        submitted: !!submitted,
        status: submitted?.status || 'not_submitted',
        lesson_plan_id: submitted?.id
      };
    });

    return c.json({
      success: true,
      submission_status: submissionStatus
    });
  } catch (error) {
    console.error('[Teacher Submission Status] Error:', error);
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : 'Failed to get submission status'
    }, 500);
  }
});

